    // ---- PDF export ------------------------------------------------------------------------------

    /// <summary>
    /// Builds the app-agnostic shared <see cref="Free.Shared.Pdf.PdfContentDocument"/> draw-op model
    /// from the current layout (the same placed glyphs the editor renders). This is FreeW Avalonia's
    /// Document → shared-page adapter: <see cref="FreeWAvaloniaPdfExport"/> hands the result to the
    /// shared Skia or portable WinAnsi backend. The export reuses the laid-out glyph positions so it
    /// matches what is on screen; it paginates the single continuous column by the page height from
    /// <see cref="TextDocument.Page"/>.
    /// <para>
    /// The adapter emits the already-laid-out table cell surfaces before inline images and body
    /// glyphs, together with the already-paginated headers, footers, footnotes, and endnotes.
    /// Floating images, shapes, and drawing groups use the same snapshot geometry and
    /// behind/in-front passes as the live Avalonia compositor. Group children are consumed from
    /// the shared recursive visual plan so their order and nested transforms remain explicit in the
    /// shared PDF operation tree.
    /// </para>
    /// </summary>
    public Free.Shared.Pdf.PdfContentDocument BuildPdfContent()
    {
        // PDF is a page-oriented artifact. Side-to-Side is a presentation projection of the live
        // editor, so export through a normal print-layout adapter and keep the horizontal strip out
        // of page-local PDF coordinates.
        if (_viewMode != DocumentViewMode.PrintLayout ||
            _viewDepthLayout.PageFlow is DocumentViewDepthPageFlow.SideToSideHorizontal
                or DocumentViewDepthPageFlow.MultiplePagesGrid)
        {
            var printView = new DocumentView { ViewMode = DocumentViewMode.PrintLayout };
            printView.LoadDocument(_doc);
            return printView.BuildPdfContent();
        }

        // Ensure a layout exists (tests/headless may export before a Render pass).
        if (_laidOutWidth < 0 || _placed.Count == 0)
            Relayout(FallbackWidth);

        var pageWidthPt = _doc.Page.WidthPt > 0 ? _doc.Page.WidthPt : 612;
        var pageHeightPt = _doc.Page.HeightPt > 0 ? _doc.Page.HeightPt : 792;
        var pageHeightPx = pageHeightPt * PxPerPoint;

        // Group consecutive same-line, same-format glyphs (excluding the page-left offset) into runs.
        var glyphs = _placed
            .Where(p => !p.Sentinel && p.Ch != '\0' && !p.Fmt.Hidden)
            .Concat(_automaticHyphenGlyphs
                .Where(glyph => !glyph.Fmt.Hidden)
                .Select(glyph => new PlacedChar(
                    glyph.Block,
                    glyph.BreakOffset,
                    glyph.X,
                    glyph.Y,
                    glyph.W,
                    glyph.LineHeight,
                    glyph.Fmt,
                    '-',
                    Sentinel: false,
                    CommentId: glyph.CommentId,
                    Revision: glyph.Revision,
                    RevisionAuthor: glyph.RevisionAuthor,
                    Link: glyph.Link,
                    HasFormatRevision: glyph.FormatRevision is not null,
                    FormatRevisionAuthor: glyph.FormatRevision?.Author)))
            .OrderBy(p => p.Y)
            .ThenBy(p => p.X)
            .ToList();

        // Bucket glyphs by page index (continuous column split at page height).
        var pagesOps = new List<List<Free.Shared.Pdf.PdfDrawOp>>();
        var pageLinkOverlays = new List<List<Free.Shared.Pdf.PdfLinkOverlay>>();
        var pageNamedDestinations = new List<List<Free.Shared.Pdf.PdfNamedDestination>>();

        var runStartX = 0.0;
        var runEndX = 0.0;
        var runY = 0.0;
        var runLineHeight = 0.0;
        var runText = new StringBuilder();
        RunFormatting? runFmt = null;
        LinkInfo? runLink = null;
        var runPageIndex = -1;

        void Flush()
        {
            if (runFmt is null || runText.Length == 0)
            {
                runText.Clear();
                runFmt = null;
                runLink = null;
                return;
            }

            while (pagesOps.Count <= runPageIndex)
                pagesOps.Add(new List<Free.Shared.Pdf.PdfDrawOp>());

            var sourceFontSizePt = runFmt.FontSizePt ?? DefaultFontSizePt;
            var fontSizePt = runFmt.VerticalAlign is VerticalAlign.Superscript or VerticalAlign.Subscript
                ? sourceFontSizePt * SuperSubScale
                : sourceFontSizePt;
            var face = (runFmt.Bold, runFmt.Italic) switch
            {
                (true, true) => Free.Shared.Pdf.PdfFontFace.BoldItalic,
                (true, false) => Free.Shared.Pdf.PdfFontFace.Bold,
                (false, true) => Free.Shared.Pdf.PdfFontFace.Italic,
                _ => Free.Shared.Pdf.PdfFontFace.Regular,
            };
            var color = ParseColor(runFmt.ColorHex);

            // Convert px -> pt and flip to PDF y-up. The glyph Y is the top of the line box; the text
            // baseline sits roughly at top + fontSize, so the PDF baseline (y-up) is page bottom minus that.
            // runY is in page-space Y (discrete multi-page layout); invert to get within-page offset.
            var xPt = (runStartX - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            // Offset within this page's page-space rectangle:
            //   pageTop(pageSpace) = DeskPadding + pageIndex*(pageHeightPx+PageGap)
            //   yWithinPagePx = runY - pageTop(pageSpace) = runY - DeskPadding - pageIndex*(pageHeightPx+PageGap)
            var yWithinPagePx = runY - _surfacePlan.PageTopDip(runPageIndex);
            var drawOffsetDip = runFmt.VerticalAlign switch
            {
                VerticalAlign.Superscript => Math.Max(1, runLineHeight) * SuperYRaiseFraction,
                VerticalAlign.Subscript => Math.Max(1, runLineHeight) * SubYLowerFraction,
                _ => 0,
            };
            var baselineFromTopPt = (yWithinPagePx + drawOffsetDip) / PxPerPoint + fontSizePt;
            var yPt = pageHeightPt - baselineFromTopPt + runFmt.PositionPt;

            var decorationPlan = RunDecorationVisualPlanner.Build(runFmt, PxPerPoint);
            if (decorationPlan.HasBackground)
            {
                var widthPt = Math.Max(1, runEndX - runStartX) / PxPerPoint;
                var heightPt = Math.Max(1, runLineHeight) / PxPerPoint;
                var bottomPt = pageHeightPt - (yWithinPagePx + Math.Max(1, runLineHeight)) / PxPerPoint;
                pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfFillRect(
                    Math.Max(0, xPt),
                    bottomPt,
                    widthPt,
                    heightPt,
                    ParseColor(decorationPlan.BackgroundColorHex)));
            }

            pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfText(
                Math.Max(0, xPt),
                yPt,
                fontSizePt,
                face,
                color,
                runText.ToString(),
                runFmt.FontFamily));

            if (decorationPlan.HasBorder && decorationPlan.Border is { } border)
            {
                var left = Math.Max(0, xPt);
                var right = left + Math.Max(1, runEndX - runStartX) / PxPerPoint;
                var bottom = pageHeightPt
                    - (yWithinPagePx + Math.Max(1, runLineHeight)) / PxPerPoint;
                var top = bottom + Math.Max(1, runLineHeight) / PxPerPoint;
                var contours = new List<Free.Shared.Pdf.PdfPathContour>(4);

                static Free.Shared.Pdf.PdfPathContour Edge(
                    double x1,
                    double y1,
                    double x2,
                    double y2) =>
                    new(
                        new Free.Shared.Pdf.PdfPathPoint(x1, y1),
                        [Free.Shared.Pdf.PdfPathSegment.LineTo(new Free.Shared.Pdf.PdfPathPoint(x2, y2))],
                        Closed: false);

                if (decorationPlan.DrawTopBorder)
                    contours.Add(Edge(left, top, right, top));
                if (decorationPlan.DrawLeftBorder)
                    contours.Add(Edge(left, top, left, bottom));
                if (decorationPlan.DrawBottomBorder)
                    contours.Add(Edge(left, bottom, right, bottom));
                if (decorationPlan.DrawRightBorder)
                    contours.Add(Edge(right, top, right, bottom));

                Free.Shared.Pdf.PdfDashPattern? dash = border.LineStyle switch
                {
                    BorderLineStyle.Dashed => new Free.Shared.Pdf.PdfDashPattern([4 / PxPerPoint, 3 / PxPerPoint]),
                    BorderLineStyle.Dotted => new Free.Shared.Pdf.PdfDashPattern([1 / PxPerPoint, 2 / PxPerPoint]),
                    _ => null,
                };
                pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfPath(
                    contours,
                    FillColor: null,
                    StrokeColor: ParseColor(border.ColorHex),
                    StrokeWidth: decorationPlan.BorderWidthDip / PxPerPoint,
                    StrokeDash: dash));
            }

            var decorationLineWidthPt = Math.Max(1, fontSizePt * PxPerPoint / 14) / PxPerPoint;
            var runWidthPt = Math.Max(1, runEndX - runStartX) / PxPerPoint;
            if (runFmt.Underline)
            {
                var underlineY = pageHeightPt
                    - (yWithinPagePx + Math.Max(1, runLineHeight) * 0.82) / PxPerPoint
                    + runFmt.PositionPt;
                pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfLine(
                    Math.Max(0, xPt),
                    underlineY,
                    Math.Max(0, xPt) + runWidthPt,
                    underlineY,
                    color,
                    decorationLineWidthPt));
            }

            if (runFmt.DoubleStrikethrough)
            {
                foreach (var fraction in new[] { 0.46, 0.54 })
                {
                    var strikeY = pageHeightPt
                        - (yWithinPagePx + Math.Max(1, runLineHeight) * fraction) / PxPerPoint
                        + runFmt.PositionPt;
                    pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfLine(
                        Math.Max(0, xPt),
                        strikeY,
                        Math.Max(0, xPt) + runWidthPt,
                        strikeY,
                        color,
                        decorationLineWidthPt));
                }
            }
            else if (runFmt.Strikethrough)
            {
                var strikeY = pageHeightPt
                    - (yWithinPagePx + Math.Max(1, runLineHeight) * 0.5) / PxPerPoint
                    + runFmt.PositionPt;
                pagesOps[runPageIndex].Add(new Free.Shared.Pdf.PdfLine(
                    Math.Max(0, xPt),
                    strikeY,
                    Math.Max(0, xPt) + runWidthPt,
                    strikeY,
                    color,
                    decorationLineWidthPt));
            }

            if (runLink is { HasTarget: true } link)
            {
                while (pageLinkOverlays.Count <= runPageIndex)
                    pageLinkOverlays.Add(new List<Free.Shared.Pdf.PdfLinkOverlay>());

                pageLinkOverlays[runPageIndex].Add(new Free.Shared.Pdf.PdfLinkOverlay(
                    Math.Max(0, xPt),
                    Math.Max(0, yWithinPagePx / PxPerPoint),
                    Math.Max(1, runEndX - runStartX) / PxPerPoint,
                    Math.Max(1, runLineHeight) / PxPerPoint,
                    link.IsExternal ? link.Url : null,
                    link.Tooltip,
                    link.IsInternal ? link.Anchor?.TrimStart('#').Trim() : null));
            }

            runText.Clear();
            runFmt = null;
            runLink = null;
        }

        // Glyphs are now in page-space Y (discrete multi-page layout).
        // Derive page index and within-page Y directly from the page-space Y.
        var pageStride = _surfacePlan.PageStrideDip; // distance between page tops in page space
        foreach (var g in glyphs)
        {
            // Invert ContentYToPageSpaceY:
            //   pageSpaceY = DeskPadding + pageIndex*(pageHeightPx+PageGap) + marginTopDip + offsetWithinPage
            var rel = g.Y - _surfacePlan.DeskPaddingDip;
            var pageIndex = Math.Max(0, (int)(rel / pageStride));
            var pdfFmt = g.IsHyperlink
                ? g.Fmt with
                {
                    ColorHex = string.IsNullOrWhiteSpace(g.Fmt.ColorHex) ? HyperlinkColorHex : g.Fmt.ColorHex,
                    Underline = true,
                }
                : g.Fmt;
            var sameRun = runFmt is not null
                && runPageIndex == pageIndex
                && Math.Abs(g.Y - runY) < 0.5
                && FormatKey(pdfFmt) == FormatKey(runFmt)
                && Nullable.Equals(g.Link, runLink)
                && g.X >= runStartX; // left-to-right on the line

            if (!sameRun)
            {
                Flush();
                runStartX = g.X;
                runEndX = g.X;
                runY = g.Y;
                runLineHeight = 0;
                runFmt = pdfFmt;
                runLink = g.Link;
                runPageIndex = pageIndex;
            }

            runText.Append(g.Ch);
            runEndX = Math.Max(runEndX, g.X + Math.Max(1, g.W));
            runLineHeight = Math.Max(runLineHeight, g.LineHeight);
        }

        Flush();

        var emittedDestinationNames = new HashSet<string>(StringComparer.Ordinal);
        foreach (var location in Bookmarks.List(_doc))
        {
            if (string.IsNullOrWhiteSpace(location.Name)
                || !emittedDestinationNames.Add(location.Name)
                || location.BlockIndex < 0
                || location.BlockIndex >= _doc.Blocks.Count
                || _doc.Blocks[location.BlockIndex] is not Paragraph paragraph)
            {
                continue;
            }

            var targetOffset = 0;
            var startBoundary = paragraph.BookmarkBoundaries.FirstOrDefault(boundary =>
                boundary.Kind == BookmarkBoundaryKind.Start
                && string.Equals(boundary.Name, location.Name, StringComparison.Ordinal));
            if (startBoundary is not null)
            {
                var runLimit = Math.Clamp(startBoundary.RunIndex, 0, paragraph.Runs.Count);
                targetOffset = paragraph.Runs.Take(runLimit).Sum(run => run.Text?.Length ?? 0);
            }

            var placement = _placed
                .Where(item => item.Block == location.BlockIndex && item.Offset >= targetOffset)
                .OrderBy(item => item.Offset)
                .ThenBy(item => item.Y)
                .Select(item => (PlacedChar?)item)
                .FirstOrDefault()
                ?? _placed
                    .Where(item => item.Block == location.BlockIndex)
                    .OrderBy(item => item.Offset)
                    .ThenBy(item => item.Y)
                    .Select(item => (PlacedChar?)item)
                    .FirstOrDefault();
            if (placement is not { } target)
                continue;

            var destinationPageIndex = PageIndexFromPageSpaceY(target.Y + 0.01);
            if (destinationPageIndex < 0)
                continue;
            while (pageNamedDestinations.Count <= destinationPageIndex)
                pageNamedDestinations.Add(new List<Free.Shared.Pdf.PdfNamedDestination>());

            pageNamedDestinations[destinationPageIndex].Add(new Free.Shared.Pdf.PdfNamedDestination(
                location.Name,
                Math.Max(0, (target.X - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt),
                Math.Max(0, (target.Y - _surfacePlan.PageTopDip(destinationPageIndex)) / PxPerPoint)));
        }

        // Table cell rectangles are already in page space and are painted below glyphs by the live
        // Avalonia renderer. Reuse those same items for PDF export; do not remeasure or paginate a
        // second time. A clipped fragment is emitted only for the page whose media box contains it.
        void EnsurePage(int pageIndex)
        {
            while (pagesOps.Count <= pageIndex)
                pagesOps.Add(new List<Free.Shared.Pdf.PdfDrawOp>());
        }

        var tableOpsByPage = new List<List<Free.Shared.Pdf.PdfDrawOp>>();

        void EnsureTablePage(int pageIndex)
        {
            while (tableOpsByPage.Count <= pageIndex)
                tableOpsByPage.Add(new List<Free.Shared.Pdf.PdfDrawOp>());
        }

        static Free.Shared.Pdf.PdfColor SolidBrushColor(IBrush? brush) =>
            brush is ISolidColorBrush solid
                ? new Free.Shared.Pdf.PdfColor(solid.Color.R, solid.Color.G, solid.Color.B)
                : Free.Shared.Pdf.PdfColor.Black;

        void AddTableEdge(
            List<Free.Shared.Pdf.PdfDrawOp> ops,
            TableCellBorderVisualEdge edge,
            string colorHex,
            double widthDip,
            BorderLineStyle style,
            Rect sourceRect,
            Rect clippedRect,
            double pageTopDip)
        {
            var edgeIsOnPage = edge switch
            {
                TableCellBorderVisualEdge.Top => sourceRect.Top >= pageTopDip - 0.01
                    && sourceRect.Top <= pageTopDip + _pageHeightPx + 0.01,
                TableCellBorderVisualEdge.Bottom => sourceRect.Bottom >= pageTopDip - 0.01
                    && sourceRect.Bottom <= pageTopDip + _pageHeightPx + 0.01,
                TableCellBorderVisualEdge.Left => sourceRect.Left >= _pageLeft - 0.01
                    && sourceRect.Left <= _pageLeft + _pageWidth + 0.01,
                TableCellBorderVisualEdge.Right => sourceRect.Right >= _pageLeft - 0.01
                    && sourceRect.Right <= _pageLeft + _pageWidth + 0.01,
                _ => false,
            };
            if (!edgeIsOnPage)
                return;

            var color = ParseColor(colorHex);
            var widthPt = Math.Max(0.1, widthDip / PxPerPoint);

            (double X1, double Y1, double X2, double Y2) Points(double offsetDip) => edge switch
            {
                TableCellBorderVisualEdge.Top =>
                    (clippedRect.Left, sourceRect.Top + offsetDip,
                        clippedRect.Right, sourceRect.Top + offsetDip),
                TableCellBorderVisualEdge.Bottom =>
                    (clippedRect.Left, sourceRect.Bottom - offsetDip,
                        clippedRect.Right, sourceRect.Bottom - offsetDip),
                TableCellBorderVisualEdge.Left =>
                    (sourceRect.Left + offsetDip, clippedRect.Top,
                        sourceRect.Left + offsetDip, clippedRect.Bottom),
                TableCellBorderVisualEdge.Right =>
                    (sourceRect.Right - offsetDip, clippedRect.Top,
                        sourceRect.Right - offsetDip, clippedRect.Bottom),
                _ => (0, 0, 0, 0),
            };

            void AddLine(double offsetDip)
            {
                var (x1Dip, y1Dip, x2Dip, y2Dip) = Points(offsetDip);
                var x1Pt = (x1Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
                var x2Pt = (x2Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
                var y1Pt = pageHeightPt - ((y1Dip - pageTopDip) / PxPerPoint);
                var y2Pt = pageHeightPt - ((y2Dip - pageTopDip) / PxPerPoint);
                ops.Add(new Free.Shared.Pdf.PdfLine(
                    x1Pt, y1Pt, x2Pt, y2Pt, color, widthPt));
            }

            if (style == BorderLineStyle.Double)
            {
                var offset = Math.Max(1.0, widthDip * 1.5) / 2.0;
                AddLine(-offset);
                AddLine(offset);
            }
            else
            {
                // The shared PDF draw-op vocabulary has no dash pattern. Dashed, dotted, and wave
                // cell borders therefore use a solid-line PDF fallback.
                AddLine(0);
            }
        }

        void AddTableOpsForPage(
            int pageIndex,
            Rect sourceRect,
            IBrush? fill,
            bool hasTableBorder,
            TableCellBorderVisualPlan? cellBorderPlan)
        {
            var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
            var pageBottomDip = pageTopDip + _pageHeightPx;
            var clippedLeft = Math.Max(sourceRect.Left, _pageLeft);
            var clippedTop = Math.Max(sourceRect.Top, pageTopDip);
            var clippedRight = Math.Min(sourceRect.Right, _pageLeft + _pageWidth);
            var clippedBottom = Math.Min(sourceRect.Bottom, pageBottomDip);
            if (clippedRight <= clippedLeft || clippedBottom <= clippedTop)
                return;

            var clippedRect = new Rect(
                clippedLeft,
                clippedTop,
                clippedRight - clippedLeft,
                clippedBottom - clippedTop);
            var ops = tableOpsByPage[pageIndex];
            var xPt = (clippedRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            var yPt = pageHeightPt - ((clippedRect.Bottom - pageTopDip) / PxPerPoint);
            var widthPt = clippedRect.Width / PxPerPoint;
            var heightPt = clippedRect.Height / PxPerPoint;

            if (fill is ISolidColorBrush solid && solid.Color.A > 0)
            {
                ops.Add(new Free.Shared.Pdf.PdfFillRect(
                    xPt, yPt, widthPt, heightPt, SolidBrushColor(solid)));
            }

            var tableBorderColor = new Free.Shared.Pdf.PdfColor(0x9A, 0x9A, 0x9A);
            var tableBorderWidthPt = 0.75 / PxPerPoint;
            if (hasTableBorder)
            {
                var fullyInsidePage = sourceRect.Left >= _pageLeft - 0.01
                    && sourceRect.Right <= _pageLeft + _pageWidth + 0.01
                    && sourceRect.Top >= pageTopDip - 0.01
                    && sourceRect.Bottom <= pageBottomDip + 0.01;
                if (fullyInsidePage)
                {
                    var sourceXPt = (sourceRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
                    var sourceYPt = pageHeightPt - ((sourceRect.Bottom - pageTopDip) / PxPerPoint);
                    ops.Add(new Free.Shared.Pdf.PdfStrokeRect(
                        sourceXPt,
                        sourceYPt,
                        sourceRect.Width / PxPerPoint,
                        sourceRect.Height / PxPerPoint,
                        tableBorderColor,
                        tableBorderWidthPt));
                }
                else
                {
                    foreach (var edge in new[]
                    {
                        TableCellBorderVisualEdge.Top,
                        TableCellBorderVisualEdge.Bottom,
                        TableCellBorderVisualEdge.Left,
                        TableCellBorderVisualEdge.Right,
                    })
                    {
                        AddTableEdge(
                            ops,
                            edge,
                            "#9A9A9A",
                            0.75,
                            BorderLineStyle.Single,
                            sourceRect,
                            clippedRect,
                            pageTopDip);
                    }
                }
            }

            if (cellBorderPlan is null)
                return;

            foreach (var edge in cellBorderPlan.Edges.Where(edge => edge.IsVisible))
            {
                AddTableEdge(
                    ops,
                    edge.Edge,
                    edge.ColorHex,
                    edge.WidthDip,
                    edge.Style,
                    sourceRect,
                    clippedRect,
                    pageTopDip);
            }
        }

        var tableSurfaceCountsByPage = new List<int>();
        var tablePageCount = Math.Max(_pageCount, pagesOps.Count);
        for (var pageIndex = 0; pageIndex < tablePageCount; pageIndex++)
        {
            EnsureTablePage(pageIndex);
            foreach (var (rect, fill, border, cellBorderPlan) in _rects)
            {
                var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
                var pageBottomDip = pageTopDip + _pageHeightPx;
                if (rect.Bottom <= pageTopDip || rect.Top >= pageBottomDip
                    || rect.Right <= _pageLeft || rect.Left >= _pageLeft + _pageWidth)
                    continue;

                AddTableOpsForPage(pageIndex, rect, fill, border, cellBorderPlan);
            }

            if (tableOpsByPage[pageIndex].Count > 0)
            {
                EnsurePage(pageIndex);
                // Cell surfaces are below all text, matching the on-screen renderer's pass order.
                pagesOps[pageIndex].InsertRange(0, tableOpsByPage[pageIndex]);
            }

            while (tableSurfaceCountsByPage.Count <= pageIndex)
                tableSurfaceCountsByPage.Add(0);
            tableSurfaceCountsByPage[pageIndex] = tableOpsByPage[pageIndex].Count;
        }

        // Inline images are already page-owned by LayoutImageParagraphPaged. Reuse those cached
        // page-space items instead of remeasuring or creating a second paginator. They sit after
        // table surfaces and before body text, matching Render's table -> image -> text passes.
        var imageOpsByPage = new List<List<Free.Shared.Pdf.PdfDrawOp>>();
        foreach (var imageItem in _images.OrderBy(item => item.Rect.Y).ThenBy(item => item.Rect.X))
        {
            var sourceRect = imageItem.Rect;
            var pageIndex = PageIndexFromPageSpaceY(sourceRect.Top + 0.01);
            if (pageIndex < 0)
                continue;

            var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
            var pageBottomDip = pageTopDip + _pageHeightPx;
            var pageRightDip = _pageLeft + _pageWidth;
            // Inline layout reserves a complete line box before placing an image. Keep the
            // operation on that page only; a split would paint into the adjacent page because
            // PdfImage has source-crop clipping but no arbitrary page-rectangle clip operation.
            if (sourceRect.Left < _pageLeft - 0.01
                || sourceRect.Right > pageRightDip + 0.01
                || sourceRect.Top < pageTopDip - 0.01
                || sourceRect.Bottom > pageBottomDip + 0.01)
                continue;

            if (BuildPdfImage(sourceRect, imageItem.Model, imageItem.Image, pageTopDip, pageHeightPt) is not { } imageOp)
                continue;

            while (imageOpsByPage.Count <= pageIndex)
                imageOpsByPage.Add(new List<Free.Shared.Pdf.PdfDrawOp>());
            imageOpsByPage[pageIndex].Add(imageOp);
        }

        for (var pageIndex = 0; pageIndex < imageOpsByPage.Count; pageIndex++)
        {
            if (imageOpsByPage[pageIndex].Count == 0)
                continue;

            EnsurePage(pageIndex);
            var insertionIndex = pageIndex < tableSurfaceCountsByPage.Count
                ? tableSurfaceCountsByPage[pageIndex]
                : 0;
            pagesOps[pageIndex].InsertRange(
                Math.Min(insertionIndex, pagesOps[pageIndex].Count),
                imageOpsByPage[pageIndex]);
        }

        // Floating images and shapes share the same snapshot/page-space geometry and merged
        // behind/in-front draw buckets as the live Avalonia renderer. Keep all object kinds in one
        // pass so a shape and image with interleaved z-order still paint in the same order.
        var floatingBehindOpsByPage = new List<List<Free.Shared.Pdf.PdfDrawOp>>();
        var floatingInFrontOpsByPage = new List<List<Free.Shared.Pdf.PdfDrawOp>>();

        void AddFloatingDrawingOps(
            bool behindText,
            List<List<Free.Shared.Pdf.PdfDrawOp>> target)
        {
            foreach (var snapshot in DocumentViewLayoutPlanner.BuildFloatingObjectDrawOrder(
                         _floatingSnapshots,
                         behindText))
            {
                if (snapshot.BlockIndex < 0
                    || snapshot.BlockIndex >= _doc.Blocks.Count
                    || _doc.Blocks[snapshot.BlockIndex] is not Paragraph paragraph
                    || snapshot.RunIndex < 0
                    || snapshot.RunIndex >= paragraph.Runs.Count
                    || snapshot.Kind is not (DocumentFloatingObjectKind.Image
                        or DocumentFloatingObjectKind.Shape
                        or DocumentFloatingObjectKind.Chart
                        or DocumentFloatingObjectKind.WordArt
                        or DocumentFloatingObjectKind.SmartArt
                        or DocumentFloatingObjectKind.Group))
                    continue;

                var pageIndex = PageIndexFromPageSpaceY(snapshot.Rect.TopDip + 0.01);
                if (pageIndex < 0)
                    continue;

                var sourceRect = new Rect(
                    snapshot.Rect.XDip,
                    snapshot.Rect.YDip,
                    snapshot.Rect.WidthDip,
                    snapshot.Rect.HeightDip);
                var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
                IReadOnlyList<Free.Shared.Pdf.PdfDrawOp> objectOps = snapshot.Kind switch
                {
                    DocumentFloatingObjectKind.Image when paragraph.Runs[snapshot.RunIndex].Image is { IsFloating: true } image =>
                        BuildPdfImage(
                            sourceRect,
                            image,
                            _floatingImages
                                .Where(item => item.BlockIndex == snapshot.BlockIndex
                                    && item.RunIndex == snapshot.RunIndex)
                                .Select(item => item.Image)
                                .FirstOrDefault()
                                ?? DecodeRenderedImage(image),
                            pageTopDip,
                            pageHeightPt) is { } imageOp
                            ? [imageOp]
                            : [],
                    DocumentFloatingObjectKind.Shape when paragraph.Runs[snapshot.RunIndex].Shape is { IsFloating: true } shape =>
                        BuildPdfShapeOps(shape, snapshot, sourceRect, pageTopDip, pageHeightPt),
                    DocumentFloatingObjectKind.Chart when paragraph.Runs[snapshot.RunIndex].Chart is { IsFloating: true } chart =>
                        BuildPdfChartOps(
                            chart,
                            DrawingObjectVisualPlanner.BuildVisualPlan(chart, snapshot),
                            sourceRect,
                            pageTopDip,
                            pageHeightPt),
                    DocumentFloatingObjectKind.WordArt when paragraph.Runs[snapshot.RunIndex].WordArt is { IsFloating: true } wordArt =>
                        BuildPdfWordArtOps(
                            DrawingObjectVisualPlanner.BuildVisualPlan(wordArt, snapshot),
                            sourceRect,
                            pageTopDip,
                            pageHeightPt),
                    DocumentFloatingObjectKind.SmartArt when paragraph.Runs[snapshot.RunIndex].SmartArt is { IsFloating: true } smartArt =>
                        BuildPdfSmartArtOps(
                            DrawingObjectVisualPlanner.BuildVisualPlan(smartArt, snapshot),
                            sourceRect,
                            pageTopDip,
                            pageHeightPt),
                    DocumentFloatingObjectKind.Group when paragraph.Runs[snapshot.RunIndex].DrawingGroup is { } group =>
                        BuildPdfGroupOps(group, snapshot, pageTopDip, pageHeightPt),
                    _ => [],
                };
                if (objectOps.Count == 0)
                    continue;

                while (target.Count <= pageIndex)
                    target.Add(new List<Free.Shared.Pdf.PdfDrawOp>());
                target[pageIndex].AddRange(objectOps);
            }
        }

        AddFloatingDrawingOps(behindText: true, target: floatingBehindOpsByPage);
        AddFloatingDrawingOps(behindText: false, target: floatingInFrontOpsByPage);

        for (var pageIndex = 0; pageIndex < floatingBehindOpsByPage.Count; pageIndex++)
        {
            if (floatingBehindOpsByPage[pageIndex].Count == 0)
                continue;

            EnsurePage(pageIndex);
            var insertionIndex = pageIndex < tableSurfaceCountsByPage.Count
                ? tableSurfaceCountsByPage[pageIndex]
                : 0;
            pagesOps[pageIndex].InsertRange(
                Math.Min(insertionIndex, pagesOps[pageIndex].Count),
                floatingBehindOpsByPage[pageIndex]);
        }

        // Inline charts, WordArt, and SmartArt are laid out into page-space rectangles by the same
        // non-text flow pass as inline images. Reuse those resolved rectangles and shared visual
        // plans, preserving the live chart -> WordArt -> SmartArt paint order before body glyphs.
        var inlineDrawingOpsByPage = new List<List<Free.Shared.Pdf.PdfDrawOp>>();

        void AddInlineDrawingOps(Rect rect, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp> objectOps)
        {
            if (objectOps.Count == 0)
                return;

            var pageIndex = PageIndexFromPageSpaceY(rect.Top + 0.01);
            if (pageIndex < 0)
                return;
            while (inlineDrawingOpsByPage.Count <= pageIndex)
                inlineDrawingOpsByPage.Add([]);
            inlineDrawingOpsByPage[pageIndex].AddRange(objectOps);
        }

        foreach (var shapeData in _inlineShapes)
        {
            if (shapeData.Model is not { } shape)
                continue;
            var pageIndex = PageIndexFromPageSpaceY(shapeData.Rect.Top + 0.01);
            if (pageIndex < 0)
                continue;
            var snapshot = BuildInlineDrawingSnapshot(
                DocumentFloatingObjectKind.Shape,
                shapeData.Rect,
                shapeData.BlockIndex,
                shapeData.RunIndex,
                shape.RotationAngle,
                shape.FlipH,
                shape.FlipV);
            AddInlineDrawingOps(
                shapeData.Rect,
                BuildPdfShapeOps(
                    shape,
                    snapshot,
                    shapeData.Rect,
                    _surfacePlan.PageTopDip(pageIndex),
                    pageHeightPt));
        }

        foreach (var chartData in _inlineCharts)
        {
            if (chartData.Model is not { } chart)
                continue;
            var pageIndex = PageIndexFromPageSpaceY(chartData.Rect.Top + 0.01);
            if (pageIndex < 0)
                continue;
            var snapshot = BuildInlineDrawingSnapshot(
                DocumentFloatingObjectKind.Chart,
                chartData.Rect,
                chartData.BlockIndex,
                chartData.RunIndex,
                chart.RotationAngle,
                chart.FlipH,
                chart.FlipV);
            AddInlineDrawingOps(
                chartData.Rect,
                BuildPdfChartOps(
                    chart,
                    DrawingObjectVisualPlanner.BuildVisualPlan(chart, snapshot),
                    chartData.Rect,
                    _surfacePlan.PageTopDip(pageIndex),
                    pageHeightPt));
        }

        foreach (var wordArtData in _inlineWordArts)
        {
            if (wordArtData.Model is not { } wordArt)
                continue;
            var pageIndex = PageIndexFromPageSpaceY(wordArtData.Rect.Top + 0.01);
            if (pageIndex < 0)
                continue;
            var snapshot = BuildInlineDrawingSnapshot(
                DocumentFloatingObjectKind.WordArt,
                wordArtData.Rect,
                wordArtData.BlockIndex,
                wordArtData.RunIndex,
                wordArt.RotationAngle,
                wordArt.FlipH,
                wordArt.FlipV);
            AddInlineDrawingOps(
                wordArtData.Rect,
                BuildPdfWordArtOps(
                    DrawingObjectVisualPlanner.BuildVisualPlan(wordArt, snapshot),
                    wordArtData.Rect,
                    _surfacePlan.PageTopDip(pageIndex),
                    pageHeightPt));
        }

        foreach (var smartArtData in _inlineSmartArts)
        {
            if (smartArtData.IsWordSuppressedByDuplicateDrawingId
                || smartArtData.Model is not { } smartArt)
            {
                continue;
            }

            var pageIndex = PageIndexFromPageSpaceY(smartArtData.Rect.Top + 0.01);
            if (pageIndex < 0)
                continue;
            var snapshot = BuildInlineDrawingSnapshot(
                DocumentFloatingObjectKind.SmartArt,
                smartArtData.Rect,
                smartArtData.BlockIndex,
                smartArtData.RunIndex,
                smartArt.RotationAngle,
                smartArt.FlipH,
                smartArt.FlipV);
            AddInlineDrawingOps(
                smartArtData.Rect,
                BuildPdfSmartArtOps(
                    DrawingObjectVisualPlanner.BuildVisualPlan(smartArt, snapshot),
                    smartArtData.Rect,
                    _surfacePlan.PageTopDip(pageIndex),
                    pageHeightPt));
        }

        foreach (var embeddedObject in _inlineEmbeddedObjects)
        {
            var sourceRect = embeddedObject.Rect;
            var pageIndex = PageIndexFromPageSpaceY(sourceRect.Top + 0.01);
            if (pageIndex < 0)
                continue;

            var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
            AddInlineDrawingOps(
                sourceRect,
                BuildPdfEmbeddedObjectOps(
                    sourceRect,
                    embeddedObject.Plan,
                    embeddedObject.Icon,
                    pageTopDip,
                    pageHeightPt));
        }

        for (var pageIndex = 0; pageIndex < inlineDrawingOpsByPage.Count; pageIndex++)
        {
            if (inlineDrawingOpsByPage[pageIndex].Count == 0)
                continue;

            EnsurePage(pageIndex);
            var tableCount = pageIndex < tableSurfaceCountsByPage.Count
                ? tableSurfaceCountsByPage[pageIndex]
                : 0;
            var behindCount = pageIndex < floatingBehindOpsByPage.Count
                ? floatingBehindOpsByPage[pageIndex].Count
                : 0;
            var imageCount = pageIndex < imageOpsByPage.Count
                ? imageOpsByPage[pageIndex].Count
                : 0;
            pagesOps[pageIndex].InsertRange(
                Math.Min(tableCount + behindCount + imageCount, pagesOps[pageIndex].Count),
                inlineDrawingOpsByPage[pageIndex]);
        }

        // The live Avalonia layout has already resolved page ownership, field text, wrapping, and
        // note bands. Carry those same text regions into the PDF model so export does not silently
        // lose document chrome that Print Preview visibly shows.
        void AddTextRegion(string text, RunFormatting fmt, double xDip, double yDip)
        {
            if (string.IsNullOrEmpty(text))
                return;

            var pageIndex = PageIndexFromPageSpaceY(yDip);
            if (pageIndex < 0)
                return;

            EnsurePage(pageIndex);
            var fontSizePt = fmt.FontSizePt ?? DefaultFontSizePt;
            var xPt = (xDip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            var yWithinPagePx = yDip - _surfacePlan.PageTopDip(pageIndex);
            var yPt = pageHeightPt - (yWithinPagePx / PxPerPoint + fontSizePt) + fmt.PositionPt;
            var face = fmt.Bold ? Free.Shared.Pdf.PdfFontFace.Bold : Free.Shared.Pdf.PdfFontFace.Regular;
            pagesOps[pageIndex].Add(new Free.Shared.Pdf.PdfText(
                Math.Max(0, xPt), yPt, fontSizePt, face, ParseColor(fmt.ColorHex), text));
        }

        // In-front floating drawings are appended after body text, matching Render's second
        // floating pass. Keep them ahead of header/footer and note regions, as in the compositor.
        for (var pageIndex = 0; pageIndex < floatingInFrontOpsByPage.Count; pageIndex++)
        {
            if (floatingInFrontOpsByPage[pageIndex].Count == 0)
                continue;

            EnsurePage(pageIndex);
            pagesOps[pageIndex].AddRange(floatingInFrontOpsByPage[pageIndex]);
        }

        foreach (var item in _headerFooterItems)
        {
            if (item.Image is { } image)
            {
                var pageIndex = PageIndexFromPageSpaceY(item.Y + 0.01);
                if (pageIndex < 0)
                    continue;

                EnsurePage(pageIndex);
                var sourceRect = new Rect(
                    item.X,
                    item.Y,
                    Math.Max(1, item.Width),
                    Math.Max(1, item.Height));
                if (BuildPdfImage(
                        sourceRect,
                        image,
                        DecodeRenderedImage(image),
                        _surfacePlan.PageTopDip(pageIndex),
                        pageHeightPt) is { } imageOp)
                {
                    pagesOps[pageIndex].Add(imageOp);
                }

                continue;
            }

            if (item.EmbeddedObject is { } embeddedObject)
            {
                var pageIndex = PageIndexFromPageSpaceY(item.Y + 0.01);
                if (pageIndex < 0)
                    continue;
                EnsurePage(pageIndex);
                var sourceRect = new Rect(
                    item.X,
                    item.Y,
                    Math.Max(1, item.Width),
                    Math.Max(1, item.Height));
                pagesOps[pageIndex].AddRange(BuildPdfEmbeddedObjectOps(
                    sourceRect,
                    embeddedObject,
                    item.EmbeddedObjectIcon,
                    _surfacePlan.PageTopDip(pageIndex),
                    pageHeightPt));
                continue;
            }

            AddTextRegion(item.Text, item.Fmt, item.X, item.Y);
        }

        foreach (var item in _noteItems)
            AddTextRegion(item.Text, item.Fmt, item.X, item.Y);

        foreach (var (x1Dip, x2Dip, yDip) in _noteSeparators)
        {
            var pageIndex = PageIndexFromPageSpaceY(yDip);
            if (pageIndex < 0)
                continue;

            EnsurePage(pageIndex);
            var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
            var yPt = pageHeightPt - ((yDip - pageTopDip) / PxPerPoint);
            var x1Pt = (x1Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            var x2Pt = (x2Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            pagesOps[pageIndex].Add(new Free.Shared.Pdf.PdfLine(
                Math.Max(0, x1Pt), yPt, Math.Max(0, x2Pt), yPt,
                new Free.Shared.Pdf.PdfColor(0x70, 0x70, 0x70), 0.5));
        }

        var columnRuleCountsByPage = new List<int>();
        foreach (var (pageIndex, columnRuleOps) in BuildPdfColumnRuleOps(pageHeightPt))
        {
            EnsurePage(pageIndex);
            var tableCount = pageIndex < tableSurfaceCountsByPage.Count
                ? tableSurfaceCountsByPage[pageIndex]
                : 0;
            pagesOps[pageIndex].InsertRange(
                Math.Min(tableCount, pagesOps[pageIndex].Count),
                columnRuleOps);
            while (columnRuleCountsByPage.Count <= pageIndex)
                columnRuleCountsByPage.Add(0);
            columnRuleCountsByPage[pageIndex] = columnRuleOps.Count;
        }

        foreach (var (pageIndex, lineNumberOps) in BuildPdfLineNumberOps(pageHeightPt))
        {
            EnsurePage(pageIndex);
            var tableCount = pageIndex < tableSurfaceCountsByPage.Count
                ? tableSurfaceCountsByPage[pageIndex]
                : 0;
            var columnRuleCount = pageIndex < columnRuleCountsByPage.Count
                ? columnRuleCountsByPage[pageIndex]
                : 0;
            pagesOps[pageIndex].InsertRange(
                Math.Min(tableCount + columnRuleCount, pagesOps[pageIndex].Count),
                lineNumberOps);
        }

        foreach (var (pageIndex, decorationOps) in BuildPdfParagraphDecorationOps(pageHeightPt))
        {
            EnsurePage(pageIndex);
            pagesOps[pageIndex].InsertRange(0, decorationOps);
        }

        if (_doc.Page.PageBorder is { } pageBorder)
        {
            var borderedPageCount = Math.Max(1, Math.Max(_pageCount, pagesOps.Count));
            EnsurePage(borderedPageCount - 1);
            var borderOps = BuildPdfPageBorderOps(pageWidthPt, pageHeightPt);
            var borderLayer = PageBorderVisibilityPlanner.LayerFor(pageBorder.ZOrder);
            for (var pageIndex = 0; pageIndex < borderedPageCount; pageIndex++)
            {
                if (!PageBorderVisibilityPlanner.ShouldRender(pageBorder.Display, pageIndex))
                    continue;

                if (borderLayer == PageBorderRenderLayer.BehindText)
                    pagesOps[pageIndex].InsertRange(0, borderOps);
                else
                    pagesOps[pageIndex].AddRange(borderOps);
            }
        }

        var watermarkOps = BuildPdfWatermarkOps(pageWidthPt, pageHeightPt);
        if (watermarkOps.Count > 0)
        {
            var watermarkedPageCount = Math.Max(1, Math.Max(_pageCount, pagesOps.Count));
            EnsurePage(watermarkedPageCount - 1);
            for (var pageIndex = 0; pageIndex < watermarkedPageCount; pageIndex++)
                pagesOps[pageIndex].InsertRange(0, watermarkOps);
        }

        if (pagesOps.Count == 0)
            pagesOps.Add(new List<Free.Shared.Pdf.PdfDrawOp>());

        var pages = pagesOps
            .Select((ops, pageIndex) => new Free.Shared.Pdf.PdfContentPage(
                pageWidthPt,
                pageHeightPt,
                ops,
                pageIndex < pageLinkOverlays.Count && pageLinkOverlays[pageIndex].Count > 0
                    ? pageLinkOverlays[pageIndex]
                    : null,
                pageIndex < pageNamedDestinations.Count && pageNamedDestinations[pageIndex].Count > 0
                    ? pageNamedDestinations[pageIndex]
                    : null))
            .ToList();
        var properties = new Free.Shared.Pdf.PdfDocumentProperties(
            Title: string.IsNullOrWhiteSpace(_doc.Properties.Title) ? null : _doc.Properties.Title,
            Author: string.IsNullOrWhiteSpace(_doc.Properties.Author) ? null : _doc.Properties.Author,
            Creator: "FreeW");
        return new Free.Shared.Pdf.PdfContentDocument(pages, properties);
    }

    private IReadOnlyList<Free.Shared.Pdf.PdfDrawOp> BuildPdfPageBorderOps(
        double pageWidthPt,
        double pageHeightPt)
    {
        if (_doc.Page.PageBorder is not { } border)
            return [];

        var widthPt = Math.Max(0.5 / PxPerPoint, border.WidthPt);
        var dash = border.LineStyle switch
        {
            BorderLineStyle.Dotted => new Free.Shared.Pdf.PdfDashPattern([widthPt, 2 * widthPt]),
            BorderLineStyle.Dashed => new Free.Shared.Pdf.PdfDashPattern([3 * widthPt, 2 * widthPt]),
            _ => null,
        };

        double x;
        double y;
        double width;
        double height;
        if (border.OffsetFrom == PageBorderOffsetFrom.Text)
        {
            var frame = PageBorderTextFramePlanner.Build(
                _doc.Page,
                border,
                pageWidthPt,
                pageHeightPt,
                unitsPerPoint: 1,
                strokeRegistration: widthPt / 2,
                _doc.PageBordersDoNotSurroundHeader,
                _doc.PageBordersDoNotSurroundFooter);
            x = frame.X;
            y = pageHeightPt - frame.Y - frame.Height;
            width = frame.Width;
            height = frame.Height;
        }
        else
        {
            var insetPt = Math.Min(
                Math.Max(0, border.SpacePt),
                Math.Min(pageWidthPt, pageHeightPt) / 4);
            var compositorRegistrationPt = border.LineStyle == BorderLineStyle.Wave
                ? 0
                : 1.5 / PxPerPoint;
            x = insetPt + compositorRegistrationPt;
            y = insetPt + compositorRegistrationPt;
            width = pageWidthPt - 2 * x;
            height = pageHeightPt - 2 * y;
        }

        if (width <= 0 || height <= 0)
            return [];

        var color = ParseColor(border.ColorHex);
        var artOriginXDip = border.OffsetFrom == PageBorderOffsetFrom.Text ? x * PxPerPoint : 0;
        var artOriginTopDip = border.OffsetFrom == PageBorderOffsetFrom.Text
            ? (pageHeightPt - y - height) * PxPerPoint
            : 0;
        var artFrameWidthDip = border.OffsetFrom == PageBorderOffsetFrom.Text
            ? width * PxPerPoint
            : pageWidthPt * PxPerPoint;
        var artFrameHeightDip = border.OffsetFrom == PageBorderOffsetFrom.Text
            ? height * PxPerPoint
            : pageHeightPt * PxPerPoint;
        var artInsetDip = border.OffsetFrom == PageBorderOffsetFrom.Text
            ? 0
            : Math.Min(Math.Max(0, border.SpacePt * PxPerPoint), Math.Min(artFrameWidthDip, artFrameHeightDip) / 4);
        if (PageBorderArtVisualPlanner.TryBuildFramePlan(
                border.ArtId,
                border.WidthPt,
                artFrameWidthDip,
                artFrameHeightDip,
                artInsetDip,
                out var artPlan))
        {
            return BuildPdfPageBorderArtOps(artPlan, artOriginXDip, artOriginTopDip, pageHeightPt);
        }

        if (border.LineStyle == BorderLineStyle.Wave)
        {
            var opacity = PageBorderWaveVisualPlanner.StrokeOpacity;
            var waveColor = new Free.Shared.Pdf.PdfColor(
                CompositeWaveChannel(color.R, opacity),
                CompositeWaveChannel(color.G, opacity),
                CompositeWaveChannel(color.B, opacity));
            var originXDip = border.OffsetFrom == PageBorderOffsetFrom.Text ? x * PxPerPoint : 0;
            var originTopDip = border.OffsetFrom == PageBorderOffsetFrom.Text
                ? (pageHeightPt - y - height) * PxPerPoint
                : 0;
            var frameWidthDip = border.OffsetFrom == PageBorderOffsetFrom.Text
                ? width * PxPerPoint
                : pageWidthPt * PxPerPoint;
            var frameHeightDip = border.OffsetFrom == PageBorderOffsetFrom.Text
                ? height * PxPerPoint
                : pageHeightPt * PxPerPoint;
            var edgeInsetDip = border.OffsetFrom == PageBorderOffsetFrom.Text ? 0 : x * PxPerPoint;
            return PageBorderWaveVisualPlanner.BuildFrame(frameWidthDip, frameHeightDip, edgeInsetDip)
                .Select(segment => new Free.Shared.Pdf.PdfLine(
                    (originXDip + segment.X1Dip) / PxPerPoint,
                    pageHeightPt - (originTopDip + segment.Y1Dip) / PxPerPoint,
                    (originXDip + segment.X2Dip) / PxPerPoint,
                    pageHeightPt - (originTopDip + segment.Y2Dip) / PxPerPoint,
                    waveColor,
                    PageBorderWaveVisualPlanner.StrokeWidthDip / PxPerPoint))
                .ToList();
        }

        var ops = new List<Free.Shared.Pdf.PdfDrawOp>
        {
            new Free.Shared.Pdf.PdfStrokeRect(x, y, width, height, color, widthPt, dash),
        };
        if (border.LineStyle == BorderLineStyle.Double)
        {
            var innerInsetPt = widthPt + 1.5 / PxPerPoint;
            var innerWidth = width - 2 * innerInsetPt;
            var innerHeight = height - 2 * innerInsetPt;
            if (innerWidth > 0 && innerHeight > 0)
            {
                ops.Add(new Free.Shared.Pdf.PdfStrokeRect(
                    x + innerInsetPt,
                    y + innerInsetPt,
                    innerWidth,
                    innerHeight,
                    color,
                    widthPt));
            }
        }

        return ops;

        static byte CompositeWaveChannel(byte channel, double opacity) =>
            (byte)Math.Round(255 + (channel - 255) * opacity);
    }

    private static IReadOnlyList<PdfDrawOp> BuildPdfPageBorderArtOps(
        PageBorderArtFramePlan plan,
        double originXDip,
        double originTopDip,
        double pageHeightPt)
    {
        var ops = new List<PdfDrawOp>(
            plan.Fills.Count + plan.Polygons.Count + plan.Lines.Count + plan.CubicFigures.Count);

        PdfColor Color(PageBorderArtColor color) => new(color.Red, color.Green, color.Blue);
        PdfPathPoint Point(PageBorderArtPoint point) => new(
            (originXDip + point.XDip) / PxPerPoint,
            pageHeightPt - (originTopDip + point.YDip) / PxPerPoint);

        foreach (var fill in plan.Fills)
        {
            // PDF rectangle fills are vector primitives and retain the planner's antialiased edges.
            ops.Add(new PdfFillRect(
                (originXDip + fill.Xdip) / PxPerPoint,
                pageHeightPt - (originTopDip + fill.Ydip + fill.HeightDip) / PxPerPoint,
                fill.WidthDip / PxPerPoint,
                fill.HeightDip / PxPerPoint,
                new PdfColor(fill.Red, fill.Green, fill.Blue)));
        }

        foreach (var polygon in plan.Polygons)
        {
            var points = polygon.Points.Select(Point).ToArray();
            if (points.Length == 0)
                continue;

            ops.Add(new PdfPath(
                [new PdfPathContour(
                    points[0],
                    points.Skip(1).Select(PdfPathSegment.LineTo).ToArray(),
                    true)],
                new PdfColor(polygon.Red, polygon.Green, polygon.Blue),
                null,
                0));
        }

        foreach (var line in plan.Lines)
        {
            ops.Add(new PdfLine(
                (originXDip + line.Segment.X1Dip) / PxPerPoint,
                pageHeightPt - (originTopDip + line.Segment.Y1Dip) / PxPerPoint,
                (originXDip + line.Segment.X2Dip) / PxPerPoint,
                pageHeightPt - (originTopDip + line.Segment.Y2Dip) / PxPerPoint,
                Color(line.Color),
                line.WidthDip / PxPerPoint));
        }

        foreach (var figure in plan.CubicFigures)
        {
            ops.Add(new PdfPath(
                [new PdfPathContour(
                    Point(figure.Start),
                    figure.Segments
                        .Select(segment => PdfPathSegment.BezierTo(
                            Point(segment.Control1),
                            Point(segment.Control2),
                            Point(segment.End)))
                        .ToArray(),
                    figure.IsClosed)],
                figure.Fill is { } fill ? Color(fill) : null,
                figure.Stroke is { } stroke ? Color(stroke) : null,
                figure.StrokeWidthDip / PxPerPoint));
        }

        return ops;
    }

    private IReadOnlyDictionary<int, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>> BuildPdfLineNumberOps(
        double pageHeightPt)
    {
        var byPage = new Dictionary<int, List<Free.Shared.Pdf.PdfDrawOp>>();
        var fontSizePt = LineNumberFormatting.FontSizePt ?? 8;
        var color = ParseColor(LineNumberFormatting.ColorHex);
        foreach (var item in BuildLineNumberRenderItems())
        {
            var number = item.Number.ToString(CultureInfo.InvariantCulture);
            var formatted = Build(number, LineNumberFormatting);
            var xDip = item.GutterRight - formatted.WidthIncludingTrailingWhitespace;
            var yDip = item.Y + Math.Max(0, (item.LineHeight - formatted.Height) / 2);
            var pageTopDip = _surfacePlan.PageTopDip(item.PageIndex);
            var xPt = (xDip - _pageLeft) / PxPerPoint;
            var yPt = pageHeightPt - ((yDip - pageTopDip) / PxPerPoint + fontSizePt);
            if (!byPage.TryGetValue(item.PageIndex, out var ops))
            {
                ops = [];
                byPage[item.PageIndex] = ops;
            }

            ops.Add(new Free.Shared.Pdf.PdfText(
                xPt,
                yPt,
                fontSizePt,
                Free.Shared.Pdf.PdfFontFace.Regular,
                color,
                number));
        }

        return byPage.ToDictionary(
            pair => pair.Key,
            pair => (IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>)pair.Value);
    }

    private IReadOnlyDictionary<int, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>> BuildPdfColumnRuleOps(
        double pageHeightPt)
    {
        if (_viewMode != DocumentViewMode.PrintLayout
            || _colCount <= 1
            || !_colLineBetween)
        {
            return new Dictionary<int, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>>();
        }

        var byPage = new Dictionary<int, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>>();
        var yBottom = _marginBottomDip / PxPerPoint;
        var yTop = pageHeightPt - _marginTopDip / PxPerPoint;
        for (var pageIndex = 0; pageIndex < _pageCount; pageIndex++)
        {
            var ops = new List<Free.Shared.Pdf.PdfDrawOp>(_colCount - 1);
            for (var columnIndex = 0; columnIndex < _colCount - 1; columnIndex++)
            {
                var gapCenterDip = _contentLeft
                    + (columnIndex + 1) * (_colWidth + _colGap)
                    - _colGap / 2;
                var pixelCenteredDip = Math.Floor(gapCenterDip) - 0.5;
                var x = (pixelCenteredDip - _pageLeft) / PxPerPoint;
                ops.Add(new Free.Shared.Pdf.PdfLine(
                    x,
                    yBottom,
                    x,
                    yTop,
                    Free.Shared.Pdf.PdfColor.Black,
                    1 / PxPerPoint));
            }

            byPage[pageIndex] = ops;
        }

        return byPage;
    }

    private IReadOnlyDictionary<int, IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>> BuildPdfParagraphDecorationOps(
        double pageHeightPt)
    {
        var byPage = new Dictionary<int, List<Free.Shared.Pdf.PdfDrawOp>>();
        foreach (var (rect, shadingHex, border) in _paragraphDecorations)
        {
            var pageIndex = PageIndexFromPageSpaceY(rect.Top + 0.01);
            if (pageIndex < 0)
                continue;

            var pageTopDip = _surfacePlan.PageTopDip(pageIndex);
            var pageBottomDip = pageTopDip + _pageHeightPx;
            var clipped = rect.Intersect(new Rect(_pageLeft, pageTopDip, _pageWidth, _pageHeightPx));
            if (clipped.Width <= 0 || clipped.Height <= 0)
                continue;

            if (!byPage.TryGetValue(pageIndex, out var ops))
            {
                ops = [];
                byPage[pageIndex] = ops;
            }

            var x = (clipped.Left - _pageLeft) / PxPerPoint;
            var y = pageHeightPt - (clipped.Bottom - pageTopDip) / PxPerPoint;
            var width = clipped.Width / PxPerPoint;
            var height = clipped.Height / PxPerPoint;
            if (!string.IsNullOrWhiteSpace(shadingHex))
            {
                ops.Add(new Free.Shared.Pdf.PdfFillRect(
                    x,
                    y,
                    width,
                    height,
                    ParseColor(shadingHex)));
            }

            if (border is null)
                continue;

            var contours = new List<Free.Shared.Pdf.PdfPathContour>();

            void AddEdge(double x1, double y1, double x2, double y2) =>
                contours.Add(new Free.Shared.Pdf.PdfPathContour(
                    new Free.Shared.Pdf.PdfPathPoint(x1, y1),
                    [Free.Shared.Pdf.PdfPathSegment.LineTo(new Free.Shared.Pdf.PdfPathPoint(x2, y2))],
                    Closed: false));

            var left = x;
            var right = x + width;
            var bottom = y;
            var top = y + height;
            if (border.Top
                && !border.BottomOnly
                && rect.Top >= pageTopDip - 0.01
                && rect.Top <= pageBottomDip + 0.01)
                AddEdge(left, top, right, top);
            if ((border.Bottom || border.BottomOnly)
                && rect.Bottom >= pageTopDip - 0.01
                && rect.Bottom <= pageBottomDip + 0.01)
            {
                AddEdge(left, bottom, right, bottom);
            }
            if (border.Left && !border.BottomOnly)
                AddEdge(left, bottom, left, top);
            if (border.Right && !border.BottomOnly)
                AddEdge(right, bottom, right, top);
            if (contours.Count == 0)
                continue;

            var widthPt = Math.Max(0.5 / PxPerPoint, border.WidthPt);
            var dash = border.LineStyle switch
            {
                BorderLineStyle.Dashed => new Free.Shared.Pdf.PdfDashPattern([4 * widthPt, 3 * widthPt]),
                BorderLineStyle.Dotted => new Free.Shared.Pdf.PdfDashPattern([widthPt, 2 * widthPt]),
                _ => null,
            };
            ops.Add(new Free.Shared.Pdf.PdfPath(
                contours,
                FillColor: null,
                StrokeColor: ParseColor(border.ColorHex),
                StrokeWidth: widthPt,
                StrokeDash: dash));
        }

        return byPage.ToDictionary(
            pair => pair.Key,
            pair => (IReadOnlyList<Free.Shared.Pdf.PdfDrawOp>)pair.Value);
    }

    private IReadOnlyList<Free.Shared.Pdf.PdfDrawOp> BuildPdfWatermarkOps(
        double pageWidthPt,
        double pageHeightPt)
    {
        if (_doc.Page.EffectiveWatermark is not { } watermark)
            return [];

        var pageWidthDip = pageWidthPt * PxPerPoint;
        var pageHeightDip = pageHeightPt * PxPerPoint;
        if (watermark.IsPicture)
        {
            using var bitmap = SKBitmap.Decode(watermark.ImageBytes!);
            if (bitmap is null || bitmap.Width <= 0 || bitmap.Height <= 0)
                return [];

            var plan = WatermarkVisualPlanner.BuildPictureLayout(
                watermark,
                pageWidthDip,
                pageHeightDip,
                bitmap.Width,
                bitmap.Height);
            if (plan is null)
                return [];

            using var skiaImage = SKImage.FromBitmap(bitmap);
            using var png = skiaImage.Encode(SKEncodedImageFormat.Png, 100);
            var pdfImage = new Free.Shared.Pdf.PdfImage(
                plan.XDip / PxPerPoint,
                pageHeightPt - (plan.YDip + plan.HeightDip) / PxPerPoint,
                plan.WidthDip / PxPerPoint,
                plan.HeightDip / PxPerPoint,
                png.ToArray(),
                "image/png",
                RotationDegrees: plan.RotationDegrees,
                Opacity: plan.Opacity);
            return
            [
                new Free.Shared.Pdf.PdfClipGroup(
                    0,
                    0,
                    pageWidthPt,
                    pageHeightPt,
                    [pdfImage]),
            ];
        }

        if (string.IsNullOrWhiteSpace(watermark.Text))
            return [];

        var textPlan = WatermarkVisualPlanner.BuildTextLayout(watermark, pageWidthDip, pageHeightDip);
        if (textPlan is null)
            return [];

        var color = TryParseAvaloniaColor(watermark.FontColorHex, out var parsedColor)
            ? parsedColor
            : Color.FromRgb(0x80, 0x80, 0x80);
        var brush = new SolidColorBrush(color);
        var typeface = new Typeface(
            watermark.FontFamily is { Length: > 0 } family ? new FontFamily(family) : FontFamily.Default,
            FontStyle.Normal,
            FontWeight.Normal);
        var unitText = new FormattedText(
            watermark.Text,
            CultureInfo.InvariantCulture,
            FlowDirection.LeftToRight,
            typeface,
            1,
            brush);
        var fontSizeDip = WatermarkVisualPlanner.ResolveTextPathFontSize(textPlan, unitText.Width);
        var text = new FormattedText(
            watermark.Text,
            CultureInfo.InvariantCulture,
            FlowDirection.LeftToRight,
            typeface,
            fontSizeDip,
            brush);
        var leftDip = textPlan.CenterXDip - text.Width / 2;
        var topDip = textPlan.CenterYDip - text.Height / 2;
        Free.Shared.Pdf.PdfDrawOp textOp = new Free.Shared.Pdf.PdfText(
            leftDip / PxPerPoint,
            pageHeightPt - (topDip + fontSizeDip) / PxPerPoint,
            fontSizeDip / PxPerPoint,
            Free.Shared.Pdf.PdfFontFace.Regular,
            new Free.Shared.Pdf.PdfColor(color.R, color.G, color.B),
            watermark.Text);

        var opacity = Math.Clamp(watermark.Opacity, 0, 1);
        if (opacity < 1)
            textOp = new Free.Shared.Pdf.PdfOpacityGroup(opacity, [textOp]);
        if (Math.Abs(textPlan.RotationDegrees) > 0.01)
        {
            textOp = new Free.Shared.Pdf.PdfRotationGroup(
                textPlan.CenterXDip / PxPerPoint,
                pageHeightPt - textPlan.CenterYDip / PxPerPoint,
                textPlan.RotationDegrees,
                [textOp]);
        }

        return
        [
            new Free.Shared.Pdf.PdfClipGroup(
                0,
                0,
                pageWidthPt,
                pageHeightPt,
                [textOp]),
        ];
    }

    private static string FormatKey(RunFormatting fmt)
    {
        var border = fmt.CharacterBorder;
        var borderKey = border is null
            ? string.Empty
            : $"{border.ColorHex}|{border.WidthPt}|{border.BottomOnly}|{border.LineStyle}|" +
              $"{border.Top}|{border.Left}|{border.Bottom}|{border.Right}";
        return $"{fmt.FontFamily}|{fmt.Bold}|{fmt.Italic}|{fmt.FontSizePt}|{fmt.VerticalAlign}|{fmt.PositionPt}|{fmt.ColorHex}|{fmt.HighlightColorHex}|" +
               $"{fmt.CharacterShadingHex}|{fmt.CharacterShadingPattern}|{fmt.Underline}|" +
               $"{fmt.Strikethrough}|{fmt.DoubleStrikethrough}|{borderKey}";
    }

    private static DocumentFloatingObjectSnapshot BuildInlineDrawingSnapshot(
        DocumentFloatingObjectKind kind,
        Rect rect,
        int blockIndex,
        int runIndex,
        double rotationAngle,
        bool flipH,
        bool flipV) =>
        new(
            kind,
            blockIndex,
            runIndex,
            ToPlannerRect(rect),
            BehindText: false,
            ZOrderIndex: 0,
            ImageWrapping.Inline,
            rotationAngle,
            flipH,
            flipV);

    private PdfDrawOp? BuildPdfImage(
        Rect sourceRect,
        InlineImage image,
        AvaloniaRenderedImage? rendered,
        double pageTopDip,
        double pageHeightPt)
    {
        var displayBytes = image.DisplayBytes;
        if (rendered is null || displayBytes.Length == 0)
            return null;

        var contentType = image.Format switch
        {
            ImageFormat.Png => "image/png",
            ImageFormat.Jpeg => "image/jpeg",
            _ => null,
        };

        byte[] imageBytes;
        double opacity;
        if (contentType is not null && !RequiresRasterImageBake(image))
        {
            // The shared operation can preserve PNG/JPEG bytes, source crop, source alpha, and
            // the model transparency as a PDF graphics-state opacity without touching the live
            // cache or changing the document's media part.
            imageBytes = displayBytes;
            opacity = 1.0 - Math.Clamp(image.TransparencyPct / 100.0, 0.0, 1.0);
        }
        else
        {
            // Avalonia's cached bitmap is the truthful source for corrections, recolor, artistic
            // effects, and formats the portable PDF vocabulary cannot embed directly. Encoding it
            // as PNG retains the already-applied alpha and pixel effects; crop/rotation still use
            // the shared PdfImage geometry below.
            using var stream = new MemoryStream();
            rendered.Bitmap.Save(stream);
            imageBytes = stream.ToArray();
            contentType = "image/png";
            opacity = 1.0;
        }

        var yPt = pageHeightPt - ((sourceRect.Bottom - pageTopDip) / PxPerPoint);
        var xPt = (sourceRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var reflection = PictureEffectVisualPlanner.BuildReflectionPlan(image);
        var needsTransformGroup = image.FlipH || image.FlipV || image.HasBorder || reflection is not null;
        var pdfImage = new PdfImage(
            xPt,
            yPt,
            sourceRect.Width / PxPerPoint,
            sourceRect.Height / PxPerPoint,
            imageBytes,
            contentType,
            RotationDegrees: needsTransformGroup ? 0 : image.RotationAngle,
            Opacity: opacity,
            SourceCrop: new PdfImageSourceCrop(
                image.CropLeft,
                image.CropTop,
                image.CropRight,
                image.CropBottom));

        if (!needsTransformGroup)
            return pdfImage;

        var imageOps = new List<PdfDrawOp>();
        if (reflection is not null)
        {
            imageOps.Add(new PdfEffectGroup(
                PdfEffectKind.Reflection,
                pdfImage.X,
                pdfImage.Y,
                pdfImage.Width,
                pdfImage.Height,
                new PdfEffectParameters(
                    Color: null,
                    Opacity: reflection.Opacity,
                    Radius: 0,
                    ReflectionGap: reflection.DistanceDip / PxPerPoint,
                    ReflectionEndOpacity: reflection.EndOpacity,
                    ReflectionStartPosition: reflection.StartPosition,
                    ReflectionEndPosition: reflection.EndPosition),
                [pdfImage]));
        }

        imageOps.Add(pdfImage);
        if (image.HasBorder)
        {
            imageOps.Add(new PdfStrokeRect(
                pdfImage.X,
                pdfImage.Y,
                pdfImage.Width,
                pdfImage.Height,
                ParseColor(image.BorderColorHex),
                Math.Max(image.BorderWidthPt, 0.75),
                BuildPdfPictureDash(image.BorderDash)));
        }

        return new PdfRotationGroup(
            xPt + pdfImage.Width / 2.0,
            yPt + pdfImage.Height / 2.0,
            image.RotationAngle,
            imageOps,
            image.FlipH,
            image.FlipV);
    }

    private static PdfDashPattern? BuildPdfPictureDash(string? dashStyle) =>
        dashStyle?.Trim().ToLowerInvariant() switch
        {
            "dash" or "sysdash" => new PdfDashPattern([4, 3]),
            "dot" or "sysdot" => new PdfDashPattern([1, 2]),
            "dashdot" or "sysdashdot" => new PdfDashPattern([4, 2, 1, 2]),
            "lgdash" => new PdfDashPattern([8, 3]),
            "lgdashdot" => new PdfDashPattern([8, 2, 1, 2]),
            "lgdashdotdot" => new PdfDashPattern([8, 2, 1, 2, 1, 2]),
            _ => null,
        };

    private IReadOnlyList<PdfDrawOp> BuildPdfGroupOps(
        FreeW.Core.Model.DrawingGroup group,
        DocumentFloatingObjectSnapshot snapshot,
        double pageTopDip,
        double pageHeightPt)
    {
        var plan = DrawingObjectVisualPlanner.BuildVisualPlan(group, snapshot);
        var childOps = new List<PdfDrawOp>();

        // The shared visual plan already resolves each child to page-space geometry in group-list
        // order. Keep that order as the PDF z-order, and only add transforms/clipping as explicit
        // shared operations so backends cannot accidentally flatten nested groups.
        foreach (var childPlan in plan.GroupChildren)
        {
            if (childPlan.ChildIndex < 0 || childPlan.ChildIndex >= group.Children.Count)
                continue;

            var child = group.Children[childPlan.ChildIndex];
            var childSnapshot = new DocumentFloatingObjectSnapshot(
                child switch
                {
                    InlineImage => DocumentFloatingObjectKind.Image,
                    Shape => DocumentFloatingObjectKind.Shape,
                    Chart => DocumentFloatingObjectKind.Chart,
                    WordArt => DocumentFloatingObjectKind.WordArt,
                    SmartArt => DocumentFloatingObjectKind.SmartArt,
                    FreeW.Core.Model.DrawingGroup => DocumentFloatingObjectKind.Group,
                    _ => DocumentFloatingObjectKind.Shape,
                },
                snapshot.BlockIndex,
                snapshot.RunIndex,
                childPlan.Visual.Rect,
                snapshot.BehindText,
                snapshot.ZOrderIndex,
                snapshot.Wrapping,
                childPlan.Visual.RotationAngle,
                childPlan.Visual.FlipH,
                childPlan.Visual.FlipV,
                snapshot.WrapTextSide);
            var childRect = ToAvaloniaRect(childPlan.Visual.Rect);

            switch (child)
            {
                case Shape shape when childPlan.Visual.Kind == DrawingObjectVisualKind.Shape:
                    childOps.AddRange(BuildPdfShapeOps(
                        childPlan.Visual,
                        childSnapshot,
                        childRect,
                        pageTopDip,
                        pageHeightPt));
                    break;

                case InlineImage image when childPlan.Visual.Kind == DrawingObjectVisualKind.Image:
                    if (BuildPdfImage(childRect, image, DecodeRenderedImage(image), pageTopDip, pageHeightPt)
                        is { } imageOp)
                    {
                        childOps.Add(imageOp);
                    }
                    break;

                case Chart chart when childPlan.Visual.Kind == DrawingObjectVisualKind.Chart:
                    childOps.AddRange(BuildPdfChartOps(
                        chart,
                        childPlan.Visual,
                        childRect,
                        pageTopDip,
                        pageHeightPt));
                    break;

                case WordArt when childPlan.Visual.Kind == DrawingObjectVisualKind.WordArt:
                    childOps.AddRange(BuildPdfWordArtOps(
                        childPlan.Visual,
                        childRect,
                        pageTopDip,
                        pageHeightPt));
                    break;

                case SmartArt when childPlan.Visual.Kind == DrawingObjectVisualKind.SmartArt:
                    childOps.AddRange(BuildPdfSmartArtOps(
                        childPlan.Visual,
                        childRect,
                        pageTopDip,
                        pageHeightPt));
                    break;

                case FreeW.Core.Model.DrawingGroup nestedGroup
                    when childPlan.Visual.Kind == DrawingObjectVisualKind.Group:
                    childOps.AddRange(BuildPdfGroupOps(
                        nestedGroup,
                        childSnapshot,
                        pageTopDip,
                        pageHeightPt));
                    break;
            }
        }

        if (childOps.Count == 0)
            return [];

        var groupRect = ToAvaloniaRect(plan.Rect);
        var xPt = (groupRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var yPt = pageHeightPt - ((groupRect.Bottom - pageTopDip) / PxPerPoint);
        var widthPt = groupRect.Width / PxPerPoint;
        var heightPt = groupRect.Height / PxPerPoint;
        var boundedOps = new PdfClipGroup(xPt, yPt, widthPt, heightPt, childOps);

        if (Math.Abs(plan.RotationAngle) > 0.001 || plan.FlipH || plan.FlipV)
        {
            return [new PdfRotationGroup(
                xPt + widthPt / 2,
                yPt + heightPt / 2,
                plan.RotationAngle,
                [boundedOps],
                plan.FlipH,
                plan.FlipV)];
        }

        return [boundedOps];
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfChartOps(
        Chart chart,
        DrawingObjectVisualPlan plan,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        var scene = ChartSmartArtVisualPlanner.BuildChartScene(chart, sourceRect.Width, sourceRect.Height);
        var ops = new List<PdfDrawOp>();
        var frame = PdfRect(sourceRect, 0, 0, sourceRect.Width, sourceRect.Height, pageTopDip, pageHeightPt);
        ops.Add(new PdfFillRect(frame.X, frame.Y, frame.Width, frame.Height, ParseColor("#F9F9F9")));
        ops.Add(new PdfStrokeRect(frame.X, frame.Y, frame.Width, frame.Height, ParseColor("#BBBBBB"), 1 / PxPerPoint));

        PdfPoint Point(double xDip, double yDip) => new(
            (sourceRect.Left + xDip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
            pageHeightPt - ((sourceRect.Top + yDip - pageTopDip) / PxPerPoint));
        PdfRectValue Rect(ChartSceneRect rect) => PdfRect(
            sourceRect,
            rect.X,
            rect.Y,
            rect.Width,
            rect.Height,
            pageTopDip,
            pageHeightPt);

        if (scene.PlotFillHex is not null)
        {
            var plot = Rect(scene.PlotBounds);
            ops.Add(new PdfFillRect(plot.X, plot.Y, plot.Width, plot.Height, ParseColor(scene.PlotFillHex)));
        }

        foreach (var line in scene.GridLines.Concat(scene.AxisLines))
        {
            var start = Point(line.X1, line.Y1);
            var end = Point(line.X2, line.Y2);
            ops.Add(new PdfLine(start.X, start.Y, end.X, end.Y, ParseColor(line.StrokeHex), line.StrokeWidth / PxPerPoint));
        }

        foreach (var bar in scene.Bars)
        {
            var barRect = Rect(bar.Bounds);
            var barOp = new PdfFillRect(barRect.X, barRect.Y, barRect.Width, barRect.Height, ParseColor(bar.FillHex));
            ops.Add(bar.FillOpacity is > 0 and < 1
                ? new PdfOpacityGroup(bar.FillOpacity, [barOp])
                : barOp);
        }

        foreach (var series in scene.LineSeries)
        {
            if (series.Points.Count < 2)
                continue;

            var points = series.Points.Select(point => Point(point.X, point.Y)).ToList();
            if (series.FillArea)
            {
                var areaStart = Point(series.Points[0].X, series.AreaBaselineY);
                var areaPoints = new List<PdfPathPoint> { new(areaStart.X, areaStart.Y) };
                areaPoints.AddRange(points.Select(point => new PdfPathPoint(point.X, point.Y)));
                var areaEnd = Point(series.Points[^1].X, series.AreaBaselineY);
                areaPoints.Add(new PdfPathPoint(areaEnd.X, areaEnd.Y));
                var area = new PdfPath(
                    [new PdfPathContour(areaPoints[0], areaPoints.Skip(1).Select(PdfPathSegment.LineTo).ToArray(), true)],
                    ParseColor(series.StrokeHex),
                    null,
                    0);
                ops.Add(series.AreaOpacity is > 0 and < 1
                    ? new PdfOpacityGroup(series.AreaOpacity, [area])
                    : area);
            }

            for (var index = 1; index < points.Count; index++)
            {
                ops.Add(new PdfLine(
                    points[index - 1].X,
                    points[index - 1].Y,
                    points[index].X,
                    points[index].Y,
                    ParseColor(series.StrokeHex),
                    series.StrokeWidth / PxPerPoint));
            }
        }

        foreach (var marker in scene.Markers)
            AddPdfChartMarker(ops, marker, Point, pageTopDip);

        foreach (var slice in scene.Slices)
            AddPdfChartSlice(ops, slice, Point);

        foreach (var text in scene.Texts)
            AddPdfSceneText(ops, text, sourceRect, pageTopDip, pageHeightPt);

        for (var index = 0; index < scene.Legend.Count; index++)
        {
            var entry = scene.Legend[index];
            var swatch = Rect(new ChartSceneRect(entry.SwatchX, entry.SwatchY, entry.SwatchSize, entry.SwatchSize));
            ops.Add(new PdfFillRect(
                swatch.X,
                swatch.Y,
                swatch.Width,
                swatch.Height,
                ParseColor(scene.PaletteHex[index % Math.Max(1, scene.PaletteHex.Count)])));
            AddPdfSceneText(ops, new ChartSceneText(
                entry.Text,
                entry.TextX,
                entry.TextY,
                ChartSceneTextAnchor.TopLeft,
                ChartSceneTextKind.Legend,
                "#000000",
                9), sourceRect, pageTopDip, pageHeightPt);
        }

        return WrapPdfVisualOps(ops, plan, frame);
    }

    private void AddPdfChartMarker(
        List<PdfDrawOp> ops,
        ChartSceneMarker marker,
        Func<double, double, PdfPoint> point,
        double pageTopDip)
    {
        var center = point(marker.CenterX, marker.CenterY);
        var radius = marker.Radius / PxPerPoint;
        var color = ParseColor(marker.FillHex);
        PdfColor? stroke = marker.StrokeHex is null ? null : ParseColor(marker.StrokeHex);
        var strokeWidth = Math.Max(0.1, marker.StrokeWidth / PxPerPoint);
        switch (marker.Kind)
        {
            case ChartSceneMarkerKind.Circle:
                ops.Add(new PdfFillEllipse(center.X - radius, center.Y - radius, radius * 2, radius * 2, color));
                break;
            case ChartSceneMarkerKind.Square:
                ops.Add(new PdfFillRect(center.X - radius, center.Y - radius, radius * 2, radius * 2, color));
                break;
            case ChartSceneMarkerKind.Cross:
                ops.Add(new PdfLine(center.X - radius, center.Y - radius, center.X + radius, center.Y + radius, color, strokeWidth));
                ops.Add(new PdfLine(center.X + radius, center.Y - radius, center.X - radius, center.Y + radius, color, strokeWidth));
                break;
            case ChartSceneMarkerKind.Diamond:
            case ChartSceneMarkerKind.Triangle:
            {
                PdfPathPoint[] points = marker.Kind == ChartSceneMarkerKind.Diamond
                    ? [new PdfPathPoint(center.X, center.Y + radius), new(center.X + radius, center.Y),
                        new(center.X, center.Y - radius), new(center.X - radius, center.Y)]
                    : [new PdfPathPoint(center.X, center.Y + radius), new(center.X + radius, center.Y - radius),
                        new(center.X - radius, center.Y - radius)];
                ops.Add(new PdfPath(
                    [new PdfPathContour(points[0], points.Skip(1).Select(PdfPathSegment.LineTo).ToArray(), true)],
                    color,
                    stroke,
                    strokeWidth));
                break;
            }
        }
    }

    private void AddPdfChartSlice(
        List<PdfDrawOp> ops,
        ChartSceneSlice slice,
        Func<double, double, PdfPoint> point)
    {
        var center = point(slice.CenterX, slice.CenterY);
        var outerRadius = slice.OuterRadius / PxPerPoint;
        var innerRadius = slice.InnerRadius / PxPerPoint;
        var steps = Math.Max(8, (int)Math.Ceiling(Math.Abs(slice.SweepAngleRadians) * 12));
        var points = new List<PdfPathPoint>(steps * 2 + 2);
        for (var index = 0; index <= steps; index++)
        {
            var angle = slice.StartAngleRadians + slice.SweepAngleRadians * index / steps;
            points.Add(new PdfPathPoint(
                center.X + outerRadius * Math.Cos(angle),
                center.Y - outerRadius * Math.Sin(angle)));
        }

        if (innerRadius > 0)
        {
            for (var index = steps; index >= 0; index--)
            {
                var angle = slice.StartAngleRadians + slice.SweepAngleRadians * index / steps;
                points.Add(new PdfPathPoint(
                    center.X + innerRadius * Math.Cos(angle),
                    center.Y - innerRadius * Math.Sin(angle)));
            }
        }
        else
        {
            points.Add(new PdfPathPoint(center.X, center.Y));
        }

        ops.Add(new PdfPath(
            [new PdfPathContour(points[0], points.Skip(1).Select(PdfPathSegment.LineTo).ToArray(), true)],
            ParseColor(slice.FillHex),
            ParseColor(slice.StrokeHex),
            Math.Max(0.1, slice.StrokeWidth / PxPerPoint)));
    }

    private void AddPdfSceneText(
        List<PdfDrawOp> ops,
        ChartSceneText text,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        if (string.IsNullOrEmpty(text.Text))
            return;

        var fontSizePt = Math.Max(1, text.FontSize / PxPerPoint);
        var estimatedWidthDip = text.Text.Length * text.FontSize * 0.5;
        var xDip = text.Anchor switch
        {
            ChartSceneTextAnchor.TopCenter or ChartSceneTextAnchor.Center => text.X - estimatedWidthDip / 2,
            ChartSceneTextAnchor.CenterRight => text.X - estimatedWidthDip,
            _ => text.X,
        };
        var baselineOffsetDip = text.Anchor is ChartSceneTextAnchor.Center or ChartSceneTextAnchor.CenterRight
            ? text.FontSize * 0.35
            : text.FontSize;
        var xPt = (sourceRect.Left + xDip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var yPt = pageHeightPt - ((sourceRect.Top + text.Y + baselineOffsetDip - pageTopDip) / PxPerPoint);
        var textOp = new PdfText(xPt, yPt, fontSizePt, PdfFontFace.Regular, ParseColor(text.ColorHex), text.Text);
        if (Math.Abs(text.RotationDegrees) > 0.001)
        {
            var centerX = (sourceRect.Left + text.X - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
            var centerY = pageHeightPt - ((sourceRect.Top + text.Y - pageTopDip) / PxPerPoint);
            ops.Add(new PdfRotationGroup(centerX, centerY, text.RotationDegrees, [textOp]));
        }
        else
        {
            ops.Add(textOp);
        }
    }

    private readonly record struct PdfPoint(double X, double Y);

    private readonly record struct PdfRectValue(double X, double Y, double Width, double Height);

    private PdfRectValue PdfRect(
        Rect sourceRect,
        double xDip,
        double yDip,
        double widthDip,
        double heightDip,
        double pageTopDip,
        double pageHeightPt) =>
        new(
            (sourceRect.Left + xDip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
            pageHeightPt - ((sourceRect.Top + yDip + heightDip - pageTopDip) / PxPerPoint),
            widthDip / PxPerPoint,
            heightDip / PxPerPoint);

    private static IReadOnlyList<PdfDrawOp> WrapPdfVisualOps(
        IReadOnlyList<PdfDrawOp> ops,
        DrawingObjectVisualPlan plan,
        PdfRectValue bounds)
    {
        if (ops.Count == 0)
            return [];

        if (Math.Abs(plan.RotationAngle) > 0.001 || plan.FlipH || plan.FlipV)
        {
            return [new PdfRotationGroup(
                bounds.X + bounds.Width / 2,
                bounds.Y + bounds.Height / 2,
                plan.RotationAngle,
                ops,
                plan.FlipH,
                plan.FlipV)];
        }

        return ops;
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfSmartArtOps(
        DrawingObjectVisualPlan plan,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        if (plan.SmartArt is not { } smartArt)
            return [];

        var ops = new List<PdfDrawOp>();
        var frame = PdfRect(sourceRect, 0, 0, sourceRect.Width, sourceRect.Height, pageTopDip, pageHeightPt);
        var isNativePyramid = string.Equals(smartArt.LayoutId, "pyramid1", StringComparison.OrdinalIgnoreCase)
            && smartArt.LayoutGeometry is { Kind: SmartArtLayoutGeometryKind.Pyramid, Nodes.Count: > 0 };
        if (!isNativePyramid)
        {
            ops.Add(new PdfFillRect(frame.X, frame.Y, frame.Width, frame.Height, ParseColor("#F9F9F9")));
            ops.Add(new PdfStrokeRect(frame.X, frame.Y, frame.Width, frame.Height, ParseColor("#BBBBBB"), 1 / PxPerPoint));
            AddPdfTextAt(ops, $"SmartArt ({smartArt.Kind})", 4, 2, 8, true, "#555555", sourceRect, pageTopDip, pageHeightPt, clip: null);
        }

        void AddNode(
            int nodeIndex,
            double xDip,
            double yDip,
            double widthDip,
            double heightDip,
            IReadOnlyList<SmartArtLayoutPoint>? polygon = null)
        {
            if (nodeIndex < 0 || nodeIndex >= smartArt.Nodes.Count)
                return;

            var node = smartArt.Nodes[nodeIndex];
            var nodeRect = PdfRect(sourceRect, xDip, yDip, widthDip, heightDip, pageTopDip, pageHeightPt);
            var fill = ParseColor(node.FillHex);
            var stroke = node.BorderThickness > 0 ? ParseColor(node.BorderHex) : (PdfColor?)null;
            var strokeWidth = Math.Max(0.1, node.BorderThickness / PxPerPoint);
            IReadOnlyList<PdfPathContour> contours;
            if (polygon is { Count: >= 3 })
            {
                var points = polygon.Select(point => new PdfPathPoint(
                    (sourceRect.Left + point.X - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
                    pageHeightPt - ((sourceRect.Top + point.Y - pageTopDip) / PxPerPoint))).ToList();
                contours = [new PdfPathContour(points[0], points.Skip(1).Select(PdfPathSegment.LineTo).ToArray(), true)];
            }
            else
            {
                contours = [BuildPdfRoundedRectangleContour(
                    nodeRect.X,
                    nodeRect.Y,
                    nodeRect.Width,
                    nodeRect.Height)];
            }

            if (node.ShadowOpacity > 0)
            {
                var depth = Math.Clamp(node.ShadowDepth / PxPerPoint, 0, 5 / PxPerPoint);
                var shadowContours = contours.Select(contour => new PdfPathContour(
                    new PdfPathPoint(contour.Start.X + depth, contour.Start.Y - depth),
                    contour.Segments.Select(segment => segment with
                    {
                        End = new PdfPathPoint(segment.End.X + depth, segment.End.Y - depth),
                        Control1 = new PdfPathPoint(segment.Control1.X + depth, segment.Control1.Y - depth),
                        Control2 = new PdfPathPoint(segment.Control2.X + depth, segment.Control2.Y - depth),
                    }).ToArray(),
                    contour.Closed)).ToArray();
                ops.Add(new PdfOpacityGroup(
                    node.ShadowOpacity * 0.24,
                    [new PdfPath(shadowContours, PdfColor.Black, null, 0)]));
            }

            ops.Add(new PdfPath(contours, fill, stroke, strokeWidth));
            AddPdfTextAt(
                ops,
                node.Text,
                xDip + widthDip / 2,
                yDip + heightDip / 2,
                node.FontSizeDip / PxPerPoint,
                false,
                node.TextHex,
                sourceRect,
                pageTopDip,
                pageHeightPt,
                nodeRect,
                node.FontFamilyName);
        }

        void AddConnector(int nodeIndex, double x1Dip, double y1Dip, double x2Dip, double y2Dip, bool arrow)
        {
            if (nodeIndex < 0 || nodeIndex >= smartArt.Nodes.Count)
                return;

            var start = new PdfPoint(
                (sourceRect.Left + x1Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
                pageHeightPt - ((sourceRect.Top + y1Dip - pageTopDip) / PxPerPoint));
            var end = new PdfPoint(
                (sourceRect.Left + x2Dip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
                pageHeightPt - ((sourceRect.Top + y2Dip - pageTopDip) / PxPerPoint));
            var node = smartArt.Nodes[nodeIndex];
            var width = Math.Max(0.1, node.BorderThickness / PxPerPoint);
            var color = ParseColor(node.ConnectorHex);
            ops.Add(new PdfLine(start.X, start.Y, end.X, end.Y, color, width));
            if (arrow)
            {
                var dx = end.X - start.X;
                var dy = end.Y - start.Y;
                var length = Math.Sqrt(dx * dx + dy * dy);
                if (length > 0.001)
                {
                    var ux = dx / length;
                    var uy = dy / length;
                    var px = -uy;
                    var py = ux;
                    const double arrowLength = 6 / 1.3333333333333333;
                    const double arrowWidth = 4 / 1.3333333333333333;
                    ops.Add(new PdfLine(end.X, end.Y, end.X - ux * arrowLength + px * arrowWidth,
                        end.Y - uy * arrowLength + py * arrowWidth, color, width));
                    ops.Add(new PdfLine(end.X, end.Y, end.X - ux * arrowLength - px * arrowWidth,
                        end.Y - uy * arrowLength - py * arrowWidth, color, width));
                }
            }
        }

        if (isNativePyramid)
        {
            var geometry = smartArt.LayoutGeometry!;
            AddPdfSmartArtLayoutGeometry(ops, smartArt, geometry, sourceRect,
                new Rect(0, 22, sourceRect.Width, sourceRect.Height), pageTopDip, pageHeightPt, AddNode, AddConnector);
        }
        else if (smartArt.HierarchyGeometry is { Nodes.Count: > 0 } hierarchy)
        {
            var headerDip = 8 + 6 + 6;
            var target = new Rect(6, headerDip + 6, Math.Max(1, sourceRect.Width - 12), Math.Max(1, sourceRect.Height - headerDip - 12));
            AddPdfSmartArtHierarchy(ops, smartArt, hierarchy, sourceRect, target, pageTopDip, pageHeightPt, AddNode, AddConnector);
        }
        else if (smartArt.LayoutGeometry is { Nodes.Count: > 0 } layout)
        {
            var headerDip = 8 + 6 + 6;
            var target = new Rect(6, headerDip + 6, Math.Max(1, sourceRect.Width - 12), Math.Max(1, sourceRect.Height - headerDip - 12));
            AddPdfSmartArtLayoutGeometry(ops, smartArt, layout, sourceRect, target, pageTopDip, pageHeightPt, AddNode, AddConnector);
        }
        else if (smartArt.Nodes.Count > 0)
        {
            const double nodePad = 6;
            const double nodeHeight = 26;
            var areaTop = 8 + 12;
            var areaHeight = sourceRect.Height - areaTop - nodePad;
            var areaWidth = sourceRect.Width - 2 * nodePad;
            var count = smartArt.Nodes.Count;
            var arrows = smartArt.Kind == SmartArtKind.Process ? count - 1 : 0;
            var arrowWidth = 12.0;
            var boxWidth = Math.Max(24, (areaWidth - arrows * (arrowWidth + 2) - 2 * nodePad) / count);
            var boxY = areaTop + (areaHeight - nodeHeight) / 2;
            var x = nodePad;
            for (var index = 0; index < count; index++)
            {
                AddNode(index, x, boxY, boxWidth, nodeHeight);
                x += boxWidth;
                if (smartArt.Kind == SmartArtKind.Process && index < count - 1)
                {
                    AddConnector(index, x + 2, boxY + nodeHeight / 2, x + 2 + arrowWidth, boxY + nodeHeight / 2, true);
                    x += arrowWidth + 2;
                }
            }
        }

        var wrapped = WrapPdfVisualOps(ops, plan, frame);
        return wrapped;
    }

    private void AddPdfSmartArtLayoutGeometry(
        List<PdfDrawOp> ops,
        SmartArtVisualPlan smartArt,
        SmartArtLayoutGeometryPlan layout,
        Rect sourceRect,
        Rect target,
        double pageTopDip,
        double pageHeightPt,
        Action<int, double, double, double, double, IReadOnlyList<SmartArtLayoutPoint>?> addNode,
        Action<int, double, double, double, double, bool> addConnector)
    {
        var naturalWidth = Math.Max(1, layout.NaturalWidth);
        var naturalHeight = Math.Max(1, layout.NaturalHeight);
        var scale = Math.Min(target.Width / naturalWidth, target.Height / naturalHeight);
        if (!double.IsFinite(scale) || scale <= 0)
            scale = 1;
        var offsetX = target.X + Math.Max(0, (target.Width - naturalWidth * scale) / 2);
        var offsetY = target.Y + Math.Max(0, (target.Height - naturalHeight * scale) / 2);
        double X(double value) => offsetX + value * scale;
        double Y(double value) => offsetY + value * scale;

        foreach (var connector in layout.Connectors)
            addConnector(connector.SourceNodeIndex, X(connector.X1), Y(connector.Y1), X(connector.X2), Y(connector.Y2), connector.Kind == SmartArtLayoutConnectorKind.Arrow);

        foreach (var node in layout.Nodes)
        {
            var polygon = node.HasPolygon
                ? node.PolygonPoints.Select(point => new SmartArtLayoutPoint(X(point.X), Y(point.Y))).ToList()
                : null;
            addNode(node.NodeIndex, X(node.X), Y(node.Y), node.Width * scale, node.Height * scale, polygon);
        }
    }

    private void AddPdfSmartArtHierarchy(
        List<PdfDrawOp> ops,
        SmartArtVisualPlan smartArt,
        SmartArtHierarchyGeometryPlan hierarchy,
        Rect sourceRect,
        Rect target,
        double pageTopDip,
        double pageHeightPt,
        Action<int, double, double, double, double, IReadOnlyList<SmartArtLayoutPoint>?> addNode,
        Action<int, double, double, double, double, bool> addConnector)
    {
        var naturalWidth = Math.Max(1, hierarchy.NaturalWidth);
        var naturalHeight = Math.Max(1, hierarchy.NaturalHeight);
        var scale = Math.Min(target.Width / naturalWidth, target.Height / naturalHeight);
        if (!double.IsFinite(scale) || scale <= 0)
            scale = 1;
        var offsetX = target.X + Math.Max(0, (target.Width - naturalWidth * scale) / 2);
        var offsetY = target.Y + Math.Max(0, (target.Height - naturalHeight * scale) / 2);
        double X(double value) => offsetX + value * scale;
        double Y(double value) => offsetY + value * scale;

        foreach (var connector in hierarchy.Connectors)
        {
            var points = connector.Points.Count > 1
                ? connector.Points
                : [new SmartArtLayoutPoint(connector.X1, connector.Y1), new(connector.X2, connector.Y2)];
            for (var index = 1; index < points.Count; index++)
                addConnector(connector.ParentNodeIndex, X(points[index - 1].X), Y(points[index - 1].Y), X(points[index].X), Y(points[index].Y), false);
        }

        foreach (var node in hierarchy.Nodes)
            addNode(node.NodeIndex, X(node.X), Y(node.Y), node.Width * scale, node.Height * scale, null);
    }

    private void AddPdfTextAt(
        List<PdfDrawOp> ops,
        string text,
        double xDip,
        double yDip,
        double fontSizePt,
        bool bold,
        string colorHex,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt,
        PdfRectValue? clip,
        string? fontFamily = null)
    {
        if (string.IsNullOrEmpty(text))
            return;

        var widthDip = text.Length * fontSizePt * PxPerPoint * 0.5;
        var x = xDip - widthDip / 2;
        var baseline = pageHeightPt - ((sourceRect.Top + yDip + fontSizePt * PxPerPoint - pageTopDip) / PxPerPoint);
        var textOp = new PdfText(
            (sourceRect.Left + x - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
            baseline,
            Math.Max(1, fontSizePt),
            bold ? PdfFontFace.Bold : PdfFontFace.Regular,
            ParseColor(colorHex),
            text,
            fontFamily);
        if (clip is { } bounds)
            ops.Add(new PdfClipGroup(bounds.X, bounds.Y, bounds.Width, bounds.Height, [textOp]));
        else
            ops.Add(textOp);
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfWordArtOps(
        DrawingObjectVisualPlan plan,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        if (plan.WordArt is not { } wordArt || string.IsNullOrEmpty(wordArt.Text))
            return [];

        var frame = PdfRect(sourceRect, 0, 0, sourceRect.Width, sourceRect.Height, pageTopDip, pageHeightPt);
        var ops = new List<PdfDrawOp>();
        var fill = ResolvePdfShapeFillFallback(wordArt.Fill);
        var pattern = BuildPdfShapePattern(wordArt.Fill);
        var gradient = BuildPdfShapeGradient(wordArt.Fill, frame.X, frame.Y, frame.Width, frame.Height);
        if (gradient is not null)
            ops.Add(new PdfFillRectLinearGradient(frame.X, frame.Y, frame.Width, frame.Height, gradient, fill ?? ParseColor("#1F4E79")));
        else if (pattern is not null)
            ops.Add(new PdfFillRectPattern(frame.X, frame.Y, frame.Width, frame.Height, pattern));
        else if (fill is { } solidFill)
            ops.Add(new PdfFillRect(frame.X, frame.Y, frame.Width, frame.Height, solidFill));

        var glyphOps = new List<PdfDrawOp>();

        var fontSizeDip = Math.Max(8, wordArt.FontSizeDip);
        var glyphWidths = wordArt.Text.Select(character =>
            fontSizeDip * (char.IsWhiteSpace(character) ? 0.34 : 0.56)).ToList();
        var targetWidthDip = sourceRect.Width * 0.80;
        var totalWidthDip = glyphWidths.Sum();
        if (totalWidthDip > targetWidthDip && totalWidthDip > 0)
        {
            var scale = targetWidthDip / totalWidthDip;
            fontSizeDip *= scale;
            glyphWidths = glyphWidths.Select(width => width * scale).ToList();
        }

        var textColor = ParseColor(WordArtForegroundPolicy.ResolveColorHex(wordArt.Style, wordArt.Fill));
        var face = wordArt.Bold ? PdfFontFace.Bold : PdfFontFace.Regular;
        var placements = wordArt.Warp is WordArtWarp.ArchUp or WordArtWarp.Wave1
            ? DrawingObjectVisualPlanner.BuildWordArtPlacementPlan(
                wordArt.Warp,
                glyphWidths,
                sourceRect.Width,
                sourceRect.Height).Glyphs
            : [];

        if (placements.Count == glyphWidths.Count)
        {
            for (var index = 0; index < glyphWidths.Count; index++)
            {
                var placement = placements[index];
                AddPdfWordArtGlyph(
                    glyphOps,
                    wordArt.Text[index].ToString(),
                    glyphWidths[index],
                    fontSizeDip,
                    placement.CenterXNormalized * sourceRect.Width,
                    placement.CenterYNormalized * sourceRect.Height,
                    placement.RotationRadians * 180 / Math.PI,
                    face,
                    wordArt.FontFamily,
                    textColor,
                    sourceRect,
                    pageTopDip,
                    pageHeightPt,
                    wordArt.Outline);
            }
        }
        else
        {
            var xDip = Math.Max(0, (sourceRect.Width - glyphWidths.Sum()) / 2);
            foreach (var (character, width) in wordArt.Text.Zip(glyphWidths))
            {
                AddPdfWordArtGlyph(
                    glyphOps,
                    character.ToString(),
                    width,
                    fontSizeDip,
                    xDip + width / 2,
                    sourceRect.Height / 2,
                    0,
                    face,
                    wordArt.FontFamily,
                    textColor,
                    sourceRect,
                    pageTopDip,
                    pageHeightPt,
                    wordArt.Outline);
                xDip += width;
            }
        }

        ops.AddRange(WrapPdfEffectOps(glyphOps, plan.Effects, frame));
        return WrapPdfVisualOps(ops, plan, frame);
    }

    private static IReadOnlyList<PdfDrawOp> WrapPdfEffectOps(
        IReadOnlyList<PdfDrawOp> source,
        DrawingObjectEffectsPlan effects,
        PdfRectValue frame)
    {
        if (source.Count == 0 || !effects.HasAny)
            return source;

        var result = new List<PdfDrawOp>();
        if (effects.HasShadow && effects.ShadowOpacity > 0)
        {
            var radians = effects.ShadowDirectionDegrees * Math.PI / 180.0;
            var distance = effects.ShadowDistanceDip / PxPerPoint;
            result.Add(new PdfEffectGroup(
                PdfEffectKind.Shadow,
                frame.X,
                frame.Y,
                frame.Width,
                frame.Height,
                new PdfEffectParameters(
                    ParseColor(effects.ShadowColorHex),
                    effects.ShadowOpacity,
                    effects.ShadowBlurDip / PxPerPoint,
                    Math.Cos(radians) * distance,
                    -Math.Sin(radians) * distance),
                source));
        }

        if (effects.HasGlow && effects.GlowOpacity > 0)
        {
            result.Add(new PdfEffectGroup(
                PdfEffectKind.Glow,
                frame.X,
                frame.Y,
                frame.Width,
                frame.Height,
                new PdfEffectParameters(
                    ParseColor(effects.GlowColorHex),
                    effects.GlowOpacity,
                    effects.GlowRadiusDip / PxPerPoint),
                source));
        }

        if (effects.HasSoftEdge)
        {
            result.Add(new PdfEffectGroup(
                PdfEffectKind.SoftEdge,
                frame.X,
                frame.Y,
                frame.Width,
                frame.Height,
                new PdfEffectParameters(null, 0.34, effects.SoftEdgeRadiusDip / PxPerPoint),
                source));
        }

        if (effects.HasReflection && effects.ReflectionOpacity > 0)
        {
            result.Add(new PdfEffectGroup(
                PdfEffectKind.Reflection,
                frame.X,
                frame.Y,
                frame.Width,
                frame.Height,
                new PdfEffectParameters(
                    null,
                    effects.ReflectionOpacity,
                    effects.ReflectionBlurDip / PxPerPoint,
                    ReflectionGap: effects.ReflectionDistanceDip / PxPerPoint,
                    ReflectionDirectionDegrees: effects.ReflectionDirectionDegrees,
                    ReflectionEndOpacity: effects.ReflectionEndOpacity,
                    ReflectionStartPosition: effects.ReflectionStartPosition,
                    ReflectionEndPosition: effects.ReflectionEndPosition,
                    ReflectionFadeDirectionDegrees: effects.ReflectionFadeDirectionDegrees,
                    ReflectionScaleX: effects.ReflectionScaleX,
                    ReflectionScaleY: effects.ReflectionScaleY,
                    ReflectionSkewXDegrees: effects.ReflectionSkewXDegrees,
                    ReflectionSkewYDegrees: effects.ReflectionSkewYDegrees),
                source));
        }

        if (effects.HasBevel)
        {
            result.Add(new PdfEffectGroup(
                PdfEffectKind.Bevel,
                frame.X,
                frame.Y,
                frame.Width,
                frame.Height,
                new PdfEffectParameters(
                    ParseColor("#E0E8FF"),
                    0.82,
                    Math.Max(effects.BevelWidthDip, effects.BevelHeightDip) / PxPerPoint,
                    SecondaryColor: ParseColor("#5C6B85"),
                    BevelWidth: effects.BevelWidthDip / PxPerPoint,
                    BevelHeight: effects.BevelHeightDip / PxPerPoint),
                source));
        }

        result.AddRange(source);
        return result;
    }

    private void AddPdfWordArtGlyph(
        List<PdfDrawOp> ops,
        string text,
        double widthDip,
        double fontSizeDip,
        double centerXDip,
        double centerYDip,
        double rotationDegrees,
        PdfFontFace face,
        string? fontFamily,
        PdfColor fillColor,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt,
        DrawingObjectOutlinePlan outline)
    {
        var fontSizePt = fontSizeDip / PxPerPoint;
        var centerXPt = (sourceRect.Left + centerXDip - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var centerYPt = pageHeightPt - ((sourceRect.Top + centerYDip - pageTopDip) / PxPerPoint);
        var glyphWidthPt = widthDip / PxPerPoint;
        var baseline = centerYPt - fontSizePt * 0.35;
        var textOps = new List<PdfDrawOp>();
        if (outline.IsVisible && outline.ColorHex is not null)
        {
            textOps.Add(new PdfText(
                centerXPt - glyphWidthPt / 2 + 0.75 / PxPerPoint,
                baseline - 0.75 / PxPerPoint,
                fontSizePt,
                face,
                ParseColor(outline.ColorHex),
                text,
                fontFamily));
        }
        textOps.Add(new PdfText(
            centerXPt - glyphWidthPt / 2,
            baseline,
            fontSizePt,
            face,
            fillColor,
            text,
            fontFamily));

        if (Math.Abs(rotationDegrees) > 0.001)
            ops.Add(new PdfRotationGroup(centerXPt, centerYPt, rotationDegrees, textOps));
        else
            ops.AddRange(textOps);
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfShapeOps(
        Shape shape,
        DocumentFloatingObjectSnapshot snapshot,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        var plan = DrawingObjectVisualPlanner.BuildVisualPlan(shape, snapshot);
        return BuildPdfShapeOps(plan, snapshot, sourceRect, pageTopDip, pageHeightPt);
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfShapeOps(
        DrawingObjectVisualPlan plan,
        DocumentFloatingObjectSnapshot snapshot,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        var xPt = (sourceRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var yPt = pageHeightPt - ((sourceRect.Bottom - pageTopDip) / PxPerPoint);
        var widthPt = sourceRect.Width / PxPerPoint;
        var heightPt = sourceRect.Height / PxPerPoint;
        var ops = new List<PdfDrawOp>();

        AddPdfShapeGeometryOps(ops, plan, xPt, yPt, widthPt, heightPt);
        AddPdfShapeTextOps(ops, plan, snapshot, sourceRect, pageTopDip, pageHeightPt);
        if (ops.Count == 0)
            return [];

        var frame = new PdfRectValue(xPt, yPt, widthPt, heightPt);
        ops = WrapPdfEffectOps(ops, plan.Effects, frame).ToList();

        if (Math.Abs(plan.RotationAngle) > 0.001 || plan.FlipH || plan.FlipV)
        {
            return [new PdfRotationGroup(
                xPt + widthPt / 2,
                yPt + heightPt / 2,
                plan.RotationAngle,
                ops,
                plan.FlipH,
                plan.FlipV)];
        }

        return ops;
    }

    private static void AddPdfShapeGeometryOps(
        List<PdfDrawOp> ops,
        DrawingObjectVisualPlan plan,
        double x,
        double y,
        double width,
        double height)
    {
        var fillColor = ResolvePdfShapeFillFallback(plan.Fill);
        var pattern = BuildPdfShapePattern(plan.Fill);
        PdfColor? outlineColor = plan.Outline.IsVisible ? ParseColor(plan.Outline.ColorHex) : null;
        var strokeWidth = Math.Max(0.1, plan.Outline.WidthDip / PxPerPoint);
        var dash = BuildPdfShapeDash(plan.Outline.DashStyle);
        var gradient = BuildPdfShapeGradient(plan.Fill, x, y, width, height);

        switch (plan.GeometryKind)
        {
            case DrawingObjectGeometryKind.Ellipse:
                if (gradient is not null)
                {
                    ops.Add(new PdfFillEllipseLinearGradient(
                        x, y, width, height, gradient, fillColor ?? new PdfColor(255, 255, 255)));
                }
                else if (fillColor is { } ellipseFill)
                {
                    ops.Add(new PdfFillEllipse(x, y, width, height, ellipseFill));
                }
                else if (pattern is { } ellipsePattern)
                {
                    ops.Add(new PdfFillEllipsePattern(x, y, width, height, ellipsePattern));
                }

                if (outlineColor is { } ellipseOutline)
                    ops.Add(new PdfStrokeEllipse(x, y, width, height, ellipseOutline, strokeWidth, dash));
                break;

            case DrawingObjectGeometryKind.RoundedRectangle:
            case DrawingObjectGeometryKind.Custom:
                var contours = plan.GeometryKind == DrawingObjectGeometryKind.Custom
                    ? BuildPdfCustomGeometry(plan.CustomGeometry, x, y, width, height)
                    : [BuildPdfRoundedRectangleContour(x, y, width, height)];
                if (contours.Count == 0)
                    break;

                if (gradient is not null)
                {
                    ops.Add(new PdfPathLinearGradient(
                        contours,
                        gradient,
                        fillColor,
                        null,
                        outlineColor,
                        strokeWidth,
                        dash));
                }
                else if (pattern is { } pathPattern)
                {
                    ops.Add(new PdfPathPattern(contours, pathPattern, outlineColor, strokeWidth, dash));
                }
                else if (fillColor is not null || outlineColor is not null)
                {
                    ops.Add(new PdfPath(contours, fillColor, outlineColor, strokeWidth, dash));
                }
                break;

            case DrawingObjectGeometryKind.Rectangle:
            case DrawingObjectGeometryKind.TextBox:
            default:
                if (gradient is not null)
                {
                    ops.Add(new PdfFillRectLinearGradient(
                        x, y, width, height, gradient, fillColor ?? new PdfColor(255, 255, 255)));
                }
                else if (fillColor is { } rectangleFill)
                {
                    ops.Add(new PdfFillRect(x, y, width, height, rectangleFill));
                }
                else if (pattern is { } rectanglePattern)
                {
                    ops.Add(new PdfFillRectPattern(x, y, width, height, rectanglePattern));
                }

                if (outlineColor is { } rectangleOutline)
                    ops.Add(new PdfStrokeRect(x, y, width, height, rectangleOutline, strokeWidth, dash));
                break;
        }
    }

    private void AddPdfShapeTextOps(
        List<PdfDrawOp> ops,
        DrawingObjectVisualPlan plan,
        DocumentFloatingObjectSnapshot snapshot,
        Rect sourceRect,
        double pageTopDip,
        double pageHeightPt)
    {
        if (plan.Text is null)
            return;

        var cachedLayout = _floatingShapes
            .Concat(_inlineShapes)
            .FirstOrDefault(item => item.BlockIndex == snapshot.BlockIndex
                && item.RunIndex == snapshot.RunIndex)
            ?.TextLayout;
        var layout = cachedLayout ?? DrawingObjectTextLayoutPlanner.LayoutPlan(
            plan.Text,
            sourceRect.Width,
            sourceRect.Height,
            (value, formatting) => Build(value, formatting).WidthIncludingTrailingWhitespace,
            formatting => Build("Ag", formatting).Height);
        if (layout is null)
            return;

        var originX = sourceRect.X + (sourceRect.Width - layout.Width) / 2;
        var originY = sourceRect.Y + (sourceRect.Height - layout.Height) / 2;
        var currentLine = -1;
        RunFormatting? currentFormatting = null;
        var currentText = new StringBuilder();
        var currentX = 0.0;
        var currentY = 0.0;
        var currentHeight = 0.0;
        var textStartIndex = ops.Count;

        void Flush()
        {
            if (currentText.Length == 0 || currentFormatting is null)
                return;

            var fontSizePt = currentFormatting.FontSizePt ?? DefaultFontSizePt;
            var baselineDip = currentY + currentHeight * 0.82
                + RunBaselinePositionPlanner.ResolveOffsetDip(currentFormatting, PxPerPoint);
            var baselinePt = pageHeightPt - ((baselineDip - pageTopDip) / PxPerPoint);
            var face = currentFormatting.Bold
                ? currentFormatting.Italic ? PdfFontFace.BoldItalic : PdfFontFace.Bold
                : currentFormatting.Italic ? PdfFontFace.Italic : PdfFontFace.Regular;
            ops.Add(new PdfText(
                (currentX - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt,
                baselinePt,
                fontSizePt,
                face,
                ParseColor(currentFormatting.ColorHex),
                currentText.ToString(),
                currentFormatting.FontFamily));
            currentText.Clear();
            currentFormatting = null;
        }

        foreach (var glyph in layout.Glyphs.OrderBy(glyph => glyph.LineIndex).ThenBy(glyph => glyph.X))
        {
            var startsNewRun = currentFormatting is null
                || currentLine != glyph.LineIndex
                || currentFormatting != glyph.Formatting;
            if (startsNewRun)
            {
                Flush();
                currentLine = glyph.LineIndex;
                currentFormatting = glyph.Formatting;
                currentX = originX + glyph.X;
                currentY = originY + glyph.Y;
                currentHeight = glyph.Height;
            }

            currentText.Append(glyph.Character);
        }

        Flush();

        if (plan.Text.Direction is ShapeTextDirection.Rotate90 or ShapeTextDirection.Rotate270)
        {
            var textOps = ops.Skip(textStartIndex).ToList();
            if (textOps.Count > 0)
            {
                ops.RemoveRange(ops.Count - textOps.Count, textOps.Count);
                ops.Add(new PdfRotationGroup(
                    (sourceRect.X - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt + sourceRect.Width / PxPerPoint / 2,
                    pageHeightPt - ((sourceRect.Bottom - pageTopDip) / PxPerPoint) + sourceRect.Height / PxPerPoint / 2,
                    plan.Text.Direction == ShapeTextDirection.Rotate90 ? 90 : -90,
                    textOps));
            }
        }
    }

    private static PdfColor? ResolvePdfShapeFillFallback(DrawingObjectFillPlan fill) =>
        fill.Kind switch
        {
            DrawingObjectFillKind.Solid => ParseColor(fill.ColorHex),
            DrawingObjectFillKind.Pattern => null,
            DrawingObjectFillKind.Gradient => ParseColor(fill.GradientStops.FirstOrDefault()?.ColorHex),
            _ => null,
        };

    private static PdfPatternFill? BuildPdfShapePattern(DrawingObjectFillPlan fill)
    {
        if (fill.Kind != DrawingObjectFillKind.Pattern)
            return null;

        return PdfPatternFill.FromPreset(
            fill.PatternPreset,
            ParseColor(fill.PatternForegroundColorHex ?? "#4472C4"),
            ParseColor(fill.PatternBackgroundColorHex ?? "#FFFFFF"),
            unitScale: 1 / PxPerPoint);
    }

    private static PdfDashPattern? BuildPdfShapeDash(string? dashStyle) =>
        dashStyle?.Trim().ToLowerInvariant() switch
        {
            "dash" => new PdfDashPattern([4, 3]),
            "sysdot" => new PdfDashPattern([1, 2]),
            "dashdot" => new PdfDashPattern([4, 2, 1, 2]),
            _ => null,
        };

    private static PdfLinearGradient? BuildPdfShapeGradient(
        DrawingObjectFillPlan fill,
        double x,
        double y,
        double width,
        double height)
    {
        if (fill.Kind != DrawingObjectFillKind.Gradient || fill.GradientStops.Count == 0)
            return null;

        var angle = fill.GradientAngle / 60000.0 * Math.PI / 180.0;
        var cos = Math.Cos(angle);
        var sin = Math.Sin(angle);
        var start = new PdfPathPoint(
            x + width * (0.5 - cos * 0.5),
            y + height * (0.5 + sin * 0.5));
        var end = new PdfPathPoint(
            x + width * (0.5 + cos * 0.5),
            y + height * (0.5 - sin * 0.5));
        var stops = fill.GradientStops
            .Select(stop => new PdfGradientStop(
                Math.Clamp(stop.Position / 100000.0, 0, 1),
                ParseColor(stop.ColorHex)))
            .ToArray();
        return new PdfLinearGradient(start.X, start.Y, end.X, end.Y, stops);
    }

    private static PdfPathContour BuildPdfRoundedRectangleContour(
        double x,
        double y,
        double width,
        double height)
    {
        var radius = Math.Min(6.0 / PxPerPoint, Math.Min(width, height) / 4);
        var right = x + width;
        var top = y + height;
        const double kappa = 0.5522847498;
        var start = new PdfPathPoint(x + radius, top);
        var segments = new List<PdfPathSegment>
        {
            PdfPathSegment.LineTo(new PdfPathPoint(right - radius, top)),
            PdfPathSegment.BezierTo(
                new PdfPathPoint(right - radius + radius * kappa, top),
                new PdfPathPoint(right, top - radius + radius * kappa),
                new PdfPathPoint(right, top - radius)),
            PdfPathSegment.LineTo(new PdfPathPoint(right, y + radius)),
            PdfPathSegment.BezierTo(
                new PdfPathPoint(right, y + radius - radius * kappa),
                new PdfPathPoint(right - radius + radius * kappa, y),
                new PdfPathPoint(right - radius, y)),
            PdfPathSegment.LineTo(new PdfPathPoint(x + radius, y)),
            PdfPathSegment.BezierTo(
                new PdfPathPoint(x + radius - radius * kappa, y),
                new PdfPathPoint(x, y + radius - radius * kappa),
                new PdfPathPoint(x, y + radius)),
            PdfPathSegment.LineTo(new PdfPathPoint(x, top - radius)),
            PdfPathSegment.BezierTo(
                new PdfPathPoint(x, top - radius + radius * kappa),
                new PdfPathPoint(x + radius - radius * kappa, top),
                start),
        };
        return new PdfPathContour(start, segments, Closed: true);
    }

    private static IReadOnlyList<PdfPathContour> BuildPdfCustomGeometry(
        CustomGeometry? geometry,
        double x,
        double y,
        double width,
        double height)
    {
        return CustomShapePathPlanner.Build(
                geometry,
                new CustomShapePathBounds(x, y, width, height, InvertY: true))
            .Select(figure => new PdfPathContour(
                ToPdfPoint(figure.Start),
                figure.Commands.Select(ToPdfSegment).ToArray(),
                figure.IsClosed))
            .ToArray();

        static PdfPathPoint ToPdfPoint(CustomShapePathPoint point) => new(point.X, point.Y);

        static PdfPathSegment ToPdfSegment(CustomShapePathCommand command) =>
            command.Kind == CustomShapePathCommandKind.LineTo
                ? PdfPathSegment.LineTo(ToPdfPoint(command.Point))
                : PdfPathSegment.BezierTo(
                    ToPdfPoint(command.ControlPoint1!.Value),
                    ToPdfPoint(command.ControlPoint2!.Value),
                    ToPdfPoint(command.Point));
    }

    private static bool RequiresRasterImageBake(InlineImage image) =>
        image.BrightnessPct != 0
        || image.ContrastPct != 0
        || image.SaturationPct != 100
        || image.HasRecolor
        || image.HasArtisticEffect
        || image.HasEffects;

    private static Free.Shared.Pdf.PdfColor ParseColor(string? hex)
    {
        return DrawingMlRgbColor.TryParseHexRgb(hex, out var color)
            ? new Free.Shared.Pdf.PdfColor(color.R, color.G, color.B)
            : Free.Shared.Pdf.PdfColor.Black;
    }

    // ---- Layout ---------------------------------------------------------------------------------

    private static DocumentViewLayoutKind ToLayoutKind(DocumentViewMode mode) => mode switch
    {
        DocumentViewMode.PrintLayout => DocumentViewLayoutKind.PrintLayout,
        DocumentViewMode.WebLayout => DocumentViewLayoutKind.WebLayout,
        DocumentViewMode.Draft => DocumentViewLayoutKind.Draft,
        _ => DocumentViewLayoutKind.PrintLayout
    };

    protected override Size MeasureOverride(Size availableSize)
    {
        var width = double.IsFinite(availableSize.Width) && availableSize.Width > 0
            ? availableSize.Width
            : FallbackWidth;
        RelayoutSafely(width);
        var measuredWidth = _surfacePlan.UsesProjectedPageFlow
            ? _surfacePlan.ScrollableWidthForPages(_pageCount)
            : width;
        return new Size(measuredWidth, _contentHeight);
    }

    /// <summary>
    /// Runs <see cref="Relayout"/> from the layout/render pass without letting a failure escape.
    /// <para>
    /// Relayout is the whole pagination engine — tables, floats, equations, headers/footers,
    /// footnotes, columns — driven by arbitrary opened .docx content. An exception escaping
    /// MeasureOverride/Render propagates into the Avalonia layout manager and kills the process, and
    /// because the layout pass re-runs on the next tick it would repeat, crashing the editor in a
    /// loop with the document still open. Degrade to whatever was laid out so far instead; the
    /// individually risky sub-steps (image decode, format parsing) already guard themselves.
    /// </para>
    /// </summary>
    private void RelayoutSafely(double width)
    {
        try
        {
            Relayout(width);
        }
        catch (Exception)
        {
            // Keep the partially-built layout: a degraded page beats a dead editor.
        }
    }

    private void Relayout(double width)
    {
        _pageFlowProjected = false;
        _placed.Clear();
        _markers.Clear();
        _rects.Clear();
        _paragraphDecorations.Clear();
        _images.Clear();
        _floatingImages.Clear();
        _floatingShapes.Clear();
        _floatingCharts.Clear();
        _floatingWordArts.Clear();
        _floatingSmartArts.Clear();
        _floatingGroups.Clear();
        _floatingSnapshots.Clear();
        _dropCapLayoutPlans.Clear();
        _wrapExclusions.Clear();
        _inlineShapes.Clear();
        _inlineCharts.Clear();
        _inlineWordArts.Clear();
        _inlineSmartArts.Clear();
        _inlineEmbeddedObjects.Clear();
        _equationVisualSegments.Clear();
        _equationVisualElements.Clear();
        _cellHits.Clear();
        _shapeTextCaretStops.Clear();
        _headerFooterItems.Clear();
        _noteItems.Clear();           // AV-NOTERENDER
        _noteSeparators.Clear();      // AV-NOTERENDER
        _endnoteExtentDip = 0;        // AV-NOTERENDER
        _footnoteBandHeightByPage.Clear(); // DB1/DB2
        _footnoteContinuationByBodyPage.Clear();
        _footnotePhysicalPagePlan = DocumentFootnotePhysicalPagePlan.Empty;
        _bodyBlockSectionAssignments = ComputeBlockSectionAssignments();
        _bodySectionPageCounts = Enumerable.Repeat(1, Math.Max(1, _doc.Sections.Count)).ToArray();
        _bodyPageCount = 0;
        _tabLeaderSpans.Clear(); // AV-TAB
        _automaticHyphenGlyphs.Clear();

        _surfacePlan = DocumentViewLayoutPlanner.BuildSurfacePlan(
            _doc.Page,
            ToLayoutKind(_viewMode),
            width,
            collapsePageBoundaries: _doc.DoNotDisplayPageBoundaries);
        _surfacePlan = _surfacePlan with
        {
            UsesHorizontalPageFlow = _viewMode == DocumentViewMode.PrintLayout
                && _viewDepthLayout.UsesHorizontalPageFlow,
            PageGridColumns = _viewMode == DocumentViewMode.PrintLayout
                && _viewDepthLayout.PageFlow == DocumentViewDepthPageFlow.MultiplePagesGrid
                    ? Math.Max(1, _viewDepthLayout.PagesAcross)
                    : 1
        };

        if (_viewMode == DocumentViewMode.PrintLayout)
        {
            // ---- Print Layout: paginated white pages on a grey desk ----
            // Page geometry from the document's PageSettings: a centred page with its own margins.
            _pageWidth = _surfacePlan.PageWidthDip;
            _pageHeightPx = _surfacePlan.PageHeightDip;
            _marginTopDip    = _surfacePlan.MarginTopDip;
            _marginBottomDip = _surfacePlan.MarginBottomDip;
            // Centre the page in the available width, never closer than the planner's minimum gutter.
            _pageLeft = _surfacePlan.PageLeftDip;
            _contentLeft = _surfacePlan.ContentLeftDip;
            _contentWidth = _surfacePlan.ContentWidthDip;
        }
        else if (_viewMode == DocumentViewMode.WebLayout)
        {
            // ---- Web Layout: continuous column, capped width, no page chrome ----
            // Responsive up to the planner's Web Layout cap; small fixed inset on each side.
            _pageWidth = _surfacePlan.PageWidthDip;
            _pageHeightPx = _surfacePlan.PageHeightDip; // effectively infinite — no pagination
            _marginTopDip    = _surfacePlan.MarginTopDip;
            _marginBottomDip = _surfacePlan.MarginBottomDip;
            _pageLeft = _surfacePlan.PageLeftDip;
            _contentLeft = _surfacePlan.ContentLeftDip;
            _contentWidth = _surfacePlan.ContentWidthDip;
        }
        else // Draft
        {
            // ---- Draft: plain left-margin continuous flow ----
            _pageWidth = _surfacePlan.PageWidthDip;
            _pageHeightPx = _surfacePlan.PageHeightDip;
            _marginTopDip    = _surfacePlan.MarginTopDip;
            _marginBottomDip = _surfacePlan.MarginBottomDip;
            _pageLeft = _surfacePlan.PageLeftDip;
            _contentLeft = _surfacePlan.ContentLeftDip;
            _contentWidth = _surfacePlan.ContentWidthDip;
        }

        // AV-COL: compute multi-column geometry from PageSettings.
        // Only active in PrintLayout mode — Web/Draft always use a single column.
        {
            var columnPlan = DocumentViewLayoutPlanner.BuildColumnPlan(
                _doc.Page,
                _contentWidth,
                usePageColumns: _surfacePlan.IsPrintLayout);
            _colCount       = columnPlan.Count;
            _colWidth       = columnPlan.WidthDip;
            _colGap         = columnPlan.GapDip;
            _colLineBetween = columnPlan.LineBetween;
        }

        // Body text layout uses _colWidth as the per-column wrap width.
        var textWidth = _colWidth;
        // Available text-area height per page (between top and bottom margin).
        // For Web/Draft this is effectively infinite so ReserveContentY never paginates.
        var textAreaHeight = _surfacePlan.TextAreaHeightDip;

        // _layoutContentY tracks the "content Y" — the offset within the flowing text area
        // (0 = start of the first text area). This gets converted to page-space Y via
        // ContentYToPageSpaceY() when placing glyphs.
        _layoutContentY = 0;
        _layoutTextAreaHeight = textAreaHeight;

        // DB1: first body-layout pass — lays out body text with _footnoteBandHeightByPage EMPTY
        // (no per-page reservation yet). After this pass we know which footnotes land on which page
        // and can measure true band heights. A second pass then re-flows the body with per-page
        // reservations so body text breaks before encroaching on the footnote band.
        RunBodyLayoutBlocks(textWidth);

        if (_viewMode == DocumentViewMode.PrintLayout)
        {
            _pageCount = CalculateBodyPageCount();
            _bodyPageCount = _pageCount;
            _contentHeight = _surfacePlan.ScrollableHeightForPages(_pageCount);

            if (HasVisibleBodySectionPagesFields())
            {
                StabilizeBodySectionPageLayout(textWidth);
            }
            // DB1: measure true footnote band heights (needs first-pass placed positions to resolve pages).
            else if (_doc.Footnotes.Count > 0)
            {
                ComputeFootnoteContinuationPlans();
                RebuildFootnotePhysicalPagePlan();

                // DB1 second pass: re-flow the body with per-page footnote reservations active.
                // ReserveContentY now consults _footnoteBandHeightByPage to shrink each page's
                // effective text area so body text breaks before the footnote band.
                ResetBodyLayoutArtifacts();
                RunBodyLayoutBlocks(textWidth);

                // Recompute page count from the second pass.
                _bodyPageCount = CalculateBodyPageCount();
                RebuildFootnotePhysicalPagePlan();
                _pageCount = _footnotePhysicalPagePlan.PhysicalPageCount;
                _contentHeight = _surfacePlan.ScrollableHeightForPages(_pageCount);
            }
        }
        else
        {
            // Web/Draft: single continuous column — total height is just the content plus margins.
            _pageCount = 1;
            _bodyPageCount = 1;
            _contentHeight = _layoutContentY + _marginBottomDip;
        }

        ApplyPageVerticalAlignment();

        _laidOutWidth = width;

        if (_viewMode == DocumentViewMode.PrintLayout)
        {
            if (!_doc.DoNotDisplayPageBoundaries)
                BuildHeaderFooterItems();
            // AV-NOTERENDER: footnotes render in the bottom margin band of the page hosting their
            // reference; endnotes render in a synthetic section after the last body page. Endnotes
            // extend the scrollable content height, so add their measured extent afterwards.
            BuildFootnoteItems();
            BuildEndnoteItems();
            _contentHeight += _endnoteExtentDip;
        }

        ApplyProjectedPageFlowTransform();
    }

    private void ApplyPageVerticalAlignment()
    {
        _bodyPageVerticalOffsets.Clear();
        _bodyPageVerticalJustifiedGaps.Clear();
        if (_viewMode != DocumentViewMode.PrintLayout
            || _doc.Page.VerticalAlignment == PageVerticalAlignment.Top)
        {
            return;
        }

        var pageCount = Math.Max(1, _pageCount);
        var bodyBottoms = new double[pageCount];
        var hasBody = new bool[pageCount];
        var bodyBlockStarts = Enumerable.Range(0, pageCount)
            .Select(_ => new Dictionary<int, PageVerticalAlignmentPlanner.BodyFlowStart>())
            .ToArray();

        void Include(double x, double y, double height)
        {
            var page = Math.Clamp(PageIndexFromPageSpaceY(y), 0, pageCount - 1);
            bodyBottoms[page] = Math.Max(bodyBottoms[page], y + Math.Max(0, height));
            hasBody[page] = true;
        }

        void IncludeBlockStart(int block, double x, double y)
        {
            if (block < 0)
                return;

            var page = Math.Clamp(PageIndexFromPageSpaceY(y), 0, pageCount - 1);
            var candidate = new PageVerticalAlignmentPlanner.BodyFlowStart(
                block,
                ColumnIndexFor(x),
                y);
            if (!bodyBlockStarts[page].TryGetValue(block, out var existing)
                || candidate.ColumnIndex < existing.ColumnIndex
                || (candidate.ColumnIndex == existing.ColumnIndex
                    && candidate.PageSpaceY < existing.PageSpaceY))
            {
                bodyBlockStarts[page][block] = candidate;
            }
        }

        foreach (var placed in _placed)
        {
            IncludeBlockStart(placed.Block, placed.X, placed.Y);
            if (placed.Sentinel)
                continue;
            Include(placed.X, placed.Y, placed.LineHeight);
        }
        foreach (var image in _images)
        {
            IncludeBlockStart(image.BlockIndex, image.Rect.X, image.Rect.Y);
            Include(image.Rect.X, image.Rect.Y, image.Rect.Height);
        }
        foreach (var (rect, _, _, _) in _rects)
            Include(rect.X, rect.Y, rect.Height);
        foreach (var (rect, _, _) in _paragraphDecorations)
            Include(rect.X, rect.Y, rect.Height);
        foreach (var (rect, _, _, _, _, _, blockIndex, _) in _floatingImages)
        {
            Include(rect.X, rect.Y, rect.Height);
        }
        foreach (var cell in _cellHits)
        {
            IncludeBlockStart(cell.Block, cell.Rect.X, cell.Rect.Y);
            Include(cell.Rect.X, cell.Rect.Y, cell.Rect.Height);
        }
        foreach (var shape in _floatingShapes)
        {
            Include(shape.Rect.X, shape.Rect.Y, shape.Rect.Height);
        }
        foreach (var chart in _floatingCharts)
        {
            Include(chart.Rect.X, chart.Rect.Y, chart.Rect.Height);
        }
        foreach (var wordArt in _floatingWordArts)
        {
            Include(wordArt.Rect.X, wordArt.Rect.Y, wordArt.Rect.Height);
        }
        foreach (var smartArt in _floatingSmartArts)
        {
            Include(smartArt.Rect.X, smartArt.Rect.Y, smartArt.Rect.Height);
        }
        foreach (var group in _floatingGroups)
        {
            Include(group.Rect.X, group.Rect.Y, group.Rect.Height);
        }
        foreach (var shape in _inlineShapes)
        {
            IncludeBlockStart(shape.BlockIndex, shape.Rect.X, shape.Rect.Y);
            Include(shape.Rect.X, shape.Rect.Y, shape.Rect.Height);
        }
        foreach (var chart in _inlineCharts)
        {
            IncludeBlockStart(chart.BlockIndex, chart.Rect.X, chart.Rect.Y);
            Include(chart.Rect.X, chart.Rect.Y, chart.Rect.Height);
        }
        foreach (var wordArt in _inlineWordArts)
        {
            IncludeBlockStart(wordArt.BlockIndex, wordArt.Rect.X, wordArt.Rect.Y);
            Include(wordArt.Rect.X, wordArt.Rect.Y, wordArt.Rect.Height);
        }
        foreach (var smartArt in _inlineSmartArts)
        {
            IncludeBlockStart(smartArt.BlockIndex, smartArt.Rect.X, smartArt.Rect.Y);
            Include(smartArt.Rect.X, smartArt.Rect.Y, smartArt.Rect.Height);
        }
        foreach (var embeddedObject in _inlineEmbeddedObjects)
        {
            IncludeBlockStart(embeddedObject.BlockIndex, embeddedObject.Rect.X, embeddedObject.Rect.Y);
            Include(embeddedObject.Rect.X, embeddedObject.Rect.Y, embeddedObject.Rect.Height);
        }

        var justifiedBoundariesByPage = new PageVerticalAlignmentPlanner.BodyFlowStart[pageCount][];
        for (var page = 0; page < pageCount; page++)
        {
            var pageTop = _surfacePlan.PageTopDip(page);
            var logicalBodyPage = LogicalBodyPageForPhysicalPage(page);
            var footnoteReservation = _footnoteBandHeightByPage.TryGetValue(logicalBodyPage, out var bandHeight)
                ? bandHeight
                : 0;
            var availableTextHeight = Math.Max(0, _surfacePlan.TextAreaHeightDip - footnoteReservation);
            var usedHeight = hasBody[page]
                ? Math.Max(0, bodyBottoms[page] - pageTop - _marginTopDip)
                : 0;
            var freeSpace = Math.Max(0, availableTextHeight - usedHeight);
            if (_doc.Page.VerticalAlignment == PageVerticalAlignment.Justified)
            {
                var starts = PageVerticalAlignmentPlanner.OrderBodyStartsByColumn(
                    bodyBlockStarts[page].Values);
                justifiedBoundariesByPage[page] = starts.Skip(1).ToArray();
                _bodyPageVerticalJustifiedGaps.Add(PageVerticalAlignmentPlanner.ResolveJustifiedParagraphGap(
                    _doc.Page.VerticalAlignment,
                    freeSpace,
                    justifiedBoundariesByPage[page].Length));
            }
            else
            {
                justifiedBoundariesByPage[page] = [];
                _bodyPageVerticalOffsets.Add(PageVerticalAlignmentPlanner.ResolveBodyOffset(
                    _doc.Page.VerticalAlignment,
                    freeSpace));
            }
        }

        double OffsetForFlow(int page, int column, double flowY)
        {
            if (_doc.Page.VerticalAlignment == PageVerticalAlignment.Justified)
            {
                page = Math.Clamp(page, 0, _bodyPageVerticalJustifiedGaps.Count - 1);
                var boundaries = justifiedBoundariesByPage[page];
                var boundariesPassed = boundaries.Count(boundary =>
                    boundary.ColumnIndex < column
                    || (boundary.ColumnIndex == column && flowY >= boundary.PageSpaceY - 0.01));
                return boundariesPassed * _bodyPageVerticalJustifiedGaps[page];
            }

            var offsetPage = Math.Clamp(page, 0, _bodyPageVerticalOffsets.Count - 1);
            return _bodyPageVerticalOffsets[offsetPage];
        }

        double OffsetFor(double x, double y) =>
            OffsetForFlow(
                PageIndexFromPageSpaceY(y),
                ColumnIndexFor(x),
                y);

        double OffsetForOwnedObject(int block, double x, double y)
        {
            var page = Math.Clamp(PageIndexFromPageSpaceY(y), 0, pageCount - 1);
            if (block >= 0
                && bodyBlockStarts[page].TryGetValue(block, out var owner))
            {
                return OffsetForFlow(page, owner.ColumnIndex, owner.PageSpaceY);
            }

            return OffsetFor(x, y);
        }

        var shiftedPlaced = _placed
            .Select(placed => placed with { Y = placed.Y + OffsetFor(placed.X, placed.Y) })
            .ToList();
        _placed.Clear();
        _placed.AddRange(shiftedPlaced);
        ShiftBodyTuples(OffsetFor, OffsetForOwnedObject);
        ShiftBodyObjects(OffsetForOwnedObject);
    }

    /// <summary>
    /// Projects the completed logical page stack into the live Side-to-Side or Multiple Pages surface. Layout still
    /// paginates in the ordinary vertical coordinate system so all existing page-break, footnote,
    /// section, and floating-object rules remain authoritative. At this point every page-owned
    /// record is complete, which lets the projection move the whole page (including caret stops and
    /// hit-test surfaces) as one unit.
    /// </summary>
    private void ApplyProjectedPageFlowTransform()
    {
        if (!_surfacePlan.UsesProjectedPageFlow || !_surfacePlan.IsPrintLayout || _pageCount <= 0)
            return;

        int PageForLegacyY(double y) => Math.Clamp(
            _surfacePlan.PageIndexFromPageSpaceY(y), 0, Math.Max(0, _pageCount - 1));

        Point Move(double x, double y)
        {
            var page = PageForLegacyY(y);
            return new Point(
                x + _surfacePlan.RenderedPageLeftDip(page) - _surfacePlan.PageLeftDip,
                y + _surfacePlan.RenderedPageTopDip(page) - _surfacePlan.PageTopDip(page));
        }

        Rect MoveRect(Rect rect)
        {
            var point = Move(rect.X, rect.Y);
            return new Rect(point.X, point.Y, rect.Width, rect.Height);
        }

        static DocumentFloatRect MovePlannerRect(DocumentFloatRect rect, Point point) =>
            rect with { XDip = point.X, YDip = point.Y };

        var placed = _placed
            .Select(item =>
            {
                var point = Move(item.X, item.Y);
                return item with { X = point.X, Y = point.Y };
            })
            .ToList();
        _placed.Clear();
        _placed.AddRange(placed);

        for (var i = 0; i < _markers.Count; i++)
        {
            var item = _markers[i];
            var point = Move(item.X, item.Y);
            _markers[i] = (point.X, point.Y, item.Text, item.Fmt);
        }

        for (var i = 0; i < _tabLeaderSpans.Count; i++)
        {
            var item = _tabLeaderSpans[i];
            var first = Move(item.X1, item.Y);
            var second = Move(item.X2, item.Y);
            _tabLeaderSpans[i] = (first.X, second.X, first.Y, item.LineHeight, item.Leader, item.Fmt);
        }

        for (var i = 0; i < _automaticHyphenGlyphs.Count; i++)
        {
            var item = _automaticHyphenGlyphs[i];
            var point = Move(item.X, item.Y);
            _automaticHyphenGlyphs[i] = item with { X = point.X, Y = point.Y };
        }

        for (var i = 0; i < _rects.Count; i++)
        {
            var item = _rects[i];
            _rects[i] = (MoveRect(item.Rect), item.Fill, item.Border, item.CellBorderPlan);
        }

        for (var i = 0; i < _paragraphDecorations.Count; i++)
        {
            var item = _paragraphDecorations[i];
            _paragraphDecorations[i] = (MoveRect(item.Rect), item.ShadingHex, item.Border);
        }

        for (var i = 0; i < _images.Count; i++)
        {
            var item = _images[i];
            _images[i] = (MoveRect(item.Rect), item.Image, item.Model, item.ReflectionPreset, item.BlockIndex);
        }

        for (var i = 0; i < _floatingImages.Count; i++)
        {
            var item = _floatingImages[i];
            _floatingImages[i] = (MoveRect(item.Rect), item.Image, item.Model, item.ReflectionPreset,
                item.BehindText, item.ZOrder, item.BlockIndex, item.RunIndex);
        }

        for (var i = 0; i < _cellHits.Count; i++)
        {
            var item = _cellHits[i];
            _cellHits[i] = (MoveRect(item.Rect), item.Block, item.Row, item.Col);
        }

        for (var i = 0; i < _shapeTextCaretStops.Count; i++)
        {
            var item = _shapeTextCaretStops[i];
            var point = Move(item.X, item.Y);
            var center = Move(item.RotationCenterX, item.RotationCenterY);
            _shapeTextCaretStops[i] = item with
            {
                X = point.X,
                Y = point.Y,
                RotationCenterX = center.X,
                RotationCenterY = center.Y
            };
        }

        Vector OffsetFor(double x, double y) => Move(x, y) - new Point(x, y);

        void MoveShape(FloatingShapeData shape, Vector? inheritedOffset = null)
        {
            var offset = inheritedOffset ?? OffsetFor(shape.Rect.X, shape.Rect.Y);
            shape.Rect = new Rect(shape.Rect.X + offset.X, shape.Rect.Y + offset.Y,
                shape.Rect.Width, shape.Rect.Height);
        }

        void MoveChart(FloatingChartData chart, Vector? inheritedOffset = null)
        {
            var offset = inheritedOffset ?? OffsetFor(chart.Rect.X, chart.Rect.Y);
            chart.Rect = new Rect(chart.Rect.X + offset.X, chart.Rect.Y + offset.Y,
                chart.Rect.Width, chart.Rect.Height);
        }

        void MoveWordArt(FloatingWordArtData wordArt, Vector? inheritedOffset = null)
        {
            var offset = inheritedOffset ?? OffsetFor(wordArt.Rect.X, wordArt.Rect.Y);
            wordArt.Rect = new Rect(wordArt.Rect.X + offset.X, wordArt.Rect.Y + offset.Y,
                wordArt.Rect.Width, wordArt.Rect.Height);
        }

        void MoveSmartArt(FloatingSmartArtData smartArt, Vector? inheritedOffset = null)
        {
            var offset = inheritedOffset ?? OffsetFor(smartArt.Rect.X, smartArt.Rect.Y);
            smartArt.Rect = new Rect(smartArt.Rect.X + offset.X, smartArt.Rect.Y + offset.Y,
                smartArt.Rect.Width, smartArt.Rect.Height);
        }

        void MoveGroup(FloatingGroupData group, Vector? inheritedOffset = null)
        {
            var offset = inheritedOffset ??
                (Move(group.Rect.X, group.Rect.Y) - new Point(group.Rect.X, group.Rect.Y));
            group.Rect = new Rect(group.Rect.X + offset.X, group.Rect.Y + offset.Y,
                group.Rect.Width, group.Rect.Height);
            foreach (var child in group.Children)
            {
                if (child.Group is not null)
                {
                    MoveGroup(child.Group, offset);
                    child.Rect = child.Group.Rect;
                }
                else
                {
                    child.Rect = new Rect(child.Rect.X + offset.X, child.Rect.Y + offset.Y,
                        child.Rect.Width, child.Rect.Height);
                    if (child.Shape is not null) MoveShape(child.Shape, offset);
                    if (child.Chart is not null) MoveChart(child.Chart, offset);
                    if (child.WordArt is not null) MoveWordArt(child.WordArt, offset);
                    if (child.SmartArt is not null) MoveSmartArt(child.SmartArt, offset);
                }
            }
        }

        foreach (var shape in _floatingShapes) MoveShape(shape);
        foreach (var chart in _floatingCharts) MoveChart(chart);
        foreach (var wordArt in _floatingWordArts) MoveWordArt(wordArt);
        foreach (var smartArt in _floatingSmartArts) MoveSmartArt(smartArt);
        foreach (var group in _floatingGroups) MoveGroup(group);
        foreach (var shape in _inlineShapes) MoveShape(shape);
        foreach (var chart in _inlineCharts) MoveChart(chart);
        foreach (var wordArt in _inlineWordArts) MoveWordArt(wordArt);
        foreach (var smartArt in _inlineSmartArts) MoveSmartArt(smartArt);
        foreach (var embeddedObject in _inlineEmbeddedObjects)
            embeddedObject.Rect = MoveRect(embeddedObject.Rect);

        for (var i = 0; i < _floatingSnapshots.Count; i++)
        {
            var snapshot = _floatingSnapshots[i];
            var point = Move(snapshot.Rect.XDip, snapshot.Rect.YDip);
            _floatingSnapshots[i] = snapshot with { Rect = MovePlannerRect(snapshot.Rect, point) };
        }

        for (var i = 0; i < _wrapExclusions.Count; i++)
        {
            var zone = _wrapExclusions[i];
            var point = Move(zone.Rect.XDip, zone.Rect.YDip);
            _wrapExclusions[i] = zone with { Rect = MovePlannerRect(zone.Rect, point) };
        }

        for (var i = 0; i < _dropCapLayoutPlans.Count; i++)
        {
            var plan = _dropCapLayoutPlans[i];
            var capPoint = Move(plan.CapBox.XDip, plan.CapBox.YDip);
            var reservationPoint = Move(plan.TextReservation.XDip, plan.TextReservation.YDip);
            _dropCapLayoutPlans[i] = plan with
            {
                CapBox = MovePlannerRect(plan.CapBox, capPoint),
                TextReservation = MovePlannerRect(plan.TextReservation, reservationPoint)
            };
        }

        for (var i = 0; i < _headerFooterItems.Count; i++)
        {
            var item = _headerFooterItems[i];
            var point = Move(item.X, item.Y);
            item.X = point.X;
            item.Y = point.Y;
        }

        for (var i = 0; i < _noteItems.Count; i++)
        {
            var item = _noteItems[i];
            var point = Move(item.X, item.Y);
            item.X = point.X;
            item.Y = point.Y;
        }

        for (var i = 0; i < _noteSeparators.Count; i++)
        {
            var item = _noteSeparators[i];
            var first = Move(item.X1, item.Y);
            var second = Move(item.X2, item.Y);
            _noteSeparators[i] = (first.X, second.X, first.Y);
        }

        if (_selectedFloating is { } selected)
            _selectedFloating = selected with { Rect = MoveRect(selected.Rect) };
        if (_selectedFloatingGroupChild is { } selectedChild)
            _selectedFloatingGroupChild = selectedChild with { Rect = MoveRect(selectedChild.Rect) };

        _contentHeight = _surfacePlan.ScrollableHeightForPages(
            _pageCount,
            Math.Max(0, _endnoteExtentDip));
        _pageFlowProjected = true;
    }

    private void ShiftBodyTuples(
        Func<double, double, double> offsetFor,
        Func<int, double, double, double> offsetForOwnedObject)
    {
        static Rect ShiftRect(Rect rect, Func<double, double, double> offset) =>
            new(rect.X, rect.Y + offset(rect.X, rect.Y), rect.Width, rect.Height);

        for (var i = 0; i < _markers.Count; i++)
        {
            var marker = _markers[i];
            _markers[i] = (marker.X, marker.Y + offsetFor(marker.X, marker.Y), marker.Text, marker.Fmt);
        }

        for (var i = 0; i < _tabLeaderSpans.Count; i++)
        {
            var span = _tabLeaderSpans[i];
            _tabLeaderSpans[i] = (span.X1, span.X2, span.Y + offsetFor(span.X1, span.Y), span.LineHeight,
                span.Leader, span.Fmt);
        }

        for (var i = 0; i < _automaticHyphenGlyphs.Count; i++)
        {
            var glyph = _automaticHyphenGlyphs[i];
            _automaticHyphenGlyphs[i] = glyph with
            {
                Y = glyph.Y + offsetFor(glyph.X, glyph.Y),
            };
        }

        for (var i = 0; i < _rects.Count; i++)
        {
            var item = _rects[i];
            _rects[i] = (ShiftRect(item.Rect, offsetFor), item.Fill,
                item.Border, item.CellBorderPlan);
        }

        for (var i = 0; i < _paragraphDecorations.Count; i++)
        {
            var item = _paragraphDecorations[i];
            _paragraphDecorations[i] = (ShiftRect(item.Rect, offsetFor),
                item.ShadingHex, item.Border);
        }

        for (var i = 0; i < _images.Count; i++)
        {
            var item = _images[i];
            _images[i] = (ShiftRect(item.Rect, (x, y) => offsetForOwnedObject(item.BlockIndex, x, y)), item.Image,
                item.Model, item.ReflectionPreset, item.BlockIndex);
        }

        for (var i = 0; i < _floatingImages.Count; i++)
        {
            var item = _floatingImages[i];
            _floatingImages[i] = (ShiftRect(item.Rect, (x, y) => offsetForOwnedObject(item.BlockIndex, x, y)), item.Image,
                item.Model, item.ReflectionPreset, item.BehindText, item.ZOrder, item.BlockIndex,
                item.RunIndex);
        }

        for (var i = 0; i < _cellHits.Count; i++)
        {
            var item = _cellHits[i];
            _cellHits[i] = (ShiftRect(item.Rect, (x, y) => offsetForOwnedObject(item.Block, x, y)), item.Block,
                item.Row, item.Col);
        }

        for (var i = 0; i < _shapeTextCaretStops.Count; i++)
        {
            var stop = _shapeTextCaretStops[i];
            var offset = offsetForOwnedObject(stop.BlockIndex, stop.X, stop.Y);
            _shapeTextCaretStops[i] = stop with
            {
                Y = stop.Y + offset,
                RotationCenterY = stop.RotationCenterY + offset
            };
        }
    }

    private void ShiftBodyObjects(Func<int, double, double, double> offsetForOwnedObject)
    {
        static Rect ShiftRectBy(Rect rect, double offset) =>
            new(rect.X, rect.Y + offset, rect.Width, rect.Height);

        static DocumentFloatRect ShiftPlannerRectBy(DocumentFloatRect rect, double offset) =>
            rect with { YDip = rect.YDip + offset };

        void ShiftShape(FloatingShapeData shape, double offset)
        {
            shape.Rect = ShiftRectBy(shape.Rect, offset);
        }

        void ShiftChart(FloatingChartData chart, double offset) => chart.Rect = ShiftRectBy(chart.Rect, offset);
        void ShiftWordArt(FloatingWordArtData wordArt, double offset) => wordArt.Rect = ShiftRectBy(wordArt.Rect, offset);
        void ShiftSmartArt(FloatingSmartArtData smartArt, double offset) => smartArt.Rect = ShiftRectBy(smartArt.Rect, offset);

        void ShiftGroup(FloatingGroupData group, double? inheritedOffset = null)
        {
            var offset = inheritedOffset
                ?? offsetForOwnedObject(group.BlockIndex, group.Rect.X, group.Rect.Y);
            group.Rect = ShiftRectBy(group.Rect, offset);
            foreach (var child in group.Children)
            {
                child.Rect = ShiftRectBy(child.Rect, offset);
                if (child.Shape is not null) ShiftShape(child.Shape, offset);
                if (child.Chart is not null) ShiftChart(child.Chart, offset);
                if (child.WordArt is not null) ShiftWordArt(child.WordArt, offset);
                if (child.SmartArt is not null) ShiftSmartArt(child.SmartArt, offset);
                if (child.Group is not null) ShiftGroup(child.Group, offset);
            }
        }

        foreach (var shape in _floatingShapes)
            ShiftShape(shape, offsetForOwnedObject(shape.BlockIndex, shape.Rect.X, shape.Rect.Y));
        foreach (var chart in _floatingCharts)
            ShiftChart(chart, offsetForOwnedObject(chart.BlockIndex, chart.Rect.X, chart.Rect.Y));
        foreach (var wordArt in _floatingWordArts)
            ShiftWordArt(wordArt, offsetForOwnedObject(wordArt.BlockIndex, wordArt.Rect.X, wordArt.Rect.Y));
        foreach (var smartArt in _floatingSmartArts)
            ShiftSmartArt(smartArt, offsetForOwnedObject(smartArt.BlockIndex, smartArt.Rect.X, smartArt.Rect.Y));
        foreach (var group in _floatingGroups) ShiftGroup(group);
        foreach (var shape in _inlineShapes)
            ShiftShape(shape, offsetForOwnedObject(shape.BlockIndex, shape.Rect.X, shape.Rect.Y));
        foreach (var chart in _inlineCharts)
            ShiftChart(chart, offsetForOwnedObject(chart.BlockIndex, chart.Rect.X, chart.Rect.Y));
        foreach (var wordArt in _inlineWordArts)
            ShiftWordArt(wordArt, offsetForOwnedObject(wordArt.BlockIndex, wordArt.Rect.X, wordArt.Rect.Y));
        foreach (var smartArt in _inlineSmartArts)
            ShiftSmartArt(smartArt, offsetForOwnedObject(smartArt.BlockIndex, smartArt.Rect.X, smartArt.Rect.Y));
        foreach (var embeddedObject in _inlineEmbeddedObjects)
        {
            embeddedObject.Rect = ShiftRectBy(
                embeddedObject.Rect,
                offsetForOwnedObject(
                    embeddedObject.BlockIndex,
                    embeddedObject.Rect.X,
                    embeddedObject.Rect.Y));
        }

        for (var i = 0; i < _floatingSnapshots.Count; i++)
        {
            var snapshot = _floatingSnapshots[i];
            var offset = offsetForOwnedObject(snapshot.BlockIndex, snapshot.Rect.XDip, snapshot.Rect.YDip);
            _floatingSnapshots[i] = snapshot with { Rect = ShiftPlannerRectBy(snapshot.Rect, offset) };
        }

        for (var i = 0; i < _wrapExclusions.Count; i++)
        {
            var zone = _wrapExclusions[i];
            var offset = offsetForOwnedObject(zone.BlockIndex, zone.Rect.XDip, zone.Rect.YDip);
            _wrapExclusions[i] = zone with { Rect = ShiftPlannerRectBy(zone.Rect, offset) };
        }

        for (var i = 0; i < _dropCapLayoutPlans.Count; i++)
        {
            var plan = _dropCapLayoutPlans[i];
            var offset = offsetForOwnedObject(plan.BlockIndex, plan.CapBox.XDip, plan.CapBox.YDip);
            _dropCapLayoutPlans[i] = plan with
            {
                CapBox = ShiftPlannerRectBy(plan.CapBox, offset),
                TextReservation = ShiftPlannerRectBy(plan.TextReservation, offset)
            };
        }

        if (_selectedFloating is { } selected)
        {
            var offset = offsetForOwnedObject(selected.BlockIndex, selected.Rect.X, selected.Rect.Y);
            _selectedFloating = selected with { Rect = ShiftRectBy(selected.Rect, offset) };
        }
        if (_selectedFloatingGroupChild is { } selectedChild)
        {
            var offset = offsetForOwnedObject(selectedChild.BlockIndex, selectedChild.Rect.X, selectedChild.Rect.Y);
            _selectedFloatingGroupChild = selectedChild with
            {
                Rect = ShiftRectBy(selectedChild.Rect, offset)
            };
        }
    }

    /// <summary>
    /// Iterates all body blocks and routes each to its layout path (paragraph/table/read-only).
    /// Extracted so <see cref="Relayout"/> can call it twice: a first pass to determine footnote-page
    /// assignment, and a second pass (DB1) with per-page band reservations active in
    /// <see cref="ReserveContentY"/> so body text reflows above the footnote band.
    /// </summary>
    private void RunBodyLayoutBlocks(double textWidth)
    {
        // The portable sequence planner owns per-level numbering, overrides, and continuation across
        // ordinary body paragraphs and interleaved bullets.
        var listMarkerSequence = new DocumentListMarkerSequencePlanner(
            _doc.MultiLevelList.NumberFormats);
        var preservedNumberingMarkers = PreservedNumberingMarkerPlanner.Build(_doc);
        var hiddenBlocks = HiddenOutlineBlockIndices();
        for (var blockIndex = 0; blockIndex < _doc.Blocks.Count; blockIndex++)
        {
            if (hiddenBlocks.Contains(blockIndex))
                continue;
            var block = _doc.Blocks[blockIndex];
            if (block is Paragraph paragraph)
            {
                if (paragraph.Formatting.PageBreakBefore)
                    AdvanceToNextPageBoundary(forceAdvance: false);

                // Route to the image-paragraph path only when the paragraph contains inline images.
                // Paragraphs whose images are ALL floating (anchored) are laid out as normal text
                // paragraphs so that the anchor content-Y is tracked; their images are collected
                // into _floatingImages by CollectFloatingObjects() called from within each layout method.
                var hasInlineImage   = paragraph.Runs.Any(r => r.Image    is { IsFloating: false });
                var hasInlineShape   = paragraph.Runs.Any(r => r.Shape    is { IsFloating: false });
                var hasInlineChart   = paragraph.Runs.Any(r => r.Chart    is { IsFloating: false });
                var hasInlineWordArt = paragraph.Runs.Any(r => r.WordArt  is { IsFloating: false });
                var hasInlineSmArt   = paragraph.Runs.Any(r => r.SmartArt is { IsFloating: false });
                var hasEmbeddedObject = paragraph.Runs.Any(r => r.EmbeddedObject is not null);
                var hasAnyImage    = paragraph.Runs.Any(r => r.Image is not null);
                if (hasAnyImage && !hasInlineShape && !hasInlineChart && !hasInlineWordArt && !hasInlineSmArt
                    && !hasEmbeddedObject)
                {
                    // Always collect floating images from this paragraph (done inside each layout path).
                    if (hasInlineImage)
                    {
                        // Mixed paragraph: inline image(s) present — use the image layout path which
                        // also calls CollectFloatingObjects internally.
                        // Non-list paragraph: reset all counters (list run ended).
                        listMarkerSequence.Reset();
                        LayoutImageParagraphPaged(blockIndex, paragraph, textWidth);
                        continue;
                    }
                    // Floating-only: fall through to normal paragraph layout below,
                    // which calls CollectFloatingObjects at the start of EmitLinePaged.
                }

                // FO4: route mixed inline drawing objects through the shared flow owner.
                if (hasInlineShape || hasInlineChart || hasInlineWordArt || hasInlineSmArt || hasEmbeddedObject)
                {
                    // Non-list paragraph: reset all counters (list run ended).
                    listMarkerSequence.Reset();
                    LayoutInlineObjectParagraphPaged(blockIndex, paragraph, textWidth);
                    continue;
                }

                var kind = paragraph.Formatting.ListKind;
                double inset = 0;
                string? marker = null;
                if (kind != ListKind.None)
                {
                    var markerPlan = listMarkerSequence.Advance(paragraph);
                    inset = ListIndentStep * (markerPlan.Level + 1);
                    marker = markerPlan.MarkerText;
                }
                else if (preservedNumberingMarkers.TryGetValue(blockIndex, out var preservedMarker))
                {
                    // Preserved numbering is Word-visible chrome, not a native FreeW list. Its counters
                    // are planned independently from the native list state and the marker is never added
                    // to editable cells or committed paragraph text. R132 MED fix: like any other non-list
                    // paragraph, it does not interrupt a native list's numbering -- Word continues the
                    // numbering across intervening non-list content unless a later Number/MultiLevel
                    // paragraph carries an explicit restart override (handled above).
                    inset = ListIndentStep * (preservedMarker.Level + 1);
                    marker = preservedMarker.Text;
                }
                else
                {
                    // R132 MED fix: a plain non-list (body text) paragraph does NOT end the numbered
                    // list run. Word continues numbering across intervening body text; only an explicit
                    // restart override on a later Number/MultiLevel paragraph resets a level's counter
                    // The shared sequence is intentionally left untouched here.
                }

                LayoutParagraphPaged(blockIndex, paragraph, textWidth, inset, marker);

                if (paragraph.SectionBreak is { BreakKind: not SectionBreakKind.Continuous } sectionBreak)
                    AdvanceToNextPageBoundary(forceAdvance: true, sectionBreak.BreakKind);
            }
            else if (block is Table table)
            {
                LayoutTablePaged(blockIndex, table, textWidth);
            }
            else
            {
                LayoutReadOnlyBlockPaged(blockIndex, block, textWidth);
            }
        }
    }

    private int CalculateBodyPageCount()
    {
        var lastSlot = _layoutContentY > 0 ? (int)(_layoutContentY / _layoutTextAreaHeight) : 0;
        return Math.Max(1, (int)Math.Ceiling((double)(lastSlot + 1) / Math.Max(1, _colCount)));
    }

    private bool HasVisibleBodySectionPagesFields() =>
        _doc.Blocks.Any(block => block switch
        {
            Paragraph paragraph => HasVisibleSectionPagesField(paragraph),
            Table table => table.Rows.SelectMany(row => row.Cells)
                .SelectMany(cell => cell.Paragraphs)
                .Any(HasVisibleSectionPagesField),
            _ => false,
        });

    private static bool HasVisibleSectionPagesField(Paragraph paragraph) =>
        paragraph.Runs.Any(run =>
            run.ComplexField is { ShowCode: false, Keyword: "SECTIONPAGES" });

    private void StabilizeBodySectionPageLayout(double textWidth)
    {
        const int MaxPasses = 8;
        var appliedCounts = (int[])_bodySectionPageCounts.Clone();
        var appliedBands = new Dictionary<int, double>(_footnoteBandHeightByPage);

        for (var pass = 0; pass < MaxPasses; pass++)
        {
            _bodyPageCount = CalculateBodyPageCount();
            if (_doc.Footnotes.Count > 0)
                ComputeFootnoteContinuationPlans();
            RebuildFootnotePhysicalPagePlan();
            _pageCount = Math.Max(1, _footnotePhysicalPagePlan.PhysicalPageCount);

            var desiredCounts = ComputeBodySectionPageCounts();
            var desiredBands = new Dictionary<int, double>(_footnoteBandHeightByPage);
            var stable = appliedCounts.SequenceEqual(desiredCounts)
                && FootnoteBandsEqual(appliedBands, desiredBands);

            _bodySectionPageCounts = desiredCounts;
            _contentHeight = _surfacePlan.ScrollableHeightForPages(_pageCount);
            if (stable)
                return;

            appliedCounts = (int[])desiredCounts.Clone();
            appliedBands = desiredBands;
            ResetBodyLayoutArtifacts();
            RunBodyLayoutBlocks(textWidth);
        }

        _bodyPageCount = CalculateBodyPageCount();
        if (_doc.Footnotes.Count > 0)
            ComputeFootnoteContinuationPlans();
        RebuildFootnotePhysicalPagePlan();
        _pageCount = Math.Max(1, _footnotePhysicalPagePlan.PhysicalPageCount);
        _contentHeight = _surfacePlan.ScrollableHeightForPages(_pageCount);
    }

    private int[] ComputeBodySectionPageCounts()
    {
        var sectionCount = Math.Max(1, _doc.Sections.Count);
        var pagesBySection = Enumerable.Range(0, sectionCount)
            .Select(_ => new HashSet<int>())
            .ToArray();
        var blockPageAssignments = ComputeBlockPageAssignments(_pageCount);
        var ownership = HeaderFooterPagePlanner.MapPagesToSections(_doc, blockPageAssignments, _pageCount);

        for (var page = 0; page < ownership.Count; page++)
            pagesBySection[Math.Clamp(ownership[page].SectionIndex, 0, sectionCount - 1)].Add(page);

        foreach (var placed in _placed)
        {
            if (placed.Sentinel || placed.Block < 0 || placed.Block >= _bodyBlockSectionAssignments.Length)
                continue;

            var logicalPage = Math.Clamp(
                PageIndexFromPageSpaceY(placed.Y),
                0,
                Math.Max(0, _bodyPageCount - 1));
            var physicalPage = PhysicalPageForBodyPage(logicalPage);
            var section = Math.Clamp(_bodyBlockSectionAssignments[placed.Block], 0, sectionCount - 1);
            pagesBySection[section].Add(physicalPage);
        }

        return pagesBySection.Select(pages => Math.Max(1, pages.Count)).ToArray();
    }

    private static bool FootnoteBandsEqual(
        IReadOnlyDictionary<int, double> left,
        IReadOnlyDictionary<int, double> right)
    {
        if (left.Count != right.Count)
            return false;
        return left.All(pair => right.TryGetValue(pair.Key, out var value)
            && Math.Abs(pair.Value - value) < 0.01);
    }

    private void ResetBodyLayoutArtifacts()
    {
        _placed.Clear();
        _markers.Clear();
        _rects.Clear();
        _paragraphDecorations.Clear();
        _images.Clear();
        _floatingImages.Clear();
        _floatingShapes.Clear();
        _floatingCharts.Clear();
        _floatingWordArts.Clear();
        _floatingSmartArts.Clear();
        _floatingGroups.Clear();
        _floatingSnapshots.Clear();
        _dropCapLayoutPlans.Clear();
        _wrapExclusions.Clear();
        _inlineShapes.Clear();
        _inlineCharts.Clear();
        _inlineWordArts.Clear();
        _inlineSmartArts.Clear();
        _inlineEmbeddedObjects.Clear();
        _equationVisualSegments.Clear();
        _equationVisualElements.Clear();
        _cellHits.Clear();
        _shapeTextCaretStops.Clear();
        _tabLeaderSpans.Clear();
        _automaticHyphenGlyphs.Clear();
        _layoutContentY = 0;
    }

    // ── HF: header/footer pre-computation ─────────────────────────────────────────────────────────

    /// <summary>
    /// Builds a mapping from 0-based page index to (SectionHeadersFooters, section-relative
    /// 1-based page number, PageSettings) for <paramref name="pageCount"/> pages.
    ///
    /// Mirrors WPF's PaginatedEditorPanel.ComputePageSectionMap: walks <see cref="_doc"/>.Blocks
    /// to assign each block a section index (incrementing at each SectionBreak paragraph), then
    /// uses <see cref="_placed"/> character positions to determine which page each block's content
    /// first appears on, giving a true block→page→section mapping.
    ///
    /// Fallback: when a section's HeadersFooters is entirely empty, substitutes
    /// <see cref="TextDocument.FinalSectionHeadersFooters"/> (AE3 fix).
    /// </summary>
    private IReadOnlyList<HeaderFooterPageSectionPlan> ComputePageSectionMap(int pageCount)
    {
        var blockPageAssignments = ComputeBlockPageAssignments(pageCount);
        return HeaderFooterPagePlanner.MapPagesToSections(_doc, blockPageAssignments, pageCount);
    }

    private int[] ComputeBlockPageAssignments(int pageCount)
    {
        var blocks = _doc.Blocks;
        var blockPageAssignments = Enumerable
            .Repeat(HeaderFooterPagePlanner.UnassignedBlockPageIndex, blocks.Count)
            .ToArray();

        foreach (var pc in _placed)
        {
            var b = pc.Block;
            if (b < 0 || b >= blocks.Count) continue;
            if (blockPageAssignments[b] >= 0) continue;

            var logicalPage = Math.Clamp(
                PageIndexFromPageSpaceY(pc.Y),
                0,
                Math.Max(0, _bodyPageCount - 1));
            var pg = _footnotePhysicalPagePlan.PhysicalPageCount > 0
                ? PhysicalPageForBodyPage(logicalPage)
                : logicalPage;
            blockPageAssignments[b] = Math.Clamp(pg, 0, pageCount - 1);
        }

        return blockPageAssignments;
    }

    private int[] ComputeBlockSectionAssignments()
    {
        var sections = _doc.Sections;
        var assignments = new int[_doc.Blocks.Count];
        var sectionIndex = 0;
        for (var blockIndex = 0; blockIndex < _doc.Blocks.Count; blockIndex++)
        {
            assignments[blockIndex] = Math.Min(sectionIndex, sections.Count - 1);
            if (_doc.Blocks[blockIndex] is Paragraph { SectionBreak: not null })
                sectionIndex++;
        }

        return assignments;
    }

    /// <summary>
    /// AV-HFEDIT: builds a stable <see cref="HfTarget"/> for a resolved HF store + slot. Identifies the
    /// store either as the document-level final-section store (which the document-level Header/Footer views
    /// alias) or by reference-equality with a section's own store.
    /// </summary>
    private HfTarget MakeHfTarget(
        SectionHeadersFooters sectionHf,
        HeaderFooterSlotKind slot,
        int paraIdx)
    {
        if (ReferenceEquals(sectionHf, _doc.FinalSectionHeadersFooters))
            return new HfTarget(_doc.Sections.Count - 1, UseFinalSectionStore: true, slot, paraIdx);
        for (var i = 0; i < _doc.Sections.Count; i++)
        {
            if (ReferenceEquals(_doc.Sections[i].HeadersFooters, sectionHf))
                return new HfTarget(i, UseFinalSectionStore: false, slot, paraIdx);
        }
        // Defensive fallback: treat as the final-section store.
        return new HfTarget(_doc.Sections.Count - 1, UseFinalSectionStore: true, slot, paraIdx);
    }

    /// <summary>
    /// AV-HFEDIT: true when the active header/footer caret targets the given resolved store + slot. Used so
    /// the layout still emits an (empty) editable band for a freshly-clicked or just-emptied slot.
    /// </summary>
    private bool HfCaretTargets(SectionHeadersFooters sectionHf, HeaderFooterSlotKind slot)
    {
        if (_hfCaret is not { } hc || hc.Target.Slot != slot)
            return false;
        var caretStore = ResolveHfStore(hc.Target);
        return ReferenceEquals(caretStore, sectionHf);
    }

    /// <summary>
    /// Pre-computes the header/footer render items for each page in PrintLayout mode.
    /// Called once per Relayout pass after _pageCount is known. Each item carries a
    /// field-resolved text string, run formatting, page-space position, and alignment so
    /// Render() can draw them with zero model access.
    /// </summary>
    private void BuildHeaderFooterItems()
    {
        // Default fallback header/footer distance: Word default 0.5 in = 36 pt.
        const double DefaultHfDistancePt = 36.0;

        var diffOddEven = HeaderFooterPagePlanner.UsesDifferentOddEvenPages(_doc);

        // Build a true page-to-section map from Avalonia's placed block positions.
        var blockPageAssignments = ComputeBlockPageAssignments(_pageCount);
        var pageToSection = HeaderFooterPagePlanner.MapPagesToSections(_doc, blockPageAssignments, _pageCount);
        var pageNumberDisplay = PageNumberFormatDialogPlanner.BuildDisplayPlans(
            pageToSection,
            _doc,
            blockPageAssignments);

        for (var pi = 0; pi < _pageCount; pi++)
        {
            // Page-space top of this page.
            var pageTop = _surfacePlan.PageTopDip(pi);

            // AE1: use the true owning section for this page (not an even distribution).
            var pageSection = pageToSection[pi];
            var sectionHf = pageSection.HeadersFooters;
            var sectionPage = pageSection.PageSettings;

            var pageNumberText = pageNumberDisplay[pi].Text;

            // Resolve header/footer slots through the shared Presentation planner.
            var slots = HeaderFooterPagePlanner.ResolveSlots(
                sectionHf,
                pageSection.SectionRelativePageNumber,
                sectionPage,
                diffOddEven,
                pageNumberDisplay[pi].LogicalPageNumber);
            var header = slots.Header;
            var footer = slots.Footer;
            var headerSlot = slots.HeaderSlot;
            var footerSlot = slots.FooterSlot;

            // Header distance from page top (in DIP).
            var headerDistPt = sectionPage.HeaderDistancePt > 0
                ? sectionPage.HeaderDistancePt
                : DefaultHfDistancePt;
            var headerDistDip = headerDistPt * PxPerPoint;

            // Footer distance from page bottom (in DIP).
            var footerDistPt = sectionPage.FooterDistancePt > 0
                ? sectionPage.FooterDistancePt
                : DefaultHfDistancePt;
            var footerDistDip = footerDistPt * PxPerPoint;

            // Render-width = page content width (use same as body text area).
            var hfWidth = _contentWidth;

            // AV-HFEDIT: emit an empty (but editable) band when the H/F caret is active in this slot even if
            // the slot has no visible content yet — so a freshly-clicked/empty header still renders + edits.
            var headerActive = header is not null && (!header.IsEmpty || HfCaretTargets(sectionHf, headerSlot));
            var footerActive = footer is not null && (!footer.IsEmpty || HfCaretTargets(sectionHf, footerSlot));

            // Emit header.
            if (headerActive)
            {
                var hfY = pageTop + headerDistDip;
                EmitHfParagraphs(header!, hfY, hfWidth, pageNumberText, _pageCount,
                    pi => MakeHfTarget(sectionHf, headerSlot, pi),
                    slots.HeaderSlot,
                    pi + 1,
                    pageSection.SectionIndex + 1,
                    pageSection.SectionRelativePageNumber,
                    pageSection.SectionPageCount);
            }

            // Emit footer.
            if (footerActive)
            {
                // Footer distance is from the BOTTOM of the page upward; the footer text
                // starts at: pageBottom - footerDistDip (+ a line-height offset per line).
                var pageBottom = pageTop + _pageHeightPx;
                var hfY = pageBottom - footerDistDip;
                EmitHfParagraphs(footer!, hfY, hfWidth, pageNumberText, _pageCount,
                    pi => MakeHfTarget(sectionHf, footerSlot, pi),
                    slots.FooterSlot,
                    pi + 1,
                    pageSection.SectionIndex + 1,
                    pageSection.SectionRelativePageNumber,
                    pageSection.SectionPageCount);
            }
        }
    }

    /// <summary>
    /// Emits <see cref="HfRenderItem"/>s for each paragraph line of a header/footer slot.
    /// Field runs (PAGE, NUMPAGES, DATE, FILENAME) are resolved to display strings here.
    /// Tab characters are interpreted as Word's default centre-tab (midpoint) and right-tab (right edge),
    /// mirroring Word's "Title[TAB]Center[TAB]Page" HF pattern. Explicit paragraph TabStops override the
    /// defaults when present. Each tab-separated segment is emitted as a separate HfRenderItem at the
    /// computed X position so the draw loop does not need tab-aware logic.
    /// </summary>
    private double EmitHfParagraphs(
        HeaderFooter hf,
        double startY,
        double availWidth,
        string pageNumberText,
        int pageCount,
        Func<int, HfTarget>? targetFactory,
        HeaderFooterSlotKind slot,
        int pageNumber = 1,
        int sectionOrdinal = 1,
        int sectionRelativePageNumber = 1,
        int sectionPageCount = 1)
    {
        var slotName = HeaderFooterDialogPlanner.SlotNameFor(slot);
        // Preserved side-by-side layout table (e.g. Word's classic Left/Center/Right header/footer
        // building block — see HeaderFooter.Table / DocxReader.IsSingleTableHeaderFooterContent): lay the
        // row's cells out side-by-side instead of falling through to the linear paragraph loop below,
        // which would stack them vertically and destroy the authored layout.
        if (hf.Table is { Rows.Count: > 0 } table)
        {
            return EmitHfTable(
                table, startY, availWidth, pageNumberText, pageCount,
                slot, pageNumber, sectionOrdinal, sectionRelativePageNumber, sectionPageCount);
        }

        var y = startY;
        for (var paraIdx = 0; paraIdx < hf.Paragraphs.Count; paraIdx++)
        {
            var para = hf.Paragraphs[paraIdx];
            var pf = ResolveParagraphFmt(para);
            var paraTarget = targetFactory?.Invoke(paraIdx);

            // Build segments split on TAB characters.
            // Each entry carries (tabStopIndex, Text, Fmt, ModelStart):
            //   tabStopIndex 0 → segment before the first tab (left-aligned at X=_contentLeft)
            //   tabStopIndex 1 → segment after the first tab (centre stop)
            //   tabStopIndex 2 → segment after the second tab (right stop)
            // Multiple consecutive tabs advance the index so the ordinal is always correct even
            // if some slots carry empty text (e.g. "Left\t\tRight" puts "Right" at stop 2).
            // AV-HFEDIT: ModelStart is the literal-model-text offset where the segment's first char
            // begins, so a click X maps to a model offset for the editing caret. Model offset advances
            // by run.Text.Length for each run (field runs are atomic — their resolved text may differ in
            // length, but the model span is run.Text.Length, including a single tab char per model tab).
            var segments = new List<HfSegment>();
            var sb = new System.Text.StringBuilder();
            RunFormatting segFmt = para.Runs.Count > 0 ? para.Runs[0].Formatting : RunFormatting.Default;
            var stopIndex = 0;
            var modelOffset = 0;       // running literal-model offset across all runs
            var segModelStart = 0;     // model offset at the start of the current (buffered) segment
            var fieldResolutionContext = new HeaderFooterFieldResolutionContext(
                _doc,
                pageNumberText,
                pageCount,
                sectionOrdinal,
                sectionPageCount,
                DateTime.Now,
                Culture: CultureInfo.CurrentCulture);

            void FlushText(bool includeEmpty = false)
            {
                if (sb.Length == 0 && !includeEmpty)
                    return;

                segments.Add(new HfSegment
                {
                    StopIndex = stopIndex,
                    Text = sb.ToString(),
                    Fmt = segFmt,
                    ModelStart = segModelStart,
                });
                sb.Clear();
                segModelStart = modelOffset;
            }

            for (var runIndex = 0; runIndex < para.Runs.Count; runIndex++)
            {
                var run = para.Runs[runIndex];
                var effectiveFormatting = ResolveRunFmt(run.Formatting, para);
                if (sb.Length > 0 && effectiveFormatting != segFmt)
                    FlushText();
                segFmt = effectiveFormatting;
                if (IsTextHiddenInCurrentView(effectiveFormatting))
                {
                    FlushText();
                    modelOffset += run.Text.Length;
                    segModelStart = modelOffset;
                    continue;
                }

                var fieldText = HeaderFooterVisualPlanner.ResolveFieldText(run, fieldResolutionContext);
                var isField = fieldText is not null;
                var text = fieldText ?? run.Text;
                if (run.Image is { } image)
                {
                    FlushText();
                    var width = Math.Max(1, PageLayout.PointsToDip(Math.Max(0, image.WidthPt)));
                    var height = Math.Max(1, PageLayout.PointsToDip(Math.Max(0, image.HeightPt)));
                    segments.Add(new HfSegment
                    {
                        StopIndex = stopIndex,
                        Image = image,
                        ImageSignature = HeaderFooterVisualPlanner.BuildImageSignature(
                            slotName,
                            pageNumber,
                            sectionOrdinal,
                            sectionRelativePageNumber,
                            paraIdx,
                            runIndex,
                            image,
                            pf.Alignment),
                        Fmt = effectiveFormatting,
                        ModelStart = modelOffset,
                        Width = width,
                        Height = height,
                    });
                    modelOffset += run.Text.Length;
                    segModelStart = modelOffset;
                    continue;
                }

                if (run.EmbeddedObject is { } embeddedObject)
                {
                    FlushText();
                    var plan = EmbeddedObjectVisualPlanner.Build(embeddedObject);
                    segments.Add(new HfSegment
                    {
                        StopIndex = stopIndex,
                        EmbeddedObject = plan,
                        EmbeddedObjectIcon = plan.Icon is null ? null : DecodeRenderedImage(plan.Icon),
                        Fmt = effectiveFormatting,
                        ModelStart = modelOffset,
                        RunIndex = runIndex,
                        Width = plan.WidthPt * PxPerPoint,
                        Height = plan.HeightPt * PxPerPoint,
                    });
                    modelOffset += run.Text.Length;
                    segModelStart = modelOffset;
                    continue;
                }

                if (isField)
                {
                    // Atomic field run: append its resolved text whole (no tab-splitting inside a field).
                    sb.Append(text);
                    modelOffset += run.Text.Length;
                    continue;
                }

                // Split the literal run text on tab characters; model offset advances per literal char.
                var parts = text.Split('\t');
                for (var pi = 0; pi < parts.Length; pi++)
                {
                    sb.Append(parts[pi]);
                    modelOffset += parts[pi].Length;
                    if (pi < parts.Length - 1)
                    {
                        // A TAB was consumed — flush the current buffer as a segment and advance the stop index.
                        FlushText(includeEmpty: true);
                        stopIndex++;
                        modelOffset += 1;            // the consumed tab is one model char
                        segModelStart = modelOffset; // next segment starts after the tab
                    }
                }
            }
            // Flush the final (or only) segment.
            FlushText(includeEmpty: segments.Count == 0);

            // Whether the paragraph contains any tab characters at all.
            var hasAnyTab = segments.Count > 1 || (segments.Count == 1 && stopIndex > 0);
            var hasVisualObjects = segments.Any(s => s.Image is not null || s.EmbeddedObject is not null);

            // Compute the line height from the first non-empty segment (or use DefaultFontSizePt).
            var lineH = DefaultFontSizePt * PxPerPoint * 1.3;
            foreach (var segment in segments)
            {
                if (segment.Image is not null || segment.EmbeddedObject is not null)
                {
                    lineH = Math.Max(lineH, segment.Height);
                    continue;
                }

                if (!string.IsNullOrEmpty(segment.Text))
                {
                    var sampleText = segment.Text.Length > 1 ? segment.Text[..1] : segment.Text;
                    lineH = Math.Max(lineH, Build(sampleText, segment.Fmt).Height * 1.15);
                }
            }

            // Resolve explicit tab stops from the paragraph; sort by position.
            var explicitStops = pf.TabStops
                .Where(stop => !stop.IsClear)
                .OrderBy(t => t.PositionPt)
                .Select(t => (PosPx: t.PositionPt * PxPerPoint, t.Alignment))
                .ToList();

            // Default Word H/F tab stops: centre at midpoint, right at full width.
            var defaultCenterPx = availWidth / 2.0;
            var defaultRightPx  = availWidth;

            double SegmentWidth(HfSegment segment) =>
                segment.Image is not null || segment.EmbeddedObject is not null
                    ? segment.Width
                    : string.IsNullOrEmpty(segment.Text)
                        ? 0
                        : Build(segment.Text, segment.Fmt).WidthIncludingTrailingWhitespace;

            void AddSegmentItem(HfSegment segment, double itemX)
            {
                var width = SegmentWidth(segment);
                _headerFooterItems.Add(new HfRenderItem
                {
                    Text             = segment.Text,
                    Fmt              = segment.Fmt,
                    Image            = segment.Image,
                    ImageSignature   = segment.ImageSignature,
                    EmbeddedObject   = segment.EmbeddedObject,
                    EmbeddedObjectIcon = segment.EmbeddedObjectIcon,
                    RunIndex         = segment.RunIndex,
                    Slot             = slot,
                    Width            = width,
                    Height           = segment.Image is not null || segment.EmbeddedObject is not null
                        ? segment.Height
                        : lineH,
                    X                = itemX,
                    Y                = y,
                    AvailableWidth   = 0,
                    Alignment        = TextAlignment.Left,
                    Target           = segment.Image is null && segment.EmbeddedObject is null ? paraTarget : null,
                    LineHeight       = lineH,
                    ModelStartOffset = segment.ModelStart,
                    OwnerTarget      = paraTarget,
                });
            }

            if (!hasAnyTab && !hasVisualObjects)
            {
                // No tabs — use paragraph alignment as before. Emit even an EMPTY paragraph so an empty
                // header/footer line is still clickable for editing (the caret needs a region to land in).
                var seg = segments[0];
                _headerFooterItems.Add(new HfRenderItem
                {
                    Text             = seg.Text,
                    Fmt              = seg.Fmt,
                    Slot             = slot,
                    X                = _contentLeft,
                    Y                = y,
                    AvailableWidth   = availWidth,
                    Alignment        = pf.Alignment,
                    Target           = paraTarget,
                    LineHeight       = lineH,
                    ModelStartOffset = seg.ModelStart,
                });
            }
            else if (!hasAnyTab)
            {
                var visible = segments
                    .Where(s => s.Image is not null || s.EmbeddedObject is not null || !string.IsNullOrEmpty(s.Text))
                    .ToList();
                if (visible.Count == 0)
                {
                    _headerFooterItems.Add(new HfRenderItem
                    {
                        Slot             = slot,
                        X                = _contentLeft,
                        Y                = y,
                        AvailableWidth   = availWidth,
                        Alignment        = pf.Alignment,
                        Target           = paraTarget,
                        LineHeight       = lineH,
                    });
                }
                else
                {
                    var totalWidth = visible.Sum(SegmentWidth);
                    var cursor = _contentLeft + AlignmentOffset(pf.Alignment, availWidth, totalWidth, isLast: true);
                    cursor = Math.Max(_contentLeft, Math.Min(_contentLeft + Math.Max(0, availWidth - totalWidth), cursor));
                    foreach (var segment in visible)
                    {
                        AddSegmentItem(segment, cursor);
                        cursor += SegmentWidth(segment);
                    }
                }
            }
            else
            {
                // Tab-split: each segment is positioned by its tab-stop ordinal.
                // StopIndex 0 → left (at _contentLeft, no stop lookup needed).
                // StopIndex 1 → first tab stop  (default: centre).
                // StopIndex 2 → second tab stop (default: right).
                foreach (var group in segments.GroupBy(s => s.StopIndex).OrderBy(g => g.Key))
                {
                    var visible = group
                        .Where(s => s.Image is not null || s.EmbeddedObject is not null || !string.IsNullOrEmpty(s.Text))
                        .ToList();
                    if (visible.Count == 0)
                        continue;

                    double stopX;
                    TabStopAlignment stopAlign;
                    var si = group.Key;

                    if (si == 0)
                    {
                        stopX     = 0; // relative to _contentLeft
                        stopAlign = TabStopAlignment.Left;
                    }
                    else
                    {
                        // Tab stop ordinal within the explicit list is (si - 1).
                        var stopIdx = si - 1;
                        if (stopIdx < explicitStops.Count)
                        {
                            (stopX, stopAlign) = explicitStops[stopIdx];
                        }
                        else
                        {
                            // Fall back to Word defaults for ordinal within the default set.
                            if (si == 1) { stopX = defaultCenterPx; stopAlign = TabStopAlignment.Center; }
                            else         { stopX = defaultRightPx;  stopAlign = TabStopAlignment.Right;  }
                        }
                    }

                    // Measure segment text to compute the draw X.
                    var groupWidth = visible.Sum(SegmentWidth);

                    var itemX = stopAlign switch
                    {
                        TabStopAlignment.Center  => _contentLeft + stopX - groupWidth / 2,
                        TabStopAlignment.Right   => _contentLeft + stopX - groupWidth,
                        TabStopAlignment.Decimal => _contentLeft + stopX - groupWidth, // approximation: treat as right
                        _                        => _contentLeft + stopX,
                    };
                    // Clamp to content area so text never overflows the page edge.
                    itemX = Math.Max(_contentLeft, Math.Min(_contentLeft + availWidth - groupWidth, itemX));

                    var cursor = itemX;
                    foreach (var segment in visible)
                    {
                        AddSegmentItem(segment, cursor);
                        cursor += SegmentWidth(segment);
                    }
                }
            }

            y += lineH;
        }

        return y;
    }

    /// <summary>
    /// Lays out a preserved header/footer layout <see cref="Table"/>'s rows side-by-side: each row's cells
    /// get an X-slice of <paramref name="totalWidth"/> (from the table's authored column widths, scaled to
    /// fit, or split evenly when no widths are known) and their paragraphs are laid out via the SAME
    /// per-paragraph tab/field/image logic <see cref="EmitHfParagraphs"/> uses for the common (non-table)
    /// case — reusing that logic instead of duplicating it. <see cref="_contentLeft"/> is temporarily
    /// pointed at each cell's X so the reused logic's existing <c>_contentLeft</c>-relative math (alignment,
    /// tab stops, clamping) lands the cell's content in the right column; it is restored afterward.
    /// Table-cell paragraphs are not wired to the click-to-edit caret target (<c>targetFactory: null</c>) —
    /// editing inside a preserved header/footer table is a follow-up, not part of this rendering fix.
    /// Returns the Y position after the table's last row.
    /// </summary>
    private double EmitHfTable(
        Table table,
        double startY,
        double totalWidth,
        string pageNumberText,
        int pageCount,
        HeaderFooterSlotKind slot,
        int pageNumber,
        int sectionOrdinal,
        int sectionRelativePageNumber,
        int sectionPageCount)
    {
        var savedContentLeft = _contentLeft;
        var y = startY;
        try
        {
            foreach (var row in table.Rows)
            {
                if (row.Cells.Count == 0)
                    continue;

                var widths = ResolveHfTableColumnWidths(table, row, totalWidth);
                var cellX = savedContentLeft;
                var rowEndY = y;
                for (var cellIndex = 0; cellIndex < row.Cells.Count; cellIndex++)
                {
                    var cell = row.Cells[cellIndex];
                    var cellWidth = cellIndex < widths.Count ? widths[cellIndex] : totalWidth / row.Cells.Count;
                    _contentLeft = cellX;
                    var cellHf = new HeaderFooter();
                    cellHf.Paragraphs.AddRange(cell.Paragraphs);
                    var cellEndY = EmitHfParagraphs(
                        cellHf, y, cellWidth, pageNumberText, pageCount,
                        targetFactory: null, slot, pageNumber, sectionOrdinal, sectionRelativePageNumber,
                        sectionPageCount);
                    rowEndY = Math.Max(rowEndY, cellEndY);
                    cellX += cellWidth;
                }

                y = rowEndY;
            }
        }
        finally
        {
            _contentLeft = savedContentLeft;
        }

        return y;
    }

    /// <summary>
    /// Resolves the DIP width of each cell in a header/footer layout table's row: the table's authored
    /// column widths (<see cref="Table.ColumnWidthsPt"/>), proportionally scaled so they sum to
    /// <paramref name="totalWidthDip"/>, or an even split across the row's cells when no authored widths
    /// are known (or they don't cover every cell).
    /// </summary>
    private static List<double> ResolveHfTableColumnWidths(Table table, TableRow row, double totalWidthDip)
    {
        var count = row.Cells.Count;
        if (count == 0)
            return [];

        if (table.ColumnWidthsPt.Count >= count)
        {
            var relevant = table.ColumnWidthsPt.Take(count).ToList();
            var sum = relevant.Sum();
            if (sum > 0)
                return relevant.Select(w => w / sum * totalWidthDip).ToList();
        }

        var even = totalWidthDip / count;
        return Enumerable.Repeat(even, count).ToList();
    }

    // ── AV-NOTERENDER: footnote / endnote content rendering ───────────────────────────────────────────

    /// <summary>Default font size (pt) for footnote / endnote body text. Word uses 10pt; we use 9pt.</summary>
    private const double NoteFontSizePt = 9.0;
    private const double FootnoteSeparatorHeight = 6.0;
    // Word leaves a little more room between the separator and first note, then preserves
    // paragraph-like space between consecutive notes and below the final note.
    private const double FootnoteTopPadding = 7.0;
    private const double FootnoteInterNoteSpacing = 15.0;
    private const double FootnoteTrailingPadding = 6.0;
    // Word reserves a small additional body-frame clearance above a footnote band.
    // Keep that reserve out of the painted note geometry; it only controls reflow.
    private const double FootnoteBodyReserveSafetyDip = 24.0;
    private const double EndnoteAfterBodyGap = 20.0;
    private const double EndnoteSeparatorToTextGap = 7.0;
    private const double EndnoteInterNoteSpacing = 15.0;
    private const double EndnoteTrailingPadding = 6.0;

    /// <summary>
    /// DB2: Measures the true wrapped height of a single note's content (number prefix + paragraph text)
    /// without emitting any render items. Mirrors the word-wrap logic of <see cref="LayoutNoteContent"/>
    /// but just returns the final Y extent (height from the starting Y).
    /// Used by <see cref="BuildFootnoteItems"/> to compute the accurate band height for reservation and
    /// clamping, instead of the previous 1-line-per-note estimate.
    /// </summary>
    private double MeasureNoteContentHeight(string number, IReadOnlyList<Paragraph> content, double x, double availWidth)
        => LayoutNoteContentCore(number, content, x, y: 0, availWidth: availWidth, emitItems: false);

    /// <summary>
    /// DB3: Computes the display number string for a note (footnote or endnote) given its
    /// 1-based sequence index and the <see cref="NoteNumberingOptions"/> that govern its format.
    /// <para>
    /// Examples: decimal 3 → "3"; lowerRoman 4 → "iv"; lowerLetter 2 → "b";
    /// Chicago 1 → "*", 2 → "†", 3 → "‡", 4 → "§", then repeats.
    /// </para>
    /// </summary>
    private static string ComputeNoteDisplayNumber(int sequenceIndex, NoteNumberingOptions opts)
        => NoteNumberFormatter.Format(sequenceIndex, opts);

    /// <summary>
    /// Resolves the 0-based page index that hosts the body reference for the note with the given id.
    /// Locates the body run carrying <paramref name="footnote"/>'s matching <see cref="Run.FootnoteId"/>
    /// (or <see cref="Run.EndnoteId"/>), computes its first character's cell offset within the host
    /// paragraph, then reads the page of the matching <see cref="PlacedChar"/>. Returns the last body
    /// page when no placed glyph is found (an acceptable approximation when a marker glyph was not laid
    /// out, e.g. a zero-width run).
    /// </summary>
    private int ResolveNoteReferencePage(int id, bool footnote)
    {
        var blocks = _doc.Blocks;
        for (var b = 0; b < blocks.Count; b++)
        {
            if (blocks[b] is not Paragraph para) continue;
            var offset = 0;
            foreach (var run in para.Runs)
            {
                var isMatch = footnote ? run.FootnoteId == id : run.EndnoteId == id;
                if (isMatch && run.Text.Length > 0)
                {
                    // Find the placed glyph for this paragraph at the run's first char offset.
                    foreach (var pc in _placed)
                    {
                        if (pc.Sentinel || pc.Block != b) continue;
                        if (pc.Offset == offset)
                            return Math.Clamp(RenderedPageIndexForPoint(pc.X, pc.Y), 0, Math.Max(0, _pageCount - 1));
                    }
                    // Run matched but no placed glyph at that offset — fall back to any glyph on the block.
                    foreach (var pc in _placed)
                    {
                        if (pc.Sentinel || pc.Block != b) continue;
                        return Math.Clamp(RenderedPageIndexForPoint(pc.X, pc.Y), 0, Math.Max(0, _pageCount - 1));
                    }
                }
                offset += run.Text.Length;
            }
        }
        // No reference glyph found — group on the last body page (documented approximation).
        return Math.Max(0, _pageCount - 1);
    }

    /// <summary>
    /// Lays out a single note's content (number + paragraph text) into <see cref="_noteItems"/> starting
    /// at page-space (<paramref name="x"/>, <paramref name="y"/>), wrapping within <paramref name="availWidth"/>.
    /// Reuses the body <see cref="Build"/> glyph metrics at <see cref="NoteFontSizePt"/>. The number prefix
    /// ("<c>n </c>") is emitted as a superscript-styled lead item; the note text follows as wrapped lines.
    /// Returns the page-space Y just past the laid-out content (the next free line).
    /// </summary>
    private double LayoutNoteContent(string number, IReadOnlyList<Paragraph> content, double x, double y, double availWidth)
        => LayoutNoteContentCore(number, content, x, y, availWidth, emitItems: true);

    private double LayoutNoteContentCore(
        string number,
        IReadOnlyList<Paragraph> content,
        double x,
        double y,
        double availWidth,
        bool emitItems)
    {
        var noteFmt = RunFormatting.Default with { FontSizePt = NoteFontSizePt };
        var numFmt  = noteFmt with { VerticalAlign = VerticalAlign.Superscript };
        var lineH = Math.Max(1, Build("Ag", noteFmt).Height);
        var right = x + availWidth;

        void AddItem(string text, RunFormatting formatting, double itemX, double itemY)
        {
            if (emitItems && !string.IsNullOrEmpty(text))
                _noteItems.Add(new NoteRenderItem { Text = text, Fmt = formatting, X = itemX, Y = itemY });
        }

        // Emit the number marker first (superscript), then the text flows after it on the same line.
        var numText = string.IsNullOrEmpty(number) ? string.Empty : number + " ";
        var numWidth = BuildForLayout(numText, numFmt).WidthIncludingTrailingWhitespace;
        AddItem(numText, numFmt, x, y);

        var textLeft = x + numWidth;
        var penX = textLeft;
        var lineVisibleRight = textLeft;
        var lineY = y;
        var lineHasContent = false;

        // Flatten the note's paragraphs into a single wrapped flow (note content is usually one paragraph).
        var first = true;
        foreach (var para in content)
        {
            if (!first)
            {
                // New paragraph in the note: break to a fresh line at the text-left indent.
                lineY += lineH;
                penX = textLeft;
                lineVisibleRight = textLeft;
                lineHasContent = false;
            }
            first = false;
            var consecutiveAutomaticHyphenLines = 0;

            var visibleText = DocumentNoteRegionPlanner.ResolveVisiblePlainText(_doc, [para]);
            var words = visibleText.Split(' ');
            for (var wi = 0; wi < words.Length; wi++)
            {
                var word = wi == words.Length - 1 ? words[wi] : words[wi] + " ";
                if (word.Length == 0) continue;

                var coreLength = word.TrimEnd(' ').Length;
                var core = word[..coreLength];
                var trailing = word[coreLength..];
                var automaticOffsets = AutomaticHyphenationDisplayPlanner.BuildBreakOffsets(
                        core,
                        _doc.Page,
                        ResolveParagraphFmt(para))
                    .Where(offset => offset > 0 && offset < core.Length)
                    .Distinct()
                    .OrderBy(offset => offset)
                    .ToArray();
                var segmentStart = 0;

                while (segmentStart < core.Length || (core.Length == 0 && trailing.Length > 0))
                {
                    var remaining = core[segmentStart..] + trailing;
                    var remainingWidth = Build(remaining, noteFmt).WidthIncludingTrailingWhitespace;
                    if (penX + remainingWidth > right)
                    {
                        var available = Math.Max(0, right - penX);
                        var automaticBreakAt = -1;
                        foreach (var offset in automaticOffsets)
                        {
                            if (offset <= segmentStart)
                                continue;
                            var candidate = core[segmentStart..offset] + "-";
                            if (Build(candidate, noteFmt).WidthIncludingTrailingWhitespace <= available)
                                automaticBreakAt = offset;
                        }

                        var trailingWhitespacePt = lineHasContent
                            ? Math.Max(0, right - lineVisibleRight) / PxPerPoint
                            : 0;
                        var useAutomaticHyphen = automaticBreakAt > segmentStart
                            && AutomaticHyphenationDisplayPlanner.AllowsAutomaticLineBreak(
                                _doc.Page,
                                consecutiveAutomaticHyphenLines,
                                lineHasContent,
                                trailingWhitespacePt);
                        if (useAutomaticHyphen)
                        {
                            var fragment = core[segmentStart..automaticBreakAt] + "-";
                            AddItem(fragment, noteFmt, penX, lineY);
                            lineY += lineH;
                            penX = textLeft;
                            lineVisibleRight = textLeft;
                            lineHasContent = false;
                            segmentStart = automaticBreakAt;
                            consecutiveAutomaticHyphenLines++;
                            continue;
                        }

                        if (lineHasContent)
                        {
                            lineY += lineH;
                            penX = textLeft;
                            lineVisibleRight = textLeft;
                            lineHasContent = false;
                            consecutiveAutomaticHyphenLines = 0;
                            continue;
                        }

                        // An overlong first word still needs a non-hyphenated line when the consecutive
                        // limit rejects the next candidate. This mirrors the body wrapper's hard fallback.
                        var hardBreakAt = segmentStart;
                        if (automaticOffsets.Any(offset => offset > segmentStart))
                        {
                            for (var offset = segmentStart + 1; offset <= core.Length; offset++)
                            {
                                if (Build(core[segmentStart..offset], noteFmt).WidthIncludingTrailingWhitespace <= available)
                                    hardBreakAt = offset;
                            }
                        }
                        if (hardBreakAt > segmentStart && hardBreakAt < core.Length)
                        {
                            AddItem(core[segmentStart..hardBreakAt], noteFmt, penX, lineY);
                            lineY += lineH;
                            penX = textLeft;
                            lineVisibleRight = textLeft;
                            lineHasContent = false;
                            segmentStart = hardBreakAt;
                            consecutiveAutomaticHyphenLines = 0;
                            continue;
                        }
                    }

                    AddItem(remaining, noteFmt, penX, lineY);
                    if (core.Length > segmentStart)
                    {
                        lineVisibleRight = penX
                            + Build(core[segmentStart..], noteFmt).WidthIncludingTrailingWhitespace;
                        lineHasContent = true;
                    }
                    penX += remainingWidth;
                    break;
                }
            }
        }

        return lineY + lineH;
    }

    /// <summary>
    /// Plans the first page of a footnote in its reference page band and moves only the remaining
    /// fragments onto inserted physical pages. This avoids the old global-height reservation, which could
    /// leave every following body page with only one line of usable content.
    /// </summary>
    private void ComputeFootnoteContinuationPlans()
    {
        _footnoteBandHeightByPage.Clear();
        _footnoteContinuationByBodyPage.Clear();
        if (_doc.Footnotes.Count == 0) return;

        // Group footnote ids by the page hosting their reference (using first-pass placed positions).
        var byPage = new Dictionary<int, List<int>>();
        foreach (var id in _doc.Footnotes.Keys.OrderBy(k => k))
        {
            var pg = ResolveNoteReferencePage(id, footnote: true);
            if (!byPage.TryGetValue(pg, out var list))
                byPage[pg] = list = new List<int>();
            list.Add(id);
        }

        foreach (var (pg, ids) in byPage)
        {
            // Word gives an overflowing note most of its reference page after the reference itself,
            // then carries only the remainder to later pages. A smaller band leaves later body
            // paragraphs below the reference, which reverses that ownership.
            var firstBand = Math.Max(
                Build("Ag", RunFormatting.Default with { FontSizePt = NoteFontSizePt }).Height,
                _layoutTextAreaHeight * 0.75);
            var continuationBand = Math.Max(firstBand, _layoutTextAreaHeight - FootnoteTopPadding);
            var plan = DocumentNoteRegionPlanner.BuildFootnoteContinuation(
                _doc,
                ids,
                pg + 1,
                _contentWidth,
                firstBand,
                continuationBand);

            if (plan.Pages.Count == 0)
                continue;

            // Keep the first body page's reservation equal to the actual planned fragment, rather than
            // the entire logical note. Normal one-page notes retain the existing rendering path below.
            _footnoteBandHeightByPage[pg] = Math.Min(
                firstBand,
                plan.Pages[0].EstimatedHeightDip + FootnoteTopPadding + FootnoteBodyReserveSafetyDip);
            if (plan.HasContinuation)
            {
                _footnoteContinuationByBodyPage[pg] = plan;
                var nextBodyPage = pg + 1;
                if (!byPage.ContainsKey(nextBodyPage))
                {
                    _footnoteBandHeightByPage[nextBodyPage] = Math.Min(
                        continuationBand,
                        plan.Pages[^1].EstimatedHeightDip + FootnoteTopPadding + FootnoteBodyReserveSafetyDip);
                }
            }
        }
    }

    /// <summary>
    /// AV-NOTERENDER (footnotes): for each page in PrintLayout, renders a short separator rule then the
    /// footnotes whose body reference lands on that page, stacked as "<c>n note text</c>" at
    /// <see cref="NoteFontSizePt"/>. The band occupies the bottom margin area, above the footer.
    /// <para>
    /// DB1: the band height was pre-computed by <see cref="ComputeFootnoteBandHeights"/> and stored in
    /// <see cref="_footnoteBandHeightByPage"/>; <see cref="ReserveContentY"/> already shrank the body
    /// text area so body text does not overlap the band.
    /// </para>
    /// <para>
    /// DB2: each note's TRUE wrapped height (from <see cref="MeasureNoteContentHeight"/>) determines
    /// the band top, replacing the old 1-line-per-note estimate. Content is clamped so it does not
    /// overflow past the footer. Overflow (band taller than available gap) is clipped with a note below.
    /// </para>
    /// <para>
    /// DB3: note numbers use <see cref="ComputeNoteDisplayNumber"/> with the document's
    /// <see cref="TextDocument.FootnoteNumbering"/> options (format + StartAt).
    /// </para>
    /// Page assignment uses <see cref="ResolveNoteReferencePage"/>; footnotes with no locatable reference
    /// glyph fall back to the last body page (documented approximation).
    /// </summary>
    private void BuildFootnoteItems()
    {
        if (_doc.Footnotes.Count == 0) return;

        if (_footnoteContinuationByBodyPage.Count > 0)
        {
            BuildFootnoteContinuationItems();
            BuildFootnoteItemsLegacy(_footnoteContinuationByBodyPage.Values
                .SelectMany(plan => plan.Pages)
                .SelectMany(page => page.Fragments)
                .Select(fragment => fragment.NoteId)
                .ToHashSet());
            return;
        }

        BuildFootnoteItemsLegacy(excludedNoteIds: null);
    }

    private void BuildFootnoteItemsLegacy(IReadOnlySet<int>? excludedNoteIds)
    {

        const double DefaultHfDistancePt = 36.0;

        // Group footnote ids by the page hosting their reference, preserving id order.
        var byPage = new Dictionary<int, List<int>>();
        foreach (var id in _doc.Footnotes.Keys.OrderBy(k => k))
        {
            if (excludedNoteIds?.Contains(id) == true)
                continue;
            var pg = LogicalBodyPageForPhysicalPage(ResolveNoteReferencePage(id, footnote: true));
            if (!byPage.TryGetValue(pg, out var list))
                byPage[pg] = list = new List<int>();
            list.Add(id);
        }

        var footerDistPt = _doc.Page.FooterDistancePt > 0 ? _doc.Page.FooterDistancePt : DefaultHfDistancePt;
        var footerDistDip = footerDistPt * PxPerPoint;

        // DB3: footnote numbering options — format (Decimal/LowerRoman/…) + StartAt offset.
        var opts = _doc.FootnoteNumbering;
        var sequenceById = _doc.Footnotes.Keys.OrderBy(id => id)
            .Select((id, index) => (id, sequence: Math.Max(1, opts.StartAt) + index))
            .ToDictionary(pair => pair.id, pair => pair.sequence);

        foreach (var (pg, ids) in byPage.OrderBy(kv => kv.Key))
        {
            var pageTop    = _surfacePlan.PageTopDip(PhysicalPageForBodyPage(pg));
            var pageBottom = pageTop + _pageHeightPx;
            // Body text area bottom on this page (page-space), using the reserved effective height.
            var bandReservation = _footnoteBandHeightByPage.TryGetValue(pg, out var bh) ? bh : 0.0;
            var bodyBottom = pageTop + _marginTopDip + (_layoutTextAreaHeight - bandReservation);
            // Footnotes occupy the bottom margin, not the lower footer-distance strip. Keep them
            // above the text margin and, when a footer sits higher, above that footer as well.
            var footerTop = pageBottom - footerDistDip;
            var footnoteBottom = Math.Min(pageBottom - _marginBottomDip, footerTop);

            // DB2: true total band height = separator + true wrapped heights of all notes on this page.
            var trueHeight = FootnoteTopPadding + FootnoteSeparatorHeight;
            for (var index = 0; index < ids.Count; index++)
            {
                var id = ids[index];
                var note2 = _doc.Footnotes[id];
                var dn = note2.HasAutomaticReferenceMark
                    ? ComputeNoteDisplayNumber(sequenceById[id], opts)
                    : string.Empty;
                var content2 = note2.Content.Count > 0
                    ? note2.Content
                    : (IReadOnlyList<Paragraph>)new List<Paragraph> { new Paragraph(string.Empty) };
                trueHeight += MeasureNoteContentHeight(dn, content2, _contentLeft, _contentWidth);
                trueHeight += index == ids.Count - 1
                    ? FootnoteTrailingPadding
                    : FootnoteInterNoteSpacing;
            }

            // DB2: anchor the band to the usable bottom-margin edge. The band top is
            // (footnoteBottom - trueHeight), but must stay at/below the body bottom.
            var bandTop = Math.Max(bodyBottom + 2, footnoteBottom - trueHeight);
            // Also clamp: band must not start above the mid-margin (guard for very tall bands on short pages).
            bandTop = Math.Min(bandTop, footnoteBottom - 6);
            // DB2: available height within the band = from bandTop to the usable margin edge. If overflow,
            // content is clipped there (split-to-next-page is a follow-up; for now we clip).
            var availBandHeight = Math.Max(6, footnoteBottom - bandTop);

            // Separator rule: a short line (~1.5") at the left of the content column.
            var sepWidth = Math.Min(2 * 72 * PxPerPoint, _contentWidth * 0.4);
            _noteSeparators.Add((_contentLeft, _contentLeft + sepWidth, bandTop));

            var y = bandTop + FootnoteTopPadding;
            for (var index = 0; index < ids.Count; index++)
            {
                var id = ids[index];
                var note = _doc.Footnotes[id];
                // DB3: compute display number from NoteNumberingOptions.
                var displayNum = note.HasAutomaticReferenceMark
                    ? ComputeNoteDisplayNumber(sequenceById[id], opts)
                    : string.Empty;

                var content = note.Content.Count > 0
                    ? note.Content
                    : (IReadOnlyList<Paragraph>)new List<Paragraph> { new Paragraph(string.Empty) };

                // DB2: only emit if still within the available band (clip overflow at footerTop).
                if (y < bandTop + availBandHeight)
                {
                    y = LayoutNoteContent(displayNum, content, _contentLeft, y, _contentWidth);
                    if (index < ids.Count - 1)
                        y += FootnoteInterNoteSpacing;
                    // DB2: clamp y to band bottom so subsequent notes don't escape past the footer.
                    y = Math.Min(y, bandTop + availBandHeight);
                }
            }
        }
    }

    /// <summary>
    /// AV-NOTERENDER (endnotes): appends numbered endnote text after the final body paragraph when the
    /// last physical page has room. A synthetic section remains as the overflow fallback. The synthetic
    /// section's vertical extent is recorded in <see cref="_endnoteExtentDip"/>.
    /// <para>
    /// DB3: endnote numbers use <see cref="ComputeNoteDisplayNumber"/> with the document's
    /// <see cref="TextDocument.EndnoteNumbering"/> options (Word defaults to LowerRoman for endnotes).
    /// </para>
    /// </summary>
    private void BuildEndnoteItems()
    {
        if (_doc.Endnotes.Count == 0) return;

        if (TryGetFinalPageEndnoteSeparatorY(out var separatorY))
        {
            LayoutEndnoteRegion(separatorY);
            return;
        }

        // Overflow fallback: retain a distinct section after the last physical body page.
        var lastPageBottom = _surfacePlan.PageTopDip(_pageCount - 1) + _pageHeightPx;
        var startY = lastPageBottom + PageGap + _marginTopDip * 0.25;

        var headingFmt = RunFormatting.Default with { FontSizePt = NoteFontSizePt + 2, Bold = true };
        var headingH = Math.Max(1, Build("Endnotes", headingFmt).Height);

        // Heading.
        _noteItems.Add(new NoteRenderItem { Text = "Endnotes", Fmt = headingFmt, X = _contentLeft, Y = startY });
        var y = startY + headingH + 2;

        // Separator rule beneath the heading.
        var separatorWidth = Math.Min(DocumentNoteRegionPlanner.FootnoteSeparatorWidthDip, _contentWidth);
        _noteSeparators.Add((_contentLeft, _contentLeft + separatorWidth, y));
        y += 6;

        // DB3: endnote numbering options — Word defaults to LowerRoman; users may override.
        var opts     = _doc.EndnoteNumbering;
        var seqIndex = Math.Max(1, opts.StartAt); // 1-based display sequence counter

        foreach (var id in _doc.Endnotes.Keys.OrderBy(k => k))
        {
            var note = _doc.Endnotes[id];
            // DB3: compute display number from EndnoteNumbering options.
            var displayNum = note.HasAutomaticReferenceMark
                ? ComputeNoteDisplayNumber(seqIndex, opts)
                : string.Empty;
            seqIndex++;
            y = LayoutNoteContent(displayNum,
                note.Content.Count > 0 ? note.Content : new List<Paragraph> { new Paragraph(string.Empty) },
                _contentLeft, y, _contentWidth);
            y += 2; // small gap between endnotes
        }

        // Record how far past the last body page the endnotes section extends.
        _endnoteExtentDip = Math.Max(0, y - lastPageBottom) + DeskPadding;
    }

    private bool TryGetFinalPageEndnoteSeparatorY(out double separatorY)
    {
        separatorY = 0;
        var finalPage = Math.Max(0, _pageCount - 1);
        var finalBodyBottom = _placed
            .Where(placed => !placed.Sentinel && RenderedPageIndexForPoint(placed.X, placed.Y) == finalPage)
            .Select(placed => placed.Y + placed.LineHeight)
            .DefaultIfEmpty(double.NaN)
            .Max();
        if (double.IsNaN(finalBodyBottom))
            return false;

        var pageTop = _surfacePlan.PageTopDip(finalPage);
        var usableBottom = pageTop + _pageHeightPx - _marginBottomDip;
        separatorY = Math.Max(pageTop + _marginTopDip, finalBodyBottom + EndnoteAfterBodyGap);
        return separatorY + MeasureEndnoteRegionHeight() <= usableBottom;
    }

    private double MeasureEndnoteRegionHeight()
    {
        var height = EndnoteSeparatorToTextGap;
        var options = _doc.EndnoteNumbering;
        var sequence = Math.Max(1, options.StartAt);
        var ids = _doc.Endnotes.Keys.OrderBy(id => id).ToList();
        for (var index = 0; index < ids.Count; index++)
        {
            var note = _doc.Endnotes[ids[index]];
            var content = note.Content.Count > 0
                ? note.Content
                : (IReadOnlyList<Paragraph>)new List<Paragraph> { new Paragraph(string.Empty) };
            var displayNumber = note.HasAutomaticReferenceMark
                ? ComputeNoteDisplayNumber(sequence, options)
                : string.Empty;
            sequence++;
            height += MeasureNoteContentHeight(displayNumber, content, _contentLeft, _contentWidth);
            height += index == ids.Count - 1 ? EndnoteTrailingPadding : EndnoteInterNoteSpacing;
        }
        return height;
    }

    private void LayoutEndnoteRegion(double separatorY)
    {
        var separatorWidth = Math.Min(DocumentNoteRegionPlanner.FootnoteSeparatorWidthDip, _contentWidth);
        _noteSeparators.Add((_contentLeft, _contentLeft + separatorWidth, separatorY));
        var y = separatorY + EndnoteSeparatorToTextGap;
        var options = _doc.EndnoteNumbering;
        var sequence = Math.Max(1, options.StartAt);
        var ids = _doc.Endnotes.Keys.OrderBy(id => id).ToList();
        for (var index = 0; index < ids.Count; index++)
        {
            var note = _doc.Endnotes[ids[index]];
            var content = note.Content.Count > 0
                ? note.Content
                : (IReadOnlyList<Paragraph>)new List<Paragraph> { new Paragraph(string.Empty) };
            var displayNumber = note.HasAutomaticReferenceMark
                ? ComputeNoteDisplayNumber(sequence, options)
                : string.Empty;
            sequence++;
            y = LayoutNoteContent(displayNumber, content, _contentLeft, y, _contentWidth);
            if (index < ids.Count - 1)
                y += EndnoteInterNoteSpacing;
        }
    }

    // Layout-pass mutable state for paged layout (reset at start of Relayout).
    private double _layoutContentY;
    private double _layoutTextAreaHeight;

    /// <summary>
    /// Converts a content-space Y (0 = first line of text area, increasing downward) to a
    /// page-space Y (the actual pixel Y in the control's coordinate system).
    /// <para>In <see cref="DocumentViewMode.PrintLayout"/>:</para>
    /// Content wraps line-granularly: a line that starts past the current page's bottom
    /// margin is pushed to the top of the next page.
    /// Formula: pageIndex = floor(contentY / textAreaHeight)
    ///          pageSpaceY = DeskPadding + pageIndex*(pageHeightPx+gap) + marginTopDip + (contentY - pageIndex*textAreaHeight)
    /// <para>In <see cref="DocumentViewMode.WebLayout"/> / <see cref="DocumentViewMode.Draft"/>:</para>
    /// No pagination — pageSpaceY = marginTopDip + contentY (simple offset by the top inset).
    /// </summary>
    private double ContentYToPageSpaceY(double contentY)
    {
        if (!_surfacePlan.IsPrintLayout || _footnoteContinuationByBodyPage.Count == 0)
            return _surfacePlan.ContentYToPageSpaceY(contentY, _colCount);

        var textAreaHeight = Math.Max(1, _surfacePlan.TextAreaHeightDip);
        var slot = Math.Max(0, (int)(contentY / textAreaHeight));
        var logicalBodyPage = slot / Math.Max(1, _colCount);
        var offsetWithinSlot = contentY - slot * textAreaHeight;
        return _surfacePlan.PageTopDip(PhysicalPageForBodyPage(logicalBodyPage))
            + _surfacePlan.MarginTopDip
            + offsetWithinSlot;
    }

    /// <summary>
    /// Derives the zero-based page index from a page-space Y coordinate.
    /// Inverse of <see cref="ContentYToPageSpaceY"/>.
    /// In Web/Draft modes always returns 0 (single continuous page).
    /// </summary>
    private int PageIndexFromPageSpaceY(double pageSpaceY)
    {
        return _surfacePlan.PageIndexFromPageSpaceY(pageSpaceY);
    }

    private void BuildFootnoteContinuationItems()
    {
        const double DefaultHfDistancePt = 36.0;
        var footerDistPt = _doc.Page.FooterDistancePt > 0 ? _doc.Page.FooterDistancePt : DefaultHfDistancePt;
        var footerDistDip = footerDistPt * PxPerPoint;
        var separatorWidth = Math.Min(DocumentNoteRegionPlanner.FootnoteSeparatorWidthDip, _contentWidth);

        foreach (var (logicalBodyPage, continuation) in _footnoteContinuationByBodyPage.OrderBy(pair => pair.Key))
        {
            for (var fragmentPageIndex = 0; fragmentPageIndex < continuation.Pages.Count; fragmentPageIndex++)
            {
                var page = continuation.Pages[fragmentPageIndex];
                var physicalPage = PhysicalPageForFootnoteFragment(logicalBodyPage, fragmentPageIndex);
                var pageTop = _surfacePlan.PageTopDip(physicalPage);
                var pageBottom = pageTop + _pageHeightPx;
                var footnoteBottom = Math.Min(pageBottom - _marginBottomDip, pageBottom - footerDistDip);
                var bandHeight = Math.Min(page.AvailableHeightDip, footnoteBottom - (pageTop + _marginTopDip));
                var bandTop = Math.Max(pageTop + _marginTopDip, footnoteBottom - bandHeight);

                if (page.SeparatorKind != DocumentFootnoteSeparatorKind.None)
                    _noteSeparators.Add((_contentLeft, _contentLeft + separatorWidth, bandTop));

                var y = bandTop + FootnoteTopPadding;
                foreach (var fragment in page.Fragments)
                {
                    y = LayoutNoteContent(
                        fragment.Label ?? string.Empty,
                        [new Paragraph(fragment.EndsNote ? fragment.Text : fragment.Text + " ")],
                        _contentLeft,
                        y,
                        _contentWidth);
                }
            }
        }
    }

    private int PhysicalPageForBodyPage(int logicalBodyPage)
    {
        return _footnotePhysicalPagePlan.PhysicalPageForBodyPage(logicalBodyPage);
    }

    private int PhysicalPageForFootnoteFragment(int logicalBodyPage, int fragmentPageIndex)
    {
        if (!_footnoteContinuationByBodyPage.TryGetValue(logicalBodyPage, out var continuation))
            return PhysicalPageForBodyPage(logicalBodyPage);

        var isFinalFragment = fragmentPageIndex == continuation.Pages.Count - 1;
        var nextBodyPage = logicalBodyPage + 1;
        var canResumeOnNextBodyPage = isFinalFragment
            && fragmentPageIndex > 0
            && nextBodyPage < _bodyPageCount
            && !_footnoteContinuationByBodyPage.ContainsKey(nextBodyPage);
        return canResumeOnNextBodyPage
            ? PhysicalPageForBodyPage(nextBodyPage)
            : PhysicalPageForBodyPage(logicalBodyPage) + Math.Max(0, fragmentPageIndex);
    }

    private int LogicalBodyPageForPhysicalPage(int physicalPage)
    {
        var page = _footnotePhysicalPagePlan.Pages
            .FirstOrDefault(candidate => candidate.PhysicalPageIndex == physicalPage);
        if (page?.LogicalBodyPageIndex is int logicalBodyPage)
            return logicalBodyPage;

        // A note reference cannot normally land inside a continuation-only page. Keep the nearest
        // preceding body page as a defensive fallback for unusual zero-width source runs.
        return Math.Clamp(physicalPage, 0, Math.Max(0, _bodyPageCount - 1));
    }

    private void RebuildFootnotePhysicalPagePlan()
    {
        _footnotePhysicalPagePlan = DocumentNoteRegionPlanner.BuildFootnotePhysicalPagePlan(
            _bodyPageCount,
            _footnoteContinuationByBodyPage);
    }

    /// <summary>
    /// Advances _layoutContentY to the next page boundary if the line of <paramref name="lineHeight"/>
    /// would overflow the current page's text area. Returns the content Y at which the line should start.
    /// <para>
    /// DB1: the effective text-area height on a page is reduced by the footnote band height for that page
    /// (stored in <see cref="_footnoteBandHeightByPage"/>), so body text reflows to the NEXT page before
    /// it would encroach on the footnote band. Computed per-page so pages without footnotes are unaffected.
    /// </para>
    /// </summary>
    private double ReserveContentY(double lineHeight)
    {
        if (_layoutTextAreaHeight <= 0) return _layoutContentY;

        // DB1: compute the 0-based page (slot) index and its per-page footnote reservation.
        var slot = (int)(_layoutContentY / _layoutTextAreaHeight);
        var pageIndex = slot / _colCount;
        var bandReservation = _footnoteBandHeightByPage.TryGetValue(pageIndex, out var bh) ? bh : 0.0;
        // effectiveHeight = page text area minus footnote band on that page.
        var effectiveHeight = Math.Max(lineHeight + 1, _layoutTextAreaHeight - bandReservation);

        var posInPage = _layoutContentY % _layoutTextAreaHeight;
        if (posInPage > 0 && posInPage + lineHeight > effectiveHeight)
        {
            // Push to the top of the next page.
            _layoutContentY += (_layoutTextAreaHeight - posInPage);
        }
        return _layoutContentY;
    }

    private void AdvanceToNextColumnSlot()
    {
        if (!_surfacePlan.IsPrintLayout || _layoutTextAreaHeight <= 0)
            return;

        var slot = Math.Max(0, (int)Math.Floor(_layoutContentY / _layoutTextAreaHeight));
        _layoutContentY = (slot + 1) * _layoutTextAreaHeight;
    }

    private void AdvanceToNextPageBoundary(
        bool forceAdvance,
        SectionBreakKind breakKind = SectionBreakKind.NextPage)
    {
        if (!_surfacePlan.IsPrintLayout || _layoutTextAreaHeight <= 0)
            return;

        var slotsPerPage = Math.Max(1, _colCount);
        var pageSpan = slotsPerPage * _layoutTextAreaHeight;
        var currentPage = Math.Max(0, (int)Math.Floor(_layoutContentY / pageSpan));
        var positionInPage = _layoutContentY % pageSpan;
        if (!forceAdvance && positionInPage <= 0)
            return;

        var targetPage = currentPage + 1;
        var targetPageNumber = targetPage + 1;
        if (breakKind == SectionBreakKind.EvenPage && targetPageNumber % 2 != 0)
            targetPage++;
        else if (breakKind == SectionBreakKind.OddPage && targetPageNumber % 2 == 0)
            targetPage++;

        _layoutContentY = targetPage * pageSpan;
    }

    /// <summary>
    /// Returns the content Y at which the next content of <paramref name="lineHeight"/> would start,
    /// applying the same page-break logic as <see cref="ReserveContentY"/> but WITHOUT mutating
    /// <c>_layoutContentY</c>.  Used to compute the post-break paragraph-anchor Y for floating images
    /// before the layout loop has consumed any lines.
    /// </summary>
    private double PeekFirstLineContentY(double lineHeight = 1)
    {
        if (_layoutTextAreaHeight <= 0)
            return _layoutContentY;

        // DB1: mirror the per-page reservation used by ReserveContentY.
        var slot = (int)(_layoutContentY / _layoutTextAreaHeight);
        var pageIndex = slot / _colCount;
        var bandReservation = _footnoteBandHeightByPage.TryGetValue(pageIndex, out var bh) ? bh : 0.0;
        var effectiveHeight = Math.Max(lineHeight + 1, _layoutTextAreaHeight - bandReservation);

        var posInPage = _layoutContentY % _layoutTextAreaHeight;
        if (posInPage > 0 && posInPage + lineHeight > effectiveHeight)
            return _layoutContentY + (_layoutTextAreaHeight - posInPage);
        return _layoutContentY;
    }

    /// <summary>
    /// Applies paragraph-after spacing without carrying it into the next print-layout column or page.
    /// Word discards the trailing paragraph space when the preceding line is the last content that fits
    /// in a column; the next paragraph starts at the next column's text-area origin.
    /// </summary>
    private void AdvanceAfterParagraphSpacing(double spaceAfter)
    {
        if (spaceAfter <= 0)
            return;

        if (_layoutTextAreaHeight <= 0)
        {
            _layoutContentY += spaceAfter;
            return;
        }

        var slot = (int)(_layoutContentY / _layoutTextAreaHeight);
        var pageIndex = slot / _colCount;
        var bandReservation = _footnoteBandHeightByPage.TryGetValue(pageIndex, out var bh) ? bh : 0.0;
        var effectiveHeight = Math.Max(1, _layoutTextAreaHeight - bandReservation);
        var posInPage = _layoutContentY % _layoutTextAreaHeight;
        if (posInPage > 0 && posInPage + spaceAfter > effectiveHeight)
        {
            _layoutContentY += _layoutTextAreaHeight - posInPage;
            return;
        }

        _layoutContentY += spaceAfter;
    }

    /// <summary>
    /// Reserves a complete ordinary paragraph when Word's keep-lines or default widow-control
    /// policy applies. Paragraphs taller than a page keep the normal line-by-line path.
    /// </summary>
    private void ReserveCompleteParagraph(double paragraphHeight)
    {
        if (paragraphHeight <= 0 || _layoutTextAreaHeight <= 0)
            return;

        var slot = (int)(_layoutContentY / _layoutTextAreaHeight);
        var pageIndex = slot / _colCount;
        var bandReservation = _footnoteBandHeightByPage.TryGetValue(pageIndex, out var bh) ? bh : 0.0;
        var effectiveHeight = Math.Max(1, _layoutTextAreaHeight - bandReservation);
        if (paragraphHeight > effectiveHeight)
            return;

        var posInPage = _layoutContentY % _layoutTextAreaHeight;
        if (posInPage > 0 && posInPage + paragraphHeight > effectiveHeight)
            _layoutContentY += _layoutTextAreaHeight - posInPage;
    }

    private static double MeasurePlainParagraphHeight(
        IReadOnlyList<Cell> cells,
        IReadOnlyList<double> measured,
        IReadOnlyList<double> heights,
        double availableWidth,
        ParagraphFormatting pf,
        PageSettings page,
        double naturalLineHeightScale,
        string automaticHyphenationText,
        IReadOnlyDictionary<int, double> automaticHyphenWidths)
    {
        if (cells.Count == 0)
            return ApplyLineSpacing(DefaultFontSizePt * PxPerPoint * 1.3 * naturalLineHeightScale, pf);

        var totalHeight = 0.0;
        var lineStart = 0;
        var lineWidth = 0.0;
        var lastBreak = -1;
        var consecutiveAutomaticHyphenLines = 0;

        void AddLine(int from, int to)
        {
            var naturalHeight = DefaultFontSizePt * PxPerPoint * 1.3;
            for (var index = from; index < to; index++)
                naturalHeight = Math.Max(naturalHeight, heights[index]);
            totalHeight += ApplyLineSpacing(naturalHeight * naturalLineHeightScale, pf);
        }

        for (var index = 0; index < cells.Count; index++)
        {
            if (cells[index].Ch == ' ')
                lastBreak = index;

            if (lineWidth + measured[index] > availableWidth && index > lineStart)
            {
                var spaceBreakAt = lastBreak >= lineStart ? lastBreak + 1 : -1;
                var automaticBreak = FindLatestAutomaticHyphenBreak(
                    lineStart, index, availableWidth, measured, automaticHyphenWidths);
                var useAutomaticHyphen = ShouldUseAutomaticHyphenBreak(
                    page,
                    consecutiveAutomaticHyphenLines,
                    automaticHyphenationText,
                    measured,
                    lineStart,
                    spaceBreakAt,
                    automaticBreak.BreakAt,
                    availableWidth);
                var breakAt = useAutomaticHyphen
                    ? automaticBreak.BreakAt
                    : spaceBreakAt > lineStart ? spaceBreakAt : index;
                AddLine(lineStart, breakAt);
                consecutiveAutomaticHyphenLines = useAutomaticHyphen
                    ? consecutiveAutomaticHyphenLines + 1
                    : 0;
                lineStart = breakAt;
                lineWidth = 0;
                lastBreak = -1;
                for (var carried = lineStart; carried < index; carried++)
                {
                    if (cells[carried].Ch == ' ')
                        lastBreak = carried;
                    lineWidth += measured[carried];
                }
            }

            lineWidth += measured[index];
        }

        AddLine(lineStart, cells.Count);
        return totalHeight;
    }

    internal static bool ShouldUseAutomaticHyphenBreak(
        PageSettings page,
        int consecutiveHyphenatedLines,
        string displayText,
        IReadOnlyList<double> measured,
        int lineStart,
        int spaceBreakAt,
        int automaticBreakAt,
        double availableWidth)
    {
        if (automaticBreakAt <= spaceBreakAt)
            return false;

        var hasOrdinaryWordBreak = spaceBreakAt > lineStart;
        var ordinaryVisibleEnd = spaceBreakAt;
        while (ordinaryVisibleEnd > lineStart
               && char.IsWhiteSpace(displayText[ordinaryVisibleEnd - 1]))
        {
            ordinaryVisibleEnd--;
        }

        var ordinaryVisibleWidth = 0.0;
        for (var index = lineStart; index < ordinaryVisibleEnd; index++)
            ordinaryVisibleWidth += measured[index];
        var trailingWhitespacePt = hasOrdinaryWordBreak
            ? Math.Max(0, availableWidth - ordinaryVisibleWidth) / PxPerPoint
            : 0;

        return AutomaticHyphenationDisplayPlanner.AllowsAutomaticLineBreak(
            page,
            consecutiveHyphenatedLines,
            hasOrdinaryWordBreak,
            trailingWhitespacePt);
    }

    private static (int BreakAt, double HyphenWidth) FindLatestAutomaticHyphenBreak(
        int lineStart,
        int overflowIndex,
        double availableWidth,
        IReadOnlyList<double> measured,
        IReadOnlyDictionary<int, double> automaticHyphenWidths)
    {
        var width = 0.0;
        var bestBreakAt = -1;
        var bestHyphenWidth = 0.0;
        for (var cellIndex = lineStart; cellIndex < overflowIndex; cellIndex++)
        {
            width += measured[cellIndex];
            var breakOffset = cellIndex + 1;
            if (automaticHyphenWidths.TryGetValue(breakOffset, out var hyphenWidth)
                && width + hyphenWidth <= availableWidth)
            {
                bestBreakAt = breakOffset;
                bestHyphenWidth = hyphenWidth;
            }
        }

        return (bestBreakAt, bestHyphenWidth);
    }

    // ── AV-WRAP: wrap-exclusion helpers ───────────────────────────────────────────────────────────────

    private DocumentFloatingTextWrapLinePlan BuildFloatingTextWrapLinePlan(
        double estimatedLineHeight,
        double baseTextWidthDip,
        double? lineContentYDip = null,
        double? currentContentYDip = null)
    {
        var wrapColumnWidth = _colCount > 1 ? _colWidth : _contentWidth;
        var peekContentY = lineContentYDip ?? PeekFirstLineContentY(estimatedLineHeight);
        return DocumentViewLayoutPlanner.BuildFloatingTextWrapLinePlan(
            _wrapExclusions,
            _surfacePlan,
            currentContentYDip ?? _layoutContentY,
            peekContentY,
            estimatedLineHeight,
            _contentLeft,
            _colCount,
            wrapColumnWidth,
            _colGap,
            baseTextWidthDip);
    }

    /// <summary>
    /// Advances <c>_layoutContentY</c> past any TopAndBottom exclusion zones that would overlap
    /// a line of <paramref name="estimatedLineHeight"/> at the current position.
    /// BB2: the shared planner advances to the last column slot on the affected page, so every column
    /// skips the blocked Y-band.
    /// </summary>
    private void AdvancePastTopAndBottomExclusions(double estimatedLineHeight, double baseTextWidthDip)
    {
        if (_wrapExclusions.Count == 0) return;

        var plan = BuildFloatingTextWrapLinePlan(estimatedLineHeight, baseTextWidthDip);
        if (plan.HasTopAndBottomAdvance && plan.PlannedContentYDip > _layoutContentY)
            _layoutContentY = plan.PlannedContentYDip;
    }

    private void LayoutParagraphPaged(int blockIndex, Paragraph paragraph, double textWidth, double leftInset = 0, string? marker = null)
    {
        var rawCells = IsEditable(paragraph)
            ? ParaCells(paragraph, includeFlowBreaks: true)
            : DisplayCells(blockIndex, paragraph, includeFlowBreaks: true);
        var flowBreakPlan = InlineFlowBreakSegmentationPlanner.Build(
            rawCells.Select(cell => new InlineFlowRunInput(
                SourceLength: 1,
                IsPageBreak: cell.IsPageBreak,
                IsColumnBreak: cell.IsColumnBreak)).ToList());
        // Resolve document defaults and named styles for display only; editing re-derives raw cells
        // from the model. Unstyled paragraphs still inherit DefaultRun, just as they do in Word.
        var cells = rawCells.Select(c => c with { Fmt = ResolveRunFmt(c.Fmt, paragraph) }).ToList();
        var reviewPolicy = CurrentReviewDisplayPolicy;
        var pf = ResolveParagraphFmt(paragraph);
        var alignment = pf.Alignment;
        var spaceAfter = pf.SpaceAfterPt * PxPerPoint;
        var naturalLineHeightScale = UsesWordDefaultBodyLineBox(paragraph, pf, cells)
            ? WordDefaultBodyLineHeightScale
            : 1.0;

        // Paragraph indents: left/right reduce available width; first-line applies only to line 0.
        var indentLeft  = pf.IndentLeftPt  * PxPerPoint;
        var indentRight = pf.IndentRightPt * PxPerPoint;
        var indentFirst = pf.FirstLineIndentPt * PxPerPoint; // positive = first-line, negative = hanging

        // Total left offset = list inset (already in leftInset) + paragraph indent.
        var paraLeftInset = leftInset + indentLeft;
        // Available width shrinks by both left+right paragraph indents.
        var availableWidth = Math.Max(60, textWidth - leftInset - indentLeft - indentRight);

        _layoutContentY += pf.SpaceBeforePt * PxPerPoint;

        // Collect floating images AND shapes AFTER the SpaceBeforePt advance, using the post-break
        // first-line content Y so that VerticalAnchor.Paragraph floats are anchored to where the
        // paragraph's first line ACTUALLY lands (correct page after any page-break, correct Y after
        // SpaceBefore). PeekFirstLineContentY is non-mutating — it simulates ReserveContentY without
        // side effects.
        //
        // VV1 fix (extends TT1): compute the paragraph's first-line height by taking the MAX glyph
        // height over ALL cells in the paragraph (an over-estimate: at most includes later-line cells,
        // but that only makes Peek break EARLIER, never later — so it is safe).
        //
        // The prior TT1 code took only the FIRST character of the FIRST text run (double break), which
        // under-estimates when line 0's tallest run is not its first character (e.g. small "see " then
        // a 24pt word).  EmitLinePaged uses max(heights[from..to)) over the line's cells; mirroring
        // that over ALL cells (safe upper bound) ensures Peek breaks whenever the real first-line
        // ReserveContentY would.  Empty paragraphs (no cells) fall back to the default line height.
        var firstLineNaturalH = DefaultFontSizePt * PxPerPoint * 1.3; // default / fallback
        foreach (var run in paragraph.Runs)
        {
            if (run.Image is not null || run.Shape is not null) continue; // skip non-text
            var effectiveFormatting = ResolveRunFmt(run.Formatting, paragraph);
            if (IsTextHiddenInCurrentView(effectiveFormatting)) continue;
            foreach (var ch in run.Text)
            {
                var h = BuildForLayout(ch.ToString(), effectiveFormatting).Height;
                if (h > firstLineNaturalH) firstLineNaturalH = h;
                // VV1: do NOT break — scan all chars across ALL text runs (max over all cells).
            }
            // VV1: do NOT break — scan all runs.
        }
        foreach (var cell in cells)
        {
            if (cell.EquationElement is { } equationElement)
                firstLineNaturalH = Math.Max(firstLineNaturalH, MeasureEquationVisualElement(equationElement, cell.Fmt).Height);
        }

        var firstLineHeight = ApplyLineSpacing(firstLineNaturalH * naturalLineHeightScale, pf);
        var anchorContentY = PeekFirstLineContentY(firstLineHeight);
        CollectFloatingObjects(blockIndex, paragraph, anchorContentY);
        var dropCapPlan = DocumentViewLayoutPlanner.BuildDropCapLayoutPlan(
            paragraph,
            blockIndex,
            _contentLeft + paraLeftInset,
            ContentYToPageSpaceY(anchorContentY),
            availableWidth,
            firstLineHeight);
        if (dropCapPlan is not null)
            _dropCapLayoutPlans.Add(dropCapPlan);

        double DropCapLineInset(int currentLineIndex) =>
            dropCapPlan is { IsDropped: true } && currentLineIndex < dropCapPlan.LineSpan
                ? dropCapPlan.BodyTextLeftInsetDip
                : 0.0;

        if (marker is not null)
        {
            var markerFmt = paragraph.Runs.Count > 0 ? paragraph.Runs[0].Formatting : RunFormatting.Default;
            var markerWidth = Build(marker, markerFmt).WidthIncludingTrailingWhitespace;
            // Place the marker at the current content-space Y converted to page-space.
            var markerY = ContentYToPageSpaceY(_layoutContentY);
            // AV-COL: resolve column X for the list marker (same column as the paragraph's first line).
            var markerSlot     = _layoutTextAreaHeight > 0 ? (int)(_layoutContentY / _layoutTextAreaHeight) : 0;
            var markerColIndex = markerSlot % _colCount;
            var markerColLeft  = _contentLeft + markerColIndex * (_colWidth + _colGap);
            _markers.Add((markerColLeft + paraLeftInset - markerWidth - 6, markerY, marker, markerFmt));
        }

        // Break the cell stream into wrapped lines.
        var lineStart = 0;
        var i = 0;
        var lineWidth = 0.0;
        var lastBreak = -1; // index of a space cell we can wrap after
        var measured = new double[cells.Count];
        var heights = new double[cells.Count];
        // AV-TAB: default tab interval from page settings (points → DIP).
        var defaultTabStopPt = Math.Max(1, _doc.Page.DefaultTabStopPt);

        for (var c = 0; c < cells.Count; c++)
        {
            if (cells[c].IsPageBreak || cells[c].IsColumnBreak)
            {
                measured[c] = 0;
                heights[c] = 0;
                continue;
            }

            if (IsTextHiddenInCurrentView(cells[c].Fmt))
            {
                measured[c] = 0;
                heights[c] = 0;
                continue;
            }

            if (cells[c].EquationElement is { } equationElement)
            {
                var equationSize = MeasureEquationVisualElement(equationElement, cells[c].Fmt);
                measured[c] = equationSize.Width;
                heights[c] = equationSize.Height;
                if (equationSize.Height > firstLineNaturalH)
                    firstLineNaturalH = equationSize.Height;
                continue;
            }

            if (cells[c].Ch == '\t')
            {
                // AV-TAB: tab width is determined lazily in the wrapping loop (depends on pen pos).
                // Use 0 here; the wrapping loop fills in the real value via ComputeTabMeasuredWidth.
                measured[c] = 0;
                heights[c] = DefaultFontSizePt * PxPerPoint * 1.3; // fallback height
            }
            else
            {
                var decision = reviewPolicy.RevisionDecision(cells[c].Revision);
                if (decision.IsTextVisible)
                {
                    var ft = BuildForLayout(cells[c].Ch.ToString(), cells[c].Fmt);
                    measured[c] = ft.WidthIncludingTrailingWhitespace;
                    heights[c] = ft.Height;
                }
            }
        }

        var automaticHyphenationText = new string(cells.Select(cell =>
            !cell.IsPageBreak
            && !cell.IsColumnBreak
            && !IsTextHiddenInCurrentView(cell.Fmt)
            && reviewPolicy.RevisionDecision(cell.Revision).IsTextVisible
            && cell.EquationElement is null
                ? cell.Ch
                : ' ').ToArray());
        var automaticHyphenWidths = AutomaticHyphenationDisplayPlanner.BuildBreakOffsets(
                automaticHyphenationText,
                _doc.Page,
                pf)
            .Where(offset => offset > 0 && offset < cells.Count)
            .Distinct()
            .ToDictionary(
                offset => offset,
                offset => BuildForLayout("-", cells[offset - 1].Fmt).WidthIncludingTrailingWhitespace);

        // Keep the full paragraph together for the ordinary text path. This mirrors the WPF host's
        // default-on widow policy without changing tabs, equations, drop caps, or wrapped float layout.
        //
        // R132 NOTE — do not "fix" this to `pf.KeepLinesTogether || pf.WidowControl` without also
        // fixing the paginator. Word's widowControl only guards a stranded first/last LINE and never
        // forces a whole paragraph to move as a unit, so dropping the `!pf.WidowControlIsSet` term is
        // the semantically correct end state. But in THIS layout engine it currently produces a page
        // containing only the watermark and the page border and no body text at all
        // (DocumentViewPdfExportTests.BuildPdfContent_IncludesTextWatermarkBehindPageBorderOnEveryPage
        // fails; reverting this single line makes it pass). The empty-page emission is a separate
        // defect that has to be closed first -- tracked separately. The WPF host's fix for the same
        // finding is implemented differently and is unaffected by this line.
        var keepParagraphTogether = pf.KeepLinesTogether || !pf.WidowControlIsSet || pf.WidowControl;
        var supportsCompleteParagraphPlanning = indentFirst == 0
            && dropCapPlan is null
            && _wrapExclusions.Count == 0
            && cells.All(cell => !cell.IsPageBreak && !cell.IsColumnBreak && cell.Ch != '\t' && cell.EquationElement is null);
        if (keepParagraphTogether && supportsCompleteParagraphPlanning)
        {
            var paragraphHeight = MeasurePlainParagraphHeight(
                cells, measured, heights, availableWidth, pf, _doc.Page,
                naturalLineHeightScale, automaticHyphenationText, automaticHyphenWidths);
            ReserveCompleteParagraph(paragraphHeight);
        }

        var lineIndex = 0;
        var consecutiveAutomaticHyphenLines = 0;
        var supportsSplitFloatFragments = alignment == TextAlignment.Left
            && Math.Abs(leftInset) < 0.01
            && Math.Abs(indentLeft) < 0.01
            && Math.Abs(indentFirst) < 0.01
            && cells.All(cell => cell.Ch != '\t' && cell.EquationElement is null);

        // AV-WRAP: ask the shared presentation planner for the current line's effective width.
        double PeekLineAvail(double estimatedH, double baseAlignWidth)
        {
            if (_wrapExclusions.Count == 0) return baseAlignWidth;
            var plan = BuildFloatingTextWrapLinePlan(estimatedH, baseAlignWidth);
            return supportsSplitFloatFragments && plan.SplitLine is { } splitLine
                ? splitLine.EffectiveTextWidthDip
                : plan.EffectiveTextWidthDip;
        }

        while (i < cells.Count)
        {
            var flowBreakKind = flowBreakPlan.Runs[i].BreakKind;
            if (flowBreakKind != InlineFlowBreakKind.None)
            {
                if (i > lineStart)
                {
                    var breakLineExtraInset = (lineIndex == 0 && indentFirst > 0) ? indentFirst :
                                              (lineIndex  > 0 && indentFirst < 0) ? -indentFirst : 0.0;
                    breakLineExtraInset += DropCapLineInset(lineIndex);
                    var breakLineAlignWidth = Math.Max(20, availableWidth - breakLineExtraInset);
                    var lineHeight = DefaultFontSizePt * PxPerPoint * 1.3;
                    for (var c = lineStart; c < i; c++)
                        if (heights[c] > lineHeight) lineHeight = heights[c];
                    if (_wrapExclusions.Count > 0)
                        AdvancePastTopAndBottomExclusions(lineHeight, breakLineAlignWidth);
                    EmitLinePaged(blockIndex, cells, measured, heights, lineStart, i, alignment,
                        breakLineAlignWidth, paraLeftInset + breakLineExtraInset, pf,
                        naturalLineHeightScale: naturalLineHeightScale,
                        inlineFlowPlan: flowBreakPlan);
                    lineIndex++;
                }

                if (flowBreakKind == InlineFlowBreakKind.Page)
                    AdvanceToNextPageBoundary(forceAdvance: true);
                else
                    AdvanceToNextColumnSlot();
                i++;
                lineStart = i;
                lineWidth = 0;
                lastBreak = -1;
                consecutiveAutomaticHyphenLines = 0;
                continue;
            }

            // OO2/OO3 fix: for each line compute how much of availableWidth is consumed by
            // the per-line left indent BEYOND paraLeftInset.  The wrapping budget (lineAvail)
            // is already reduced for the first-line positive indent; hanging-indent continuation
            // lines also need the same reduction so they do not overshoot the right margin.
            // lineExtraInset is the extra indent relative to paraLeftInset for this line:
            //   • line 0 + positive first-line indent  → indentFirst  (normal first-line indent)
            //   • line > 0 + hanging indent (negative) → -indentFirst (continuation shifted right)
            //   • everything else                      → 0
            // BP1 fix: moved BEFORE the tab check so the full margin-relative pen offset
            // (lineWidth + paraLeftInset + lineExtraInset) is available for ComputeTabMeasuredWidth.
            var lineExtraInset = (lineIndex == 0 && indentFirst > 0) ? indentFirst :
                                 (lineIndex  > 0 && indentFirst < 0) ? -indentFirst : 0.0;
            lineExtraInset += DropCapLineInset(lineIndex);

            // AV-TAB: resolve tab advance lazily at the wrapping loop so measured[] reflects the
            // actual pen position at the time each tab is encountered on its line.
            // BP1 fix: pass pen position from the MARGIN (lineWidth + full indent) so tab stops
            // compare against OOXML positions (margin-relative), not the indented text origin.
            if (cells[i].Ch == '\t' && reviewPolicy.IsRevisionTextVisible(cells[i].Revision))
                measured[i] = ComputeTabMeasuredWidth(lineWidth + paraLeftInset + lineExtraInset, pf, defaultTabStopPt);

            if (cells[i].Ch == ' ')
                lastBreak = i;

            // Effective alignment / wrap width for this line so the right edge always lands at
            // the right margin regardless of indent variant.
            var lineAlignWidth = Math.Max(20, availableWidth - lineExtraInset);
            // AV-WRAP: reduce lineAvail further for any Square/Tight exclusion zones.
            var lineH2 = DefaultFontSizePt * PxPerPoint * 1.3;
            for (var c2 = lineStart; c2 <= i && c2 < heights.Length; c2++)
                if (heights[c2] > lineH2) lineH2 = heights[c2];
            var lineAvail = PeekLineAvail(lineH2, lineAlignWidth);

            if (lineWidth + measured[i] > lineAvail && i > lineStart)
            {
                var spaceBreakAt = lastBreak >= lineStart ? lastBreak + 1 : -1;
                var automaticBreak = FindLatestAutomaticHyphenBreak(
                    lineStart, i, lineAvail, measured, automaticHyphenWidths);
                var useAutomaticHyphen = ShouldUseAutomaticHyphenBreak(
                    _doc.Page,
                    consecutiveAutomaticHyphenLines,
                    automaticHyphenationText,
                    measured,
                    lineStart,
                    spaceBreakAt,
                    automaticBreak.BreakAt,
                    lineAvail);
                var breakAt = useAutomaticHyphen
                    ? automaticBreak.BreakAt
                    : spaceBreakAt > lineStart ? spaceBreakAt : i;
                // AV-WRAP: push past any TopAndBottom exclusion zones before emitting.
                if (_wrapExclusions.Count > 0)
                    AdvancePastTopAndBottomExclusions(lineH2, lineAlignWidth);
                EmitLinePaged(blockIndex, cells, measured, heights, lineStart, breakAt, alignment,
                    lineAlignWidth, paraLeftInset + lineExtraInset, pf,
                    naturalLineHeightScale: naturalLineHeightScale,
                    automaticHyphenWidth: useAutomaticHyphen ? automaticBreak.HyphenWidth : 0,
                    automaticHyphenSourceCell: useAutomaticHyphen ? cells[breakAt - 1] : null,
                    automaticHyphenBreakOffset: useAutomaticHyphen
                        ? flowBreakPlan.SourceOffsetAtBoundary(breakAt)
                        : -1,
                    inlineFlowPlan: flowBreakPlan);
                consecutiveAutomaticHyphenLines = useAutomaticHyphen
                    ? consecutiveAutomaticHyphenLines + 1
                    : 0;
                lineIndex++;
                lineStart = breakAt;
                lineWidth = 0;
                lastBreak = -1;
                // AV-TAB: recompute tab widths in the partial accumulation so they use the
                // new line's pen position (tabs reset to a fresh pen at the new lineStart).
                // BP1 fix: the new lineIndex may change lineExtraInset — recompute it now.
                var newLineExtraInset = (lineIndex == 0 && indentFirst > 0) ? indentFirst :
                                       (lineIndex  > 0 && indentFirst < 0) ? -indentFirst : 0.0;
                newLineExtraInset += DropCapLineInset(lineIndex);
                for (var k = lineStart; k < i; k++)
                {
                    if (cells[k].Ch == '\t' && reviewPolicy.IsRevisionTextVisible(cells[k].Revision))
                        measured[k] = ComputeTabMeasuredWidth(lineWidth + paraLeftInset + newLineExtraInset, pf, defaultTabStopPt);
                    if (cells[k].Ch == ' ')
                        lastBreak = k;
                    lineWidth += measured[k];
                }
            }

            lineWidth += measured[i];
            i++;
        }

        {
            // Last (or only) line of the paragraph.
            var lineExtraInset = (lineIndex == 0 && indentFirst > 0) ? indentFirst :
                                 (lineIndex  > 0 && indentFirst < 0) ? -indentFirst : 0.0;
            lineExtraInset += DropCapLineInset(lineIndex);
            var lineAlignWidth = Math.Max(20, availableWidth - lineExtraInset);
            // AV-WRAP: push past any TopAndBottom exclusion zones before emitting the last line.
            if (_wrapExclusions.Count > 0)
            {
                var lineH = DefaultFontSizePt * PxPerPoint * 1.3;
                for (var c2 = lineStart; c2 < cells.Count; c2++)
                    if (heights[c2] > lineH) lineH = heights[c2];
                AdvancePastTopAndBottomExclusions(lineH, lineAlignWidth);
            }
            EmitLinePaged(blockIndex, cells, measured, heights, lineStart, cells.Count, alignment,
                lineAlignWidth, paraLeftInset + lineExtraInset, pf, isLast: true,
                naturalLineHeightScale: naturalLineHeightScale,
                inlineFlowPlan: flowBreakPlan);
        }
        AdvanceAfterParagraphSpacing(spaceAfter);
    }

    private void EmitLinePaged(
        int blockIndex,
        IReadOnlyList<Cell> cells,
        double[] measured,
        double[] heights,
        int from,
        int to,
        TextAlignment alignment,
        double availableWidth,
        double leftInset,
        ParagraphFormatting pf,
        bool isLast = false,
        double naturalLineHeightScale = 1.0,
        double automaticHyphenWidth = 0,
        Cell? automaticHyphenSourceCell = null,
        int automaticHyphenBreakOffset = -1,
        InlineFlowBreakSegmentationPlan? inlineFlowPlan = null)
    {
        int SourceOffsetAt(int cellIndex) => inlineFlowPlan is null
            ? cellIndex
            : inlineFlowPlan.Runs[cellIndex].SourceOffset;

        int SourceOffsetAtBoundary(int boundaryIndex) => inlineFlowPlan is null
            ? Math.Max(0, boundaryIndex)
            : inlineFlowPlan.SourceOffsetAtBoundary(boundaryIndex);

        double lineWidth = automaticHyphenWidth;
        // Natural line height: use the tallest glyph but also respect line-spacing rule.
        double naturalHeight = DefaultFontSizePt * PxPerPoint * 1.3;
        for (var c = from; c < to; c++)
        {
            lineWidth += measured[c];
            if (heights[c] > naturalHeight)
                naturalHeight = heights[c];
        }

        // Apply line-spacing rule from paragraph formatting.
        double lineHeight = ApplyLineSpacing(naturalHeight * naturalLineHeightScale, pf);

        // Ensure the whole line fits on one page (push to next page if it overflows).
        var contentY = ReserveContentY(lineHeight);

        // Word-spacing expansion for justify (last line stays left).
        // OO1 fix: exclude the trailing space from BOTH the visible-width sum and the gap-add loop.
        // breakAt = lastBreak+1, so [from, to) includes the trailing space at index lastBreak.
        // That space is invisible at the right edge: it must not receive a wordGap, and its natural
        // width must not count against the slack we distribute.  We find the last non-space cell,
        // compute visible width = sum of measured[from..lastNonSpaceIdx] inclusive, and distribute
        // (availableWidth - visibleWidth) only among inter-word spaces strictly before lastNonSpaceIdx.
        double wordGap = 0;
        int lastNonSpaceIdx = from - 1; // sentinel: no non-space found
        if (alignment == TextAlignment.Justify && !isLast)
        {
            // Find the index of the last non-space cell in [from, to).
            for (var c = to - 1; c >= from; c--)
            {
                if (cells[c].Ch != ' ')
                {
                    lastNonSpaceIdx = c;
                    break;
                }
            }
            if (lastNonSpaceIdx >= from)
            {
                // Visible line width: chars from `from` up to and including `lastNonSpaceIdx`
                // (excludes trailing spaces that follow the last word).
                var visibleWidth = 0.0;
                for (var c = from; c <= lastNonSpaceIdx; c++)
                    visibleWidth += measured[c];
                visibleWidth += automaticHyphenWidth;
                // Count inter-word spaces strictly between the first and last non-space cell.
                var spaceCount = 0;
                for (var c = from; c < lastNonSpaceIdx; c++)
                    if (cells[c].Ch == ' ')
                        spaceCount++;
                if (spaceCount > 0)
                    wordGap = Math.Max(0, availableWidth - visibleWidth) / spaceCount;
            }
        }

        var pageSpaceY = ContentYToPageSpaceY(contentY);

        // AV-COL: compute the left edge of the column this line lands in.
        // slot = which column-slot (0-based across all pages); colIndex = slot % _colCount.
        var lineSlot = _layoutTextAreaHeight > 0 ? (int)(contentY / _layoutTextAreaHeight) : 0;
        var colLeft = _contentLeft + (lineSlot % _colCount) * (_colWidth + _colGap);

        DocumentFloatingTextWrapLinePlan? wrapLinePlan = null;
        if (_wrapExclusions.Count > 0)
        {
            wrapLinePlan = BuildFloatingTextWrapLinePlan(
                lineHeight,
                availableWidth,
                lineContentYDip: contentY,
                currentContentYDip: contentY);
            if (wrapLinePlan.HasTopAndBottomAdvance && wrapLinePlan.PlannedContentYDip > contentY)
            {
                _layoutContentY = wrapLinePlan.PlannedContentYDip;
                contentY = ReserveContentY(lineHeight);
                wrapLinePlan = BuildFloatingTextWrapLinePlan(
                    lineHeight,
                    availableWidth,
                    lineContentYDip: contentY,
                    currentContentYDip: contentY);
            }

            pageSpaceY = wrapLinePlan.PageSpaceYDip;
            colLeft = wrapLinePlan.ColumnLeftDip;
        }

        // AV-TAB: detect whether this line contains any tab characters.
        var lineHasTabs = false;
        for (var c = from; c < to; c++)
            if (cells[c].Ch == '\t') { lineHasTabs = true; break; }

        var splitLine = wrapLinePlan?.SplitLine;
        var usesSplitFloatFragments = splitLine is not null
            && alignment == TextAlignment.Left
            && !lineHasTabs
            && Math.Abs(leftInset) < 0.01;
        var wrapLeftDelta = usesSplitFloatFragments ? 0 : wrapLinePlan?.LeftDeltaDip ?? 0;
        var effectiveLeftInset = leftInset + wrapLeftDelta;
        var effectiveWidth = usesSplitFloatFragments
            ? splitLine!.EffectiveTextWidthDip
            : wrapLinePlan?.EffectiveTextWidthDip ?? availableWidth;
        if (effectiveWidth < 20) effectiveWidth = 20; // safety floor

        // Content origin: absolute left edge where pen-position 0 begins (before alignment offset).
        // Tab stops are measured from this origin, not from the alignment-shifted x.
        var contentOriginX = colLeft + effectiveLeftInset;

        // BP1 fix: OOXML w:tab/@w:pos is measured from the LEFT MARGIN (colLeft), not from the
        // indented paragraph origin.  Ruler.cs confirms: tab markers are placed at
        //   contentStart + PointsToDip(tab.PositionPt)
        // where contentStart = pageX + MarginLeft (excludes IndentLeftPt).
        // So the tab-stop coordinate origin is colLeft + wrapLeftDelta, NOT contentOriginX.
        // effectiveLeftInset = leftInset + wrapLeftDelta  →  tabOriginX = contentOriginX - leftInset.
        var tabOriginX = contentOriginX - leftInset;
        var alignOffset    = AlignmentOffset(alignment, effectiveWidth, lineWidth, isLast);

        // For lines without tabs, keep the existing simple path (no extra overhead).
        // For lines with tabs, alignment applies only to the pre-tab prefix segment; subsequent
        // segments are pinned absolutely to their stop positions.
        var x = contentOriginX + (lineHasTabs ? 0.0 : alignOffset);

        if (!string.IsNullOrWhiteSpace(pf.ShadingColorHex) || pf.Border is not null)
        {
            const double decorationPad = 2.0;
            if (usesSplitFloatFragments)
            {
                _paragraphDecorations.Add((
                    new Rect(contentOriginX - decorationPad, pageSpaceY,
                        Math.Max(1, splitLine!.FirstWidthDip + decorationPad * 2), lineHeight),
                    pf.ShadingColorHex,
                    pf.Border));
                _paragraphDecorations.Add((
                    new Rect(colLeft + splitLine.SecondStartDeltaDip - decorationPad, pageSpaceY,
                        Math.Max(1, splitLine.SecondWidthDip + decorationPad * 2), lineHeight),
                    pf.ShadingColorHex,
                    pf.Border));
            }
            else
            {
                _paragraphDecorations.Add((
                    new Rect(
                        contentOriginX - decorationPad,
                        pageSpaceY,
                        Math.Max(1, effectiveWidth + decorationPad * 2),
                        lineHeight),
                    pf.ShadingColorHex,
                    pf.Border));
            }
        }

        // AV-TAB: default tab interval for this line (from document page settings).
        var lineDefaultTabStopPt = Math.Max(1.0, _doc.Page.DefaultTabStopPt);

        // AV-TAB: pre-tab alignment offset for lines with tabs — applied to the pre-tab prefix.
        // We compute the pre-tab segment width and centre/right-align it, then the first tab snaps x.
        if (lineHasTabs && alignment != TextAlignment.Left && alignment != TextAlignment.Justify)
        {
            // Find the first tab in [from, to).
            var firstTabIdx = from;
            while (firstTabIdx < to && cells[firstTabIdx].Ch != '\t') firstTabIdx++;
            // Sum the pre-tab segment width.
            var preTabWidth = 0.0;
            for (var c = from; c < firstTabIdx; c++) preTabWidth += measured[c];
            // Apply alignment to pre-tab segment only.
            x += alignment switch
            {
                TextAlignment.Center => Math.Max(0, (effectiveWidth - preTabWidth) / 2),
                TextAlignment.Right  => Math.Max(0, effectiveWidth - preTabWidth),
                _                   => 0.0,
            };
        }

        var splitAt = to;
        var splitSecondStartX = 0.0;
        if (usesSplitFloatFragments)
        {
            var firstWidth = 0.0;
            var lastSplitBreak = -1;
            for (var c = from; c < to; c++)
            {
                if (cells[c].Ch == ' ')
                    lastSplitBreak = c + 1;
                if (firstWidth + measured[c] > splitLine!.FirstWidthDip)
                {
                    splitAt = lastSplitBreak > from ? lastSplitBreak : c;
                    break;
                }
                firstWidth += measured[c];
            }
            splitSecondStartX = colLeft + splitLine!.SecondStartDeltaDip;
        }

        var reviewPolicy = CurrentReviewDisplayPolicy;
        for (var c = from; c < to; c++)
        {
            if (usesSplitFloatFragments && c == splitAt)
                x = splitSecondStartX;

            if (!reviewPolicy.IsRevisionTextVisible(cells[c].Revision))
            {
                _placed.Add(new PlacedChar(blockIndex, SourceOffsetAt(c), x, pageSpaceY, 0, lineHeight, cells[c].Fmt, cells[c].Ch, Sentinel: false, CommentId: cells[c].CommentId, Revision: cells[c].Revision, RevisionAuthor: cells[c].RevisionAuthor, Link: cells[c].Link, HasFormatRevision: cells[c].FormatRevision is not null, FormatRevisionAuthor: cells[c].FormatRevision?.Author));
                continue;
            }

            if (cells[c].Ch == '\t')
            {
                // AV-TAB / BP1 fix: pen position and tab stops are relative to the margin origin
                // (tabOriginX = colLeft + wrapLeftDelta), NOT the indented content origin.
                var penPosInLine = x - tabOriginX;

                // Compute the advance: for left tabs this is straightforward. For center/right tabs the
                // shared planner needs the following segment's measured width.
                var segmentWidth = 0.0;
                double? decimalAlignmentOffset = null;
                for (var k = c + 1; k < to; k++)
                {
                    if (cells[k].Ch == '\t') break;
                    if (decimalAlignmentOffset is null && IsDecimalTabSeparator(cells[k].Ch))
                        decimalAlignmentOffset = segmentWidth;
                    segmentWidth += measured[k];
                }

                // Target X in page space where the segment should land.
                // BP1 fix: use tabOriginX (margin-relative) not contentOriginX (indent-relative).
                var plan = ParagraphTabStopLayoutPlanner.BuildPlacementPlan(
                    penPosInLine,
                    segmentWidth,
                    pf.TabStops,
                    lineDefaultTabStopPt,
                    PxPerPoint,
                    decimalAlignmentOffset);
                var segmentStartX = tabOriginX + plan.SegmentStartDip;

                // Tab glyph occupies the gap from current x to the segment start.
                var tabAdvance = plan.AdvanceDip;
                var tabX = x; // where the '\t' PlacedChar starts

                // Emit leader span if the tab stop has one.
                if (plan.HasLeader)
                    _tabLeaderSpans.Add((tabX, segmentStartX, pageSpaceY, lineHeight, plan.Leader, cells[c].Fmt));

                // Place the tab character with its computed advance width (for caret hit-testing).
                _placed.Add(new PlacedChar(blockIndex, SourceOffsetAt(c), tabX, pageSpaceY, tabAdvance, lineHeight, cells[c].Fmt, '\t', Sentinel: false, CommentId: cells[c].CommentId, Revision: cells[c].Revision, RevisionAuthor: cells[c].RevisionAuthor, Link: cells[c].Link, HasFormatRevision: cells[c].FormatRevision is not null, FormatRevisionAuthor: cells[c].FormatRevision?.Author));
                x = segmentStartX;
                continue;
            }

            _placed.Add(new PlacedChar(blockIndex, SourceOffsetAt(c), x, pageSpaceY, measured[c], lineHeight, cells[c].Fmt, cells[c].Ch, Sentinel: false, CommentId: cells[c].CommentId, Revision: cells[c].Revision, RevisionAuthor: cells[c].RevisionAuthor, Link: cells[c].Link, HasFormatRevision: cells[c].FormatRevision is not null, EquationElement: cells[c].EquationElement, FormatRevisionAuthor: cells[c].FormatRevision?.Author));
            x += measured[c];
            // Extra inter-word gap for justify alignment: only for spaces before the last non-space cell.
            if (wordGap > 0 && cells[c].Ch == ' ' && c < lastNonSpaceIdx)
                x += wordGap;
        }

        if (automaticHyphenWidth > 0
            && automaticHyphenSourceCell is { } sourceCell
            && automaticHyphenBreakOffset >= 0)
        {
            _automaticHyphenGlyphs.Add(new AutomaticHyphenGlyph(
                blockIndex,
                automaticHyphenBreakOffset,
                x,
                pageSpaceY,
                automaticHyphenWidth,
                lineHeight,
                sourceCell.Fmt,
                sourceCell.CommentId,
                sourceCell.Revision,
                sourceCell.RevisionAuthor,
                sourceCell.Link,
                sourceCell.FormatRevision));
            x += automaticHyphenWidth;
        }

        // End-of-line / end-of-paragraph sentinel carries the caret slot after the last char.
        if (isLast)
            _placed.Add(new PlacedChar(blockIndex, SourceOffsetAtBoundary(to), x, pageSpaceY, 0, lineHeight, RunFormatting.Default, '\0', Sentinel: true));

        _layoutContentY = contentY + lineHeight;
    }

    /// <summary>
    /// Applies the paragraph line-spacing rule to the natural line height and returns the final
    /// line height to use for layout. Matches Word's line-spacing semantics:
    /// <list type="bullet">
    ///   <item><see cref="LineSpacingRule.Multiple"/> — multiply natural height by <c>LineSpacing</c> (default 1.15).</item>
    ///   <item><see cref="LineSpacingRule.Exact"/> — always use <c>LineHeightPt * PxPerPoint</c> exactly.</item>
    ///   <item><see cref="LineSpacingRule.AtLeast"/> — use <c>LineHeightPt * PxPerPoint</c> as a floor, allow taller glyphs.</item>
    /// </list>
    /// Approximation: we use a 1.2× leading factor on the raw glyph height as the "natural" height
    /// baseline (Avalonia <see cref="FormattedText.Height"/> already includes leading). The
    /// multiplier is applied on top of that.
    /// </summary>
    private static double ApplyLineSpacing(double naturalHeight, ParagraphFormatting pf)
    {
        return pf.LineRule switch
        {
            LineSpacingRule.Exact   => Math.Max(1, pf.LineHeightPt  * PxPerPoint),
            LineSpacingRule.AtLeast => Math.Max(naturalHeight, pf.LineHeightPt * PxPerPoint),
            // A missing w:spacing/@w:line uses Word's natural single-line height. The model carries
            // 1.15 as a convenience default, but it is not an explicit OOXML line-spacing instruction.
            _ => (pf.LineSpacingIsSet || Math.Abs(pf.LineSpacing - ParagraphFormatting.Default.LineSpacing) > 0.0001)
                ? naturalHeight * (pf.LineSpacing > 0 ? pf.LineSpacing : 1.15)
                : naturalHeight,
        };
    }

    private bool UsesWordDefaultBodyLineBox(
        Paragraph paragraph,
        ParagraphFormatting paragraphFormatting,
        IReadOnlyList<Cell> cells)
    {
        if (paragraphFormatting.LineRule != LineSpacingRule.Multiple || paragraphFormatting.LineSpacingIsSet)
            return false;

        if (paragraph.StyleId is { Length: > 0 } styleId &&
            !string.Equals(styleId, "Normal", StringComparison.OrdinalIgnoreCase))
            return false;

        return cells.Count > 0 && cells.Where(cell => !IsTextHiddenInCurrentView(cell.Fmt)).All(cell =>
            string.Equals(cell.Fmt.FontFamily, "Calibri", StringComparison.OrdinalIgnoreCase) &&
            Math.Abs((cell.Fmt.FontSizePt ?? DefaultFontSizePt) - 11.0) < 0.01);
    }

    private static double AlignmentOffset(TextAlignment alignment, double textWidth, double lineWidth, bool isLast = false) => alignment switch
    {
        TextAlignment.Center  => Math.Max(0, (textWidth - lineWidth) / 2),
        TextAlignment.Right   => Math.Max(0, textWidth - lineWidth),
        // Justify: last line (or single-line paragraphs) fall back to left.
        TextAlignment.Justify => isLast ? 0 : 0, // x already adjusted by wordGap in caller
        _ => 0,
    };

    /// <summary>
    /// AV-COL-NONTXT: Returns the left edge of the document column that contains a piece of content
    /// at the given <paramref name="contentY"/> (the flowing content-space Y, not page-space Y).
    /// <para>
    /// The snaking column model works by dividing the continuous content-Y axis into slots of height
    /// <see cref="_layoutTextAreaHeight"/>. Slot <c>k</c> maps to column-index <c>k % _colCount</c>
    /// within a page. The left edge of that column is
    /// <c>_contentLeft + colIndex * (_colWidth + _colGap)</c>.
    /// </para>
    /// When <c>_colCount == 1</c> this returns <see cref="_contentLeft"/> unchanged (no regression).
    /// </summary>
    private double ColumnLeftFor(double contentY)
    {
        if (_colCount <= 1 || _layoutTextAreaHeight <= 0)
            return _contentLeft;
        var slot     = (int)(contentY / _layoutTextAreaHeight);
        var colIndex = slot % _colCount;
        return _contentLeft + colIndex * (_colWidth + _colGap);
    }

    // ── AV-TAB: tab-stop resolution helpers ───────────────────────────────────────────────────────

    /// <summary>
    /// Computes the measured width to assign to a <c>\t</c> cell in <see cref="LayoutParagraphPaged"/>'s
    /// wrapping loop.  <paramref name="penPosInLine"/> must be the pen distance from the
    /// <em>left margin / column left</em> (i.e. lineWidth + paraLeftInset + lineExtraInset),
    /// matching the coordinate system of <see cref="ParagraphTabStopLayoutPlanner.ResolveNextStop"/>.
    /// The advance is from the current pen to the resolved stop, clamped to at least 1 px.
    /// </summary>
    private static double ComputeTabMeasuredWidth(double penPosInLine, ParagraphFormatting pf, double defaultTabStopPt) =>
        ParagraphTabStopLayoutPlanner.ComputeTabAdvance(
            penPosInLine,
            pf.TabStops,
            defaultTabStopPt,
            PxPerPoint);

    private static bool IsDecimalTabSeparator(char ch) => ch is '.' or ',';

    private void LayoutReadOnlyBlockPaged(int blockIndex, Block block, double textWidth)
    {
        var text = block is Table table ? TablePlainText(table) : block.ToString() ?? "";
        var cells = FallbackCells(text);
        var measured = new double[cells.Count];
        var heights = new double[cells.Count];
        for (var c = 0; c < cells.Count; c++)
        {
            var ft = BuildForLayout(cells[c].Ch.ToString(), cells[c].Fmt);
            measured[c] = ft.WidthIncludingTrailingWhitespace;
            heights[c] = ft.Height;
        }

        EmitLinePaged(blockIndex, cells, measured, heights, 0, cells.Count, TextAlignment.Left, textWidth, 0, ParagraphFormatting.Default, isLast: true);
    }

    private static string TablePlainText(Table table) =>
        string.Join("  |  ", table.Rows.SelectMany(r => r.Cells).Select(c => c.PlainText));

    private static double ApplyAuthoredTableRowHeight(TableRow row, double measuredHeight)
    {
        var authoredHeight = row.HeightPt is > 0
            ? PageLayout.PointsToDip(row.HeightPt.Value)
            : 0;
        if (row.HeightRule == TableRowHeightRule.Exact && authoredHeight > 0)
            return Math.Max(14, authoredHeight);

        return Math.Max(measuredHeight, authoredHeight);
    }

    // ---- Table rendering (grid + modal cell text editing) ----------------------------------------

    private void LayoutTablePaged(int blockIndex, Table table, double textWidth)
    {
        var cols = Math.Max(1, table.ColumnCount);
        var colWidths = ComputeColumnWidths(table, cols, textWidth);
        // AV-COL-NONTXT AG1: build columnLeft[] as offsets from _contentLeft (column-0 base).
        // Each row re-applies the per-row column shift after reserving its Y slot.
        var colOffsets = new double[cols + 1]; // relative to _contentLeft
        var running = 0.0;
        for (var c = 0; c < cols; c++)
        {
            colOffsets[c] = running;
            running += colWidths[c];
        }
        colOffsets[cols] = running;

        const double pad = 5;
        // Word preserves the nominal table grid and treats tblCellSpacing as a gap around each
        // physical cell surface. Keep row measurement and pagination on the nominal grid; only
        // the painted cell and its content origin consume this surface reservation.
        var cellSpacingInset = table.CellSpacingPt is > 0
            ? table.CellSpacingPt.Value * PxPerPoint
            : 0;
        var borders = table.Formatting.Borders || _showTableGridlines;
        var tableLayoutPlan = DocumentViewLayoutPlanner.BuildTableLayoutPlan(
            table,
            page: _doc.Page,
            firstPageLeadingContentHeightDip: DocumentViewLayoutPlanner.EstimateLeadingContentHeightDip(
                _doc,
                blockIndex));
        var cellEffectiveFills = tableLayoutPlan.Cells.ToDictionary(
            cell => (cell.RowIndex, cell.CellIndex),
            cell => cell.EffectiveFill);
        var preservedNumberingMarkers = PreservedNumberingMarkerPlanner.BuildByParagraph(_doc);

        DocumentTableCellEffectiveFillPlan EffectiveFillFor(int rowIndex, int cellIndex) =>
            cellEffectiveFills.TryGetValue((rowIndex, cellIndex), out var fillPlan)
                ? fillPlan
                : DocumentTableCellEffectiveFillPlan.Empty;

        IBrush? EffectiveFillBrush(DocumentTableCellEffectiveFillPlan fillPlan) =>
            string.IsNullOrWhiteSpace(fillPlan.EffectiveFillHex)
                ? null
                : BrushFor(fillPlan.EffectiveFillHex);

        Rect SurfaceRectFor(double x, double y, double width, double height, int startCol, int span, int rowIndex)
        {
            if (cellSpacingInset <= 0)
                return new Rect(x, y, width, height);

            var endCol = startCol + span;
            var left = startCol == 0 ? 2 * cellSpacingInset : cellSpacingInset;
            var right = endCol == cols ? 2 * cellSpacingInset : cellSpacingInset;
            var top = rowIndex == 0 ? 2 * cellSpacingInset : cellSpacingInset;
            var bottom = rowIndex == table.Rows.Count - 1 ? 2 * cellSpacingInset : cellSpacingInset;
            return new Rect(
                x + left,
                y + top,
                Math.Max(1, width - left - right),
                Math.Max(1, height - top - bottom));
        }

        (double Before, double After) CellParagraphSpacing(Paragraph paragraph)
        {
            var formatting = ResolveParagraphFmt(paragraph);
            return (
                formatting.SpaceBeforeIsSet ? Math.Max(0, formatting.SpaceBeforePt) * PxPerPoint : 0,
                formatting.SpaceAfterIsSet ? Math.Max(0, formatting.SpaceAfterPt) * PxPerPoint : 0);
        }

        // AV-TBL: glyphOffset is unique within this table block and is used as PlacedChar.Offset so
        // TryGetCaretRect can match (Block == tableBlockIndex && Offset == glyphOffset).
        var glyphOffset = 0;

        // AV-TBL5-VRENDER-VMERGE: pre-compute every row's height up front. A vertical-merge Restart
        // cell needs the TOTAL height of all rows it spans to vertically align its content within the
        // whole merged region rather than just its own (first) row — that total isn't known yet when
        // the row loop below reaches the Restart row, since later rows haven't been measured. This
        // pass mirrors the exact rowHeight computation the main loop performs (same cell wrapping),
        // so results are identical — just computed early enough to sum across rows.
        var rowHeights = new double[table.Rows.Count];
        for (var pr = 0; pr < table.Rows.Count; pr++)
        {
            var prRow = table.Rows[pr];
            var prRowHeight = Build("Ag", RunFormatting.Default).Height + 2 * pad;
            foreach (var projected in TableGridProjection.ProjectRow(prRow))
            {
                var cell = projected.Cell;
                var cellIndex = projected.CellIndex;
                var prCol = projected.StartColumn;
                if (prCol >= cols)
                    break;
                var prSpan = TableGridProjection.SpanWithinWidth(projected, cols);
                double prCellWidth = 0;
                for (var s = 0; s < prSpan; s++)
                    prCellWidth += colWidths[prCol + s];

                var prFmt = cell.Paragraphs.Count > 0 && cell.Paragraphs[0].Runs.Count > 0
                    ? ResolveRunFmt(cell.Paragraphs[0].Runs[0].Formatting, cell.Paragraphs[0])
                    : RunFormatting.Default;
                if (EffectiveFillFor(pr, cellIndex).EffectiveBold)
                    prFmt = prFmt with { Bold = true };

                var prInnerW = Math.Max(10, prCellWidth - 2 * pad);
                var prParagraphs = cell.Paragraphs.Count > 0
                    ? cell.Paragraphs
                    : [new Paragraph()];
                var prCellHeight = prParagraphs.Sum(paragraph =>
                {
                    var spacing = CellParagraphSpacing(paragraph);
                    return WrapCellLines(blockIndex, paragraph, prFmt, prInnerW).Sum(line => line.Height)
                        + spacing.Before + spacing.After;
                }) + 2 * pad;
                if (prCellHeight > prRowHeight)
                    prRowHeight = prCellHeight;
            }
            rowHeights[pr] = ApplyAuthoredTableRowHeight(prRow, prRowHeight);
        }

        var floatingAnchorContentY = _layoutContentY;
        var floatingPlacement = tableLayoutPlan.FloatingPosition is { } floatingPosition
            && tableLayoutPlan.Pagination.Pages.Count == 1
            ? DocumentViewLayoutPlanner.BuildFloatingTablePlacement(
                _surfacePlan,
                floatingAnchorContentY,
                _colCount,
                running,
                rowHeights.Sum(),
                floatingPosition,
                ColumnLeftFor(floatingAnchorContentY),
                textWidth)
            : null;
        double? floatingVisualYOffsetDip = null;

        // WPF suppresses synthetic table page segments when a vertical merge is present. The
        // shared layout plan already records that eligibility fact, so use it as the cross-platform
        // authority instead of repeating headers across a merge boundary.
        var shouldRenderPlannedTablePages = _viewMode == DocumentViewMode.PrintLayout
            && tableLayoutPlan.Pagination.Pages.Count > 1
            && !tableLayoutPlan.HasVerticalMerges;
        var plannedPagesByFirstSourceRow = shouldRenderPlannedTablePages
            ? tableLayoutPlan.Pagination.Pages
                .Where(page => page.PageNumber > 1 && page.SourceRowIndexes.Count > 0)
                .ToDictionary(page => page.SourceRowIndexes[0])
            : new Dictionary<int, DocumentTablePaginationPagePlan>();

        double NextPhysicalPageStartContentY()
        {
            if (_layoutTextAreaHeight <= 0)
                return _layoutContentY;

            var slotsPerPage = Math.Max(1, _colCount);
            var currentSlot = Math.Max(0, (int)(_layoutContentY / _layoutTextAreaHeight));
            var currentPage = currentSlot / slotsPerPage;
            var currentPageStart = currentPage * slotsPerPage * _layoutTextAreaHeight;
            return _layoutContentY <= currentPageStart + 0.5
                ? _layoutContentY
                : (currentPage + 1) * slotsPerPage * _layoutTextAreaHeight;
        }

        void RenderTableRow(int r, double? reservedContentY = null)
        {
            var row = table.Rows[r];

            // AV-TBL: carry the TableCell model reference and actual column index so we can emit
            // per-paragraph, per-character cell-aware PlacedChars for caret routing.
            // BE2: CellParas holds wrapped lines per-paragraph (outer list = para, inner = wrapped lines).
            var measured = new List<(TableCell Cell, int CellIndex, int StartCol, int Span, List<List<CellWrappedLine>> CellParas, List<(double Before, double After)> ParagraphSpacings, List<double> MarkerInsets, RunFormatting Fmt)>();
            var rowHeight = Build("Ag", RunFormatting.Default).Height + 2 * pad;
            foreach (var projected in TableGridProjection.ProjectRow(row))
            {
                var cell = projected.Cell;
                var cellIndex = projected.CellIndex;
                var col = projected.StartColumn;
                if (col >= cols)
                    break;
                var span = TableGridProjection.SpanWithinWidth(projected, cols);
                double cellWidth = 0;
                for (var s = 0; s < span; s++)
                    cellWidth += colWidths[col + s];

                var fmt = cell.Paragraphs.Count > 0 && cell.Paragraphs[0].Runs.Count > 0
                    ? ResolveRunFmt(cell.Paragraphs[0].Runs[0].Formatting, cell.Paragraphs[0])
                    : RunFormatting.Default;
                var cellAppearance = EffectiveFillFor(r, cellIndex);
                if (cellAppearance.EffectiveBold)
                    fmt = fmt with { Bold = true };

                // BE2: wrap each cell paragraph independently so multi-paragraph cells render on
                // separate visual lines instead of collapsing onto one line via a '\n' glyph.
                var innerW = Math.Max(10, cellWidth - 2 * pad);
                var cellParagraphs = cell.Paragraphs.Count > 0
                    ? cell.Paragraphs
                    : [new Paragraph()];
                var markerInsets = cellParagraphs.Select(paragraph =>
                    preservedNumberingMarkers.TryGetValue(paragraph, out var marker)
                        ? Build(marker.Text, fmt).WidthIncludingTrailingWhitespace + 6
                        : 0d).ToList();
                var paragraphSpacings = cellParagraphs.Select(CellParagraphSpacing).ToList();
                var cellParas = cellParagraphs.Select((paragraph, paragraphIndex) =>
                    WrapCellLines(blockIndex, paragraph, fmt, Math.Max(10, innerW - markerInsets[paragraphIndex]))).ToList();
                var lines = cellParas.SelectMany(pl => pl).ToList(); // flattened for height calc
                var cellHeight = lines.Sum(l => l.Height)
                    + paragraphSpacings.Sum(spacing => spacing.Before + spacing.After)
                    + 2 * pad;
                if (cellHeight > rowHeight)
                    rowHeight = cellHeight;

                measured.Add((cell, cellIndex, col, span, cellParas, paragraphSpacings, markerInsets, fmt));
            }

            rowHeight = ApplyAuthoredTableRowHeight(row, rowHeight);

            // Treat the row as a unit: reserve space on the current page (or push to next).
            var rowContentY = reservedContentY ?? ReserveContentY(rowHeight);
            var rowPageSpaceY = ContentYToPageSpaceY(rowContentY);
            if (floatingPlacement is not null)
            {
                floatingVisualYOffsetDip ??= floatingPlacement.YDip - rowPageSpaceY;
                rowPageSpaceY += floatingVisualYOffsetDip.Value;
            }

            // AV-COL-NONTXT AG1: use the column band that this row's content-Y falls in.
            var rowColLeft = floatingPlacement?.XDip ?? ColumnLeftFor(rowContentY);

            foreach (var (cellModel, cellIndex, startCol, span, cellParas, paragraphSpacings, markerInsets, fmt) in measured)
            {
                double cellWidth = 0;
                for (var s = 0; s < span; s++)
                    cellWidth += colWidths[startCol + s];
                var cellX = rowColLeft + colOffsets[startCol];
                var rect = SurfaceRectFor(cellX, rowPageSpaceY, cellWidth, rowHeight, startCol, span, r);
                var fill = EffectiveFillBrush(EffectiveFillFor(r, cellIndex));
                var cellBorderPlan = TableCellBorderVisualPlanner.Build(cellModel.Borders, PxPerPoint);
                _rects.Add((rect, fill, borders, cellBorderPlan.HasVisibleEdges ? cellBorderPlan : null));
                _cellHits.Add((rect, blockIndex, r, startCol));

                // AV-TBL5-VRENDER: per-cell vertical alignment offset within the row.
                // cellAvailableHeight = row interior height (row height minus top+bottom padding).
                // contentHeight = sum of this cell's laid-out line heights.
                // For single-row cells (no rowspan), the available height is the full row interior.
                //
                // AV-TBL5-VRENDER-VMERGE: for a cell that STARTS a vertical merge (Restart), Word
                // aligns the content within the height of the WHOLE merged span, not just the first
                // row. Sum the pre-computed heights of every row this cell spans (this row plus each
                // consecutive VerticalMerge.Continue cell below it at the same grid column) and use
                // that as the available height instead of the single rowHeight. A non-merged cell
                // (span 1) is unaffected — cellAvailableHeight still reduces to rowHeight - 2*pad.
                //
                // Paginated cells (content split across pages): ReserveContentY treats the row as a
                // unit so the whole row lands on one page; no per-page split of a single row occurs,
                // so the vAlign offset is safe to apply without extra pagination logic. If a merged
                // span crosses a page break, the span-height sum still uses each row's full measured
                // height (best-effort — matches the existing per-row pagination behavior rather than
                // clipping the merged region further).
                var cellLines = cellParas.SelectMany(pl => pl).ToList();
                var contentHeight = cellLines.Sum(l => l.Height)
                    + paragraphSpacings.Sum(spacing => spacing.Before + spacing.After);
                var mergedSpanHeight = rowHeight;
                if (cellModel.VerticalMerge == VerticalMergeState.Restart)
                {
                    mergedSpanHeight = 0;
                    for (var mr = r; mr < table.Rows.Count; mr++)
                    {
                        if (mr > r && GetCellModelGridCol(table, mr, startCol)?.VerticalMerge != VerticalMergeState.Continue)
                            break;
                        mergedSpanHeight += mr == r ? rowHeight : rowHeights[mr];
                    }
                }
                var cellAvailableHeight = mergedSpanHeight - 2 * pad;
                var vAlignOffset = cellModel.VerticalAlignment switch
                {
                    TableCellVerticalAlignment.Center =>
                        Math.Max(0.0, (cellAvailableHeight - contentHeight) / 2.0),
                    TableCellVerticalAlignment.Bottom =>
                        Math.Max(0.0, cellAvailableHeight - contentHeight),
                    _ => 0.0  // Top (default)
                };
                var contentTopY = rect.Top + pad + vAlignOffset;

                var ty = contentTopY;
                // BE2+BE1: iterate paragraphs independently — each paragraph's wrapped lines render
                // on their own visual Y band, so multi-paragraph cells never collapse to one line.
                // BE1: emit one sentinel PlacedChar per paragraph so the caret is findable at the
                // end of every paragraph, not just the last one.
                for (var pIdx = 0; pIdx < cellParas.Count; pIdx++)
                {
                    var paraLines = cellParas[pIdx];
                    var paraCharOffset = 0;
                    var markerInset = markerInsets[pIdx];
                    var paragraphSpacing = paragraphSpacings[pIdx];
                    ty += paragraphSpacing.Before;
                    if (cellModel.Paragraphs.Count > pIdx
                        && preservedNumberingMarkers.TryGetValue(cellModel.Paragraphs[pIdx], out var preservedMarker))
                    {
                        // Markers are visual chrome, so they reserve the first-line leading space but
                        // are not added to editable table-cell character offsets.
                        _markers.Add((rect.Left + pad, ty, preservedMarker.Text, fmt));
                    }

                    foreach (var line in paraLines)
                    {
                        var lineHeight = line.Height;
                        var tx = rect.Left + pad + markerInset;
                        foreach (var item in line.Items)
                        {
                            if (item.EmbeddedObject is { } embeddedObject)
                            {
                                var objectY = ty + Math.Max(0, lineHeight - item.Height);
                                var objectRect = new Rect(tx, objectY, item.Width, item.Height);
                                _inlineEmbeddedObjects.Add(new InlineEmbeddedObjectData(
                                    objectRect,
                                    embeddedObject,
                                    embeddedObject.Icon is null ? null : DecodeRenderedImage(embeddedObject.Icon),
                                    blockIndex,
                                    item.RunIndex,
                                    r,
                                    startCol,
                                    pIdx));
                                _placed.Add(new PlacedChar(blockIndex, glyphOffset, tx, objectY, 0, item.Height,
                                    fmt, '\0', Sentinel: false, CellRow: r, CellCol: startCol,
                                    CellParaIdx: pIdx, CellParaOffset: paraCharOffset));
                                glyphOffset++;
                                tx += item.Width;
                                continue;
                            }

                            var ch = item.Ch;
                            var w = item.Width;
                            var hidden = item.Hidden;
                            var placedFormatting = hidden ? fmt with { Hidden = true } : fmt;
                            _placed.Add(new PlacedChar(blockIndex, glyphOffset, tx, ty, w, lineHeight, placedFormatting, ch,
                                Sentinel: false, CellRow: r, CellCol: startCol, CellParaIdx: pIdx, CellParaOffset: paraCharOffset));
                            glyphOffset++;
                            paraCharOffset++;
                            tx += w;
                        }

                        if (line.AutomaticHyphenWidth > 0)
                        {
                            _automaticHyphenGlyphs.Add(new AutomaticHyphenGlyph(
                                blockIndex,
                                glyphOffset,
                                tx,
                                ty,
                                line.AutomaticHyphenWidth,
                                lineHeight,
                                fmt,
                                CommentId: null,
                                Revision: RevisionKind.None,
                                RevisionAuthor: null,
                                Link: null,
                                FormatRevision: null));
                        }

                        ty += lineHeight;
                    }

                    ty += paragraphSpacing.After;

                    // BE1: sentinel at end of this paragraph (at the end of its last visual line).
                    CellWrappedLine? lastParaLine = paraLines.Count > 0 ? paraLines[^1] : null;
                    var sentinelX = rect.Left + pad + markerInset
                        + (lastParaLine.HasValue ? lastParaLine.Value.Items.Sum(item => item.Width) : 0);
                    var sentinelY = lastParaLine.HasValue
                        ? ty - paragraphSpacing.After - lastParaLine.Value.Height
                        : contentTopY;
                    var sentinelH = lastParaLine.HasValue ? lastParaLine.Value.Height : Build("A", fmt).Height;
                    var sentinelParaOffset = cellModel.Paragraphs.Count > pIdx
                        ? cellModel.Paragraphs[pIdx].PlainText.Length
                        : 0;
                    _placed.Add(new PlacedChar(blockIndex, glyphOffset, sentinelX, sentinelY, 0, sentinelH, fmt, '\0',
                        Sentinel: true, CellRow: r, CellCol: startCol, CellParaIdx: pIdx, CellParaOffset: sentinelParaOffset));
                    glyphOffset++;
                }
            }

            _layoutContentY = rowContentY + rowHeight;
        }

        for (var r = 0; r < table.Rows.Count; r++)
        {
            if (plannedPagesByFirstSourceRow.TryGetValue(r, out var plannedPage))
            {
                var nextPageStart = NextPhysicalPageStartContentY();
                if (nextPageStart > _layoutContentY)
                    _layoutContentY = nextPageStart;

                var openingRows = plannedPage.RenderRows
                    .TakeWhile(row => row.IsRepeatedHeader || row.SourceRowIndex == r)
                    .ToList();
                var openingRowsHeight = openingRows.Sum(row =>
                    row.SourceRowIndex >= 0 && row.SourceRowIndex < rowHeights.Length
                        ? rowHeights[row.SourceRowIndex]
                        : Math.Max(0, row.EstimatedHeightDip));
                _layoutContentY = ReserveContentY(openingRowsHeight);

                foreach (var repeatedHeaderRow in openingRows.Where(row => row.IsRepeatedHeader))
                {
                    if (repeatedHeaderRow.SourceRowIndex >= 0 && repeatedHeaderRow.SourceRowIndex < table.Rows.Count)
                        RenderTableRow(repeatedHeaderRow.SourceRowIndex, _layoutContentY);
                }
            }

            RenderTableRow(r);
        }

        if (floatingVisualYOffsetDip is > 0)
            _layoutContentY += floatingVisualYOffsetDip.Value;
        _layoutContentY += 8;
    }

    private void LayoutImageParagraphPaged(int blockIndex, Paragraph paragraph, double textWidth)
    {
        const double gap = 6;
        var alignment = paragraph.Formatting.Alignment;

        // Collect floating images and shapes using the post-break first-line content Y so that
        // VerticalAnchor.Paragraph floats land on the same page as the first inline image.
        //
        // TT1 fix: compute the image paragraph's first-line height (the first inline image's pixel
        // height) and pass it to PeekFirstLineContentY so the page-break probe matches the actual
        // first ReserveContentY call for that image.
        double firstImgLineH = 1; // fallback: default probe height
        foreach (var run in paragraph.Runs)
        {
            if (run.Image is not { IsFloating: false } firstImg) continue;
            var imgH = firstImg.HeightPt > 0 ? firstImg.HeightPt * PxPerPoint : 80;
            firstImgLineH = imgH;
            break;
        }
        var anchorContentY = PeekFirstLineContentY(firstImgLineH);
        CollectFloatingObjects(blockIndex, paragraph, anchorContentY);

        foreach (var run in paragraph.Runs)
        {
            if (run.Image is not { IsFloating: false } image)
                continue; // Skip floating images — they are handled by CollectFloatingObjects.

            var width = image.WidthPt > 0 ? image.WidthPt * PxPerPoint : 120;
            var height = image.HeightPt > 0 ? image.HeightPt * PxPerPoint : 80;
            if (width > textWidth)
            {
                var scale = textWidth / width;
                width = textWidth;
                height *= scale;
            }

            var imgContentY = ReserveContentY(height);
            var imgPageSpaceY = ContentYToPageSpaceY(imgContentY);
            // AV-COL-NONTXT AG2: shift X to the column band that this image's content-Y falls in.
            var x = ColumnLeftFor(imgContentY) + AlignmentOffset(alignment, textWidth, width);
            _images.Add((new Rect(x, imgPageSpaceY, width, height), DecodeRenderedImage(image), image,
                image.ReflectionPreset, blockIndex));
            _layoutContentY = imgContentY + height + ReflectionExtraHeight(image, height) + gap;
        }
    }

    /// <summary>
    /// FO4: lays out a paragraph that contains inline (non-floating) charts, WordArt, or SmartArt.
    /// Each inline object reserves a line-box in the flow (like an inline image) and is stored in
    /// <c>_inlineCharts</c> / <c>_inlineWordArts</c> / <c>_inlineSmartArts</c> for rendering.
    /// A zero-width sentinel <see cref="PlacedChar"/> is emitted so that caret navigation steps over
    /// each object as a single atomic position.  Floating objects anchored to this paragraph are also
    /// collected via the normal FO1-FO3 helpers.
    /// </summary>
    private void LayoutInlineObjectParagraphPaged(int blockIndex, Paragraph paragraph, double textWidth)
    {
        const double gap = 6;
        var alignment = paragraph.Formatting.Alignment;

        // YY1 fix: compute the first inline object's pixel height (chart/WordArt/SmartArt/image, in
        // document order, using the same size formulas as the layout loop below) and pass it to
        // PeekFirstLineContentY so that Peek's page-break probe matches the actual first
        // ReserveContentY call.  Before this fix, PeekFirstLineContentY() used the default lineHeight=1,
        // which failed to detect the page-break for a tall inline chart/SmartArt near a page bottom —
        // the inline object correctly broke to the next page but the floating object anchored to this
        // paragraph stayed on the prior page (wrong).  Mirrors the TT1/VV1 fix in LayoutImageParagraphPaged.
        double firstObjHeight = DefaultFontSizePt * PxPerPoint * 1.3; // fallback: default text line height
        for (var runIndex = 0; runIndex < paragraph.Runs.Count; runIndex++)
        {
            var run = paragraph.Runs[runIndex];
            if (run.Shape is { IsFloating: false } firstShape)
            {
                var h = firstShape.HeightPt > 0 ? firstShape.HeightPt * PxPerPoint : 80;
                var w = firstShape.WidthPt > 0 ? firstShape.WidthPt * PxPerPoint : 120;
                if (w > textWidth) h *= textWidth / w;
                firstObjHeight = h;
                break;
            }
            if (run.Chart is { IsFloating: false } firstChart)
            {
                var h = firstChart.HeightPt > 0 ? firstChart.HeightPt * PxPerPoint : 216 * PxPerPoint;
                // Apply width-constrained scale if needed (mirrors the layout loop).
                var w = firstChart.WidthPt > 0 ? firstChart.WidthPt * PxPerPoint : 360 * PxPerPoint;
                if (w > textWidth) h *= textWidth / w;
                firstObjHeight = h;
                break;
            }
            if (run.WordArt is { IsFloating: false } firstWa)
            {
                var w = Math.Max(72, firstWa.FontSizePt * Math.Max(1, firstWa.Text.Length) * 0.62) * PxPerPoint;
                var h = Math.Max(40, firstWa.FontSizePt * 1.6) * PxPerPoint;
                if (w > textWidth) h *= textWidth / w;
                firstObjHeight = h;
                break;
            }
            if (run.SmartArt is { IsFloating: false } firstSa)
            {
                var h = firstSa.HeightPt > 0 ? firstSa.HeightPt * PxPerPoint : 216 * PxPerPoint;
                var w = firstSa.WidthPt  > 0 ? firstSa.WidthPt  * PxPerPoint : 468 * PxPerPoint;
                if (w > textWidth) h *= textWidth / w;
                firstObjHeight = h;
                break;
            }
            if (run.EmbeddedObject is { } firstEmbedded)
            {
                var plan = EmbeddedObjectVisualPlanner.Build(firstEmbedded);
                var width = plan.WidthPt * PxPerPoint;
                var height = plan.HeightPt * PxPerPoint;
                if (width > textWidth)
                    height *= textWidth / width;
                firstObjHeight = height;
                break;
            }
            if (run.Image is { IsFloating: false } firstImg)
            {
                firstObjHeight = firstImg.HeightPt > 0 ? firstImg.HeightPt * PxPerPoint : 80;
                break;
            }
            // Plain text run: use text-line height as the Peek estimate.
            if (!string.IsNullOrEmpty(run.Text))
            {
                var formatting = ResolveRunFmt(run.Formatting, paragraph);
                if (IsTextHiddenInCurrentView(formatting))
                    continue;
                firstObjHeight = Build("Ag", formatting).Height;
                break;
            }
        }
        // Collect floating objects anchored to this paragraph (mirrors LayoutImageParagraphPaged).
        var anchorContentY = PeekFirstLineContentY(firstObjHeight);
        CollectFloatingObjects(blockIndex, paragraph, anchorContentY);

        // Track a virtual glyph offset so the caret can step over inline objects.
        var glyphOffset = _placed.Count > 0
            ? _placed.Max(p => p.Block == blockIndex ? p.Offset : -1) + 1
            : 0;

        for (var runIndex = 0; runIndex < paragraph.Runs.Count; runIndex++)
        {
            var run = paragraph.Runs[runIndex];
            if (run.Image is { IsFloating: false } image)
            {
                var width = image.WidthPt > 0 ? image.WidthPt * PxPerPoint : 120;
                var height = image.HeightPt > 0 ? image.HeightPt * PxPerPoint : 80;
                if (width > textWidth) { var scale = textWidth / width; width = textWidth; height *= scale; }

                var contentY = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                var x = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                _images.Add((new Rect(x, pageSpaceY, width, height), DecodeRenderedImage(image), image,
                    image.ReflectionPreset, blockIndex));
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));
                _layoutContentY = contentY + height + ReflectionExtraHeight(image, height) + gap;
                continue;
            }

            if (run.Shape is { IsFloating: false } shape)
            {
                var width = shape.WidthPt > 0 ? shape.WidthPt * PxPerPoint : 120;
                var height = shape.HeightPt > 0 ? shape.HeightPt * PxPerPoint : 80;
                if (width > textWidth) { var scale = textWidth / width; width = textWidth; height *= scale; }

                var contentY = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                var x = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                var rect = new Rect(x, pageSpaceY, width, height);
                var snapshot = BuildInlineDrawingSnapshot(
                    DocumentFloatingObjectKind.Shape,
                    rect,
                    blockIndex,
                    runIndex,
                    shape.RotationAngle,
                    shape.FlipH,
                    shape.FlipV);
                var shapeData = BuildFloatingShapeData(
                    DrawingObjectVisualPlanner.BuildVisualPlan(shape, snapshot),
                    blockIndex,
                    runIndex);
                shapeData.Model = shape;
                shapeData.TextLayout = BuildFloatingShapeTextLayout(shapeData, rect);
                _inlineShapes.Add(shapeData);
                BuildShapeTextCaretStops(shapeData);
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));
                _layoutContentY = contentY + height + gap;
                continue;
            }
            // ── Inline chart ─────────────────────────────────────────────────────────
            if (run.Chart is { IsFloating: false } chart)
            {
                var width  = chart.WidthPt  > 0 ? chart.WidthPt  * PxPerPoint : 360 * PxPerPoint;
                var height = chart.HeightPt > 0 ? chart.HeightPt * PxPerPoint : 216 * PxPerPoint;
                if (width > textWidth) { var s = textWidth / width; width = textWidth; height *= s; }

                var contentY   = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                // AV-COL-NONTXT AG3: shift X to the column band for this inline chart's content-Y.
                var x          = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                var rect       = new Rect(x, pageSpaceY, width, height);

                // Build inline chart data (reuses the same struct as floating charts).
                var chartData = BuildChartData(chart, rect, behindText: false, zOrder: 0);
                chartData.BlockIndex = blockIndex;
                chartData.RunIndex = runIndex;
                _inlineCharts.Add(chartData);

                // ZZ1 fix: use the FULL object box as the hit-test band so TryHitTest/MoveCaretVertical
                // can reach a tall inline chart from above (pressing Down) or via a click in the upper
                // portion.  PlacedChar has no separate caret-draw Y field, so navigation correctness
                // takes priority; the YY3 baseline-cosmetic is dropped (it was LOW value, caused a MED
                // regression).  Y = pageSpaceY and LineHeight = height → band is [top, bottom].
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));

                _layoutContentY = contentY + height + gap;
                continue;
            }

            // ── Inline WordArt ───────────────────────────────────────────────────────
            if (run.WordArt is { IsFloating: false } wa)
            {
                // Size: estimate from text + font size (same formula as floating WordArt collector).
                var width  = Math.Max(72, wa.FontSizePt * Math.Max(1, wa.Text.Length) * 0.62) * PxPerPoint;
                var height = Math.Max(40, wa.FontSizePt * 1.6) * PxPerPoint;
                if (width > textWidth) { var s = textWidth / width; width = textWidth; height *= s; }

                var contentY   = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                // AV-COL-NONTXT AG3: shift X to the column band for this inline WordArt's content-Y.
                var x          = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                var rect       = new Rect(x, pageSpaceY, width, height);

                _inlineWordArts.Add(BuildInlineWordArtData(wa, rect, blockIndex, runIndex));

                // ZZ1 fix: full-height sentinel for correct hit-test reach (see chart site above).
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));

                _layoutContentY = contentY + height + gap;
                continue;
            }

            // ── Inline SmartArt ──────────────────────────────────────────────────────
            if (run.SmartArt is { IsFloating: false } sa)
            {
                var width  = sa.WidthPt  > 0 ? sa.WidthPt  * PxPerPoint : 468 * PxPerPoint;
                var height = sa.HeightPt > 0 ? sa.HeightPt * PxPerPoint : 216 * PxPerPoint;
                if (width > textWidth) { var s = textWidth / width; width = textWidth; height *= s; }

                var contentY   = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                // AV-COL-NONTXT AG3: shift X to the column band for this inline SmartArt's content-Y.
                var x          = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                var rect       = new Rect(x, pageSpaceY, width, height);

                _inlineSmartArts.Add(BuildFloatingSmartArtData(
                    sa,
                    rect,
                    behindText: false,
                    zOrder: 0,
                    blockIndex,
                    runIndex));

                // ZZ1 fix: full-height sentinel for correct hit-test reach (see chart site above).
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));

                _layoutContentY = contentY + height + gap;
                continue;
            }

            if (run.EmbeddedObject is { } embeddedObject)
            {
                var plan = EmbeddedObjectVisualPlanner.Build(embeddedObject);
                var width = plan.WidthPt * PxPerPoint;
                var height = plan.HeightPt * PxPerPoint;
                if (width > textWidth)
                {
                    var scale = textWidth / width;
                    width = textWidth;
                    height *= scale;
                }

                var contentY = ReserveContentY(height);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                var x = ColumnLeftFor(contentY) + AlignmentOffset(alignment, textWidth, width);
                _inlineEmbeddedObjects.Add(new InlineEmbeddedObjectData(
                    new Rect(x, pageSpaceY, width, height),
                    plan,
                    plan.Icon is null ? null : DecodeRenderedImage(plan.Icon),
                    blockIndex,
                    runIndex));
                _placed.Add(new PlacedChar(blockIndex, glyphOffset++, x, pageSpaceY, 0, height,
                    RunFormatting.Default, '\0', Sentinel: false));
                _layoutContentY = contentY + height + gap;
                continue;
            }

            // ── Inline text runs in the same paragraph ───────────────────────────────
            // (Treat any plain text runs as a single-line text block so mixed paragraphs
            //  with text + inline objects still show the text.)
            if (!string.IsNullOrEmpty(run.Text))
            {
                var fmt = ResolveRunFmt(run.Formatting, paragraph);
                if (IsTextHiddenInCurrentView(fmt))
                {
                    var hiddenY = ContentYToPageSpaceY(_layoutContentY);
                    var hiddenX = ColumnLeftFor(_layoutContentY);
                    foreach (var ch in run.Text)
                    {
                        _placed.Add(new PlacedChar(blockIndex, glyphOffset++, hiddenX, hiddenY,
                            0, 0, fmt, ch, Sentinel: false));
                    }
                    continue;
                }

                var lineH = Build("Ag", fmt).Height;
                var contentY   = ReserveContentY(lineH);
                var pageSpaceY = ContentYToPageSpaceY(contentY);
                // AV-COL-NONTXT AG3: shift X to the column band for this inline text's content-Y.
                var tx = ColumnLeftFor(contentY);
                foreach (var ch in run.Text)
                {
                    var ft = Build(ch.ToString(), fmt);
                    _placed.Add(new PlacedChar(blockIndex, glyphOffset++, tx, pageSpaceY,
                        ft.WidthIncludingTrailingWhitespace, lineH, fmt, ch, Sentinel: false));
                    tx += ft.WidthIncludingTrailingWhitespace;
                }
                _layoutContentY = contentY + lineH;
            }
        }

        // End-of-paragraph sentinel so the caret can rest after the last inline object.
        // AV-COL-NONTXT AG3: use the column-shifted X for the sentinel as well.
        var sentinelY = _placed.Count > 0
            ? _placed.Last(p => p.Block == blockIndex).Y
            : ContentYToPageSpaceY(_layoutContentY);
        _placed.Add(new PlacedChar(blockIndex, glyphOffset, ColumnLeftFor(_layoutContentY), sentinelY,
            0, DefaultFontSizePt * PxPerPoint * 1.3, RunFormatting.Default, '\0', Sentinel: true));

        _layoutContentY += gap;
    }

    // Internal for render-pipeline tests; the cache owns the returned rendered image.
    internal Bitmap? DecodeBitmap(InlineImage image)
        => DecodeRenderedImage(image)?.Bitmap;

    internal AvaloniaRenderedImage? DecodeRenderedImage(InlineImage image)
    {
        if (_bitmapCache.TryGetValue(image, out var cached))
            return cached;

        AvaloniaRenderedImage? rendered = null;
        Bitmap? decoded = null;
        try
        {
            if (image.DisplayBytes.Length > 0)
            {
                using var stream = new MemoryStream(image.DisplayBytes);
                decoded = new Bitmap(stream);
                var applied = AvaloniaImageAdjustHelper.ApplyWithBounds(decoded, image);
                rendered = new AvaloniaRenderedImage(applied.Bitmap, applied.SourcePixelRect);
                if (ReferenceEquals(applied.Bitmap, decoded))
                {
                    // The neutral fast path returns the decoded instance; transfer ownership to the cache.
                    decoded = null;
                }
                else
                {
                    decoded.Dispose();
                    decoded = null;
                }
            }
        }
        catch (Exception)
        {
            rendered?.Dispose();
            rendered = null; // undecodable -> placeholder rendered instead
        }
        finally
        {
            decoded?.Dispose();
        }

        _bitmapCache[image] = rendered;
        return rendered;
    }

    private void CollectFloatingObjects(int blockIndex, Paragraph paragraph, double anchorContentY)
    {
        var snapshots = DocumentViewLayoutPlanner.BuildFloatingObjectSnapshots(
            paragraph,
            blockIndex,
            anchorContentY,
            _surfacePlan,
            _colCount);

        if (snapshots.Count == 0)
            return;

        _floatingSnapshots.AddRange(snapshots);
        _wrapExclusions.AddRange(DocumentViewLayoutPlanner.BuildFloatingWrapExclusionZones(snapshots));

        foreach (var snapshot in snapshots)
        {
            if (snapshot.RunIndex < 0 || snapshot.RunIndex >= paragraph.Runs.Count)
                continue;

            var run = paragraph.Runs[snapshot.RunIndex];
            var rect = ToAvaloniaRect(snapshot.Rect);

            switch (snapshot.Kind)
            {
                case DocumentFloatingObjectKind.Image when run.Image is { IsFloating: true } img:
                    _floatingImages.Add((
                        rect,
                        DecodeRenderedImage(img),
                        img,
                        img.ReflectionPreset,
                        snapshot.BehindText,
                        snapshot.ZOrderIndex,
                        snapshot.BlockIndex,
                        snapshot.RunIndex));
                    break;

                case DocumentFloatingObjectKind.Shape when run.Shape is { IsFloating: true } shape:
                    var shapeData = BuildFloatingShapeData(
                        DrawingObjectVisualPlanner.BuildVisualPlan(shape, snapshot),
                        snapshot.BlockIndex,
                        snapshot.RunIndex);
                    shapeData.TextLayout = BuildFloatingShapeTextLayout(shapeData, rect);
                    _floatingShapes.Add(shapeData);
                    BuildShapeTextCaretStops(shapeData);
                    break;

                case DocumentFloatingObjectKind.Chart when run.Chart is { IsFloating: true } chart:
                    var chartData = BuildChartData(chart, rect, snapshot.BehindText, snapshot.ZOrderIndex);
                    chartData.BlockIndex = snapshot.BlockIndex;
                    chartData.RunIndex = snapshot.RunIndex;
                    _floatingCharts.Add(chartData);
                    break;

                case DocumentFloatingObjectKind.WordArt when run.WordArt is { IsFloating: true } wordArt:
                    _floatingWordArts.Add(BuildFloatingWordArtData(
                        DrawingObjectVisualPlanner.BuildVisualPlan(wordArt, snapshot),
                        snapshot.BlockIndex,
                        snapshot.RunIndex));
                    break;

                case DocumentFloatingObjectKind.SmartArt when run.SmartArt is { IsFloating: true } smartArt:
                    _floatingSmartArts.Add(BuildFloatingSmartArtData(
                        smartArt,
                        rect,
                        snapshot.BehindText,
                        snapshot.ZOrderIndex,
                        snapshot.BlockIndex,
                        snapshot.RunIndex));
                    break;

                case DocumentFloatingObjectKind.Group when run.DrawingGroup is { } group:
                    _floatingGroups.Add(BuildFloatingGroupData(group, snapshot));
                    break;
            }
        }
    }

    private DrawingObjectTextLayoutPlan? BuildFloatingShapeTextLayout(FloatingShapeData shapeData, Rect rect)
    {
        if (shapeData.TextPlan is not { } plan)
            return null;

        var isRotated = plan.Direction is ShapeTextDirection.Rotate90 or ShapeTextDirection.Rotate270;
        var layoutWidth = isRotated ? rect.Height : rect.Width;
        var layoutHeight = isRotated ? rect.Width : rect.Height;
        return DrawingObjectTextLayoutPlanner.LayoutPlan(
            plan,
            layoutWidth,
            layoutHeight,
            (value, formatting) => Build(value, formatting).WidthIncludingTrailingWhitespace,
            formatting => Build("Ag", formatting).Height);
    }

    /// <summary>
    /// Builds pointer-addressable caret stops from the shared floating-text layout. The renderer, hit-test,
    /// drag-selection, and selection paint all consume the same run-aware positions and font metrics.
    /// </summary>
    private void BuildShapeTextCaretStops(FloatingShapeData shapeData)
    {
        if (shapeData.TextLayout is not { } layout)
            return;

        var rotationRadians = shapeData.TextDirection == ShapeTextDirection.Rotate90
            ? Math.PI / 2
            : shapeData.TextDirection == ShapeTextDirection.Rotate270
                ? -Math.PI / 2
                : 0;
        var rect = shapeData.Rect;
        var rotationCenter = new Point(rect.Center.X, rect.Center.Y);
        var origin = ShapeTextLayoutOrigin(rect, layout);

        foreach (var stop in layout.CaretStops)
        {
            AddShapeTextCaretStop(
                shapeData.BlockIndex,
                shapeData.RunIndex,
                stop.ParagraphIndex,
                stop.RunIndex,
                stop.Offset,
                origin.X + stop.X,
                origin.Y + stop.Y,
                stop.Height,
                rotationRadians,
                rotationCenter,
                shapeData.ChildPath);
        }
    }

    private static Point ShapeTextLayoutOrigin(Rect rect, DrawingObjectTextLayoutPlan layout) =>
        new(rect.Center.X - layout.Width / 2, rect.Center.Y - layout.Height / 2);

    private void AddShapeTextCaretStop(
        int blockIndex,
        int runIndex,
        int paragraphIndex,
        int textRunIndex,
        int offset,
        double x,
        double y,
        double height,
        double rotationRadians,
        Point rotationCenter,
        IReadOnlyList<int>? childPath = null) =>
        _shapeTextCaretStops.Add(new ShapeTextCaretStop(
            blockIndex, runIndex, paragraphIndex, textRunIndex, offset, x, y, height,
            rotationRadians, rotationCenter.X, rotationCenter.Y,
            childPath?.ToArray()));

    private static FloatingShapeData BuildFloatingShapeData(
        DrawingObjectVisualPlan plan,
        int blockIndex = -1,
        int runIndex = -1)
    {
        var rect = ToAvaloniaRect(plan.Rect);
        IBrush? fillBrush = plan.Fill.Kind switch
        {
            DrawingObjectFillKind.Solid => ParseSolidBrush(plan.Fill.ColorHex),
            DrawingObjectFillKind.Gradient => BuildAvaloniaGradientBrush(ToShapeFill(plan.Fill), rect),
            DrawingObjectFillKind.Pattern => BuildAvaloniaPatternBrush(ToShapeFill(plan.Fill)),
            _ => null
        };

        Pen? outlinePen = null;
        if (plan.Outline.IsVisible)
        {
            var strokeBrush = ParseSolidBrush(plan.Outline.ColorHex);
            var strokeW = plan.Outline.WidthDip > 0 ? plan.Outline.WidthDip : 1.0;
            DashStyle? dashStyle = plan.Outline.DashStyle?.ToLowerInvariant() switch
            {
                "dash" => new DashStyle([4, 3], 0),
                "sysdot" => new DashStyle([1, 2], 0),
                "dashdot" => new DashStyle([4, 2, 1, 2], 0),
                _ => null,
            };
            outlinePen = dashStyle is not null
                ? new Pen(strokeBrush, strokeW, dashStyle)
                : new Pen(strokeBrush, strokeW);
        }

        return new FloatingShapeData
        {
            Rect = rect,
            BehindText = plan.BehindText,
            ZOrder = plan.ZOrderIndex,
            BlockIndex = blockIndex,
            RunIndex = runIndex,
            Kind = ToShapeKind(plan.GeometryKind),
            CustomGeo = plan.CustomGeometry,
            FillBrush = fillBrush,
            OutlinePen = outlinePen,
            Text = plan.Text?.Text,
            TextPlan = plan.Text,
            TextDirection = plan.Text?.Direction ?? ShapeTextDirection.Horizontal,
            RotationAngle = plan.RotationAngle,
            FlipH = plan.FlipH,
            FlipV = plan.FlipV,
            Effects = plan.Effects,
        };
    }

    private static ShapeKind ToShapeKind(DrawingObjectGeometryKind? geometryKind) =>
        geometryKind switch
        {
            DrawingObjectGeometryKind.Ellipse => ShapeKind.Ellipse,
            DrawingObjectGeometryKind.RoundedRectangle => ShapeKind.RoundedRectangle,
            DrawingObjectGeometryKind.TextBox => ShapeKind.TextBox,
            _ => ShapeKind.Rectangle
        };

    private static ShapeFill ToShapeFill(DrawingObjectFillPlan plan)
    {
        if (plan.Kind == DrawingObjectFillKind.Gradient)
        {
            return ShapeFill.LinearGradient(
                plan.GradientAngle,
                plan.GradientStops
                    .Select(stop => new FreeW.Core.Model.GradientStop(stop.Position, stop.ColorHex))
                    .ToArray());
        }

        if (plan.Kind == DrawingObjectFillKind.Pattern)
        {
            return ShapeFill.Patterned(
                plan.PatternPreset ?? "diagCross",
                plan.PatternForegroundColorHex,
                plan.PatternBackgroundColorHex);
        }

        return ShapeFill.NoFill();
    }

    /// <summary>Builds an Avalonia <see cref="LinearGradientBrush"/> from a <see cref="ShapeFill"/> gradient.</summary>
    private static LinearGradientBrush BuildAvaloniaGradientBrush(ShapeFill fill, Rect rect)
    {
        // GradientAngle in 60k-degree units; 0=left→right, 5400000=top→bottom.
        var angleDeg = fill.GradientAngle / 60000.0;
        var angleRad = angleDeg * Math.PI / 180.0;
        // Convert angle to relative start/end points on the unit bounding box.
        var cos = Math.Cos(angleRad);
        var sin = Math.Sin(angleRad);
        var brush = new LinearGradientBrush
        {
            StartPoint = new RelativePoint(0.5 - cos * 0.5, 0.5 - sin * 0.5, RelativeUnit.Relative),
            EndPoint   = new RelativePoint(0.5 + cos * 0.5, 0.5 + sin * 0.5, RelativeUnit.Relative),
        };
        foreach (var stop in fill.GradientStops)
        {
            if (TryParseAvaloniaColor(stop.ColorHex, out var c))
                brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(c, stop.Position / 100000.0));
        }
        return brush;
    }

    /// <summary>
    /// Builds an Avalonia tiled <see cref="DrawingBrush"/> approximating a DrawingML preset pattern fill.
    /// Uses foreground/background colours from <paramref name="fill"/>; approximates each pattern family
    /// with a distinct tile so different presets are visually distinguishable.
    /// </summary>
    private static TileBrush BuildAvaloniaPatternBrush(ShapeFill fill)
    {
        TryParseAvaloniaColor(fill.PatternFgColorHex ?? "#4472C4", out var fg);
        TryParseAvaloniaColor(fill.PatternBgColorHex ?? "#FFFFFF", out var bg);

        var fgBrush = new SolidColorBrush(fg);
        var bgBrush = new SolidColorBrush(bg);
        var recipe = DrawingMlPatternFillPlanner.Plan(fill.PatternPreset);
        var tile = new global::Avalonia.Media.DrawingGroup();

        foreach (var primitive in recipe.Primitives)
        {
            var brush = primitive.ColorRole == DrawingMlPatternFillColorRole.Foreground ? fgBrush : bgBrush;
            tile.Children.Add(primitive switch
            {
                DrawingMlPatternFillRectangle rectangle => new GeometryDrawing
                {
                    Brush = brush,
                    Geometry = new RectangleGeometry(new Rect(
                        rectangle.X,
                        rectangle.Y,
                        rectangle.Width,
                        rectangle.Height))
                },
                DrawingMlPatternFillLine line => new GeometryDrawing
                {
                    Pen = new Pen(brush, line.StrokeWidth),
                    Geometry = new LineGeometry(
                        new Point(line.Start.X, line.Start.Y),
                        new Point(line.End.X, line.End.Y))
                },
                DrawingMlPatternFillEllipse ellipse => new GeometryDrawing
                {
                    Brush = brush,
                    Geometry = new EllipseGeometry(new Rect(
                        ellipse.CenterX - ellipse.RadiusX,
                        ellipse.CenterY - ellipse.RadiusY,
                        ellipse.RadiusX * 2,
                        ellipse.RadiusY * 2))
                },
                _ => throw new InvalidOperationException($"Unsupported pattern primitive {primitive.GetType().Name}.")
            });
        }

        return new DrawingBrush(tile)
        {
            TileMode        = TileMode.Tile,
            DestinationRect = new RelativeRect(
                0,
                0,
                recipe.TileWidth,
                recipe.TileHeight,
                RelativeUnit.Absolute),
        };
    }

    /// <summary>
    /// Parses an RRGGBB (or #RRGGBB) hex string to an Avalonia <see cref="Color"/>. Returns false on failure.
    /// </summary>
    private static bool TryParseAvaloniaColor(string? hex, out Color color)
    {
        color = Colors.Black;
        if (!DrawingMlRgbColor.TryParseHexRgb(hex, out var parsed))
            return false;

        color = Color.FromRgb(parsed.R, parsed.G, parsed.B);
        return true;
    }

    /// <summary>Parses a hex colour string to a <see cref="SolidColorBrush"/>. Returns null on failure.</summary>
    private static IBrush? ParseSolidBrush(string? hex)
    {
        if (TryParseAvaloniaColor(hex, out var c))
            return new SolidColorBrush(c);
        return null;
    }

    private static double[] ComputeColumnWidths(Table table, int cols, double textWidth)
        => TableColumnLayoutPlanner.AllocateColumnWidths(table, cols, textWidth);

    private List<CellWrappedLine> WrapCellLines(
        int blockIndex,
        Paragraph paragraph,
        RunFormatting fmt,
        double maxInner)
    {
        var result = new List<CellWrappedLine>();
        var lineHeight = Build("Ag", fmt).Height;
        var items = new List<CellWrappedItem>();

        for (var runIndex = 0; runIndex < paragraph.Runs.Count; runIndex++)
        {
            var run = paragraph.Runs[runIndex];
            if (run.EmbeddedObject is { } embeddedObject)
            {
                var plan = EmbeddedObjectVisualPlanner.Build(embeddedObject);
                var width = plan.WidthPt * PxPerPoint;
                var height = plan.HeightPt * PxPerPoint;
                if (width > maxInner)
                {
                    var scale = maxInner / width;
                    width = maxInner;
                    height *= scale;
                }
                items.Add(new CellWrappedItem('\0', width, height, Hidden: false, plan, runIndex));
                continue;
            }

            var hidden = IsTextHiddenInCurrentView(ResolveRunFmt(run.Formatting, paragraph));
            var text = run.ComplexField is null
                ? run.Text
                : BuildBodyComplexFieldDisplayPlan(blockIndex, run).Text;
            foreach (var ch in text)
            {
                var width = hidden ? 0 : Build(ch.ToString(), fmt).WidthIncludingTrailingWhitespace;
                items.Add(new CellWrappedItem(ch, width, lineHeight, hidden, null, runIndex));
            }
        }

        if (items.Count == 0)
        {
            result.Add(new CellWrappedLine(lineHeight, [], 0));
            return result;
        }

        if (items.Any(item => item.EmbeddedObject is not null))
        {
            var lineItems = new List<CellWrappedItem>();
            var objectLineWidth = 0.0;
            var currentHeight = lineHeight;

            void FlushLine()
            {
                if (lineItems.Count == 0)
                    return;
                result.Add(new CellWrappedLine(currentHeight, [.. lineItems], 0));
                lineItems.Clear();
                objectLineWidth = 0;
                currentHeight = lineHeight;
            }

            foreach (var item in items)
            {
                if (lineItems.Count > 0 && objectLineWidth + item.Width > maxInner)
                    FlushLine();
                lineItems.Add(item);
                objectLineWidth += item.Width;
                currentHeight = Math.Max(currentHeight, item.Height);
            }
            FlushLine();
            return result;
        }

        var displayText = new string(items.Select(item => item.Hidden ? ' ' : item.Ch).ToArray());
        var measured = items.Select(item => item.Width).ToArray();
        var automaticHyphenWidths = AutomaticHyphenationDisplayPlanner.BuildBreakOffsets(
                displayText,
                _doc.Page,
                ResolveParagraphFmt(paragraph))
            .Where(offset => offset > 0 && offset < items.Count)
            .Distinct()
            .ToDictionary(
                offset => offset,
                _ => Build("-", fmt).WidthIncludingTrailingWhitespace);

        var lineStart = 0;
        var currentWidth = 0.0;
        var lastSpace = -1;
        var consecutiveAutomaticHyphenLines = 0;

        void AddLine(int from, int to, double automaticHyphenWidth = 0)
        {
            result.Add(new CellWrappedLine(
                lineHeight,
                items.Skip(from).Take(to - from).ToList(),
                automaticHyphenWidth));
        }

        for (var index = 0; index < items.Count; index++)
        {
            if (!items[index].Hidden && items[index].Ch == ' ')
                lastSpace = index;

            if (currentWidth + measured[index] > maxInner && index > lineStart)
            {
                var spaceBreakAt = lastSpace > lineStart ? lastSpace : -1;
                var automaticBreak = FindLatestAutomaticHyphenBreak(
                    lineStart,
                    index,
                    maxInner,
                    measured,
                    automaticHyphenWidths);
                var useAutomaticHyphen = ShouldUseAutomaticHyphenBreak(
                    _doc.Page,
                    consecutiveAutomaticHyphenLines,
                    displayText,
                    measured,
                    lineStart,
                    spaceBreakAt,
                    automaticBreak.BreakAt,
                    maxInner);
                var breakAt = useAutomaticHyphen
                    ? automaticBreak.BreakAt
                    : spaceBreakAt > lineStart ? spaceBreakAt : index;

                AddLine(
                    lineStart,
                    breakAt,
                    useAutomaticHyphen ? automaticBreak.HyphenWidth : 0);
                consecutiveAutomaticHyphenLines = useAutomaticHyphen
                    ? consecutiveAutomaticHyphenLines + 1
                    : 0;
                lineStart = breakAt;
                currentWidth = 0;
                lastSpace = -1;
                for (var carried = lineStart; carried < index; carried++)
                {
                    currentWidth += measured[carried];
                    if (!items[carried].Hidden && items[carried].Ch == ' ')
                        lastSpace = carried;
                }
            }

            currentWidth += measured[index];
        }

        AddLine(lineStart, items.Count);
        return result;
    }

    // AV-TBL4: draw per-edge cell borders using the shared host-neutral border plan.
    private void DrawCellBorderEdges(DrawingContext context, Rect rect, TableCellBorderVisualPlan plan)
    {
        foreach (var edge in plan.Edges)
            DrawCellEdgeLine(context, edge, rect);
    }

    private void DrawParagraphDecoration(DrawingContext context, Rect rect, string? shadingHex, ParagraphBorder? border)
    {
        if (!string.IsNullOrWhiteSpace(shadingHex))
            context.FillRectangle(BrushFor(shadingHex), rect);

        if (border is null)
            return;

        var pen = ParagraphBorderPen(border);
        if (border.Top && !border.BottomOnly)
            context.DrawLine(pen, new Point(rect.Left, rect.Top), new Point(rect.Right, rect.Top));
        if (border.Bottom || border.BottomOnly)
            context.DrawLine(pen, new Point(rect.Left, rect.Bottom), new Point(rect.Right, rect.Bottom));
        if (border.Left && !border.BottomOnly)
            context.DrawLine(pen, new Point(rect.Left, rect.Top), new Point(rect.Left, rect.Bottom));
        if (border.Right && !border.BottomOnly)
            context.DrawLine(pen, new Point(rect.Right, rect.Top), new Point(rect.Right, rect.Bottom));
    }

    private Pen ParagraphBorderPen(ParagraphBorder border)
    {
        DashStyle? dashStyle = border.LineStyle switch
        {
            BorderLineStyle.Dashed => new DashStyle([4, 3], 0),
            BorderLineStyle.Dotted => new DashStyle([1, 2], 0),
            _ => null,
        };
        var width = Math.Max(0.5, border.WidthPt * PxPerPoint);
        return dashStyle is null
            ? new Pen(BrushFor(border.ColorHex), width)
            : new Pen(BrushFor(border.ColorHex), width, dashStyle);
    }

    private void DrawCharacterBorder(
        DrawingContext context,
        int placedIndex,
        PlacedChar pc,
        RunDecorationVisualPlan plan)
    {
        if (!plan.HasBorder || plan.Border is null)
            return;

        var rect = new Rect(pc.X, pc.Y, Math.Max(1, pc.W), pc.LineHeight);
        var pen = RunBorderPen(plan);
        var drawLeft = plan.DrawLeftBorder && !AdjacentGlyphSharesBorder(placedIndex - 1, pc, plan);
        var drawRight = plan.DrawRightBorder && !AdjacentGlyphSharesBorder(placedIndex + 1, pc, plan);

        if (plan.DrawTopBorder)
            context.DrawLine(pen, new Point(rect.Left, rect.Top), new Point(rect.Right, rect.Top));
        if (plan.DrawBottomBorder)
            context.DrawLine(pen, new Point(rect.Left, rect.Bottom), new Point(rect.Right, rect.Bottom));
        if (drawLeft)
            context.DrawLine(pen, new Point(rect.Left, rect.Top), new Point(rect.Left, rect.Bottom));
        if (drawRight)
            context.DrawLine(pen, new Point(rect.Right, rect.Top), new Point(rect.Right, rect.Bottom));
    }

    private bool AdjacentGlyphSharesBorder(int index, PlacedChar current, RunDecorationVisualPlan currentPlan)
    {
        if (index < 0 || index >= _placed.Count)
            return false;

        var adjacent = _placed[index];
        if (adjacent.Sentinel
            || adjacent.Block != current.Block
            || adjacent.IsCell != current.IsCell
            || Math.Abs(adjacent.Y - current.Y) > 0.5)
            return false;

        var adjacentPlan = RunDecorationVisualPlanner.Build(adjacent.Fmt, PxPerPoint);
        return adjacentPlan.HasBorder
            && adjacentPlan.Border == currentPlan.Border
            && adjacentPlan.DrawTopBorder == currentPlan.DrawTopBorder
            && adjacentPlan.DrawLeftBorder == currentPlan.DrawLeftBorder
            && adjacentPlan.DrawBottomBorder == currentPlan.DrawBottomBorder
            && adjacentPlan.DrawRightBorder == currentPlan.DrawRightBorder;
    }

    private Pen RunBorderPen(RunDecorationVisualPlan plan)
    {
        var border = plan.Border!;
        DashStyle? dashStyle = border.LineStyle switch
        {
            BorderLineStyle.Dashed => new DashStyle([4, 3], 0),
            BorderLineStyle.Dotted => new DashStyle([1, 2], 0),
            _ => null,
        };

        return dashStyle is null
            ? new Pen(BrushFor(border.ColorHex), plan.BorderWidthDip)
            : new Pen(BrushFor(border.ColorHex), plan.BorderWidthDip, dashStyle);
    }

    private void DrawCellEdgeLine(DrawingContext context, TableCellBorderEdgeVisualPlan edge, Rect rect)
    {
        if (!edge.IsVisible)
            return;

        DashStyle? dashStyle = edge.Style switch
        {
            BorderLineStyle.Dashed => new DashStyle([4, 3], 0),
            BorderLineStyle.Dotted => new DashStyle([1, 2], 0),
            _ => null,
        };
        var brush = edge.IsWave ? WaveBorderBrush(edge) : BrushFor(edge.ColorHex);
        var pen = dashStyle is not null
            ? new Pen(brush, edge.WidthDip, dashStyle)
            : new Pen(brush, edge.WidthDip);

        foreach (var segment in TableCellBorderVisualPlanner.BuildStrokeSegments(
                     edge,
                     rect.Left,
                     rect.Top,
                     rect.Right,
                     rect.Bottom,
                     waveRegistrationDip: -4.0))
        {
            context.DrawLine(
                pen,
                new Point(segment.X1Dip, segment.Y1Dip),
                new Point(segment.X2Dip, segment.Y2Dip));
        }
    }

    private static IBrush WaveBorderBrush(TableCellBorderEdgeVisualPlan edge)
    {
        var color = TryParseAvaloniaColor(edge.ColorHex, out var parsed) ? parsed : Colors.Black;

        return new SolidColorBrush(Color.FromArgb(
            (byte)Math.Round(255 * edge.StrokeOpacity),
            color.R,
            color.G,
            color.B));
    }

    /// <summary>
    /// AV-VIEW: Draw the ruler strips for the first page in Print Layout — a horizontal strip along the
    /// page top and a vertical strip along the page left edge, each with the page margins tinted darker
    /// (so the lighter span marks the editable body area) and inch tick marks. Pure render chrome.
    /// </summary>
    private void DrawRuler(DrawingContext context)
    {
        const double inchDip = 72.0;
        var pageTop = _surfacePlan.PageTopDip(0); // first page only
        // ── Horizontal ruler: sits just above the page's top edge. ──
        var hRect = new Rect(_pageLeft, pageTop - RulerThicknessDip, _pageWidth, RulerThicknessDip);
        context.FillRectangle(RulerFill, hRect);
        // Margin tint: left margin + right margin spans (darker); body area stays light.
        context.FillRectangle(RulerMarginFill, new Rect(_pageLeft, hRect.Y, _contentLeft - _pageLeft, RulerThicknessDip));
        var bodyRight = _contentLeft + _contentWidth;
        context.FillRectangle(RulerMarginFill, new Rect(bodyRight, hRect.Y, _pageLeft + _pageWidth - bodyRight, RulerThicknessDip));
        context.DrawRectangle(null, RulerBorderPen, hRect);
        var rulerTicks = DocumentViewLayoutPlanner.BuildRulerTicks(_surfacePlan, inchDip);
        foreach (var x in rulerTicks)
            context.DrawLine(RulerTickPen, new Point(x, hRect.Y + RulerThicknessDip - 4), new Point(x, hRect.Y + RulerThicknessDip));

        // ── Vertical ruler: sits just left of the page's left edge. ──
        var vRect = new Rect(_pageLeft - RulerThicknessDip, pageTop, RulerThicknessDip, _pageHeightPx);
        context.FillRectangle(RulerFill, vRect);
        var bodyTop    = pageTop + _marginTopDip;
        var bodyBottom = pageTop + _pageHeightPx - _marginBottomDip;
        context.FillRectangle(RulerMarginFill, new Rect(vRect.X, pageTop, RulerThicknessDip, _marginTopDip));
        context.FillRectangle(RulerMarginFill, new Rect(vRect.X, bodyBottom, RulerThicknessDip, pageTop + _pageHeightPx - bodyBottom));
        context.DrawRectangle(null, RulerBorderPen, vRect);
        foreach (var y in rulerTicks.Select(tick => pageTop + tick - _pageLeft))
            context.DrawLine(RulerTickPen, new Point(vRect.X + RulerThicknessDip - 4, y), new Point(vRect.X + RulerThicknessDip, y));
    }

    // AV-DESIGN: the model's page border (w:pgBorders) drawn inset just inside the page sheet. Word draws
    // page borders a fixed offset from the page edge (its "Measure from: Edge of page" default is 24pt); we
    // mirror that with a small inset so the border sits between the chrome edge and the body text. FreeW's
    // own DocxWriter.BuildPageBorders emits w:space="24" (POINTS — w:space on w:pgBorders is always measured
    // in points, never twips/DXA), so the inset here must be 24 points converted to DIP, not 24 raw DIP.
    private const double PageBorderInsetPt = 24.0;

    // Test-only: exposes the DIP inset so tests can assert it matches 24pt (the writer's w:space) rather
    // than the raw point value, catching any future re-introduction of a DIP/point mismatch.
    internal static double PageBorderInsetDip => PageBorderInsetPt * PxPerPoint;

    private void DrawPageBorder(DrawingContext context, Rect pageRect, int pageIndex)
    {
        if (_doc.Page.PageBorder is not { } pb
            || !PageBorderVisibilityPlanner.ShouldRender(pb.Display, pageIndex))
            return;

        var color = TryParseAvaloniaColor(pb.ColorHex, out var c) ? c : Colors.Black;
        var widthDip = Math.Max(0.5, pb.WidthPt * PxPerPoint);
        var pen = new Pen(new SolidColorBrush(color), widthDip)
        {
            DashStyle = pb.LineStyle switch
            {
                BorderLineStyle.Dotted => new DashStyle([1, 2], 0),
                BorderLineStyle.Dashed => new DashStyle([3, 2], 0),
                _ => null,
            },
        };

        Rect rect;
        Rect artFrame;
        double artInset;
        if (pb.OffsetFrom == PageBorderOffsetFrom.Text)
        {
            var planned = PageBorderTextFramePlanner.Build(
                _doc.Page,
                pb,
                pageRect.Width,
                pageRect.Height,
                PxPerPoint,
                widthDip,
                _doc.PageBordersDoNotSurroundHeader,
                _doc.PageBordersDoNotSurroundFooter);
            var outerFrame = new Rect(
                pageRect.X + planned.X,
                pageRect.Y + planned.Y,
                planned.Width,
                planned.Height);
            artFrame = outerFrame;
            artInset = 0;
            rect = outerFrame.Deflate(new Thickness(widthDip / 2));
        }
        else
        {
            var inset = Math.Min(Math.Max(0, pb.SpacePt * PxPerPoint), Math.Min(pageRect.Width, pageRect.Height) / 4);
            artFrame = pageRect;
            artInset = inset;
            // Avalonia centers the stroke on this rectangle. Move the paint geometry 1.5 DIPs inward
            // so both rails of an imported double border register with Word's opaque raster bands.
            rect = pageRect.Deflate(new Thickness(inset + 1.5));
        }

        if (TryDrawPageBorderArt(context, pb, artFrame, artInset))
            return;

        if (pb.LineStyle == BorderLineStyle.Wave)
        {
            var waveColor = Color.FromArgb(
                (byte)Math.Round(255 * PageBorderWaveVisualPlanner.StrokeOpacity),
                color.R,
                color.G,
                color.B);
            var wavePen = new Pen(
                new SolidColorBrush(waveColor),
                PageBorderWaveVisualPlanner.StrokeWidthDip);
            var frame = pb.OffsetFrom == PageBorderOffsetFrom.Text ? rect : pageRect;
            var edgeInset = pb.OffsetFrom == PageBorderOffsetFrom.Text
                ? 0
                : Math.Min(
                    Math.Max(0, pb.SpacePt * PxPerPoint),
                    Math.Min(pageRect.Width, pageRect.Height) / 4);
            foreach (var segment in PageBorderWaveVisualPlanner.BuildFrame(frame.Width, frame.Height, edgeInset))
            {
                context.DrawLine(
                    wavePen,
                    new Point(frame.X + segment.X1Dip, frame.Y + segment.Y1Dip),
                    new Point(frame.X + segment.X2Dip, frame.Y + segment.Y2Dip));
            }

            return;
        }

        context.DrawRectangle(null, pen, rect);
        // BorderLineStyle.Double: draw a second, inner stroke a couple of DIP inside the first.
        if (pb.LineStyle == BorderLineStyle.Double)
            context.DrawRectangle(null, pen, rect.Deflate(new Thickness(widthDip + 1.5)));
    }

    private static bool TryDrawPageBorderArt(
        DrawingContext context,
        PageBorder border,
        Rect frame,
        double edgeInsetDip)
    {
        if (!PageBorderArtVisualPlanner.TryBuildFramePlan(
                border.ArtId,
                border.WidthPt,
                frame.Width,
                frame.Height,
                edgeInsetDip,
                out var plan))
        {
            return false;
        }

        DrawPageBorderArtFramePlan(context, frame, plan);
        return true;
    }

    private static void DrawPageBorderArtFramePlan(
        DrawingContext context,
        Rect frame,
        PageBorderArtFramePlan plan)
    {
        foreach (var fill in plan.Fills)
        {
            context.FillRectangle(
                new SolidColorBrush(Color.FromRgb(fill.Red, fill.Green, fill.Blue)),
                new Rect(
                    frame.X + fill.Xdip,
                    frame.Y + fill.Ydip,
                    fill.WidthDip,
                    fill.HeightDip));
        }

        foreach (var polygon in plan.Polygons)
        {
            if (polygon.Points.Count == 0)
                continue;

            var geometry = new StreamGeometry();
            using (var path = geometry.Open())
            {
                path.BeginFigure(ToPageBorderPoint(frame, polygon.Points[0]), true);
                foreach (var point in polygon.Points.Skip(1))
                    path.LineTo(ToPageBorderPoint(frame, point));
                path.EndFigure(true);
            }
            context.DrawGeometry(
                new SolidColorBrush(Color.FromRgb(polygon.Red, polygon.Green, polygon.Blue)),
                null,
                geometry);
        }

        foreach (var line in plan.Lines)
        {
            var pen = new Pen(
                new SolidColorBrush(Color.FromRgb(line.Color.Red, line.Color.Green, line.Color.Blue)),
                line.WidthDip)
            {
                LineCap = line.RoundCaps ? PenLineCap.Round : PenLineCap.Flat,
            };
            context.DrawLine(
                pen,
                new Point(frame.X + line.Segment.X1Dip, frame.Y + line.Segment.Y1Dip),
                new Point(frame.X + line.Segment.X2Dip, frame.Y + line.Segment.Y2Dip));
        }

        foreach (var figure in plan.CubicFigures)
        {
            var geometry = new StreamGeometry();
            using (var path = geometry.Open())
            {
                path.BeginFigure(ToPageBorderPoint(frame, figure.Start), figure.Fill is not null);
                foreach (var segment in figure.Segments)
                {
                    path.CubicBezierTo(
                        ToPageBorderPoint(frame, segment.Control1),
                        ToPageBorderPoint(frame, segment.Control2),
                        ToPageBorderPoint(frame, segment.End));
                }
                path.EndFigure(figure.IsClosed);
            }

            IBrush? fill = figure.Fill is { } fillColor
                ? new SolidColorBrush(Color.FromRgb(fillColor.Red, fillColor.Green, fillColor.Blue))
                : null;
            Pen? stroke = figure.Stroke is { } strokeColor
                ? new Pen(
                    new SolidColorBrush(Color.FromRgb(strokeColor.Red, strokeColor.Green, strokeColor.Blue)),
                    figure.StrokeWidthDip)
                {
                    LineCap = figure.RoundCaps ? PenLineCap.Round : PenLineCap.Flat,
                }
                : null;
            context.DrawGeometry(fill, stroke, geometry);
        }
    }

    private static Point ToPageBorderPoint(Rect frame, PageBorderArtPoint point) =>
        new(frame.X + point.XDip, frame.Y + point.YDip);
    // AV-DESIGN: faint watermark drawn behind the body on each page. Mirrors Word's Design >
    // Watermark: a large, low-opacity, optionally diagonal label or picture centred on the page.
    private void DrawWatermark(DrawingContext context, Rect pageRect)
    {
        if (_doc.Page.EffectiveWatermark is not { } wm)
            return;

        if (wm.IsPicture)
        {
            DrawPictureWatermark(context, pageRect, wm);
            return;
        }

        if (string.IsNullOrWhiteSpace(wm.Text))
            return;

        var plan = WatermarkVisualPlanner.BuildTextLayout(wm, pageRect.Width, pageRect.Height);
        if (plan is null)
            return;

        var color = TryParseAvaloniaColor(wm.FontColorHex, out var c) ? c : Color.FromRgb(0x80, 0x80, 0x80);
        var opacity = Math.Clamp(wm.Opacity, 0.0, 1.0);
        var brush = new SolidColorBrush(color, opacity);

        // The shared planner preserves Word's VML text-path footprint and fitshape sizing.
        var typeface = new Typeface(
            wm.FontFamily is { Length: > 0 } family ? new FontFamily(family) : FontFamily.Default,
            FontStyle.Normal, FontWeight.Normal);
        var unitText = new FormattedText(
            wm.Text, CultureInfo.InvariantCulture, FlowDirection.LeftToRight, typeface, 1, brush);
        var fontSize = WatermarkVisualPlanner.ResolveTextPathFontSize(plan, unitText.Width);
        var text = new FormattedText(
            wm.Text, CultureInfo.InvariantCulture, FlowDirection.LeftToRight, typeface, fontSize, brush);

        // Clip to the page sheet: an un-clipped long watermark string (fontSize floors at 24pt) can extend
        // past the page rect onto the grey desk / an adjacent page. Word tiles+clips watermarks via a brush
        // so they never overflow the page — mirror that here with a hard clip to pageRect.
        using var clip = context.PushClip(pageRect);

        var centerX = pageRect.X + plan.CenterXDip;
        var centerY = pageRect.Y + plan.CenterYDip;
        if (Math.Abs(plan.RotationDegrees) > 0.01)
        {
            using var transform = context.PushTransform(
                Matrix.CreateTranslation(-centerX, -centerY)
                * Matrix.CreateRotation(plan.RotationDegrees * Math.PI / 180.0)
                * Matrix.CreateTranslation(centerX, centerY));
            context.DrawText(text, new Point(centerX - text.Width / 2, centerY - text.Height / 2));
            return;
        }

        context.DrawText(text, new Point(centerX - text.Width / 2, centerY - text.Height / 2));
    }

    private void DrawPictureWatermark(DrawingContext context, Rect pageRect, WatermarkOptions wm)
    {
        if (wm.ImageBytes is not { Length: > 0 })
            return;

        var bitmap = DecodeWatermarkBitmap(wm.ImageBytes);
        if (bitmap is null)
            return;

        var plan = WatermarkVisualPlanner.BuildPictureLayout(
            wm,
            pageRect.Width,
            pageRect.Height,
            bitmap.PixelSize.Width,
            bitmap.PixelSize.Height);
        if (plan is null)
            return;

        var rect = new Rect(
            pageRect.X + plan.XDip,
            pageRect.Y + plan.YDip,
            plan.WidthDip,
            plan.HeightDip);

        using var clip = context.PushClip(pageRect);
        using var opacity = context.PushOpacity(plan.Opacity);
        if (Math.Abs(plan.RotationDegrees) > 0.01)
        {
            var centerX = pageRect.X + plan.CenterXDip;
            var centerY = pageRect.Y + plan.CenterYDip;
            using var transform = context.PushTransform(
                Matrix.CreateTranslation(-centerX, -centerY)
                * Matrix.CreateRotation(plan.RotationDegrees * Math.PI / 180.0)
                * Matrix.CreateTranslation(centerX, centerY));
            context.DrawImage(bitmap, rect);
            return;
        }

        context.DrawImage(bitmap, rect);
    }

    private Bitmap? DecodeWatermarkBitmap(byte[] imageBytes)
    {
        if (ReferenceEquals(_watermarkBitmapCacheBytes, imageBytes))
            return _watermarkBitmapCache;

        Bitmap? bitmap = null;
        try
        {
            using var stream = new MemoryStream(imageBytes);
            bitmap = new Bitmap(stream);
        }
        catch (Exception)
        {
            bitmap = null;
        }

        _watermarkBitmapCacheBytes = imageBytes;
        _watermarkBitmapCache = bitmap;
        return bitmap;
    }

    private static IBrush BandFill { get; } = new SolidColorBrush(Color.FromRgb(0xF2, 0xF2, 0xF2));
    private static Pen TableBorderPen { get; } = new Pen(new SolidColorBrush(Color.FromRgb(0x9A, 0x9A, 0x9A)), 0.75);
    private static IBrush PageDeskBrush   { get; } = new SolidColorBrush(Color.FromRgb(0xD0, 0xD0, 0xD0));
    private static IBrush PageShadowBrush { get; } = new SolidColorBrush(Color.FromArgb(0x55, 0x00, 0x00, 0x00));
    private static Pen    PageBorderPen   { get; } = new Pen(new SolidColorBrush(Color.FromRgb(0xBB, 0xBB, 0xBB)), 0.5);
    // Word's column separator is an opaque one-pixel black rule at the gap's device-pixel centre.
    private static Pen    ColumnRulePen   { get; } = new Pen(new SolidColorBrush(Colors.Black), 1.0);
    // AV-NOTERENDER: thin separator rule above the footnote band / under the Endnotes heading.
    private static Pen    NoteSeparatorPen { get; } = new Pen(new SolidColorBrush(Color.FromRgb(0x80, 0x80, 0x80)), 0.75);
    // AV-VIEW: faint layout-gridlines drawn behind body text when ShowGridlines is set.
    private static Pen    GridlinePen      { get; } = new Pen(new SolidColorBrush(Color.FromArgb(0x30, 0x60, 0x90, 0xC0)), 0.5);
    // AV-VIEW: ruler strip fill, border, and tick marks drawn at the page top/left when ShowRuler is set.
    private static IBrush RulerFill        { get; } = new SolidColorBrush(Color.FromRgb(0xF4, 0xF6, 0xFA));
    private static Pen    RulerBorderPen   { get; } = new Pen(new SolidColorBrush(Color.FromRgb(0xC0, 0xC8, 0xD4)), 0.75);
    private static Pen    RulerTickPen     { get; } = new Pen(new SolidColorBrush(Color.FromRgb(0x70, 0x80, 0x98)), 0.75);
    // AV-VIEW: darker tint marking the page margins on the ruler (the body text area is the lighter span).
    private static IBrush RulerMarginFill  { get; } = new SolidColorBrush(Color.FromRgb(0xD8, 0xDE, 0xE8));
    private static RunFormatting LineNumberFormatting { get; } = new() { FontSizePt = 8, ColorHex = "#606060" };

    // ---- Render ---------------------------------------------------------------------------------

    public override void Render(DrawingContext context)
    {
        // In projected page flow Bounds.Width is the scrollable grid/strip width, while the layout pass
        // was measured against the viewport width. Re-running from Bounds.Width would progressively
        // recenter the strip as pages are added, so resize invalidation is owned by MeasureOverride.
        if (_laidOutWidth < 0
            || (!_surfacePlan.UsesProjectedPageFlow && Math.Abs(_laidOutWidth - Bounds.Width) > 0.5))
            RelayoutSafely(Bounds.Width > 0 ? Bounds.Width : FallbackWidth);

        // AV-DESIGN: the page sheet is filled with the document's Page Color (w:background) when set,
        // else white. The page border (w:pgBorders) and watermark draw on top of the sheet fill.
        var pageFill = ParseSolidBrush(_viewBackgroundColorHex)
            ?? ParseSolidBrush(_doc.Page.BackgroundColorHex)
            ?? Brushes.White;

        if (_viewMode == DocumentViewMode.PrintLayout)
        {
            // Grey desk fills the full control area.
            context.FillRectangle(PageDeskBrush, new Rect(Bounds.Size));

            // Draw each discrete page rectangle: page-coloured sheet with drop-shadow + chrome border.
            for (var pi = 0; pi < _pageCount; pi++)
            {
                var pageTop = _surfacePlan.RenderedPageTopDip(pi);
                var pageLeft = _surfacePlan.RenderedPageLeftDip(pi);
                var pageRect   = new Rect(pageLeft, pageTop, _pageWidth, _pageHeightPx);
                var shadowRect = new Rect(pageLeft + 3, pageTop + 3, _pageWidth, _pageHeightPx);
                context.FillRectangle(PageShadowBrush, shadowRect);
                context.FillRectangle(pageFill, pageRect);
                context.DrawRectangle(null, PageBorderPen, pageRect);
                // The page background owns color and watermark. The authored border is painted later by
                // its explicit behind-text or in-front-of-text compositor pass.
                DrawWatermark(context, pageRect);
            }

            DrawPageBordersForLayer(context, PageBorderRenderLayer.BehindText);
        }
        else
        {
            // Web Layout / Draft: plain page-coloured background — no desk, no page chrome.
            context.FillRectangle(pageFill, new Rect(Bounds.Size));
        }

        // AV-VIEW: faint layout-gridlines behind the body text (Print Layout only). Drawn after the
        // white page fill so the grid shows through, before table fills / text so it sits underneath.
        if (_showGridlines && _viewMode == DocumentViewMode.PrintLayout)
        {
            foreach (var (x1, y1, x2, y2) in ComputeGridlines())
                context.DrawLine(GridlinePen, new Point(x1, y1), new Point(x2, y2));
        }

        // AV-VIEW: horizontal + vertical ruler strips on the first page (Print Layout only).
        if (_showRuler && _viewMode == DocumentViewMode.PrintLayout)
            DrawRuler(context);

        foreach (var (rect, shadingHex, border) in _paragraphDecorations)
            DrawParagraphDecoration(context, rect, shadingHex, border);

        // Table fills + borders sit beneath the text.
        foreach (var (rect, fill, border, cellBorderPlan) in _rects)
        {
            if (fill is not null)
                context.FillRectangle(fill, rect);
            if (border)
                context.DrawRectangle(null, TableBorderPen, rect);
            // AV-TBL4: per-edge cell borders drawn on top of the table-level border.
            if (cellBorderPlan is not null)
                DrawCellBorderEdges(context, rect, cellBorderPlan);
        }

        // AV-COL: draw column rules (vertical divider lines in each inter-column gap) when enabled.
        // One rule per gap, centred horizontally, running the full text-area height on each page.
        if (_viewMode == DocumentViewMode.PrintLayout && _colCount > 1 && _colLineBetween)
        {
            for (var pi = 0; pi < _pageCount; pi++)
            {
                var pageTop = _surfacePlan.RenderedPageTopDip(pi);
                var ruleTop    = pageTop + _marginTopDip;
                var ruleBottom = pageTop + _pageHeightPx - _marginBottomDip;
                for (var ci = 0; ci < _colCount - 1; ci++)
                {
                    // Gap centre X = left edge of next column minus half gap.
                    var gapCentreX = _surfacePlan.RenderedPageLeftDip(pi)
                        + (_contentLeft - _pageLeft)
                        + (ci + 1) * (_colWidth + _colGap) - _colGap / 2;
                    var pixelCenteredX = Math.Floor(gapCentreX) - 0.5;
                    context.DrawLine(ColumnRulePen, new Point(pixelCenteredX, ruleTop), new Point(pixelCenteredX, ruleBottom));
                }
            }
        }

        DrawLineNumbers(context);

        // Behind-text pass: planner snapshots merge all floating kinds into one z-ordered band.
        foreach (var snapshot in DocumentViewLayoutPlanner.BuildFloatingObjectDrawOrder(_floatingSnapshots, behindText: true))
            DrawFloatingObjectSnapshot(context, snapshot);

        // Inline images (non-floating).
        foreach (var (rect, bitmap, model, reflectionPreset, _) in _images)
            DrawFloatingImage(context, rect, bitmap, model, reflectionPreset);

        // FO4: inline drawing objects rendered in the text flow using the same FO3 helpers.
        foreach (var shape in _inlineShapes)
            DrawFloatingShape(context, shape);
        foreach (var cd in _inlineCharts)
            DrawFloatingChart(context, cd);
        foreach (var wd in _inlineWordArts)
            DrawFloatingWordArt(context, wd);
        foreach (var sd in _inlineSmartArts)
            DrawFloatingSmartArt(context, sd);
        foreach (var embeddedObject in _inlineEmbeddedObjects)
            DrawInlineEmbeddedObject(context, embeddedObject);

        // AV-TBL2: cross-cell block-selection highlight. Draw a semi-transparent overlay over each
        // cell-hit rect that falls inside the selected row×col rectangle.
        // BF5: use span-overlap test so merged cells straddling the boundary are highlighted.
        if (SelectedCellRange is { } cellSel)
        {
            foreach (var (cellRect, cellBlock, cellRow, cellCol) in _cellHits)
            {
                if (cellBlock != cellSel.TableBlock) continue;
                if (cellRow < cellSel.MinRow || cellRow > cellSel.MaxRow) continue;
                // Overlap test: include cell if its column range [startCol, startCol+span-1] overlaps
                // the selection [MinCol, MaxCol]. For cells with no merged span, GridSpan is 1.
                var cellSpan = GetCellModel(cellBlock, cellRow, cellCol)?.GridSpan ?? 1;
                cellSpan = Math.Max(1, cellSpan);
                if (cellCol + cellSpan - 1 < cellSel.MinCol) continue; // cell ends before selection
                if (cellCol > cellSel.MaxCol) continue;                 // cell starts after selection
                context.FillRectangle(CellBlockSelectionBrush, cellRect);
            }
        }

        // AV-TAB: draw tab leader spans (dots/dashes/underline) before the glyph text.
        foreach (var (x1, x2, spanY, lineH, leader, spanFmt) in _tabLeaderSpans)
        {
            if (leader == TabLeader.None || x2 <= x1 || IsTextHiddenInCurrentView(spanFmt)) continue;
            DrawTabLeader(context, x1, x2, spanY, lineH, leader, spanFmt);
        }

        var selection = NormalizedSelection();
        var proofingOffsets = BuildProofingOffsetSet();
        var reviewPolicy = CurrentReviewDisplayPolicy;
        var revisionColors = ReviewRevisionColorPlanner.BuildAuthorColors(_doc);
        for (var placedIndex = 0; placedIndex < _placed.Count; placedIndex++)
        {
            var pc = _placed[placedIndex];
            if (pc.Sentinel)
                continue;
            var revisionDecision = reviewPolicy.RevisionDecision(pc.Revision);
            if (!revisionDecision.IsTextVisible)
                continue;
            if (IsTextHiddenInCurrentView(pc.Fmt))
                continue;
            var decorationPlan = RunDecorationVisualPlanner.Build(pc.Fmt, PxPerPoint);

            if (selection is { } sel && IsWithin(sel, pc.Block, pc.Offset))
                context.FillRectangle(SelectionBrush, new Rect(pc.X, pc.Y, Math.Max(2, pc.W), pc.LineHeight));

            // Character shading takes precedence over highlight; both fill behind glyphs.
            if (decorationPlan.HasBackground)
                context.FillRectangle(
                    BrushFor(decorationPlan.BackgroundColorHex),
                    new Rect(pc.X, pc.Y, Math.Max(1, pc.W), pc.LineHeight));

            // AV-COMMENT: a subtle amber background tint behind glyphs anchored by a review comment, so
            // the commented range reads as one region (the underline + margin marker are drawn after the
            // glyph loop). Resolved threads tint muted/grey to match Word's de-emphasised resolved state.
            if (pc.CommentId is { } commentTintId && reviewPolicy.ShouldHighlightComments)
            {
                var tint = IsCommentResolved(commentTintId) ? ResolvedCommentTintBrush : CommentTintBrush;
                context.FillRectangle(tint, new Rect(pc.X, pc.Y, Math.Max(1, pc.W), pc.LineHeight));
            }

            // AV-LINK: a hyperlinked glyph renders in the hyperlink style — Word's default blue + underline —
            // unless the run already carries an explicit colour / its own underline (e.g. a "Hyperlink"
            // character style was applied), in which case those win. Layered before super/sub + revision.
            var linkFmt = pc.Fmt;
            if (pc.IsHyperlink)
            {
                linkFmt = linkFmt with
                {
                    ColorHex = string.IsNullOrWhiteSpace(linkFmt.ColorHex) ? HyperlinkColorHex : linkFmt.ColorHex,
                    Underline = true,
                };
            }

            // Superscript/subscript: draw at a smaller size + vertical offset.
            // Word approximation: ~58% of the font size, raised/lowered by ~33% of line height.
            var drawFmt = linkFmt;
            var drawY   = pc.Y;
            if (pc.Fmt.VerticalAlign == VerticalAlign.Superscript)
            {
                var sz = (drawFmt.FontSizePt ?? DefaultFontSizePt) * SuperSubScale;
                drawFmt = drawFmt with { FontSizePt = sz };
                drawY   = pc.Y + pc.LineHeight * SuperYRaiseFraction;
            }
            else if (pc.Fmt.VerticalAlign == VerticalAlign.Subscript)
            {
                var sz = (drawFmt.FontSizePt ?? DefaultFontSizePt) * SuperSubScale;
                drawFmt = drawFmt with { FontSizePt = sz };
                drawY   = pc.Y + pc.LineHeight * SubYLowerFraction;
            }

            // AV-TRACKEDIT: tracked insertions/deletions draw in the revision colour; insertions are also
            // underlined and deletions struck through (the marks layered on top of any run decorations below).
            var revisionColorHex = ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, pc.RevisionAuthor);
            if (revisionDecision.IsRevisionStylingApplied)
                drawFmt = drawFmt with { ColorHex = revisionColorHex };
            var formatRevisionHighlighted = pc.HasFormatRevision && reviewPolicy.ShouldHighlightFormattingChanges;
            if (formatRevisionHighlighted && string.IsNullOrWhiteSpace(drawFmt.ColorHex))
                drawFmt = drawFmt with { ColorHex = ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, pc.FormatRevisionAuthor) };
            var baselineOffsetDip = RunBaselinePositionPlanner.ResolveOffsetDip(drawFmt, PxPerPoint);
            var positionedPc = Math.Abs(baselineOffsetDip) < 0.001
                ? pc
                : pc with { Y = pc.Y + baselineOffsetDip };

            if (pc.EquationElement is { } equationElement)
            {
                DrawEquationVisualElement(
                    context,
                    equationElement,
                    new Rect(pc.X, pc.Y, pc.W, pc.LineHeight),
                    drawFmt);
                continue;
            }

            // AV-TAB: tab characters have no glyph — skip text drawing (leader was drawn separately).
            if (pc.Ch == '\t')
            {
                DrawCharacterBorder(context, placedIndex, pc, decorationPlan);
                // Still draw underline/strikethrough across the tab gap if the run has them.
                if (drawFmt.Underline)
                    DrawDecoration(context, positionedPc, positionedPc.Y + pc.LineHeight * 0.82, drawFmt);
                DrawStrikethroughDecorations(context, positionedPc, drawFmt);
                DrawRevisionDecoration(context, positionedPc, revisionDecision, revisionColorHex);
                if (formatRevisionHighlighted)
                    DrawFormatRevisionDecoration(context, positionedPc, ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, pc.FormatRevisionAuthor));
                continue;
            }

            var ft = Build(pc.Ch.ToString(), drawFmt);
            drawY += baselineOffsetDip;
            context.DrawText(ft, new Point(pc.X, drawY));

            DrawCharacterBorder(context, placedIndex, pc, decorationPlan);
            if (drawFmt.Underline)
                DrawDecoration(context, positionedPc, positionedPc.Y + pc.LineHeight * 0.82, drawFmt);
            DrawStrikethroughDecorations(context, positionedPc, drawFmt);
            DrawRevisionDecoration(context, positionedPc, revisionDecision, revisionColorHex);
            if (formatRevisionHighlighted)
                DrawFormatRevisionDecoration(context, positionedPc, ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, pc.FormatRevisionAuthor));
            if (!pc.IsCell && proofingOffsets.Contains((pc.Block, pc.Offset)))
                DrawProofingSquiggle(context, positionedPc);
        }

        foreach (var glyph in _automaticHyphenGlyphs)
        {
            if (IsTextHiddenInCurrentView(glyph.Fmt))
                continue;
            var revisionDecision = reviewPolicy.RevisionDecision(glyph.Revision);
            if (!revisionDecision.IsTextVisible)
                continue;

            var drawFmt = glyph.Fmt;
            if (glyph.Link is { HasTarget: true })
            {
                drawFmt = drawFmt with
                {
                    ColorHex = string.IsNullOrWhiteSpace(drawFmt.ColorHex) ? HyperlinkColorHex : drawFmt.ColorHex,
                    Underline = true,
                };
            }
            var revisionColorHex = ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, glyph.RevisionAuthor);
            if (revisionDecision.IsRevisionStylingApplied)
                drawFmt = drawFmt with { ColorHex = revisionColorHex };
            var formatRevisionHighlighted = glyph.FormatRevision is not null
                && reviewPolicy.ShouldHighlightFormattingChanges;
            if (formatRevisionHighlighted && string.IsNullOrWhiteSpace(drawFmt.ColorHex))
            {
                drawFmt = drawFmt with
                {
                    ColorHex = ReviewRevisionColorPlanner.ResolveColorHex(
                        revisionColors,
                        glyph.FormatRevision?.Author),
                };
            }

            if (glyph.CommentId is { } commentId && reviewPolicy.ShouldHighlightComments)
            {
                var tint = IsCommentResolved(commentId) ? ResolvedCommentTintBrush : CommentTintBrush;
                context.FillRectangle(tint, new Rect(glyph.X, glyph.Y, Math.Max(1, glyph.W), glyph.LineHeight));
            }

            var drawY = glyph.Y;
            if (glyph.Fmt.VerticalAlign == VerticalAlign.Superscript)
            {
                drawFmt = drawFmt with
                {
                    FontSizePt = (drawFmt.FontSizePt ?? DefaultFontSizePt) * SuperSubScale,
                };
                drawY += glyph.LineHeight * SuperYRaiseFraction;
            }
            else if (glyph.Fmt.VerticalAlign == VerticalAlign.Subscript)
            {
                drawFmt = drawFmt with
                {
                    FontSizePt = (drawFmt.FontSizePt ?? DefaultFontSizePt) * SuperSubScale,
                };
                drawY += glyph.LineHeight * SubYLowerFraction;
            }

            drawY += RunBaselinePositionPlanner.ResolveOffsetDip(drawFmt, PxPerPoint);
            context.DrawText(Build("-", drawFmt), new Point(glyph.X, drawY));

            var placedGlyph = new PlacedChar(
                glyph.Block,
                glyph.BreakOffset,
                glyph.X,
                glyph.Y,
                glyph.W,
                glyph.LineHeight,
                drawFmt,
                '-',
                Sentinel: false,
                CommentId: glyph.CommentId,
                Revision: glyph.Revision,
                RevisionAuthor: glyph.RevisionAuthor,
                Link: glyph.Link,
                HasFormatRevision: glyph.FormatRevision is not null,
                FormatRevisionAuthor: glyph.FormatRevision?.Author);
            if (drawFmt.Underline)
                DrawDecoration(context, placedGlyph, glyph.Y + glyph.LineHeight * 0.82, drawFmt);
            DrawStrikethroughDecorations(context, placedGlyph, drawFmt);
            DrawRevisionDecoration(context, placedGlyph, revisionDecision, revisionColorHex);
            if (formatRevisionHighlighted)
            {
                DrawFormatRevisionDecoration(
                    context,
                    placedGlyph,
                    ReviewRevisionColorPlanner.ResolveColorHex(revisionColors, glyph.FormatRevision?.Author));
            }
        }

        foreach (var (mx, my, text, fmt) in _markers)
            context.DrawText(Build(text, fmt), new Point(mx, my));

        // AV-COMMENT: draw the comment-anchor decorations on top of the text — an amber underline under
        // every commented glyph (the in-text anchor mark) plus, for each anchor line, a minimal marker in
        // the right margin (a balloon glyph + the author's initial) aligned to that line.
        DrawCommentAnchors(context);
        DrawSimpleMarkupChangeBars(context);

        // Paragraph marks (¶) rendered faintly at the end-sentinel of each block when enabled.
        if (_showParagraphMarks)
        {
            var pilcrowFmt = new RunFormatting { FontSizePt = 8, ColorHex = "#999999" };
            foreach (var pc in _placed)
            {
                if (pc.Sentinel)
                {
                    var ft = Build("¶", pilcrowFmt);
                    context.DrawText(ft, new Point(pc.X + 1, pc.Y + pc.LineHeight - ft.Height));
                }
            }
        }

        // In-front pass: same merged ZOrder logic for all six types (UU1 + XX1 fix).
        foreach (var snapshot in DocumentViewLayoutPlanner.BuildFloatingObjectDrawOrder(_floatingSnapshots, behindText: false))
            DrawFloatingObjectSnapshot(context, snapshot);

        // HF: draw header/footer items (pre-computed in BuildHeaderFooterItems). The in-front floating
        // objects are already drawn by the planner-ordered front pass above.
        if (_viewMode == DocumentViewMode.PrintLayout)
        {
            foreach (var item in _headerFooterItems)
            {
                if (item.Image is { } image)
                {
                    var rect = new Rect(item.X, item.Y, Math.Max(1, item.Width), Math.Max(1, item.Height));
                    DrawFloatingImage(context, rect, DecodeRenderedImage(image), image, image.ReflectionPreset);
                    continue;
                }

                if (item.EmbeddedObject is { } embeddedObject)
                {
                    DrawInlineEmbeddedObject(
                        context,
                        new InlineEmbeddedObjectData(
                            new Rect(item.X, item.Y, Math.Max(1, item.Width), Math.Max(1, item.Height)),
                            embeddedObject,
                            item.EmbeddedObjectIcon,
                            blockIndex: -1,
                            runIndex: item.RunIndex));
                    continue;
                }

                if (string.IsNullOrEmpty(item.Text))
                    continue;
                var ft = Build(item.Text, item.Fmt);
                var alignOffset = AlignmentOffset(item.Alignment, item.AvailableWidth,
                    ft.WidthIncludingTrailingWhitespace, isLast: true);
                var baselineOffsetDip = RunBaselinePositionPlanner.ResolveOffsetDip(item.Fmt, PxPerPoint);
                context.DrawText(ft, new Point(item.X + alignOffset, item.Y + baselineOffsetDip));
            }

            // AV-NOTERENDER: footnote-band separators + footnote/endnote text (pre-computed in
            // BuildFootnoteItems / BuildEndnoteItems). Separators draw first so the text sits below them.
            foreach (var (x1, x2, sy) in _noteSeparators)
                context.DrawLine(NoteSeparatorPen, new Point(x1, sy), new Point(x2, sy));

            foreach (var note in _noteItems)
            {
                if (string.IsNullOrEmpty(note.Text)) continue;
                var drawFmt = note.Fmt;
                var drawY = note.Y;
                // Render the superscript number prefix smaller + raised, mirroring the body super/subscript draw.
                if (note.Fmt.VerticalAlign == VerticalAlign.Superscript)
                {
                    var sz = (drawFmt.FontSizePt ?? NoteFontSizePt) * SuperSubScale;
                    drawFmt = drawFmt with { FontSizePt = sz };
                    drawY = note.Y - (note.Fmt.FontSizePt ?? NoteFontSizePt) * PxPerPoint * 0.15;
                }
                drawY += RunBaselinePositionPlanner.ResolveOffsetDip(drawFmt, PxPerPoint);
                context.DrawText(Build(note.Text, drawFmt), new Point(note.X, drawY));
            }

            // AV-HFEDIT: when the caret is inside a header/footer region, draw a subtle region
            // outline + a small "Header"/"Footer" label so the active edit zone is obvious.
            DrawHeaderFooterEditRegion(context);
        }

        DrawPageBordersForLayer(context, PageBorderRenderLayer.InFrontOfText);

        // AV-FLSEL: draw selection outline + 8 resize handles over the selected floating object.
        if (_selectedFloatingGroupChild is { } selChild)
        {
            if (TryGetFloatingGroupChildGeometry(
                    selChild.BlockIndex,
                    selChild.RunIndex,
                    selChild.ChildPath,
                    out var geometry))
            {
                DrawFloatingGroupChildSelection(
                    context,
                    geometry.Child.Rect,
                    geometry.Child.RotationAngle,
                    geometry.Child.FlipH,
                    geometry.Child.FlipV,
                    geometry.ParentTransforms);
                if (geometry.Child.Kind == FloatingGroupChildData.ChildKind.Shape)
                    DrawShapeEditPointHandles(
                        context,
                        geometry.Child.Rect,
                        selChild.BlockIndex,
                        selChild.RunIndex,
                        selChild.ChildPath);
            }
        }
        else if (_selectedFloating is { } selFl)
        {
            DrawFloatingSelection(context, selFl.Rect, selFl.BlockIndex, selFl.RunIndex, selFl.Kind);
        }

        // AV-HFEDIT: the header/footer caret renders independently of the body caret.
        if (IsFocused && _hfCaret is not null && TryGetHfCaretRect(out var hfRect))
            context.FillRectangle(Brushes.Black, hfRect);
        else if (IsFocused && NormalizedSelection() is null && _hfCaret is null && TryGetCaretRect(out var caretRect))
            context.FillRectangle(Brushes.Black, caretRect);
    }

    private void DrawPageBordersForLayer(DrawingContext context, PageBorderRenderLayer layer)
    {
        if (_viewMode != DocumentViewMode.PrintLayout
            || _doc.Page.PageBorder is not { } border
            || PageBorderVisibilityPlanner.LayerFor(border.ZOrder) != layer)
            return;

        for (var pageIndex = 0; pageIndex < _pageCount; pageIndex++)
        {
            var pageRect = new Rect(
                _surfacePlan.RenderedPageLeftDip(pageIndex),
                _surfacePlan.RenderedPageTopDip(pageIndex),
                _pageWidth,
                _pageHeightPx);
            DrawPageBorder(context, pageRect, pageIndex);
        }
    }

    // ── AV-HFEDIT: render the active header/footer edit region outline + label + caret ──────────────

    private void DrawLineNumbers(DrawingContext context)
    {
        foreach (var item in BuildLineNumberRenderItems())
        {
            var formatted = Build(item.Number.ToString(CultureInfo.InvariantCulture), LineNumberFormatting);
            var x = item.GutterRight - formatted.WidthIncludingTrailingWhitespace;
            var y = item.Y + Math.Max(0, (item.LineHeight - formatted.Height) / 2);
            context.DrawText(formatted, new Point(x, y));
        }
    }

    internal IReadOnlyList<LineNumberRenderItem> GetLineNumberRenderItemsForTest() =>
        BuildLineNumberRenderItems();

    private IReadOnlyList<LineNumberRenderItem> BuildLineNumberRenderItems()
    {
        var sections = _doc.Sections;
        if (_viewMode != DocumentViewMode.PrintLayout
            || sections.All(section => section.Page.LineNumberMode == LineNumberMode.None))
            return [];

        var blockSectionAssignments = ComputeBlockSectionAssignments();
        var sourceLines = _placed
            .Where(placed => !placed.IsCell
                && placed.Block >= 0
                && placed.Block < _doc.Blocks.Count
                && _doc.Blocks[placed.Block] is Paragraph)
            .GroupBy(placed => new
            {
                PageIndex = RenderedPageIndexForPoint(placed.X, placed.Y),
                ColumnIndex = ColumnIndexForRenderedX(placed.X, RenderedPageIndexForPoint(placed.X, placed.Y)),
                SectionIndex = blockSectionAssignments[placed.Block],
                Y = Math.Round(placed.Y * 16),
            })
            .OrderBy(group => group.Key.PageIndex)
            .ThenBy(group => group.Key.ColumnIndex)
            .ThenBy(group => group.Key.Y)
            .Select(group =>
            {
                var placed = group.OrderBy(item => item.X).First();
                var paragraph = (Paragraph)_doc.Blocks[placed.Block];
                var formatting = ResolveParagraphFmt(paragraph);
                return new LineNumberSourcePlacement(
                    group.Key.PageIndex,
                    group.Key.ColumnIndex,
                    group.Key.SectionIndex,
                    placed.Y,
                    placed.LineHeight,
                    formatting.SuppressLineNumbers);
            })
            .ToList();

        var plans = LineNumberVisualPlanner.Build(
            sourceLines.Select(line => new LineNumberVisualSourceLine(
                line.PageIndex,
                line.SuppressNumber,
                line.SectionIndex)).ToList(),
            sections.Select(section => new LineNumberVisualSectionSettings(
                section.Page.LineNumberMode,
                section.Page.LineNumberStartAt,
                section.Page.LineNumberCountBy)).ToList());

        var results = new List<LineNumberRenderItem>(plans.Count);
        for (var index = 0; index < plans.Count; index++)
        {
            var plan = plans[index];
            if (!plan.IsVisible)
                continue;

            var line = sourceLines[index];
            var pageLeft = _surfacePlan.RenderedPageLeftDip(line.PageIndex);
            var columnLeft = pageLeft + (_contentLeft - _pageLeft)
                + line.ColumnIndex * (_colWidth + _colGap);
            results.Add(new LineNumberRenderItem(
                plan.Number,
                plan.PageIndex,
                line.ColumnIndex,
                Math.Max(_pageLeft, columnLeft - 8),
                line.Y,
                line.LineHeight));
        }

        return results;
    }

    private int ColumnIndexFor(double x) =>
        _colCount <= 1 || _colWidth <= 0
            ? 0
            : Math.Clamp((int)Math.Floor((x - _contentLeft) / (_colWidth + _colGap)), 0, _colCount - 1);

    private int ColumnIndexForRenderedX(double x, int pageIndex)
    {
        if (!_surfacePlan.UsesProjectedPageFlow)
            return ColumnIndexFor(x);

        var pageOffset = _surfacePlan.RenderedPageLeftDip(pageIndex) - _surfacePlan.PageLeftDip;
        return ColumnIndexFor(x - pageOffset);
    }

    private int RenderedPageIndexForPoint(double x, double y)
    {
        if (!_surfacePlan.UsesProjectedPageFlow || !_pageFlowProjected)
            return PageIndexFromPageSpaceY(y);

        var relativeX = x - _surfacePlan.PageLeftDip;
        var relativeY = y - _surfacePlan.DeskPaddingDip;
        if (relativeX < 0 || relativeY < 0)
            return 0;
        var renderedColumns = _surfacePlan.UsesHorizontalPageFlow
            ? Math.Max(1, _pageCount)
            : _surfacePlan.PageGridColumns;
        var column = Math.Clamp(
            (int)(relativeX / Math.Max(1, _surfacePlan.HorizontalPageStrideDip)),
            0,
            renderedColumns - 1);
        var row = _surfacePlan.UsesHorizontalPageFlow
            ? 0
            : Math.Max(0, (int)(relativeY / Math.Max(1, _surfacePlan.PageStrideDip)));
        return Math.Clamp(
            row * renderedColumns + column,
            0,
            Math.Max(0, _pageCount - 1));
    }

    private static readonly IPen HfRegionPen =
        new Pen(new SolidColorBrush(Color.FromArgb(160, 90, 120, 200)), 1, DashStyle.Dash);
    private static readonly IBrush HfRegionLabelBrush = new SolidColorBrush(Color.FromArgb(200, 90, 120, 200));

    /// <summary>
    /// Draws a dashed outline around the line band of the currently-edited header/footer paragraph plus a
    /// "Header"/"Footer" label at its left edge. No-op when no H/F caret is active.
    /// </summary>
    private void DrawHeaderFooterEditRegion(DrawingContext context)
    {
        if (_hfCaret is not { } hc)
            return;
        // Find the rendered item(s) for this target's paragraph to derive the band.
        double top = double.MaxValue, bottom = double.MinValue, lineH = 0;
        var found = false;
        foreach (var item in _headerFooterItems)
        {
            if (item.Target is not { } t || !t.Equals(hc.Target))
                continue;
            found = true;
            top = Math.Min(top, item.Y);
            var h = item.LineHeight > 0 ? item.LineHeight : DefaultFontSizePt * PxPerPoint * 1.3;
            bottom = Math.Max(bottom, item.Y + h);
            lineH = Math.Max(lineH, h);
        }
        if (!found)
            return;

        var pad = 3.0;
        var regionItem = _headerFooterItems.First(item => item.Target is { } t && t.Equals(hc.Target));
        var pageIndex = RenderedPageIndexForPoint(regionItem.X, regionItem.Y);
        var pageLeft = _surfacePlan.RenderedPageLeftDip(pageIndex);
        var contentLeft = pageLeft + (_contentLeft - _pageLeft);
        var rect = new Rect(contentLeft - pad, top - pad,
            _contentWidth + 2 * pad, (bottom - top) + 2 * pad);
        context.DrawRectangle(null, HfRegionPen, rect);

        // Label: "Header"/"Footer" above the band's top-left (clamped into the page).
        var label = HeaderFooterDialogPlanner.IsFooterSlot(hc.Target.Slot) ? "Footer" : "Header";
        var labelFt = Build(label, RunFormatting.Default with { FontSizePt = 8 });
        var labelY = Math.Max(0, top - pad - labelFt.Height);
        context.DrawText(labelFt, new Point(contentLeft - pad, labelY));
    }

    /// <summary>
    /// Computes the caret rectangle for the active header/footer caret by measuring the prefix width up to
    /// the caret offset within the target paragraph's first rendered line. Returns false when no item for
    /// the target is laid out.
    /// </summary>
    private bool TryGetHfCaretRect(out Rect rect)
    {
        rect = default;
        if (_hfCaret is not { } hc)
            return false;

        // Locate the rendered item whose model span contains the caret offset (or the line's last item).
        HfRenderItem? hostItem = null;
        HfRenderItem? firstForTarget = null;
        foreach (var item in _headerFooterItems)
        {
            if (item.Target is not { } t || !t.Equals(hc.Target))
                continue;
            firstForTarget ??= item;
            var start = item.ModelStartOffset;
            var end = start + item.Text.Length;
            if (hc.Offset >= start && hc.Offset <= end)
            {
                hostItem = item;
                break;
            }
        }
        hostItem ??= firstForTarget;
        if (hostItem is null)
        {
            // Empty paragraph with no text segment: place caret at content-left on the band (use first item).
            // firstForTarget is null here only when nothing was laid out → fail.
            return false;
        }

        var ft = Build(hostItem.Text.Length == 0 ? " " : hostItem.Text, hostItem.Fmt);
        var alignOffset = AlignmentOffset(hostItem.Alignment, hostItem.AvailableWidth,
            ft.WidthIncludingTrailingWhitespace, isLast: true);
        var localOffset = Math.Clamp(hc.Offset - hostItem.ModelStartOffset, 0, hostItem.Text.Length);
        var prefixW = hostItem.Text.Length == 0 || localOffset == 0
            ? 0
            : Build(hostItem.Text[..localOffset], hostItem.Fmt).WidthIncludingTrailingWhitespace;
        var caretX = hostItem.X + alignOffset + prefixW;
        var caretH = hostItem.LineHeight > 0 ? hostItem.LineHeight : ft.Height;
        rect = new Rect(caretX, hostItem.Y, 1.5, caretH);
        return true;
    }

    /// <summary>
    /// Renders a single floating image (or a placeholder rect if the bitmap could not be decoded).
    /// Shared by the behind-text and in-front passes in <see cref="Render"/>.
    /// </summary>
    private void DrawFloatingObjectSnapshot(DrawingContext context, DocumentFloatingObjectSnapshot snapshot)
    {
        switch (snapshot.Kind)
        {
            case DocumentFloatingObjectKind.Image:
                foreach (var image in _floatingImages)
                {
                    if (image.BlockIndex == snapshot.BlockIndex && image.RunIndex == snapshot.RunIndex)
                    {
                        DrawFloatingImage(context, image.Rect, image.Image, image.Model, image.ReflectionPreset);
                        return;
                    }
                }
                break;

            case DocumentFloatingObjectKind.Shape:
                if (_floatingShapes.FirstOrDefault(shape =>
                        shape.BlockIndex == snapshot.BlockIndex && shape.RunIndex == snapshot.RunIndex) is { } shape)
                    DrawFloatingShape(context, shape);
                break;

            case DocumentFloatingObjectKind.Chart:
                if (_floatingCharts.FirstOrDefault(chart =>
                        chart.BlockIndex == snapshot.BlockIndex && chart.RunIndex == snapshot.RunIndex) is { } chart)
                    DrawFloatingChart(context, chart);
                break;

            case DocumentFloatingObjectKind.WordArt:
                if (_floatingWordArts.FirstOrDefault(wordArt =>
                        wordArt.BlockIndex == snapshot.BlockIndex && wordArt.RunIndex == snapshot.RunIndex) is { } wordArt)
                    DrawFloatingWordArt(context, wordArt);
                break;

            case DocumentFloatingObjectKind.SmartArt:
                if (_floatingSmartArts.FirstOrDefault(smartArt =>
                        smartArt.BlockIndex == snapshot.BlockIndex && smartArt.RunIndex == snapshot.RunIndex) is { } smartArt)
                    DrawFloatingSmartArt(context, smartArt);
                break;

            case DocumentFloatingObjectKind.Group:
                if (_floatingGroups.FirstOrDefault(group =>
                        group.BlockIndex == snapshot.BlockIndex && group.RunIndex == snapshot.RunIndex) is { } group)
                    DrawFloatingGroup(context, group);
                break;
        }
    }

    private void DrawFloatingImage(
        DrawingContext context,
        Rect rect,
        AvaloniaRenderedImage? rendered,
        InlineImage model,
        int reflectionPreset = 0)
    {
        IDisposable? transformState = null;
        if (model.RotationAngle != 0 || model.FlipH || model.FlipV)
            transformState = context.PushTransform(BuildPictureTransform(rect, model));

        try
        {
            if (rendered is not null)
            {
                var visualRect = rendered.VisualRect(rect);
                context.DrawImage(rendered.Bitmap, visualRect);
                DrawFloatingImageReflection(context, rect, rendered, model);
            }
            else
            {
                // Placeholder: light-blue fill + dashed border so the position is visible even without bitmap data.
                context.FillRectangle(FloatPlaceholderFill, rect);
                context.DrawRectangle(null, FloatPlaceholderPen, rect);
            }

            if (BuildPictureBorderPen(model) is { } borderPen)
                context.DrawRectangle(null, borderPen, rect);
        }
        finally
        {
            transformState?.Dispose();
        }
    }

    private IReadOnlyList<PdfDrawOp> BuildPdfEmbeddedObjectOps(
        Rect sourceRect,
        EmbeddedObjectVisualPlan plan,
        AvaloniaRenderedImage? renderedIcon,
        double pageTopDip,
        double pageHeightPt)
    {
        var xPt = (sourceRect.Left - _contentLeft) / PxPerPoint + _doc.Page.MarginLeftPt;
        var yPt = pageHeightPt - ((sourceRect.Bottom - pageTopDip) / PxPerPoint);
        var widthPt = sourceRect.Width / PxPerPoint;
        var heightPt = sourceRect.Height / PxPerPoint;
        var ops = new List<PdfDrawOp>
        {
            new PdfFillRect(xPt, yPt, widthPt, heightPt, ParseColor(plan.BackgroundColorHex))
        };
        if (plan.Icon is { } icon
            && BuildPdfImage(sourceRect, icon, renderedIcon, pageTopDip, pageHeightPt) is { } iconOp)
        {
            ops.Add(iconOp);
        }
        else
        {
            const double fontSizePt = 10;
            var estimatedTextWidth = plan.Label.Length * fontSizePt * 0.52;
            ops.Add(new PdfText(
                xPt + Math.Max(4, (widthPt - estimatedTextWidth) / 2),
                yPt + Math.Max(fontSizePt, (heightPt - fontSizePt) / 2),
                fontSizePt,
                PdfFontFace.Regular,
                ParseColor(plan.ForegroundColorHex),
                plan.Label));
        }
        ops.Add(new PdfStrokeRect(
            xPt,
            yPt,
            widthPt,
            heightPt,
            ParseColor(plan.BorderColorHex),
            0.75));
        return ops;
    }

    private void DrawInlineEmbeddedObject(DrawingContext context, InlineEmbeddedObjectData data)
    {
        var plan = data.Plan;
        context.FillRectangle(BrushFor(plan.BackgroundColorHex), data.Rect);

        var inset = Math.Min(4, Math.Min(data.Rect.Width, data.Rect.Height) / 4);
        var contentRect = new Rect(
            data.Rect.X + inset,
            data.Rect.Y + inset,
            Math.Max(0, data.Rect.Width - inset * 2),
            Math.Max(0, data.Rect.Height - inset * 2));
        if (data.Icon is not null && contentRect.Width > 0 && contentRect.Height > 0)
        {
            context.DrawImage(data.Icon.Bitmap, data.Icon.VisualRect(contentRect));
        }
        else if (contentRect.Width > 0 && contentRect.Height > 0)
        {
            var formatted = Build(
                plan.Label,
                RunFormatting.Default with { ColorHex = plan.ForegroundColorHex });
            var x = contentRect.X + Math.Max(0, (contentRect.Width - formatted.WidthIncludingTrailingWhitespace) / 2);
            var y = contentRect.Y + Math.Max(0, (contentRect.Height - formatted.Height) / 2);
            using (context.PushClip(contentRect))
                context.DrawText(formatted, new Point(x, y));
        }

        context.DrawRectangle(null, new Pen(BrushFor(plan.BorderColorHex), 1), data.Rect);
    }

    internal static Matrix BuildPictureTransform(Rect rect, InlineImage image)
    {
        var centerX = rect.X + rect.Width / 2;
        var centerY = rect.Y + rect.Height / 2;
        var matrix = Matrix.Identity;
        matrix *= Matrix.CreateTranslation(-centerX, -centerY);
        if (image.FlipH) matrix *= new Matrix(-1, 0, 0, 1, 0, 0);
        if (image.FlipV) matrix *= new Matrix(1, 0, 0, -1, 0, 0);
        if (image.RotationAngle != 0)
            matrix *= Matrix.CreateRotation(image.RotationAngle * Math.PI / 180.0);
        return matrix * Matrix.CreateTranslation(centerX, centerY);
    }

    internal Pen? BuildPictureBorderPen(InlineImage image)
    {
        if (!image.HasBorder)
            return null;

        var colorHex = image.BorderColorHex!.Trim();
        if (!colorHex.StartsWith('#'))
            colorHex = "#" + colorHex;
        return new Pen(
            BrushFor(colorHex),
            Math.Max(image.BorderWidthPt, 0.75) * PxPerPoint,
            BuildPictureDashStyle(image.BorderDash));
    }

    internal static DashStyle? BuildPictureDashStyle(string? dashStyle) =>
        dashStyle?.Trim().ToLowerInvariant() switch
        {
            "dash" or "sysdash" => new DashStyle([4, 3], 0),
            "dot" or "sysdot" => new DashStyle([1, 2], 0),
            "dashdot" or "sysdashdot" => new DashStyle([4, 2, 1, 2], 0),
            "lgdash" => new DashStyle([8, 3], 0),
            "lgdashdot" => new DashStyle([8, 2, 1, 2], 0),
            "lgdashdotdot" => new DashStyle([8, 2, 1, 2, 1, 2], 0),
            _ => null,
        };

    private static void DrawFloatingImageReflection(
        DrawingContext context,
        Rect imageRect,
        AvaloniaRenderedImage rendered,
        InlineImage image)
    {
        var parameters = ReflectionParameters(image);
        if (parameters is null)
            return;

        var reflectionRect = new Rect(
            imageRect.X,
            imageRect.Bottom + parameters.DistanceDip,
            imageRect.Width,
            imageRect.Height);
        var fadeMask = new LinearGradientBrush
        {
            StartPoint = new RelativePoint(0, 0, RelativeUnit.Relative),
            EndPoint = new RelativePoint(0, 1, RelativeUnit.Relative),
        };
        fadeMask.GradientStops.Add(new global::Avalonia.Media.GradientStop(
            Color.FromArgb((byte)Math.Round(parameters.Opacity * 255), 0, 0, 0),
            parameters.StartPosition));
        fadeMask.GradientStops.Add(new global::Avalonia.Media.GradientStop(
            Color.FromArgb((byte)Math.Round(parameters.EndOpacity * 255), 0, 0, 0),
            parameters.EndPosition));

        var mirror = Matrix.Identity;
        mirror = mirror * Matrix.CreateTranslation(0, -imageRect.Bottom);
        mirror = mirror * new Matrix(1, 0, 0, -1, 0, 0);
        mirror = mirror * Matrix.CreateTranslation(0, imageRect.Bottom);

        using var clip = context.PushClip(reflectionRect);
        using var mask = context.PushOpacityMask(fadeMask, reflectionRect);
        using var transform = context.PushTransform(mirror);
        context.DrawImage(rendered.Bitmap, rendered.VisualRect(imageRect));
    }

    internal static PictureReflectionVisualPlan? ReflectionParameters(InlineImage image) =>
        PictureEffectVisualPlanner.BuildReflectionPlan(image);

    private static double ReflectionExtraHeight(InlineImage image, double imageHeight)
    {
        return ReflectionParameters(image) is { } parameters
            ? imageHeight + parameters.DistanceDip
            : 0;
    }

    private void DrawShapeTextSelection(
        DrawingContext context,
        FloatingShapeData shapeData,
        Rect rect,
        DrawingObjectTextLayoutPlan layout,
        Point origin,
        Point center)
    {
        if (ShapeTextSelectionInfo is not { } selection
            || selection.Start.BlockIndex != shapeData.BlockIndex
            || selection.Start.RunIndex != shapeData.RunIndex
            || !TryGetShapeTextTarget(
                shapeData.BlockIndex, shapeData.RunIndex, shapeData.ChildPath,
                out _, out var shape))
            return;

        IDisposable? rotation = null;
        if (shapeData.TextDirection is ShapeTextDirection.Rotate90 or ShapeTextDirection.Rotate270)
        {
            var angle = shapeData.TextDirection == ShapeTextDirection.Rotate90
                ? Math.PI / 2
                : -Math.PI / 2;
            rotation = context.PushTransform(
                Matrix.CreateTranslation(-center.X, -center.Y)
                * Matrix.CreateRotation(angle)
                * Matrix.CreateTranslation(center.X, center.Y));
        }

        try
        {
            foreach (var glyph in layout.Glyphs)
            {
                var position = (shapeData.BlockIndex, shapeData.RunIndex, glyph.ParagraphIndex,
                    glyph.RunIndex, glyph.Offset);
                if (CompareShapeTextPositions(position, selection.Start) < 0
                    || CompareShapeTextPositions(position, selection.End) >= 0)
                    continue;

                context.FillRectangle(SelectionBrush, new Rect(
                    origin.X + glyph.X,
                    origin.Y + glyph.Y,
                    Math.Max(1, glyph.Width),
                    Math.Max(1, glyph.Height)));
            }
        }
        finally
        {
            rotation?.Dispose();
        }
    }

    /// <summary>
    /// Renders a single floating shape from its pre-computed <see cref="FloatingShapeData"/>.
    /// Applies rotation/flip transforms around the shape centre when present, then draws
    /// the geometry (fill + outline) followed by any centred shape text.
    /// </summary>
    private void DrawFloatingShape(DrawingContext context, FloatingShapeData sd)
    {
        var rect = sd.Rect;
        var cx = rect.X + rect.Width  / 2;
        var cy = rect.Y + rect.Height / 2;

        // Push a transform when rotation or flip is needed.
        bool needTransform = sd.RotationAngle != 0 || sd.FlipH || sd.FlipV;
        IDisposable? xformState = null;

        if (needTransform)
        {
            // Avalonia ScaleTransform has no center-point overload.
            // Build a composite matrix: translate to origin, scale/rotate, translate back.
            var mat = Matrix.Identity;
            // Translate to shape centre.
            mat = mat * Matrix.CreateTranslation(-cx, -cy);
            // Apply flip(s).
            if (sd.FlipH) mat = mat * new Matrix(-1, 0, 0, 1, 0, 0);
            if (sd.FlipV) mat = mat * new Matrix(1, 0, 0, -1, 0, 0);
            // Apply rotation (Avalonia RotateTransform takes degrees; convert to radians for matrix).
            if (sd.RotationAngle != 0)
            {
                var rad = sd.RotationAngle * Math.PI / 180.0;
                mat = mat * Matrix.CreateRotation(rad);
            }
            // Translate back.
            mat = mat * Matrix.CreateTranslation(cx, cy);
            xformState = context.PushTransform(mat);
        }

        try
        {
            DrawFloatingShapeEffects(context, sd, rect);

            // ── Draw geometry ──────────────────────────────────────────────────────
            if (sd.CustomGeo is { } cg && cg.Segments.Count > 0)
            {
                // Freeform custom geometry: build a StreamGeometry from the 21600×21600 grid segments.
                var geo = CustomShapePathAvaloniaAdapter.Build(cg, rect, sd.FillBrush is not null);
                context.DrawGeometry(sd.FillBrush, sd.OutlinePen, geo);
            }
            else
            {
                switch (sd.Kind)
                {
                    case ShapeKind.Ellipse:
                        context.DrawEllipse(sd.FillBrush, sd.OutlinePen,
                            new Point(cx, cy), rect.Width / 2, rect.Height / 2);
                        break;

                    case ShapeKind.RoundedRectangle:
                    {
                        // Build a rounded rectangle with a 6pt corner radius (matches WPF reference CornerRadius=6).
                        var cornerR = Math.Min(6 * PxPerPoint, Math.Min(rect.Width, rect.Height) / 4);
                        var geo = BuildRoundedRectGeometry(rect, cornerR);
                        context.DrawGeometry(sd.FillBrush, sd.OutlinePen, geo);
                        break;
                    }

                    default: // Rectangle, TextBox — plain rect
                        context.DrawRectangle(sd.FillBrush, sd.OutlinePen, rect);
                        break;
                }
            }

            // ── Draw shape text (UU3 fix) ──────────────────────────────────────────
            // Draw the shared run-aware layout. Rotated text is laid out in the swapped text box
            // dimensions and then rotated around the shape centre; the outer clip remains unchanged.
            if (sd.TextLayout is { } textLayout)
            {
                var origin = ShapeTextLayoutOrigin(rect, textLayout);
                using var clip = context.PushClip(rect);
                DrawShapeTextSelection(context, sd, rect, textLayout, origin, new Point(cx, cy));
                IDisposable? rotation = null;
                if (sd.TextDirection is ShapeTextDirection.Rotate90 or ShapeTextDirection.Rotate270)
                {
                    var angle = sd.TextDirection == ShapeTextDirection.Rotate90
                        ? Math.PI / 2
                        : -Math.PI / 2;
                    var center = new Point(cx, cy);
                    rotation = context.PushTransform(
                        Matrix.CreateTranslation(-center.X, -center.Y)
                        * Matrix.CreateRotation(angle)
                        * Matrix.CreateTranslation(center.X, center.Y));
                }
                foreach (var glyph in textLayout.Glyphs)
                {
                    var point = new Point(origin.X + glyph.X, origin.Y + glyph.Y);
                    context.DrawText(Build(glyph.Character.ToString(), glyph.Formatting), point);
                    var decorationPen = new Pen(BrushFor(glyph.Formatting.ColorHex),
                        Math.Max(1, glyph.Height / 14));
                    if (glyph.Formatting.Underline)
                        context.DrawLine(decorationPen,
                            new Point(point.X, point.Y + glyph.Height * 0.82),
                            new Point(point.X + glyph.Width, point.Y + glyph.Height * 0.82));
                    if (glyph.Formatting.DoubleStrikethrough)
                    {
                        foreach (var fraction in new[] { 0.46, 0.54 })
                            context.DrawLine(decorationPen,
                                new Point(point.X, point.Y + glyph.Height * fraction),
                                new Point(point.X + glyph.Width, point.Y + glyph.Height * fraction));
                    }
                    else if (glyph.Formatting.Strikethrough)
                    {
                        context.DrawLine(decorationPen,
                            new Point(point.X, point.Y + glyph.Height * 0.5),
                            new Point(point.X + glyph.Width, point.Y + glyph.Height * 0.5));
                    }
                }
                rotation?.Dispose();
            }
        }
        finally
        {
            xformState?.Dispose();
        }
    }

    private static void DrawFloatingShapeEffects(DrawingContext context, FloatingShapeData sd, Rect rect)
    {
        var effects = sd.Effects;
        if (!effects.HasAny)
            return;

        if (effects.HasShadow)
        {
            var shadowColor = TryParseAvaloniaColor(effects.ShadowColorHex, out var parsed)
                ? parsed
                : Colors.Black;
            var radians = effects.ShadowDirectionDegrees * Math.PI / 180.0;
            var distance = effects.ShadowDistanceDip > 0 ? effects.ShadowDistanceDip : 3.0;
            var offsetX = Math.Cos(radians) * distance;
            var offsetY = Math.Sin(radians) * distance;
            var spread = Math.Max(0, effects.ShadowBlurDip * 0.12);
            DrawFloatingShapeEffectGeometry(
                context,
                sd,
                OffsetAndInflate(rect, offsetX, offsetY, spread),
                EffectBrush(shadowColor, effects.ShadowOpacity));
        }

        if (effects.HasGlow)
        {
            var glowColor = TryParseAvaloniaColor(effects.GlowColorHex, out var parsed)
                ? parsed
                : Color.FromRgb(0x44, 0x72, 0xC4);
            var radius = Math.Max(2.0, effects.GlowRadiusDip);
            DrawFloatingShapeEffectGeometry(
                context,
                sd,
                OffsetAndInflate(rect, 0, 0, radius * 0.55),
                EffectBrush(glowColor, effects.GlowOpacity * 0.24));
            DrawFloatingShapeEffectGeometry(
                context,
                sd,
                OffsetAndInflate(rect, 0, 0, radius * 0.25),
                EffectBrush(glowColor, effects.GlowOpacity * 0.36));
        }
    }

    private static void DrawFloatingShapeEffectGeometry(
        DrawingContext context,
        FloatingShapeData sd,
        Rect rect,
        IBrush brush)
    {
        if (sd.CustomGeo is { } cg && cg.Segments.Count > 0)
        {
            var geo = CustomShapePathAvaloniaAdapter.Build(cg, rect, isFilled: true);

            context.DrawGeometry(brush, null, geo);
            return;
        }

        switch (sd.Kind)
        {
            case ShapeKind.Ellipse:
                context.DrawEllipse(brush, null, rect.Center, rect.Width / 2, rect.Height / 2);
                break;

            case ShapeKind.RoundedRectangle:
                var cornerRadius = Math.Min(6 * PxPerPoint, Math.Min(rect.Width, rect.Height) / 4);
                context.DrawGeometry(brush, null, BuildRoundedRectGeometry(rect, cornerRadius));
                break;

            default:
                context.DrawRectangle(brush, null, rect);
                break;
        }
    }

    private static Rect OffsetAndInflate(Rect rect, double offsetX, double offsetY, double inflate) =>
        new(
            rect.X + offsetX - inflate,
            rect.Y + offsetY - inflate,
            Math.Max(1, rect.Width + 2 * inflate),
            Math.Max(1, rect.Height + 2 * inflate));

    private static IBrush EffectBrush(Color color, double opacity)
    {
        var alpha = (byte)Math.Clamp((int)Math.Round(255 * Math.Clamp(opacity, 0, 1)), 0, 255);
        return new SolidColorBrush(Color.FromArgb(alpha, color.R, color.G, color.B));
    }

    /// <summary>
    /// Builds a rounded-rectangle <see cref="StreamGeometry"/> with a uniform corner radius.
    /// </summary>
    private static StreamGeometry BuildRoundedRectGeometry(Rect rect, double r)
    {
        var geo = new StreamGeometry();
        using var ctx = geo.Open();
        ctx.BeginFigure(new Point(rect.X + r, rect.Y), isFilled: true);
        ctx.LineTo(new Point(rect.Right - r, rect.Y));
        ctx.ArcTo(new Point(rect.Right, rect.Y + r),
            new Size(r, r), 0, false, SweepDirection.Clockwise);
        ctx.LineTo(new Point(rect.Right, rect.Bottom - r));
        ctx.ArcTo(new Point(rect.Right - r, rect.Bottom),
            new Size(r, r), 0, false, SweepDirection.Clockwise);
        ctx.LineTo(new Point(rect.X + r, rect.Bottom));
        ctx.ArcTo(new Point(rect.X, rect.Bottom - r),
            new Size(r, r), 0, false, SweepDirection.Clockwise);
        ctx.LineTo(new Point(rect.X, rect.Y + r));
        ctx.ArcTo(new Point(rect.X + r, rect.Y),
            new Size(r, r), 0, false, SweepDirection.Clockwise);
        ctx.EndFigure(true);
        return geo;
    }

    private static IBrush FloatPlaceholderFill { get; } =
        new SolidColorBrush(Color.FromArgb(0x44, 0x33, 0x99, 0xFF));
    private static Pen FloatPlaceholderPen { get; } =
        new Pen(new SolidColorBrush(Color.FromArgb(0xBB, 0x33, 0x99, 0xFF)), 1.0,
            new DashStyle([4, 3], 0));

    // ── AV-FLSEL: floating selection rendering + hit-test + edit methods ───────────────────────────

    // Selection outline pen: solid blue, 1.5px.
    private static readonly Pen FloatSelectionPen =
        new Pen(new SolidColorBrush(Color.FromRgb(0x00, 0x78, 0xD4)), 1.5);
    // Handle fill: white square with blue border.
    private static readonly IBrush FloatHandleFill   = Brushes.White;
    private static readonly Pen    FloatHandlePen    =
        new Pen(new SolidColorBrush(Color.FromRgb(0x00, 0x78, 0xD4)), 1.0);
    private const double FloatHandleSize = 7; // handle square side length in px

    private static DocumentFloatRect ToPlannerRect(Rect rect) =>
        new(rect.X, rect.Y, rect.Width, rect.Height);

    private static Rect ToAvaloniaRect(DocumentFloatRect rect) =>
        new(rect.XDip, rect.YDip, rect.WidthDip, rect.HeightDip);

    private static DocumentFloatPoint ToPlannerPoint(Point point) =>
        new(point.X, point.Y);

    /// <summary>
    /// Resolves the current RotationAngle/FlipH/FlipV for the floating object at (blockIndex, runIndex,
    /// kind), so handle geometry, resize, and hit-test can un-rotate/un-flip against the SAME transform
    /// DrawFloatingShape uses to render it (see ~line 5828: <c>needTransform = RotationAngle != 0 ||
    /// FlipH || FlipV</c>, flip-then-rotate about the rect centre). Only <see cref="InlineImage"/> and
    /// <see cref="Shape"/> carry rotation/flip today; every other floating kind (Chart/WordArt/SmartArt/
    /// Group) has none, so they fall back to the identity (0, false, false) — same as an unrotated image
    /// shape. Drawing groups and WordArt use the same centre transform contract.
    /// </summary>
    private (double Angle, bool FlipH, bool FlipV) GetFloatRotation(int blockIndex, int runIndex, string kind)
    {
        if (blockIndex < 0 || blockIndex >= _doc.Blocks.Count) return (0, false, false);
        if (_doc.Blocks[blockIndex] is not Paragraph para) return (0, false, false);
        if (runIndex < 0 || runIndex >= para.Runs.Count) return (0, false, false);
        var run = para.Runs[runIndex];

        return kind switch
        {
            "Image" when run.Image is { } img => (img.RotationAngle, img.FlipH, img.FlipV),
            "Shape" when run.Shape is { } shape => (shape.RotationAngle, shape.FlipH, shape.FlipV),
            "WordArt" when run.WordArt is { } wordArt => (wordArt.RotationAngle, wordArt.FlipH, wordArt.FlipV),
            "Group" when run.DrawingGroup is { } group => (group.RotationAngle, group.FlipH, group.FlipV),
            _ => (0, false, false),
        };
    }

    private static DocumentFloatingHandle ToPlannerHandle(FloatHandle handle) => handle switch
    {
        FloatHandle.Body => DocumentFloatingHandle.Body,
        FloatHandle.TopLeft => DocumentFloatingHandle.TopLeft,
        FloatHandle.Top => DocumentFloatingHandle.Top,
        FloatHandle.TopRight => DocumentFloatingHandle.TopRight,
        FloatHandle.Left => DocumentFloatingHandle.Left,
        FloatHandle.Right => DocumentFloatingHandle.Right,
        FloatHandle.BottomLeft => DocumentFloatingHandle.BottomLeft,
        FloatHandle.Bottom => DocumentFloatingHandle.Bottom,
        FloatHandle.BottomRight => DocumentFloatingHandle.BottomRight,
        _ => DocumentFloatingHandle.None,
    };

    private static FloatHandle FromPlannerHandle(DocumentFloatingHandle handle) => handle switch
    {
        DocumentFloatingHandle.Body => FloatHandle.Body,
        DocumentFloatingHandle.TopLeft => FloatHandle.TopLeft,
        DocumentFloatingHandle.Top => FloatHandle.Top,
        DocumentFloatingHandle.TopRight => FloatHandle.TopRight,
        DocumentFloatingHandle.Left => FloatHandle.Left,
        DocumentFloatingHandle.Right => FloatHandle.Right,
        DocumentFloatingHandle.BottomLeft => FloatHandle.BottomLeft,
        DocumentFloatingHandle.Bottom => FloatHandle.Bottom,
        DocumentFloatingHandle.BottomRight => FloatHandle.BottomRight,
        _ => FloatHandle.None,
    };

    /// <summary>
    /// Draws the selection outline (dashed blue rectangle) and 8 resize handles around
    /// the selected floating object's page-space bounding rect.
    /// </summary>
    private void DrawFloatingSelection(DrawingContext context, Rect rect, int blockIndex, int runIndex, string kind)
    {
        var (angle, flipH, flipV) = GetFloatRotation(blockIndex, runIndex, kind);
        DrawFloatingSelection(context, rect, angle, flipH, flipV);
        DrawShapeEditPointHandles(context, rect, blockIndex, runIndex);
    }

    private static void DrawFloatingSelection(
        DrawingContext context, Rect rect, double angle, bool flipH, bool flipV)
    {
        context.DrawRectangle(null, FloatSelectionPen, rect);

        foreach (var (_, hRect) in HandleRects(rect, angle, flipH, flipV))
        {
            context.FillRectangle(FloatHandleFill, hRect);
            context.DrawRectangle(null, FloatHandlePen, hRect);
        }
    }

    private static readonly IBrush ShapeEditPointFill =
        new SolidColorBrush(Color.FromRgb(0xFF, 0xF2, 0xB2));
    private static readonly Pen ShapeEditPointPen =
        new Pen(new SolidColorBrush(Color.FromRgb(0x00, 0x78, 0xD4)), 1.0);
    private const double ShapeEditPointSize = 9;

    private bool IsCurrentShapeEditPointsTarget(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath = null) =>
        _shapeEditPointsTarget is { } target
        && target.BlockIndex == blockIndex
        && target.RunIndex == runIndex
        && (childPath is null
            ? target.ChildPath is null
            : target.ChildPath is not null && target.ChildPath.SequenceEqual(childPath))
        && TryGetShapeEditPointModel(blockIndex, runIndex, childPath, out var shape)
        && shape.HasCustomGeometry;

    private bool TryGetShapeEditPointModel(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath,
        out Shape shape)
    {
        shape = null!;
        if (!TryGetRun(blockIndex, runIndex, out var run))
            return false;

        if (childPath is null)
        {
            shape = run.Shape!;
            return run.Shape is not null;
        }

        if (run.DrawingGroup is { } root
            && DrawingGroupChildPathResolver.TryGetChild(root, childPath, out _, out var child)
            && child is Shape candidate)
        {
            shape = candidate;
            return true;
        }

        return false;
    }

    private bool TryGetShapeEditPointSurface(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath,
        out Shape shape,
        out Rect rect,
        out double rotationAngle,
        out bool flipH,
        out bool flipV,
        out IReadOnlyList<DocumentFloatTransform> parentTransforms)
    {
        shape = null!;
        rect = default;
        rotationAngle = 0;
        flipH = flipV = false;
        parentTransforms = [];
        if (!TryGetShapeEditPointModel(blockIndex, runIndex, childPath, out shape))
            return false;

        if (childPath is null)
        {
            if (_selectedFloating is not { Kind: "Shape" } selected
                || selected.BlockIndex != blockIndex || selected.RunIndex != runIndex)
                return false;
            rect = selected.Rect;
            rotationAngle = shape.RotationAngle;
            flipH = shape.FlipH;
            flipV = shape.FlipV;
            return true;
        }

        if (_selectedFloatingGroupChild is not { } selectedChild
            || selectedChild.BlockIndex != blockIndex
            || selectedChild.RunIndex != runIndex
            || !selectedChild.ChildPath.SequenceEqual(childPath)
            || !TryGetFloatingGroupChildGeometry(blockIndex, runIndex, childPath, out var geometry))
            return false;

        rect = geometry.Child.Rect;
        rotationAngle = geometry.Child.RotationAngle;
        flipH = geometry.Child.FlipH;
        flipV = geometry.Child.FlipV;
        parentTransforms = geometry.ParentTransforms;
        return true;
    }

    private static Point ShapePointToPage(
        Rect rect,
        CustomGeometry geometry,
        CustomPoint point,
        double rotationAngle,
        bool flipH,
        bool flipV,
        IReadOnlyList<DocumentFloatTransform> parentTransforms)
    {
        var local = new DocumentFloatPoint(
            rect.X + point.X / (double)geometry.Width * rect.Width,
            rect.Y + point.Y / (double)geometry.Height * rect.Height);
        var transformed = DocumentViewLayoutPlanner.TransformPointThroughGroupChain(
            local,
            ToPlannerRect(rect),
            rotationAngle,
            flipH,
            flipV,
            parentTransforms);
        return new Point(transformed.XDip, transformed.YDip);
    }

    private IEnumerable<(int SegmentIndex, Rect Rect)> ShapeEditPointRects(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath)
    {
        if (!IsCurrentShapeEditPointsTarget(blockIndex, runIndex, childPath)
            || !TryGetShapeEditPointSurface(
                blockIndex, runIndex, childPath,
                out _, out var rect, out var rotationAngle, out var flipH, out var flipV,
                out var parentTransforms)
            || !TryGetShapeEditPointModel(blockIndex, runIndex, childPath, out var shape)
            || shape.CustomGeometry is not { } geometry)
            yield break;

        var half = ShapeEditPointSize / 2;
        for (var index = 0; index < geometry.Segments.Count; index++)
        {
            if (geometry.Segments[index].Point is not { } point)
                continue;
            var center = ShapePointToPage(
                rect, geometry, point, rotationAngle, flipH, flipV, parentTransforms);
            yield return (index, new Rect(center.X - half, center.Y - half, ShapeEditPointSize, ShapeEditPointSize));
        }
    }

    private void DrawShapeEditPointHandles(
        DrawingContext context,
        Rect rect,
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath = null)
    {
        if (!IsCurrentShapeEditPointsTarget(blockIndex, runIndex, childPath))
            return;
        foreach (var (_, handleRect) in ShapeEditPointRects(blockIndex, runIndex, childPath))
        {
            context.FillRectangle(ShapeEditPointFill, handleRect);
            context.DrawRectangle(null, ShapeEditPointPen, handleRect);
        }
    }

    /// <summary>Returns the active freeform vertex handles for headless tests and host automation.</summary>
    public IReadOnlyDictionary<int, Rect> ShapeEditPointRectsForSelection()
    {
        var result = new Dictionary<int, Rect>();
        int blockIndex;
        int runIndex;
        IReadOnlyList<int>? childPath;
        if (_selectedFloatingGroupChild is { Kind: "Shape" } child)
        {
            blockIndex = child.BlockIndex;
            runIndex = child.RunIndex;
            childPath = child.ChildPath;
        }
        else if (_selectedFloating is { Kind: "Shape" } direct)
        {
            blockIndex = direct.BlockIndex;
            runIndex = direct.RunIndex;
            childPath = null;
        }
        else
        {
            return result;
        }

        foreach (var (index, rect) in ShapeEditPointRects(blockIndex, runIndex, childPath))
            result[index] = rect;
        return result;
    }

    public int ActiveShapeEditPointHandleCount => ShapeEditPointRectsForSelection().Count;

    private int HitTestShapeEditPoint(Point point)
    {
        if (_shapeEditPointsTarget is not { } target)
            return -1;
        foreach (var (index, rect) in ShapeEditPointRects(
                     target.BlockIndex, target.RunIndex, target.ChildPath))
        {
            if (rect.Inflate(3).Contains(point))
                return index;
        }
        return -1;
    }

    private bool TryPointToCustomCoordinate(Point pagePoint, out long x, out long y)
    {
        x = y = 0;
        if (_shapeEditPointsTarget is not { } target
            || !TryGetShapeEditPointSurface(
                target.BlockIndex, target.RunIndex, target.ChildPath,
                out var shape, out var rect, out var rotationAngle,
                out var flipH, out var flipV, out var parentTransforms)
            || !shape.HasCustomGeometry
            || !IsCurrentShapeEditPointsTarget(
                target.BlockIndex, target.RunIndex, target.ChildPath)
            || shape.CustomGeometry is not { } geometry)
            return false;

        var local = DocumentViewLayoutPlanner.UnTransformPointThroughGroupChain(
            ToPlannerPoint(pagePoint),
            ToPlannerRect(rect),
            rotationAngle,
            flipH,
            flipV,
            parentTransforms);

        x = Math.Clamp((long)Math.Round((local.XDip - rect.X) / rect.Width * geometry.Width), 0, geometry.Width);
        y = Math.Clamp((long)Math.Round((local.YDip - rect.Y) / rect.Height * geometry.Height), 0, geometry.Height);
        return true;
    }

    /// <summary>Converts the selected shape to editable freeform geometry through the shared undo bus.</summary>
    public void ConvertSelectedShapeToFreeform()
    {
        if (SelectedFloatingShapeLocation() is not { } selected)
            return;
        InvalidateObjectEdit(
            ObjectEdits.ConvertShapeToFreeform(ObjectTarget(selected.BlockIndex, selected.RunIndex)),
            selected.Kind);
    }

    /// <summary>Enters WPF-compatible vertex editing for the selected shape.</summary>
    public void BeginShapeEditPoints()
    {
        if (_selectedFloatingGroupChild is { Kind: "Shape" } selectedChild
            && TryGetRun(selectedChild.BlockIndex, selectedChild.RunIndex, out var groupRun)
            && groupRun.DrawingGroup is { } rootGroup
            && DrawingGroupChildPathResolver.TryGetChild(
                rootGroup, selectedChild.ChildPath, out _, out var nestedChild)
            && nestedChild is Shape nestedShape)
        {
            if (!nestedShape.HasCustomGeometry)
                ObjectEdits.ConvertShapeToFreeform(ObjectTarget(
                    selectedChild.BlockIndex,
                    selectedChild.RunIndex,
                    selectedChild.ChildPath));

            if (nestedShape.HasCustomGeometry)
            {
                _shapeEditPointsTarget = (
                    selectedChild.BlockIndex,
                    selectedChild.RunIndex,
                    selectedChild.ChildPath.ToArray());
                InvalidateVisual();
            }
            return;
        }

        if (SelectedFloatingShapeLocation() is not { } selected)
            return;
        if (!selected.Shape.HasCustomGeometry)
            ConvertSelectedShapeToFreeform();
        if (selected.Shape.HasCustomGeometry)
        {
            _shapeEditPointsTarget = (selected.BlockIndex, selected.RunIndex, null);
            InvalidateVisual();
        }
    }

    /// <summary>Moves one active vertex through the shared undoable model command.</summary>
    public bool MoveActiveShapeEditPoint(int segmentIndex, long x, long y)
    {
        if (_shapeEditPointsTarget is not { } target
            || !TryGetShapeEditPointModel(
                target.BlockIndex, target.RunIndex, target.ChildPath, out var shape)
            || !IsCurrentShapeEditPointsTarget(
                target.BlockIndex, target.RunIndex, target.ChildPath)
            || shape.CustomGeometry is not { } geometry
            || segmentIndex < 0 || segmentIndex >= geometry.Segments.Count
            || geometry.Segments[segmentIndex].Point is null)
            return false;

        var result = ObjectEdits.MoveShapeEditPoint(
            ObjectTarget(target.BlockIndex, target.RunIndex, target.ChildPath),
            segmentIndex,
            x,
            y);
        if (!result.Applied)
            return false;
        if (_shapeEditPointDragState is not null)
            _shapeEditPointDragChanged = true;
        InvalidateLayoutAndVisual();
        if (target.ChildPath is not null)
            RefreshSelectedFloatingGroupChildRect(target.BlockIndex, target.RunIndex);
        else if (_selectedFloating is { } selected)
            RefreshSelectedFloatingRect(selected.BlockIndex, selected.RunIndex, selected.Kind);
        return true;
    }

    private void BeginShapeEditPointDrag(int segmentIndex, IPointer? pointer)
    {
        _shapeEditPointDragState = (segmentIndex, pointer);
        _shapeEditPointDragChanged = false;
        _shapeEditPointDragOwnsUndoGroup = !_bus.IsUndoGroupOpen;
        if (_shapeEditPointDragOwnsUndoGroup)
            _bus.BeginUndoGroup();
        pointer?.Capture(this);
    }

    private void FinishShapeEditPointDrag(bool releasePointerCapture)
    {
        if (_shapeEditPointDragState is null)
            return;

        var pointer = _shapeEditPointDragState.Value.Pointer;
        _shapeEditPointDragState = null;
        var changed = _shapeEditPointDragChanged;
        _shapeEditPointDragChanged = false;
        var ownsUndoGroup = _shapeEditPointDragOwnsUndoGroup;
        _shapeEditPointDragOwnsUndoGroup = false;
        if (ownsUndoGroup && _bus.IsUndoGroupOpen)
        {
            if (changed)
                _bus.CommitUndoGroup("Move Shape Edit Point");
            else
                _bus.AbortUndoGroup();
        }

        // Clear state before releasing capture. Avalonia may synchronously raise capture-lost,
        // and that callback must not commit or undo this drag a second time.
        if (releasePointerCapture)
            pointer?.Capture(null);
    }

    private void CancelShapeEditPointDrag()
    {
        if (_shapeEditPointDragState is null)
            return;

        var pointer = _shapeEditPointDragState.Value.Pointer;
        _shapeEditPointDragState = null;
        var changed = _shapeEditPointDragChanged;
        _shapeEditPointDragChanged = false;
        var ownsUndoGroup = _shapeEditPointDragOwnsUndoGroup;
        _shapeEditPointDragOwnsUndoGroup = false;
        if (ownsUndoGroup && _bus.IsUndoGroupOpen)
        {
            if (changed)
            {
                _bus.CommitUndoGroup("Move Shape Edit Point");
                Undo();
            }
            else
                _bus.AbortUndoGroup();
        }

        InvalidateLayoutAndVisual();
        if (_selectedFloating is { } selected)
            RefreshSelectedFloatingRect(selected.BlockIndex, selected.RunIndex, selected.Kind);
        // State is already cleared, so capture loss cannot re-enter this cancellation path.
        pointer?.Capture(null);
    }

    /// <summary>Test seam for exercising the real point-drag undo lifecycle without synthesizing a pointer.</summary>
    internal bool BeginShapeEditPointDragForTest(int segmentIndex, IPointer? pointer = null)
    {
        if (_shapeEditPointsTarget is null || !ShapeEditPointRectsForSelection().ContainsKey(segmentIndex))
            return false;
        BeginShapeEditPointDrag(segmentIndex, pointer);
        return true;
    }

    /// <summary>Test seam for exercising the real page-to-custom-coordinate conversion path.</summary>
    internal bool MoveActiveShapeEditPointFromPageForTest(int segmentIndex, Point pagePoint)
    {
        return TryPointToCustomCoordinate(pagePoint, out var x, out var y)
            && MoveActiveShapeEditPoint(segmentIndex, x, y);
    }

    internal bool IsShapeEditPointUndoGroupOpenForTest => _bus.IsUndoGroupOpen;

    // ── AV-HANDLES: handle geometry, hit-test, cursors, resize-drag commit ──────────────────────────

    // Minimum floating-object size in points (Word clamps tiny drags so the object never collapses).
    private const double MinFloatSizePt = 9; // ~0.125in

    /// <summary>
    /// Returns the eight resize-handle squares (corners + edge midpoints) for a selection
    /// <paramref name="rect"/>, each tagged with the <see cref="FloatHandle"/> it represents. When
    /// <paramref name="rotationAngle"/>/<paramref name="flipH"/>/<paramref name="flipV"/> are set, the
    /// drawn handle positions are carried through the same transform DrawFloatingShape renders with, so
    /// they track the VISIBLE rotated/flipped corners instead of the plain axis-aligned box. Shared by
    /// the renderer and the pointer hit-test so the drawn squares and the clickable targets never drift
    /// apart.
    /// </summary>
    private static IEnumerable<(FloatHandle Handle, Rect Rect)> HandleRects(
        Rect rect, double rotationAngle = 0, bool flipH = false, bool flipV = false)
    {
        foreach (var handle in DocumentViewLayoutPlanner.BuildFloatingHandleRects(
                     ToPlannerRect(rect),
                     FloatHandleSize,
                     rotationAngle,
                     flipH,
                     flipV))
            yield return (FromPlannerHandle(handle.Handle), ToAvaloniaRect(handle.Rect));
    }

    /// <summary>
    /// AV-HANDLES test seam: the eight resize-handle rects for the CURRENT floating selection,
    /// keyed by <see cref="FloatHandle"/>. Empty when nothing is selected. Lets tests assert that
    /// selecting a float exposes exactly eight handles in the expected geometry.
    /// </summary>
    public IReadOnlyDictionary<FloatHandle, Rect> HandleRectsForSelection()
    {
        var dict = new Dictionary<FloatHandle, Rect>();
        if (_selectedFloatingGroupChild is { } child
            && TryGetFloatingGroupChildGeometry(
                child.BlockIndex,
                child.RunIndex,
                child.ChildPath,
                out var geometry))
        {
            foreach (var handle in DocumentViewLayoutPlanner.BuildFloatingGroupChildHandleRectsThroughGroupChain(
                         ToPlannerRect(geometry.Child.Rect),
                         FloatHandleSize,
                         geometry.Child.RotationAngle,
                         geometry.Child.FlipH,
                         geometry.Child.FlipV,
                         geometry.ParentTransforms))
                dict[FromPlannerHandle(handle.Handle)] = ToAvaloniaRect(handle.Rect);
            return dict;
        }

        if (_selectedFloating is { } sel)
        {
            var (angle, flipH, flipV) = GetFloatRotation(sel.BlockIndex, sel.RunIndex, sel.Kind);
            foreach (var (h, r) in HandleRects(sel.Rect, angle, flipH, flipV))
                dict[h] = r;
        }
        return dict;
    }

    /// <summary>
    /// Hit-tests <paramref name="point"/> against the current selection's handles + body. A handle
    /// hit (within the handle square, padded slightly for easier grabbing) wins; otherwise a point
    /// inside the selection rect is <see cref="FloatHandle.Body"/>; anything else is
    /// <see cref="FloatHandle.None"/>. No selection → <see cref="FloatHandle.None"/>. Accounts for the
    /// selected object's rotation/flip so a click on the visible (rotated/flipped) handle or body
    /// resolves correctly — see <see cref="DocumentViewLayoutPlanner.HitTestFloatingHandle"/>.
    /// </summary>
    private FloatHandle HitTestHandle(Point point)
    {
        if (_selectedFloatingGroupChild is { } child
            && TryGetFloatingGroupChildGeometry(
                child.BlockIndex,
                child.RunIndex,
                child.ChildPath,
                out var geometry))
        {
            var resolved = FromPlannerHandle(DocumentViewLayoutPlanner.HitTestFloatingGroupChildHandleThroughGroupChain(
                ToPlannerRect(geometry.Child.Rect),
                ToPlannerPoint(point),
                FloatHandleSize,
                hitPaddingDip: 2,
                geometry.Child.RotationAngle,
                geometry.Child.FlipH,
                geometry.Child.FlipV,
                geometry.ParentTransforms));
            return resolved;
        }

        if (_selectedFloating is not { } sel) return FloatHandle.None;
        var (angle, flipH, flipV) = GetFloatRotation(sel.BlockIndex, sel.RunIndex, sel.Kind);
        return FromPlannerHandle(DocumentViewLayoutPlanner.HitTestFloatingHandle(
            ToPlannerRect(sel.Rect),
            ToPlannerPoint(point),
            FloatHandleSize,
            hitPaddingDip: 2,
            angle,
            flipH,
            flipV));
    }

    /// <summary>The mouse cursor appropriate for hovering a given handle (or moving the body).</summary>
    private static Cursor CursorForHandle(FloatHandle handle) => handle switch
    {
        FloatHandle.TopLeft or FloatHandle.BottomRight => new Cursor(StandardCursorType.TopLeftCorner),
        FloatHandle.TopRight or FloatHandle.BottomLeft => new Cursor(StandardCursorType.TopRightCorner),
        FloatHandle.Left or FloatHandle.Right          => new Cursor(StandardCursorType.SizeWestEast),
        FloatHandle.Top or FloatHandle.Bottom          => new Cursor(StandardCursorType.SizeNorthSouth),
        FloatHandle.Body                               => new Cursor(StandardCursorType.SizeAll),
        _                                              => Cursor.Default,
    };

    /// <summary>
    /// Commits a handle-resize: converts the dragged page-space <paramref name="newRect"/> to model
    /// width/height (and a position delta when the anchored edge actually moved) and issues the
    /// undoable command(s). When only the size changed, a single <see cref="SetFloatingSizeCommand"/>
    /// (or image-size command) is pushed; when the top/left edge moved too, the size + position commands
    /// are wrapped in one <see cref="CompositeDocumentCommand"/> so a single undo reverts the whole drag.
    /// </summary>
    private void CommitFloatResize(int blockIndex, int runIndex, string kind, Rect baseRect, Rect newRect)
    {
        var newWidthPt  = newRect.Width  / PxPerPoint;
        var newHeightPt = newRect.Height / PxPerPoint;
        // Offset delta in points: how far the top-left corner moved (non-zero only for top/left handles).
        var dxPt = (newRect.Left - baseRect.Left) / PxPerPoint;
        var dyPt = (newRect.Top  - baseRect.Top)  / PxPerPoint;
        var result = ObjectEdits.ResizeAndMove(
            ObjectTarget(blockIndex, runIndex),
            newWidthPt,
            newHeightPt,
            dxPt,
            dyPt);

        if (!result.Applied)
        {
            return;
        }

        InvalidateLayoutAndVisual();
        Relayout(_laidOutWidth > 0 ? _laidOutWidth : FallbackWidth);
        RefreshSelectedFloatingRect(blockIndex, runIndex, kind);
    }

    // ── AV-HANDLES: pointer-driven drag test seams ──────────────────────────────────────────────────

    /// <summary>
    /// Test seam: begin a drag on the current floating selection at page-space <paramref name="start"/>.
    /// The handle under that point decides whether the drag moves or resizes the object. Returns the
    /// resolved handle (<see cref="FloatHandle.None"/> if the point is off the selection, in which case
    /// no drag starts). Mirrors what <see cref="OnPointerPressed"/> does for a real press.
    /// </summary>
    public FloatHandle BeginFloatDrag(Point start)
    {
        if (_selectedFloating is not { } sel) return FloatHandle.None;
        var handle = HitTestHandle(start);
        if (handle == FloatHandle.None) return FloatHandle.None;
        BeginFloatingDrag(start, SelectedFloatingDragRect(sel), handle);
        return handle;
    }

    internal Rect? FloatDragBaseRectForTest => _floatingDrag.BaseRect is { } rect
        ? ToAvaloniaRect(rect)
        : null;

    private Rect SelectedFloatingDragRect(
        (int BlockIndex, int RunIndex, string Kind, Rect Rect) selection)
    {
        if (_selectedFloatingGroupChild is { } child
            && child.BlockIndex == selection.BlockIndex
            && child.RunIndex == selection.RunIndex
            && TryGetFloatingGroupChildGeometry(
                child.BlockIndex,
                child.RunIndex,
                child.ChildPath,
                out var geometry))
            return geometry.Child.Rect;

        return selection.Rect;
    }

    private void BeginFloatingDrag(Point pointerDown, Rect baseRect, FloatHandle handle)
    {
        if (_selectedFloatingGroupChild is { } child
            && TryGetFloatingGroupChildGeometry(
                child.BlockIndex,
                child.RunIndex,
                child.ChildPath,
                out var geometry))
        {
            _floatingDrag.Begin(
                ToPlannerPoint(pointerDown),
                ToPlannerRect(baseRect),
                ToPlannerHandle(handle),
                geometry.Child.RotationAngle,
                geometry.Child.FlipH,
                geometry.Child.FlipV,
                geometry.ParentTransforms);
            return;
        }

        var (angle, flipH, flipV) = _selectedFloating is { } selected
            ? GetFloatRotation(selected.BlockIndex, selected.RunIndex, selected.Kind)
            : default;
        _floatingDrag.Begin(
            ToPlannerPoint(pointerDown),
            ToPlannerRect(baseRect),
            ToPlannerHandle(handle),
            angle,
            flipH,
            flipV);
    }

    /// <summary>
    /// Test seam: drive an in-flight drag (started via <see cref="BeginFloatDrag"/>) to page-space
    /// <paramref name="to"/>, optionally holding <paramref name="shift"/> for aspect-locked corner
    /// resizing. Updates the transient selection rect exactly as live pointer movement would. No-op
    /// when no drag is active.
    /// </summary>
    public void SimulateDragTo(Point to, bool shift = false)
    {
        UpdateFloatDrag(to, shift);
    }

    /// <summary>
    /// Test seam: release an in-flight drag at page-space <paramref name="to"/>, committing the move or
    /// resize through the undoable command bus (a single undo reverts it). No-op when no drag is active.
    /// </summary>
    public void EndFloatDrag(Point to, bool shift = false)
    {
        CommitFloatDrag(to, shift);
    }

    /// <summary>
    /// Test seam: cancel an in-flight drag, reverting the transient rect to the drag-start geometry
    /// without touching the model — exactly what pressing Esc mid-drag does.
    /// </summary>
    public bool CancelFloatDrag()
    {
        if (!_floatingDrag.Cancel(out var baseRect) || _selectedFloating is not { } sel)
            return false;
        if (_selectedFloatingGroupChild is { } child
            && child.BlockIndex == sel.BlockIndex
            && child.RunIndex == sel.RunIndex)
            _selectedFloatingGroupChild = child with { Rect = ToAvaloniaRect(baseRect) };
        else
            _selectedFloating = sel with { Rect = ToAvaloniaRect(baseRect) };
        InvalidateVisual();
        return true;
    }

    /// <summary>
    /// Updates the transient selection rect for an in-flight drag (move or resize). Shared by the live
    /// pointer handler and the <see cref="SimulateDragTo"/> test seam.
    /// </summary>
    private void UpdateFloatDrag(Point point, bool shift)
    {
        if (_selectedFloating is not { } sel
            || _floatingDrag.Update(
                ToPlannerPoint(point),
                shift,
                MinFloatSizePt * PxPerPoint) is not { } update)
            return;

        var newRect = ToAvaloniaRect(update.Rect);
        if (_selectedFloatingGroupChild is { } selectedChild
            && selectedChild.BlockIndex == sel.BlockIndex
            && selectedChild.RunIndex == sel.RunIndex)
        {
            _selectedFloatingGroupChild = selectedChild with { Rect = newRect };
            _selectedFloating = sel;
        }
        else
        {
            _selectedFloating = sel with { Rect = newRect };
        }
        InvalidateVisual();
    }

    /// <summary>
    /// Commits an in-flight drag at the release point: a move routes to
    /// <see cref="CommitFloatDragMove"/>; a resize routes to <see cref="CommitFloatResize"/>. Below a
    /// 1px threshold the drag is treated as a plain click (no model change). Clears the drag state.
    /// </summary>
    private void CommitFloatDrag(Point releasePoint, bool shift)
    {
        if (_selectedFloating is not { } sel)
        {
            _floatingDrag.Reset();
            return;
        }

        var commit = _floatingDrag.Complete(
            ToPlannerPoint(releasePoint),
            shift,
            MinFloatSizePt * PxPerPoint,
            minimumMoveDip: PxPerPoint,
            minimumResizeChangeDip: 1);
        if (commit is not { HasModelChange: true })
            return;

        if (commit.IsGroupChild
            && _selectedFloatingGroupChild is { } child
            && child.BlockIndex == sel.BlockIndex
            && child.RunIndex == sel.RunIndex)
        {
            if (commit.IsMove)
                CommitFloatingGroupChildMove(
                    sel.BlockIndex,
                    sel.RunIndex,
                    child.ChildPath,
                    commit.DeltaXDip / PxPerPoint,
                    commit.DeltaYDip / PxPerPoint);
            else
                CommitFloatingGroupChildResize(
                    sel.BlockIndex,
                    sel.RunIndex,
                    child.ChildPath,
                    commit.BaseRect,
                    commit.Rect);
        }
        else if (commit.IsMove)
        {
            CommitFloatDragMove(
                sel.BlockIndex,
                sel.RunIndex,
                commit.DeltaXDip / PxPerPoint,
                commit.DeltaYDip / PxPerPoint,
                sel.Kind);
        }
        else
        {
            CommitFloatResize(
                sel.BlockIndex,
                sel.RunIndex,
                sel.Kind,
                ToAvaloniaRect(commit.BaseRect),
                ToAvaloniaRect(commit.Rect));
        }
    }

    /// <summary>
    /// Draws the AV-COMMENT anchor decorations over the laid-out text: an amber underline beneath every
    /// commented glyph (the in-text anchor mark), and one minimal marker in the right margin per
    /// (comment, line) — a small balloon bracket plus the author's initial — aligned to that line. The
    /// margin marker only renders when there is room to the right of the content column (PrintLayout has
    /// a page margin there); otherwise the in-text underline alone marks the anchor. Resolved threads draw
    /// muted/grey to mirror Word's de-emphasised resolved state.
    /// </summary>
    private void DrawCommentAnchors(DrawingContext context)
    {
        var anchors = CommentAnchorGlyphSnapshot(highlightedOnly: true);
        if (anchors.Count == 0)
            return;

        // Track, per (comment id, line top Y), whether we've already drawn a margin marker for that line
        // (one marker per anchor line, not one per glyph).
        var markedLines = new HashSet<(int Id, long Y)>();

        foreach (var (id, rect) in anchors)
        {
            var resolved = IsCommentResolved(id);

            // In-text anchor mark: amber underline just below the glyph baseline band.
            var underlineY = rect.Y + rect.Height * 0.90;
            var pen = resolved ? ResolvedCommentUnderlinePen : CommentUnderlinePen;
            context.DrawLine(pen, new Point(rect.X, underlineY), new Point(rect.Right, underlineY));

            // Right-margin marker: one per anchor line.
            var pageIndex = RenderedPageIndexForPoint(rect.X, rect.Y);
            var pageLeft = _surfacePlan.RenderedPageLeftDip(pageIndex);
            var pageRight = pageLeft + _pageWidth;
            var contentRight = pageLeft + (_contentLeft - _pageLeft) + _contentWidth;
            var marginX = contentRight + 6;
            var hasMargin = pageRight - contentRight > 14;
            if (!hasMargin)
                continue;
            var lineKey = (id, (long)Math.Round(rect.Y));
            if (!markedLines.Add(lineKey))
                continue;

            DrawCommentMarginMarker(context, marginX, rect.Y, rect.Height, id, resolved);
        }
    }

    private void DrawSimpleMarkupChangeBars(DrawingContext context)
    {
        foreach (var (_, rect) in SimpleMarkupChangeBarSnapshot())
        {
            var x = rect.X + rect.Width / 2;
            context.DrawLine(SimpleMarkupChangeBarPen, new Point(x, rect.Y), new Point(x, rect.Bottom));
        }
    }

    /// <summary>
    /// Draws a single minimal comment marker in the right margin aligned to an anchor line: a small
    /// rounded balloon filled in the comment colour, with the author's initial drawn inside it.
    /// </summary>
    private void DrawCommentMarginMarker(DrawingContext context, double x, double lineY, double lineHeight, int id, bool resolved)
    {
        const double size = 14;
        var top = lineY + Math.Max(0, (lineHeight - size) / 2);
        var balloon = new Rect(x, top, size, size);
        var fill = resolved ? ResolvedCommentMarkerBrush : CommentMarkerBrush;
        context.DrawRectangle(fill, null, new RoundedRect(balloon, 3));

        var initial = CommentInitial(id);
        if (string.IsNullOrEmpty(initial))
            return;
        var ft = Build(initial, new RunFormatting { FontSizePt = 8, ColorHex = "#FFFFFF", Bold = true });
        context.DrawText(ft, new Point(x + (size - ft.Width) / 2, top + (size - ft.Height) / 2));
    }

    /// <summary>True when the top-level comment thread anchoring <paramref name="commentId"/> is resolved.</summary>
    private bool IsCommentResolved(int commentId)
    {
        var topId = _editingSession.Review.ResolveTopLevelCommentId(commentId);
        return _doc.Comments.TryGetValue(topId, out var comment) && comment.Resolved;
    }

    /// <summary>The author's initial (or 'C') for the comment thread anchoring <paramref name="commentId"/>.</summary>
    private string CommentInitial(int commentId)
    {
        var topId = _editingSession.Review.ResolveTopLevelCommentId(commentId);
        if (!_doc.Comments.TryGetValue(topId, out var comment))
            return string.Empty;
        return CommentInitialsPolicy.ResolveBadge(comment.Initials, comment.Author);
    }

    /// <summary>
    /// Hit-tests <paramref name="point"/> against all floating objects (images, shapes, charts,
    /// WordArts, SmartArts, groups). Returns the topmost (highest z-order; in-front preferred
    /// over behind-text) object that contains the point, or false if none.
    /// Requires at least one layout pass to have been completed.
    /// </summary>
    private bool TryHitTestFloat(Point point,
        out (int BlockIndex, int RunIndex, string Kind, Rect Rect) hit)
    {
        hit = default;
        if (_laidOutWidth < 0) Relayout(FallbackWidth);

        // Rotation/flip are carried on each snapshot (threaded from the model's Image/Shape
        // RotationAngle/FlipH/FlipV in BuildFloatingObjectSnapshots) and un-applied per-candidate
        // inside HitTestFloatingObject before the containment test, so a rotated/flipped float's visible
        // (not axis-aligned) bounds decide the hit and the z-order winner among overlapping floats.
        var winner = DocumentViewLayoutPlanner.HitTestFloatingObject(
            _floatingSnapshots,
            ToPlannerPoint(point));
        if (winner is null)
            return false;

        hit = (winner.BlockIndex, winner.RunIndex, winner.TypeTag, ToAvaloniaRect(winner.Rect));
        return true;
    }

    private sealed record FloatingGroupChildGeometry(
        FloatingGroupData OwnerGroup,
        FloatingGroupChildData Child,
        IReadOnlyList<DocumentFloatTransform> ParentTransforms);

    private static DocumentFloatTransform ToGroupTransform(FloatingGroupData group) =>
        new(
            ToPlannerRect(group.Rect),
            group.RotationAngle,
            group.FlipH,
            group.FlipV);

    private static bool TryFindFloatingGroupChildGeometry(
        FloatingGroupData group,
        IReadOnlyList<int> childPath,
        int depth,
        IReadOnlyList<DocumentFloatTransform> parentTransforms,
        out FloatingGroupChildGeometry geometry)
    {
        geometry = null!;
        if (depth < 0 || depth >= childPath.Count)
            return false;

        var child = group.Children.FirstOrDefault(
            candidate => candidate.ChildIndex == childPath[depth]);
        if (child is null)
            return false;

        if (depth == childPath.Count - 1)
        {
            geometry = new FloatingGroupChildGeometry(
                group,
                child,
                parentTransforms);
            return true;
        }

        return child.Group is not null
            && TryFindFloatingGroupChildGeometry(
                child.Group,
                childPath,
                depth + 1,
                new[] { ToGroupTransform(child.Group) }
                    .Concat(parentTransforms)
                    .ToArray(),
                out geometry);
    }

    private bool TryGetFloatingGroupChildGeometry(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int> childPath,
        out FloatingGroupChildGeometry geometry)
    {
        geometry = null!;
        return TryGetFloatingGroupData(blockIndex, runIndex, out var rootGroup)
            && TryFindFloatingGroupChildGeometry(
                rootGroup,
                childPath,
                0,
                new[] { ToGroupTransform(rootGroup) },
                out geometry);
    }

    private static bool TryHitNestedFloatingGroupChild(
        FloatingGroupData group,
        Point point,
        IReadOnlyList<DocumentFloatTransform> parentTransforms,
        IReadOnlyList<int> pathPrefix,
        out (IReadOnlyList<int> Path, FloatingGroupChildData Child) hit)
    {
        hit = default;
        foreach (var child in group.Children.AsEnumerable().Reverse())
        {
            var path = pathPrefix.Append(child.ChildIndex).ToArray();
            if (child.Group is not null)
            {
                var nestedTransforms = new[] { ToGroupTransform(child.Group) }
                    .Concat(parentTransforms)
                    .ToArray();
                if (TryHitNestedFloatingGroupChild(
                        child.Group,
                        point,
                        nestedTransforms,
                        path,
                        out hit))
                    return true;

                var nestedGroupRect = ToPlannerRect(child.Rect);
                if (DocumentViewLayoutPlanner.ContainsFloatingGroupChildPointThroughGroupChain(
                        nestedGroupRect,
                        ToPlannerPoint(point),
                        child.RotationAngle,
                        child.FlipH,
                        child.FlipV,
                        parentTransforms))
                {
                    hit = (path, child);
                    return true;
                }
                continue;
            }

            var childPlannerRect = ToPlannerRect(child.Rect);
            if (DocumentViewLayoutPlanner.ContainsFloatingGroupChildPointThroughGroupChain(
                    childPlannerRect,
                    ToPlannerPoint(point),
                    child.RotationAngle,
                    child.FlipH,
                    child.FlipV,
                    parentTransforms))
            {
                hit = (path, child);
                return true;
            }
        }

        return false;
    }

    private bool TryHitTestFloatingGroupChild(
        Point point,
        out FloatingGroupChildSelection hit)
    {
        hit = null!;

        foreach (var group in _floatingGroups
            .OrderBy(group => group.BehindText ? 1 : 0)
            .ThenByDescending(group => group.ZOrder)
            .ThenByDescending(group => group.BlockIndex)
            .ThenByDescending(group => group.RunIndex))
        {
            if (!TryHitNestedFloatingGroupChild(
                    group,
                    point,
                    new[] { ToGroupTransform(group) },
                    [],
                    out var nestedHit))
                continue;

            hit = new FloatingGroupChildSelection(
                group.BlockIndex,
                group.RunIndex,
                nestedHit.Path,
                nestedHit.Child.Kind.ToString(),
                nestedHit.Child.Rect);
            return true;
        }

        return false;
    }

    private static void DrawFloatingGroupChildSelection(
        DrawingContext context,
        Rect childRect,
        double childAngle,
        bool childFlipH,
        bool childFlipV,
        IReadOnlyList<DocumentFloatTransform> parentTransforms)
    {
        var childPlanRect = ToPlannerRect(childRect);
        var corners = new[]
        {
            new DocumentFloatPoint(childPlanRect.LeftDip, childPlanRect.TopDip),
            new DocumentFloatPoint(childPlanRect.RightDip, childPlanRect.TopDip),
            new DocumentFloatPoint(childPlanRect.RightDip, childPlanRect.BottomDip),
            new DocumentFloatPoint(childPlanRect.LeftDip, childPlanRect.BottomDip)
        }
        .Select(corner => DocumentViewLayoutPlanner.TransformPointThroughGroupChain(
            corner,
            childPlanRect,
            childAngle,
            childFlipH,
            childFlipV,
            parentTransforms))
        .Select(corner => new Point(corner.XDip, corner.YDip))
        .ToArray();

        for (var index = 0; index < corners.Length; index++)
            context.DrawLine(FloatSelectionPen, corners[index], corners[(index + 1) % corners.Length]);

        foreach (var handle in DocumentViewLayoutPlanner.BuildFloatingGroupChildHandleRectsThroughGroupChain(
                     childPlanRect,
                     FloatHandleSize,
                     childAngle,
                     childFlipH,
                     childFlipV,
                     parentTransforms))
        {
            var rect = ToAvaloniaRect(handle.Rect);
            context.FillRectangle(FloatHandleFill, rect);
            context.DrawRectangle(null, FloatHandlePen, rect);
        }
    }

    private static bool ContainsTransformedPoint(
        Point point, Rect rect, double angle, bool flipH, bool flipV) =>
        rect.Contains(UntransformPoint(point, rect, angle, flipH, flipV));

    private static Point UntransformPoint(
        Point point, Rect rect, double angle, bool flipH, bool flipV)
    {
        var local = DocumentViewLayoutPlanner.UnTransformPoint(
            ToPlannerPoint(point), ToPlannerRect(rect), angle, flipH, flipV);
        return new Point(local.XDip, local.YDip);
    }

    private (double Angle, bool FlipH, bool FlipV) GetFloatingGroupChildRotation(
        int blockIndex, int runIndex, int childIndex)
        => GetFloatingGroupChildRotation(blockIndex, runIndex, [childIndex]);

    private (double Angle, bool FlipH, bool FlipV) GetFloatingGroupChildRotation(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int> childPath)
    {
        if (!TryGetRun(blockIndex, runIndex, out var run)
            || run.DrawingGroup is not { } group
            || !DrawingGroupChildPathResolver.TryGetChild(
                group,
                childPath,
                out _,
                out var child))
            return (0, false, false);

        return child switch
        {
            InlineImage image => (image.RotationAngle, image.FlipH, image.FlipV),
            Shape shape => (shape.RotationAngle, shape.FlipH, shape.FlipV),
            Chart chart => (chart.RotationAngle, chart.FlipH, chart.FlipV),
            WordArt wordArt => (wordArt.RotationAngle, wordArt.FlipH, wordArt.FlipV),
            SmartArt smartArt => (smartArt.RotationAngle, smartArt.FlipH, smartArt.FlipV),
            FreeW.Core.Model.DrawingGroup nestedGroup =>
                (nestedGroup.RotationAngle, nestedGroup.FlipH, nestedGroup.FlipV),
            _ => (0, false, false)
        };
    }

    internal (int BlockIndex, int RunIndex, int ChildIndex, string Kind, Rect Rect)?
        HitTestFloatingGroupChildForTest(Point point) =>
        TryHitTestFloatingGroupChild(point, out var hit)
            ? (hit.BlockIndex, hit.RunIndex, hit.ChildIndex, hit.Kind, hit.Rect)
            : null;

    internal IReadOnlyList<int>? SelectedFloatingGroupChildPathForTest =>
        _selectedFloatingGroupChild?.ChildPath;

    internal IReadOnlyList<(int ChildIndex, Rect Rect)> FloatingGroupChildRectsForTest(
        int blockIndex, int runIndex) =>
        TryGetFloatingGroupData(blockIndex, runIndex, out var groupData)
            ? groupData.Children.Select(child => (child.ChildIndex, child.Rect)).ToArray()
            : [];

    internal Rect? FloatingGroupChildRectForPathForTest(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int> childPath) =>
        TryGetFloatingGroupChildGeometry(
            blockIndex,
            runIndex,
            childPath,
            out var geometry)
            ? geometry.Child.Rect
            : null;

    private void CommitFloatingGroupChildMove(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int> childPath,
        double dxPt,
        double dyPt)
    {
        var result = ObjectEdits.MoveGroupChildBy(
            ObjectTarget(blockIndex, runIndex, childPath),
            dxPt,
            dyPt);
        if (!result.Applied)
            return;
        InvalidateLayoutAndVisual();
        Relayout(_laidOutWidth > 0 ? _laidOutWidth : FallbackWidth);
        RefreshSelectedFloatingRect(blockIndex, runIndex, "Group");
    }

    private void CommitFloatingGroupChildResize(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int> childPath,
        DocumentFloatRect baseRect,
        DocumentFloatRect newRect)
    {
        var newWidthPt = newRect.WidthDip / PxPerPoint;
        var newHeightPt = newRect.HeightDip / PxPerPoint;
        var dxPt = (newRect.XDip - baseRect.XDip) / PxPerPoint;
        var dyPt = (newRect.YDip - baseRect.YDip) / PxPerPoint;
        var result = ObjectEdits.ResizeGroupChild(
            ObjectTarget(blockIndex, runIndex, childPath),
            newWidthPt,
            newHeightPt,
            dxPt,
            dyPt);
        if (!result.Applied)
            return;
        InvalidateLayoutAndVisual();
        Relayout(_laidOutWidth > 0 ? _laidOutWidth : FallbackWidth);
        RefreshSelectedFloatingRect(blockIndex, runIndex, "Group");
    }

    /// <summary>
    /// Commits a drag-move by computing the new HOffset/VOffset in points (delta from the layout-time
    /// position, converted back through PxPerPoint) and issuing the appropriate move command.
    /// For Images: uses <see cref="NudgeImagePositionCommand"/> (direct offset fields).
    /// For all others: uses <see cref="SetFloatingPositionCommand"/> (via FloatingPlacement).
    /// </summary>
    private void CommitFloatDragMove(int blockIndex, int runIndex, double dxPt, double dyPt, string kind)
    {
        if (_selectedFloatingGroupChild is { } child
            && child.BlockIndex == blockIndex
            && child.RunIndex == runIndex
            && TryGetFloatingGroupChildGeometry(
                blockIndex,
                runIndex,
                child.ChildPath,
                out var geometry))
        {
            var localDelta = DocumentViewLayoutPlanner.UnTransformVectorThroughGroupChain(
                new DocumentFloatPoint(dxPt * PxPerPoint, dyPt * PxPerPoint),
                geometry.ParentTransforms);
            CommitFloatingGroupChildMove(
                blockIndex,
                runIndex,
                child.ChildPath,
                localDelta.XDip / PxPerPoint,
                localDelta.YDip / PxPerPoint);
            return;
        }

        if (!ObjectEdits.MoveBy(ObjectTarget(blockIndex, runIndex), dxPt, dyPt).Applied)
            return;
        InvalidateLayoutAndVisual();
        // Refresh selected state after re-layout (the Rect changes).
        Relayout(_laidOutWidth > 0 ? _laidOutWidth : FallbackWidth);
        RefreshSelectedFloatingRect(blockIndex, runIndex, kind);
    }

    /// <summary>
    /// Arrow-key nudge: shifts the selected floating object by (dxPt, dyPt) points, routing through
    /// the appropriate undoable command. No-op if nothing is selected or the block/run is stale.
    /// </summary>
    private void NudgeSelectedFloating(double dxPt, double dyPt)
    {
        if (_selectedFloating is not { } sel) return;
        CommitFloatDragMove(sel.BlockIndex, sel.RunIndex, dxPt, dyPt, sel.Kind);
    }

    /// <summary>
    /// Rescans the floating lists after a layout pass to re-anchor <see cref="_selectedFloating"/>'s
    /// Rect to the newly computed page-space position.
    /// </summary>
    private void RefreshSelectedFloatingRect(int blockIndex, int runIndex, string kind)
    {
        var found = _floatingSnapshots.FirstOrDefault(snapshot =>
            snapshot.BlockIndex == blockIndex
            && snapshot.RunIndex == runIndex
            && snapshot.TypeTag == kind);
        if (found is not null)
            _selectedFloating = (blockIndex, runIndex, kind, ToAvaloniaRect(found.Rect));
        else
        {
            _selectedFloating = null; // object was deleted / moved out of view
            _selectedFloatingObjects.RemoveAll(item =>
                item.BlockIndex == blockIndex && item.RunIndex == runIndex);
        }
        RefreshSelectedFloatingGroupChildRect(blockIndex, runIndex);
        RaiseFloatingSelectionChangedIfIdentityChanged();
        InvalidateVisual();
    }

    private void RefreshSelectedFloatingGroupChildRect(int blockIndex, int runIndex)
    {
        if (_selectedFloatingGroupChild is not { } selected
            || selected.BlockIndex != blockIndex
            || selected.RunIndex != runIndex
            || !TryGetFloatingGroupChildGeometry(
                blockIndex,
                runIndex,
                selected.ChildPath,
                out var geometry))
        {
            return;
        }

        _selectedFloatingGroupChild = selected with
        {
            Kind = geometry.Child.Kind.ToString(),
            Rect = geometry.Child.Rect
        };
    }

    private bool TryGetFloatingGroupData(int blockIndex, int runIndex, out FloatingGroupData groupData)
    {
        groupData = null!;
        groupData = _floatingGroups.FirstOrDefault(group =>
            group.BlockIndex == blockIndex && group.RunIndex == runIndex)!;
        return groupData is not null;
    }

    // ── AV-FLSEL: public edit API ──────────────────────────────────────────────────────────────────

    /// <summary>
    /// Info about the currently selected floating object, or null if nothing is selected.
    /// Kind = "Image" | "Shape" | "Chart" | "WordArt" | "SmartArt" | "Group".
    /// Placement is the model's current FloatingPlacement (null for Image, which stores offsets inline).
    /// </summary>
    public (int BlockIndex, int RunIndex, string Kind, Rect Rect)? SelectedFloatingInfo
        => _selectedFloating;

    /// <summary>
    /// Direct child selected inside the active drawing group, or null when the group itself is active.
    /// The parent remains the active <see cref="SelectedFloatingInfo"/> so group-level arrange commands
    /// retain their existing behavior.
    /// </summary>
    public (int BlockIndex, int RunIndex, int ChildIndex, string Kind, Rect Rect)? SelectedFloatingGroupChildInfo
        => _selectedFloatingGroupChild is { } child
            ? (child.BlockIndex, child.RunIndex, child.ChildIndex, child.Kind, child.Rect)
            : null;

    /// <summary>Root-relative path of the selected group child, or null when no child is selected.</summary>
    public IReadOnlyList<int>? SelectedFloatingGroupChildPath =>
        _selectedFloatingGroupChild?.ChildPath;

    /// <summary>The currently selected floating image, or null when the active object is not an image.</summary>
    public InlineImage? SelectedFloatingImage()
    {
        if (_selectedFloating is not { Kind: "Image" } selected)
            return null;
        return TryGetRun(selected.BlockIndex, selected.RunIndex, out var run)
            ? run.Image
            : null;
    }

    /// <summary>The currently selected floating chart, or null when another object kind is active.</summary>
    public Chart? SelectedFloatingChart()
    {
        if (_selectedFloating is not { Kind: "Chart" } selected)
            return null;
        return TryGetRun(selected.BlockIndex, selected.RunIndex, out var run)
            ? run.Chart
            : null;
    }

    /// <summary>Current floating-object multi-selection as model coordinates.</summary>
    public IReadOnlyList<(int BlockIndex, int RunIndex, string Kind)> SelectedFloatingObjects =>
        _selectedFloatingObjects.AsReadOnly();

    /// <summary>True when the selection contains at least two groupable floating object runs.</summary>
    public bool HasMultipleFloatingObjectsSelected =>
        SelectedGroupMemberLocations().Count >= 2;

    /// <summary>True when exactly one valid drawing group run is selected.</summary>
    public bool IsGroupSelected =>
        _selectedFloatingObjects.Count == 1
        && _selectedFloatingObjects[0].Kind == "Group"
        && TryGetRun(_selectedFloatingObjects[0].BlockIndex, _selectedFloatingObjects[0].RunIndex, out var run)
        && run.DrawingGroup is { IsValid: true };

    /// <summary>
    /// Returns the selected floating shape or text box, or null when the current drawing selection is
    /// a non-shape object such as WordArt or a group.
    /// </summary>
    public Shape? SelectedFloatingShape()
    {
        if (_selectedFloatingGroupChild is { Kind: "Shape" } selectedChild
            && TryGetRun(selectedChild.BlockIndex, selectedChild.RunIndex, out var groupRun)
            && groupRun.DrawingGroup is { } rootGroup
            && DrawingGroupChildPathResolver.TryGetChild(
                rootGroup,
                selectedChild.ChildPath,
                out _,
                out var nestedChild)
            && nestedChild is Shape nestedShape)
            return nestedShape;

        return SelectedFloatingShapeLocation()?.Shape;
    }

    /// <summary>The currently selected floating WordArt, or null for another selection kind.</summary>
    public WordArt? SelectedFloatingWordArt()
    {
        if (_selectedFloating is not { Kind: "WordArt" } selected)
            return null;
        return TryGetRun(selected.BlockIndex, selected.RunIndex, out var run)
            ? run.WordArt
            : null;
    }

    /// <summary>True while keyboard input is editing the first text run of a selected text box.</summary>
    public bool IsShapeTextEditing => _shapeCaret is not null;

    /// <summary>Current selected text-box caret, or null when the object is not in text-edit mode.</summary>
    public (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset)? ShapeTextCaretInfo =>
        _shapeCaret;

    /// <summary>
    /// Enter the text-edit route for the selected floating text box. The caret starts at the end of
    /// its first text run; Enter and paragraph-start Backspace route through the shared shape-text
    /// paragraph commands so multiline text-box content remains editable and undoable.
    /// </summary>
    public bool EnterSelectedShapeTextEditing()
    {
        if (IsEditingLocked)
            return false;

        int blockIndex;
        int runIndex;
        Shape shape;
        IReadOnlyList<int>? childPath;
        if (_selectedFloatingGroupChild is { Kind: "Shape" } selectedChild
            && TryGetRun(selectedChild.BlockIndex, selectedChild.RunIndex, out var groupRun)
            && groupRun.DrawingGroup is { } rootGroup
            && DrawingGroupChildPathResolver.TryGetChild(
                rootGroup, selectedChild.ChildPath, out _, out var child)
            && child is Shape nestedShape)
        {
            blockIndex = selectedChild.BlockIndex;
            runIndex = selectedChild.RunIndex;
            shape = nestedShape;
            childPath = selectedChild.ChildPath;
        }
        else if (_selectedFloating is { Kind: "Shape" } selected
            && TryGetRun(selected.BlockIndex, selected.RunIndex, out var shapeRun)
            && shapeRun.Shape is { } directShape)
        {
            blockIndex = selected.BlockIndex;
            runIndex = selected.RunIndex;
            shape = directShape;
            childPath = null;
        }
        else
        {
            return false;
        }

        if (shape.TextParagraphs.Count == 0
            || !TryGetShapeTextRun(blockIndex, runIndex, 0, 0, out var run, childPath))
            return false;

        _activeShapeTextChildPath = childPath;

        _shapeCaret = (blockIndex, runIndex, 0, 0, run.Text.Length);
        _shapeSelectionAnchor = _shapeCaret;
        Focus();
        InvalidateVisual();
        CaretMoved?.Invoke();
        return true;
    }

    /// <summary>
    /// Resolves a pointer inside the active horizontal text box to the nearest visible caret stop.
    /// This mirrors the WPF RichTextBox pointer contract while keeping the existing floating-object
    /// selection and drag routes intact when the shape is not already being edited.
    /// </summary>
    private bool TryResolveShapeTextCaret(Point point,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) active,
        out (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) resolved)
    {
        resolved = default;
        IReadOnlyList<int>? activePath = _activeShapeTextChildPath;
        Point localPoint;
        if (activePath is { Count: > 0 })
        {
            if (!TryHitTestFloatingGroupChild(point, out var groupHit)
                || groupHit.BlockIndex != active.BlockIndex
                || groupHit.RunIndex != active.RunIndex
                || !groupHit.ChildPath.SequenceEqual(activePath)
                || !TryGetFloatingGroupChildGeometry(
                    active.BlockIndex, active.RunIndex, activePath, out var geometry))
                return false;

            var local = DocumentViewLayoutPlanner.UnTransformPointThroughGroupChain(
                ToPlannerPoint(point),
                ToPlannerRect(geometry.Child.Rect),
                geometry.Child.RotationAngle,
                geometry.Child.FlipH,
                geometry.Child.FlipV,
                geometry.ParentTransforms);
            localPoint = new Point(local.XDip, local.YDip);
        }
        else
        {
            if (!TryHitTestFloat(point, out var floatHit)
                || floatHit.BlockIndex != active.BlockIndex
                || floatHit.RunIndex != active.RunIndex
                || floatHit.Kind != "Shape")
                return false;
            localPoint = point;
        }

        var stops = _shapeTextCaretStops
            .Where(candidate => candidate.BlockIndex == active.BlockIndex
                && candidate.RunIndex == active.RunIndex
                && ((candidate.ChildPath is null && activePath is null)
                    || (candidate.ChildPath is not null
                        && activePath is not null
                        && candidate.ChildPath.SequenceEqual(activePath))))
            .ToArray();
        if (stops.Length == 0)
            return false;

        if (activePath is null)
        {
            var first = stops[0];
            localPoint = RotateAround(
                localPoint,
                new Point(first.RotationCenterX, first.RotationCenterY),
                -first.RotationRadians);
        }
        var stop = stops
            .OrderBy(candidate => VerticalDistance(localPoint.Y, candidate.Y, candidate.Height))
            .ThenBy(candidate => Math.Abs(localPoint.X - candidate.X))
            .First();

        resolved = (
            stop.BlockIndex,
            stop.RunIndex,
            stop.TextParagraphIndex,
            stop.TextRunIndex,
            stop.Offset);
        return true;
    }

    private bool TryPlaceShapeTextCaret(Point point,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) active)
    {
        if (!TryResolveShapeTextCaret(point, active, out var resolved))
            return false;

        _shapeCaret = resolved;
        _shapeSelectionAnchor = resolved;
        Focus();
        InvalidateVisual();
        CaretMoved?.Invoke();
        return true;
    }

    private bool BeginShapeTextSelectionDrag(
        Point point,
        bool extend,
        IPointer? pointer,
        out (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) resolved)
    {
        resolved = default;
        if (_shapeCaret is not { } active
            || !TryResolveShapeTextCaret(point, active, out resolved))
            return false;

        if (!extend || _shapeSelectionAnchor is null)
            _shapeSelectionAnchor = resolved;
        _shapeCaret = resolved;
        _shapeTextSelectionDragState = (point, pointer);
        pointer?.Capture(this);
        Focus();
        InvalidateVisual();
        CaretMoved?.Invoke();
        return true;
    }

    private void UpdateShapeTextSelectionDrag(Point point)
    {
        if (_shapeTextSelectionDragState is null || _shapeCaret is not { } active
            || !TryResolveShapeTextCaret(point, active, out var resolved))
            return;

        _shapeCaret = resolved;
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    private void FinishShapeTextSelectionDrag(bool releasePointerCapture)
    {
        if (_shapeTextSelectionDragState is not { } drag)
            return;

        _shapeTextSelectionDragState = null;
        if (releasePointerCapture)
            drag.Pointer?.Capture(null);
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    private static double VerticalDistance(double pointY, double lineY, double lineHeight) =>
        pointY < lineY
            ? lineY - pointY
            : pointY > lineY + lineHeight
                ? pointY - (lineY + lineHeight)
                : 0;

    private static Point RotateAround(Point point, Point center, double radians)
    {
        var cos = Math.Cos(radians);
        var sin = Math.Sin(radians);
        var dx = point.X - center.X;
        var dy = point.Y - center.Y;
        return new Point(
            center.X + dx * cos - dy * sin,
            center.Y + dx * sin + dy * cos);
    }

    /// <summary>Test hook for the pointer-to-shape-caret parity path.</summary>
    internal bool PlaceShapeTextCaretForTest(Point point) =>
        _shapeCaret is { } active && TryPlaceShapeTextCaret(point, active);

    /// <summary>Test seam for the real pointer drag-selection path inside the active text box.</summary>
    internal bool BeginShapeTextSelectionForTest(Point point)
    {
        return BeginShapeTextSelectionDrag(point, extend: false, pointer: null, out _);
    }

    /// <summary>Test seam for moving the active shape-text selection endpoint.</summary>
    internal void UpdateShapeTextSelectionForTest(Point point) => UpdateShapeTextSelectionDrag(point);

    /// <summary>Test seam for releasing the active shape-text selection.</summary>
    internal void EndShapeTextSelectionForTest(Point point)
    {
        UpdateShapeTextSelectionDrag(point);
        FinishShapeTextSelectionDrag(releasePointerCapture: false);
    }

    /// <summary>Test seam for deterministic range-formatting and paint assertions.</summary>
    internal bool SelectShapeTextRangeForTest(int paragraphIndex, int startOffset, int endOffset)
    {
        if (_shapeCaret is not { } caret
            || !TryGetShapeTextTarget(
                caret.BlockIndex, caret.RunIndex, _activeShapeTextChildPath,
                out _, out var shape)
            || paragraphIndex < 0
            || paragraphIndex >= shape.TextParagraphs.Count)
            return false;

        _shapeSelectionAnchor = ShapeTextPositionAtOffset(
            shape, caret.BlockIndex, caret.RunIndex, paragraphIndex, startOffset);
        _shapeCaret = ShapeTextPositionAtOffset(
            shape, caret.BlockIndex, caret.RunIndex, paragraphIndex, endOffset);
        InvalidateVisual();
        CaretMoved?.Invoke();
        return ShapeTextSelectionInfo is not null;
    }

    /// <summary>Current shape-text selection endpoints in document order, or null when collapsed.</summary>
    internal ((int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) Start,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) End)? ShapeTextSelectionInfo
    {
        get
        {
            if (_shapeSelectionAnchor is not { } anchor || _shapeCaret is not { } caret
                || CompareShapeTextPositions(anchor, caret) == 0)
                return null;
            return CompareShapeTextPositions(anchor, caret) <= 0
                ? (anchor, caret)
                : (caret, anchor);
        }
    }

    private static int CompareShapeTextPositions(
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) left,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) right)
    {
        var result = left.BlockIndex.CompareTo(right.BlockIndex);
        if (result != 0) return result;
        result = left.RunIndex.CompareTo(right.RunIndex);
        if (result != 0) return result;
        result = left.TextParagraphIndex.CompareTo(right.TextParagraphIndex);
        if (result != 0) return result;
        result = left.TextRunIndex.CompareTo(right.TextRunIndex);
        return result != 0 ? result : left.Offset.CompareTo(right.Offset);
    }

    private static bool IsValidShapeTextPosition(
        Shape shape,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) position)
    {
        if (position.TextParagraphIndex < 0 || position.TextParagraphIndex >= shape.TextParagraphs.Count)
            return false;

        var paragraph = shape.TextParagraphs[position.TextParagraphIndex];
        if (paragraph.Runs.Count == 0)
            return position.TextRunIndex == 0 && position.Offset == 0;
        return position.TextRunIndex >= 0
            && position.TextRunIndex < paragraph.Runs.Count
            && position.Offset >= 0
            && position.Offset <= paragraph.Runs[position.TextRunIndex].Text.Length;
    }

    private static bool IsValidShapeTextSelection(
        Shape shape,
        ((int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) Start,
         (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) End) selection,
        int blockIndex,
        int runIndex) =>
        selection.Start.BlockIndex == blockIndex
        && selection.Start.RunIndex == runIndex
        && selection.End.BlockIndex == blockIndex
        && selection.End.RunIndex == runIndex
        && CompareShapeTextPositions(selection.Start, selection.End) <= 0
        && IsValidShapeTextPosition(shape, selection.Start)
        && IsValidShapeTextPosition(shape, selection.End);

    private static int ShapeTextOffset(
        Shape shape,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) position)
    {
        if (position.TextParagraphIndex < 0 || position.TextParagraphIndex >= shape.TextParagraphs.Count)
            return 0;
        var paragraph = shape.TextParagraphs[position.TextParagraphIndex];
        var offset = 0;
        for (var index = 0; index < paragraph.Runs.Count && index < position.TextRunIndex; index++)
            offset += paragraph.Runs[index].Text.Length;
        return offset + Math.Clamp(position.Offset, 0,
            position.TextRunIndex >= 0 && position.TextRunIndex < paragraph.Runs.Count
                ? paragraph.Runs[position.TextRunIndex].Text.Length
                : 0);
    }

    private static (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset)
        ShapeTextPositionAtOffset(Shape shape, int blockIndex, int runIndex, int paragraphIndex, int offset)
    {
        if (shape.TextParagraphs.Count == 0)
            return (blockIndex, runIndex, 0, 0, 0);

        paragraphIndex = Math.Clamp(paragraphIndex, 0, shape.TextParagraphs.Count - 1);
        var paragraph = shape.TextParagraphs[paragraphIndex];
        var remaining = Math.Clamp(offset, 0, paragraph.PlainText.Length);
        for (var runIndexInParagraph = 0; runIndexInParagraph < paragraph.Runs.Count; runIndexInParagraph++)
        {
            var length = paragraph.Runs[runIndexInParagraph].Text.Length;
            if (remaining <= length || runIndexInParagraph == paragraph.Runs.Count - 1)
                return (blockIndex, runIndex, paragraphIndex, runIndexInParagraph, Math.Min(remaining, length));
            remaining -= length;
        }

        return (blockIndex, runIndex, paragraphIndex, 0, 0);
    }

    private static void AppendShapeTextRun(Paragraph paragraph, string text, RunFormatting formatting)
    {
        if (!string.IsNullOrEmpty(text))
            paragraph.Runs.Add(new Run(text, formatting));
    }

    private static void AppendShapeParagraphRuns(Paragraph target, Paragraph fragment)
    {
        foreach (var run in fragment.Runs)
            target.Runs.Add(run);
    }

    private static void EnsureShapeParagraphRun(Paragraph paragraph)
    {
        if (paragraph.Runs.Count == 0)
            paragraph.Runs.Add(new Run(string.Empty));
    }

    private (List<Paragraph> Paragraphs,
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) Caret)
        BuildShapeTextReplacement(Shape shape,
            ((int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) Start,
             (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) End) selection,
            string replacement)
    {
        var startParagraph = selection.Start.TextParagraphIndex;
        var endParagraph = selection.End.TextParagraphIndex;
        var startOffset = ShapeTextOffset(shape, selection.Start);
        var endOffset = ShapeTextOffset(shape, selection.End);
        var result = new List<Paragraph>();

        for (var index = 0; index < startParagraph; index++)
            result.Add((Paragraph)DocumentMerge.CloneBlock(shape.TextParagraphs[index]));

        var start = shape.TextParagraphs[startParagraph];
        var end = shape.TextParagraphs[endParagraph];
        var merged = (Paragraph)DocumentMerge.CloneBlock(start);
        merged.Runs.Clear();

        var prefixEnd = Math.Clamp(startOffset, 0, start.PlainText.Length);
        var prefix = start.PlainText[..prefixEnd];
        var insertionFormatting = RevisionEditPlanner.FormattingAtOffset(start, startOffset);
        AppendShapeParagraphRuns(merged, DocumentModelCloner.CloneParagraphTextRange(
            start, 0, prefixEnd, RevisionClonePolicy.Preserve));
        AppendShapeTextRun(merged, replacement, insertionFormatting);
        AppendShapeParagraphRuns(merged, DocumentModelCloner.CloneParagraphTextRange(
            end,
            Math.Clamp(endOffset, 0, end.PlainText.Length),
            end.PlainText.Length,
            RevisionClonePolicy.Preserve));
        EnsureShapeParagraphRun(merged);
        result.Add(merged);

        for (var index = endParagraph + 1; index < shape.TextParagraphs.Count; index++)
            result.Add((Paragraph)DocumentMerge.CloneBlock(shape.TextParagraphs[index]));

        var caretParagraphIndex = startParagraph;
        var caretOffset = prefix.Length + replacement.Length;
        var caret = ShapeTextPositionAtOffset(shape, selection.Start.BlockIndex, selection.Start.RunIndex,
            caretParagraphIndex, caretOffset);
        // Map against the rebuilt paragraph list, whose first edited paragraph may have fewer/more runs.
        var rebuiltShape = new Shape();
        rebuiltShape.TextParagraphs.AddRange(result);
        caret = ShapeTextPositionAtOffset(rebuiltShape, selection.Start.BlockIndex, selection.Start.RunIndex,
            caretParagraphIndex, caretOffset);
        return (result, caret);
    }

    private void ReplaceShapeTextSelection(string replacement)
    {
        if (ShapeTextSelectionInfo is not { } selection
            || _shapeCaret is not { } current
            || !TryGetShapeTextTarget(
                current.BlockIndex, current.RunIndex, _activeShapeTextChildPath,
                out _, out var shape)
            || !IsValidShapeTextSelection(shape, selection, current.BlockIndex, current.RunIndex))
            return;

        var plan = BuildShapeTextReplacement(shape, selection, replacement);
        _bus.Execute(new ReplaceShapeTextParagraphsCommand(
            current.BlockIndex, current.RunIndex, plan.Paragraphs,
            _activeShapeTextChildPath));
        _shapeCaret = plan.Caret;
        _shapeSelectionAnchor = plan.Caret;
        InvalidateLayoutAndVisual();
        CaretMoved?.Invoke();
    }

    private bool InsertShapeFieldRun(Run run)
    {
        if (_shapeCaret is not { } caret
            || !TryGetShapeTextTarget(
                caret.BlockIndex, caret.RunIndex, _activeShapeTextChildPath,
                out _, out var shape))
            return false;

        var selection = ShapeTextSelectionInfo ?? (caret, caret);
        if (!IsValidShapeTextSelection(shape, selection, caret.BlockIndex, caret.RunIndex))
            return false;

        var plan = BuildShapeTextReplacement(shape, selection, string.Empty);
        var rebuiltShape = new Shape();
        rebuiltShape.TextParagraphs.AddRange(plan.Paragraphs);
        var paragraphIndex = plan.Caret.TextParagraphIndex;
        var insertionOffset = ShapeTextOffset(rebuiltShape, plan.Caret);
        RevisionEditPlanner.InsertRunAtOffset(
            plan.Paragraphs[paragraphIndex], insertionOffset, run);

        rebuiltShape = new Shape();
        rebuiltShape.TextParagraphs.AddRange(plan.Paragraphs);
        var nextCaret = ShapeTextPositionAtOffset(
            rebuiltShape,
            caret.BlockIndex,
            caret.RunIndex,
            paragraphIndex,
            insertionOffset + run.Text.Length);
        _bus.Execute(new ReplaceShapeTextParagraphsCommand(
            caret.BlockIndex,
            caret.RunIndex,
            plan.Paragraphs,
            _activeShapeTextChildPath));
        _shapeCaret = nextCaret;
        _shapeSelectionAnchor = nextCaret;
        InvalidateLayoutAndVisual();
        CaretMoved?.Invoke();
        return true;
    }

    private void ApplyShapeTextFormatting(Func<RunFormatting, RunFormatting> transform)
    {
        if (ShapeTextSelectionInfo is not { } selection
            || _shapeCaret is not { } current
            || !TryGetShapeTextTarget(
                current.BlockIndex, current.RunIndex, _activeShapeTextChildPath,
                out _, out var shape)
            || !IsValidShapeTextSelection(shape, selection, current.BlockIndex, current.RunIndex))
            return;

        var startParagraphIndex = selection.Start.TextParagraphIndex;
        var endParagraphIndex = selection.End.TextParagraphIndex;
        var startOffset = ShapeTextOffset(shape, selection.Start);
        var endOffset = ShapeTextOffset(shape, selection.End);
        var paragraphs = new List<Paragraph>();
        for (var index = 0; index < shape.TextParagraphs.Count; index++)
        {
            var source = shape.TextParagraphs[index];
            if (index < startParagraphIndex || index > endParagraphIndex)
            {
                paragraphs.Add((Paragraph)DocumentMerge.CloneBlock(source));
                continue;
            }

            var from = index == startParagraphIndex ? startOffset : 0;
            var to = index == endParagraphIndex ? endOffset : source.PlainText.Length;
            paragraphs.Add(DocumentModelCloner.CloneParagraphTextRange(
                source,
                from,
                to,
                RevisionClonePolicy.Preserve,
                transform,
                preserveUnselectedText: true));
        }

        _bus.Execute(new ReplaceShapeTextParagraphsCommand(
            current.BlockIndex, current.RunIndex, paragraphs, _activeShapeTextChildPath));
        var rebuiltShape = new Shape();
        rebuiltShape.TextParagraphs.AddRange(paragraphs);
        _shapeSelectionAnchor = ShapeTextPositionAtOffset(rebuiltShape, current.BlockIndex, current.RunIndex,
            startParagraphIndex, startOffset);
        _shapeCaret = ShapeTextPositionAtOffset(rebuiltShape, current.BlockIndex, current.RunIndex,
            endParagraphIndex, endOffset);
        InvalidateLayoutAndVisual();
        CaretMoved?.Invoke();
    }

    /// <summary>Insert a real paragraph break at the active text-box caret.</summary>
    public void InsertShapeTextParagraphBreak()
    {
        if (IsEditingLocked || _shapeCaret is not { } caret
            || !TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, caret.TextParagraphIndex,
                caret.TextRunIndex, out _))
            return;

        _bus.Execute(new InsertShapeTextParagraphBreakCommand(
            caret.BlockIndex,
            caret.RunIndex,
            caret.TextParagraphIndex,
            caret.TextRunIndex,
            caret.Offset,
            _activeShapeTextChildPath));
        _shapeCaret = caret with
        {
            TextParagraphIndex = caret.TextParagraphIndex + 1,
            TextRunIndex = 0,
            Offset = 0
        };
        _shapeSelectionAnchor = _shapeCaret;
        InvalidateLayoutAndVisual();
        CaretMoved?.Invoke();
    }

    /// <summary>Exit floating text-box editing while keeping the object selected.</summary>
    public void ExitShapeTextEditing()
    {
        if (_shapeCaret is null) return;
        FinishShapeTextSelectionDrag(releasePointerCapture: true);
        _shapeCaret = null;
        _shapeSelectionAnchor = null;
        _activeShapeTextChildPath = null;
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    /// <summary>Deselect any selected floating object. No-op when nothing is selected.</summary>
    public void DeselectFloating()
    {
        if (_selectedFloating is null && _selectedFloatingObjects.Count == 0) return;
        FinishShapeTextSelectionDrag(releasePointerCapture: true);
        _shapeCaret = null;
        _shapeSelectionAnchor = null;
        _activeShapeTextChildPath = null;
        _selectedFloating = null;
        _selectedFloatingGroupChild = null;
        _selectedFloatingObjects.Clear();
        _floatingDrag.Reset();
        _shapeEditPointsTarget = null;
        _shapeEditPointDragState = null;
        RaiseFloatingSelectionChangedIfIdentityChanged();
        InvalidateVisual();
    }

    /// <summary>
    /// Programmatically select the floating object at (blockIndex, runIndex). Triggers a layout pass
    /// if needed and refreshes the selection rect. Used by tests and the host shell.
    /// </summary>
    public void SelectFloating(int blockIndex, int runIndex, bool addToMultiSelect = false)
    {
        if (_laidOutWidth < 0) Relayout(FallbackWidth);
        // Determine kind.
        if (blockIndex < 0 || blockIndex >= _doc.Blocks.Count) return;
        if (_doc.Blocks[blockIndex] is not Paragraph para) return;
        if (runIndex < 0 || runIndex >= para.Runs.Count) return;
        var run = para.Runs[runIndex];
        string kind;
        if (run.Image is { IsFloating: true })         kind = "Image";
        else if (run.Shape is { IsFloating: true })    kind = "Shape";
        else if (run.Chart is { IsFloating: true })    kind = "Chart";
        else if (run.WordArt is { IsFloating: true })  kind = "WordArt";
        else if (run.SmartArt is { IsFloating: true }) kind = "SmartArt";
        else if (run.DrawingGroup is not null)         kind = "Group";
        else return;

        SelectFloatingCore(blockIndex, runIndex, kind, addToMultiSelect);
    }

    private void SelectFloatingCore(int blockIndex, int runIndex, string kind, bool addToMultiSelect)
    {
        FinishShapeTextSelectionDrag(releasePointerCapture: true);
        _shapeCaret = null;
        _shapeSelectionAnchor = null;
        _activeShapeTextChildPath = null;
        _selectedFloatingGroupChild = null;
        _shapeEditPointsTarget = null;
        _shapeEditPointDragState = null;
        var item = (blockIndex, runIndex, kind);
        if (addToMultiSelect && IsGroupableFloatingKind(kind))
        {
            var existing = _selectedFloatingObjects.FindIndex(existingItem =>
                existingItem.BlockIndex == blockIndex && existingItem.RunIndex == runIndex);
            if (existing >= 0)
            {
                _selectedFloatingObjects.RemoveAt(existing);
                if (_selectedFloatingObjects.Count == 0)
                {
                    _selectedFloating = null;
                    _floatingDrag.Reset();
                    _shapeEditPointsTarget = null;
                    _shapeEditPointDragState = null;
                    RaiseFloatingSelectionChangedIfIdentityChanged();
                    InvalidateVisual();
                    return;
                }

                var fallback = _selectedFloatingObjects[^1];
                _selectedFloating = (fallback.BlockIndex, fallback.RunIndex, fallback.Kind, default);
                RefreshSelectedFloatingRect(fallback.BlockIndex, fallback.RunIndex, fallback.Kind);
                return;
            }

            _selectedFloatingObjects.Add(item);
        }
        else
        {
            _selectedFloatingObjects.Clear();
            _selectedFloatingObjects.Add(item);
        }

        // Dummy rect; RefreshSelectedFloatingRect will update.
        _selectedFloating = (blockIndex, runIndex, kind, default);
        RefreshSelectedFloatingRect(blockIndex, runIndex, kind);
    }

    private void SelectFloatingGroupChildCore(
        FloatingGroupChildSelection hit)
    {
        // Keep the group as the active floating object so group-level commands continue to target
        // the owning run, while the child identity drives the local edit route and outline.
        SelectFloatingCore(hit.BlockIndex, hit.RunIndex, "Group", addToMultiSelect: false);
        _selectedFloatingGroupChild = hit;
        RaiseFloatingSelectionChangedIfIdentityChanged();
        InvalidateVisual();
    }

    private static bool IsSameFloatingGroupChild(
        FloatingGroupChildSelection selected,
        FloatingGroupChildSelection hit) =>
        selected.BlockIndex == hit.BlockIndex
        && selected.RunIndex == hit.RunIndex
        && selected.ChildPath.SequenceEqual(hit.ChildPath);

    internal bool SelectedFloatingGroupChildMatchesPointForTest(Point point) =>
        _selectedFloatingGroupChild is { } selected
        && TryHitTestFloatingGroupChild(point, out var hit)
        && IsSameFloatingGroupChild(selected, hit);

    internal bool SelectFloatingGroupChildForTest(Point point)
    {
        if (!TryHitTestFloatingGroupChild(point, out var hit))
            return false;

        SelectFloatingGroupChildCore(hit);
        return true;
    }

    private static bool IsGroupableFloatingKind(string kind) =>
        kind is "Image" or "Shape" or "Chart" or "WordArt" or "SmartArt" or "Group";

    private bool TryGetRun(int blockIndex, int runIndex, out Run run)
    {
        run = null!;
        if (blockIndex < 0 || blockIndex >= _doc.Blocks.Count) return false;
        if (_doc.Blocks[blockIndex] is not Paragraph para) return false;
        if (runIndex < 0 || runIndex >= para.Runs.Count) return false;
        run = para.Runs[runIndex];
        return true;
    }

    private bool TryGetShapeTextRun(
        int blockIndex,
        int runIndex,
        int textParagraphIndex,
        int textRunIndex,
        out Run textRun,
        IReadOnlyList<int>? childPath = null)
    {
        textRun = null!;
        if (!TryGetShapeTextTarget(blockIndex, runIndex, childPath, out _, out var shape)
            || textParagraphIndex < 0 || textParagraphIndex >= shape.TextParagraphs.Count)
            return false;

        var paragraph = shape.TextParagraphs[textParagraphIndex];
        if (textRunIndex < 0 || textRunIndex >= paragraph.Runs.Count)
            return false;

        textRun = paragraph.Runs[textRunIndex];
        return true;
    }

    private bool TryGetShapeTextTarget(
        int blockIndex,
        int runIndex,
        IReadOnlyList<int>? childPath,
        out Run ownerRun,
        out Shape shape)
    {
        ownerRun = null!;
        shape = null!;
        if (!TryGetRun(blockIndex, runIndex, out ownerRun))
            return false;

        childPath ??= _activeShapeTextChildPath;
        if (childPath is { Count: > 0 })
        {
            if (ownerRun.DrawingGroup is not { } group
                || !DrawingGroupChildPathResolver.TryGetChild(
                    group, childPath, out _, out var child)
                || child is not Shape nestedShape)
                return false;
            shape = nestedShape;
            return true;
        }

        if (ownerRun.Shape is not { } directShape)
            return false;
        shape = directShape;
        return true;
    }

    private bool IsGroupableFloatingRun(int blockIndex, int runIndex)
    {
        if (!TryGetRun(blockIndex, runIndex, out var run)) return false;
        return run.Image is { IsFloating: true }
            || run.Shape is { IsFloating: true }
            || run.Chart is { IsFloating: true }
            || run.WordArt is { IsFloating: true }
            || run.SmartArt is { IsFloating: true }
            || run.DrawingGroup is { IsValid: true };
    }

    private List<DocumentObjectTarget> SelectedGroupMemberLocations()
    {
        var members = new List<DocumentObjectTarget>();
        foreach (var selected in _selectedFloatingObjects)
        {
            if (!IsGroupableFloatingRun(selected.BlockIndex, selected.RunIndex))
                continue;

            var member = ObjectTarget(selected.BlockIndex, selected.RunIndex);
            if (!members.Contains(member))
                members.Add(member);
        }

        return members;
    }

    private (int BlockIndex, int RunIndex, Shape Shape, string Kind)? SelectedFloatingShapeLocation()
    {
        if (_selectedFloating is not { Kind: "Shape" } sel) return null;
        if (_doc.Blocks[sel.BlockIndex] is not Paragraph para) return null;
        if (sel.RunIndex < 0 || sel.RunIndex >= para.Runs.Count) return null;
        if (para.Runs[sel.RunIndex].Shape is not { } shape) return null;
        return (sel.BlockIndex, sel.RunIndex, shape, sel.Kind);
    }

    private (int BlockIndex, int RunIndex, IReadOnlyList<int> ChildPath)? SelectedNestedShapeLocation()
    {
        if (_selectedFloatingGroupChild is not { Kind: "Shape" } selected
            || !TryGetRun(selected.BlockIndex, selected.RunIndex, out var run)
            || run.DrawingGroup is not { } root
            || !DrawingGroupChildPathResolver.TryGetChild(
                root, selected.ChildPath, out _, out var child)
            || child is not Shape)
            return null;

        return (selected.BlockIndex, selected.RunIndex, selected.ChildPath);
    }

    /// <summary>
    /// Align the paragraph containing the selected floating image, matching the WPF command behavior.
    /// </summary>
    public void SetSelectedImageAlignment(TextAlignment alignment) =>
        SetSelectedFloatingParagraphAlignment("Image", alignment);

    /// <summary>
    /// Align the paragraph containing the selected floating shape, matching the WPF command behavior.
    /// </summary>
    public void SetSelectedShapeAlignment(TextAlignment alignment) =>
        SetSelectedFloatingParagraphAlignment("Shape", alignment);

    private void SetSelectedFloatingParagraphAlignment(string kind, TextAlignment alignment)
    {
        if (kind == "Shape"
            && _selectedFloatingGroupChild is { Kind: "Shape" } selectedChild
            && TryGetRun(selectedChild.BlockIndex, selectedChild.RunIndex, out var groupRun)
            && groupRun.DrawingGroup is { } rootGroup
            && DrawingGroupChildPathResolver.TryGetChild(
                rootGroup,
                selectedChild.ChildPath,
                out _,
                out var nestedChild)
            && nestedChild is Shape nestedShape
            && ShapeTextFormattingPlanner.CanApplyParagraphAlignment(nestedShape))
        {
            InvalidateObjectEdit(
                ObjectEdits.SetShapeAlignment(
                    ObjectTarget(
                        selectedChild.BlockIndex,
                        selectedChild.RunIndex,
                        selectedChild.ChildPath),
                    alignment),
                "Group");
            return;
        }

        if (_selectedFloating is not { } sel || sel.Kind != kind)
            return;
        if (_doc.Blocks[sel.BlockIndex] is not Paragraph para)
            return;
        if (sel.RunIndex < 0 || sel.RunIndex >= para.Runs.Count)
            return;

        var run = para.Runs[sel.RunIndex];
        var applies = kind switch
        {
            "Image" => run.Image is { IsFloating: true },
            "Shape" => run.Shape is { IsFloating: true },
            _ => false
        };
        if (!applies)
            return;

        var target = ObjectTarget(sel.BlockIndex, sel.RunIndex);
        var result = kind == "Image"
            ? ObjectEdits.SetImageAlignment(target, alignment)
            : ObjectEdits.SetShapeAlignment(target, alignment);
        InvalidateObjectEdit(result, sel.Kind);
    }

