        _floatingDrag.Reset();
        _shapeEditPointsTarget = null;
        _shapeEditPointDragState = null;
        RaiseFloatingSelectionChangedIfIdentityChanged();
        InvalidateLayoutAndVisual();
    }

    private void DrawDecoration(DrawingContext context, PlacedChar pc, double yLine) =>
        DrawDecoration(context, pc, yLine, pc.Fmt);

    // AV-LINK: overload that draws the decoration (under-/strike-line) in an explicit format's colour, so a
    // hyperlink underline uses the resolved hyperlink colour rather than the run's raw (unstyled) colour.
    private void DrawDecoration(DrawingContext context, PlacedChar pc, double yLine, RunFormatting fmt)
    {
        var pen = new Pen(BrushFor(fmt.ColorHex), Math.Max(1, FontSizePx(fmt) / 14));
        context.DrawLine(pen, new Point(pc.X, yLine), new Point(pc.X + pc.W, yLine));
    }

    private void DrawStrikethroughDecorations(DrawingContext context, PlacedChar pc, RunFormatting formatting)
    {
        if (formatting.DoubleStrikethrough)
        {
            DrawDecoration(context, pc, pc.Y + pc.LineHeight * 0.46, formatting);
            DrawDecoration(context, pc, pc.Y + pc.LineHeight * 0.54, formatting);
        }
        else if (formatting.Strikethrough)
        {
            DrawDecoration(context, pc, pc.Y + pc.LineHeight * 0.5, formatting);
        }
    }

    /// <summary>
    /// AV-TRACKEDIT: draw the tracked-change mark for a glyph — a revision-coloured underline under a tracked
    /// insertion (Word's w:ins decoration) or a revision-coloured strikethrough across a tracked deletion
    /// (w:del). A no-op for ordinary (un-tracked) glyphs.
    /// </summary>
    private void DrawRevisionDecoration(
        DrawingContext context,
        PlacedChar pc,
        ReviewRevisionDisplayDecision decision,
        string colorHex)
    {
        if (pc.W <= 0 || !decision.IsRevisionStylingApplied)
            return;
        if (decision.IsInsertionDecorationApplied)
        {
            var y = pc.Y + pc.LineHeight * 0.86;
            context.DrawLine(new Pen(BrushFor(colorHex), 1.0), new Point(pc.X, y), new Point(pc.X + pc.W, y));
        }
        else if (decision.IsDeletionDecorationApplied)
        {
            var y = pc.Y + pc.LineHeight * 0.5;
            context.DrawLine(new Pen(BrushFor(colorHex), 1.0), new Point(pc.X, y), new Point(pc.X + pc.W, y));
        }
    }

    private void DrawFormatRevisionDecoration(DrawingContext context, PlacedChar pc, string colorHex)
    {
        if (pc.W <= 0)
            return;

        var y = pc.Y + pc.LineHeight * 0.92;
        context.DrawLine(new Pen(BrushFor(colorHex), 1.0, new DashStyle([1, 2], 0)), new Point(pc.X, y), new Point(pc.X + pc.W, y));
    }

    private static void DrawProofingSquiggle(DrawingContext context, PlacedChar pc)
    {
        if (pc.W <= 0)
            return;

        var y = pc.Y + pc.LineHeight * 0.92;
        var x = pc.X;
        var end = pc.X + pc.W;
        var step = 3.0;
        var amplitude = 1.4;
        var high = true;
        var current = new Point(x, y);
        while (x < end)
        {
            x = Math.Min(end, x + step);
            var next = new Point(x, y + (high ? -amplitude : amplitude));
            context.DrawLine(ProofingSquigglePen, current, next);
            current = next;
            high = !high;
        }
    }

    /// <summary>
    /// AV-TAB: Draws a tab leader (dots / dashes / underline) filling the gap between
    /// <paramref name="x1"/> (tab character start) and <paramref name="x2"/> (next segment start)
    /// for the given <paramref name="leader"/> kind and run formatting.
    /// </summary>
    private void DrawTabLeader(DrawingContext context, double x1, double x2, double y, double lineH,
        TabLeader leader, RunFormatting fmt)
    {
        if (x2 <= x1) return;
        var brush = BrushFor(fmt.ColorHex);
        var thickness = Math.Max(0.8, FontSizePx(fmt) / 18);

        switch (leader)
        {
            case TabLeader.Underline:
            {
                // Solid underline across the full gap.
                var pen = new Pen(brush, thickness);
                var yLine = y + lineH * 0.82;
                context.DrawLine(pen, new Point(x1, yLine), new Point(x2, yLine));
                break;
            }
            case TabLeader.Dots:
            {
                // Dots spaced ~4px apart, drawn as small filled circles at the baseline.
                var yLine = y + lineH * 0.82;
                var dotR  = Math.Max(0.7, thickness * 0.6);
                var step  = Math.Max(4, dotR * 5);
                for (var dotX = x1 + step / 2; dotX < x2 - dotR; dotX += step)
                    context.FillRectangle(brush, new Rect(dotX - dotR, yLine - dotR, dotR * 2, dotR * 2));
                break;
            }
            case TabLeader.Dashes:
            {
                // Dashes via a dash-style pen.
                var dashPen = new Pen(brush, thickness, new DashStyle([4, 3], 0));
                var yLine   = y + lineH * 0.82;
                context.DrawLine(dashPen, new Point(x1, yLine), new Point(x2, yLine));
                break;
            }
        }
    }

    private bool TryGetCaretRect(out Rect rect)
    {
        // AV-TBL: when the caret is inside a cell, search by cell address + para-offset instead of
        // block+glyph-offset. This is robust after model edits (which invalidate glyph offsets).
        if (_cellCaret is { } cc)
        {
            foreach (var pc in _placed)
            {
                if (pc.Block == cc.TableBlock && pc.CellRow == cc.Row && pc.CellCol == cc.Col
                    && pc.CellParaIdx == cc.ParaIdx && pc.CellParaOffset == cc.Offset)
                {
                    rect = new Rect(pc.X, pc.Y, 1.5, pc.LineHeight);
                    return true;
                }
            }
            // If no exact glyph found (e.g., caret is at end of text = sentinel position),
            // look for the sentinel at that cell + para.
            foreach (var pc in _placed)
            {
                if (pc.Block == cc.TableBlock && pc.CellRow == cc.Row && pc.CellCol == cc.Col
                    && pc.CellParaIdx == cc.ParaIdx && pc.Sentinel)
                {
                    rect = new Rect(pc.X, pc.Y, 1.5, pc.LineHeight);
                    return true;
                }
            }
            rect = default;
            return false;
        }

        // Body paragraph: search by block + glyph offset (original logic).
        foreach (var pc in _placed)
        {
            if (pc.Block == _caret.Block && pc.Offset == _caret.Offset)
            {
                rect = new Rect(pc.X, pc.Y, 1.5, pc.LineHeight);
                return true;
            }
        }

        rect = default;
        return false;
    }

    private readonly record struct ContentControlTarget(
        int BlockIndex,
        int RunIndex,
        int? Row = null,
        int? Column = null,
        int? ParagraphIndex = null);

    private bool TryActivateContentControl(Point point)
    {
        if (!TryHitTest(point, out var position)
            || !TryGetContentControlAt(position, out var target, out var run))
            return false;

        _caret = position;
        _selectionAnchor = position;
        if (run.Control!.Kind == ContentControlKind.CheckBox)
            return ApplyContentControlInteraction(target, ContentControlInteractionPlanner.ToggleCheckBox);
        if (run.Control.Kind is ContentControlKind.DropDownList or ContentControlKind.ComboBox or ContentControlKind.DatePicker)
            return OpenContentControlMenu(target, run);
        return false;
    }

    private bool TryOpenContentControlMenu(Point point)
    {
        if (!TryHitTest(point, out var position)
            || !TryGetContentControlAt(position, out var target, out var run))
            return false;
        _caret = position;
        _selectionAnchor = position;
        return OpenContentControlMenu(target, run);
    }

    private bool TryOpenContentControlMenuAtCaret() =>
        TryGetContentControlAt(_caret, out var target, out var run)
        && OpenContentControlMenu(target, run);

    private bool TryGetContentControlAt(
        DocPosition position,
        out ContentControlTarget target,
        out Run run)
    {
        target = default;
        run = null!;
        Paragraph? paragraph;
        int contentOffset;
        if (_cellCaret is { } cell && cell.TableBlock == position.Block)
        {
            paragraph = GetCellParagraph(cell.TableBlock, cell.Row, cell.Col, cell.ParaIdx);
            contentOffset = cell.Offset;
        }
        else
        {
            if (position.Block < 0
                || position.Block >= _doc.Blocks.Count
                || _doc.Blocks[position.Block] is not Paragraph bodyParagraph)
            {
                return false;
            }

            paragraph = bodyParagraph;
            contentOffset = position.Offset;
        }

        if (paragraph is null)
            return false;

        var offset = 0;
        for (var index = 0; index < paragraph.Runs.Count; index++)
        {
            var candidate = paragraph.Runs[index];
            var end = offset + candidate.Text.Length;
            if (candidate.Control is not null
                && contentOffset >= offset
                && (contentOffset < end || candidate.Text.Length == 0 && contentOffset == offset))
            {
                target = _cellCaret is { } cellTarget
                    ? new ContentControlTarget(cellTarget.TableBlock, index, cellTarget.Row, cellTarget.Col, cellTarget.ParaIdx)
                    : new ContentControlTarget(position.Block, index);
                run = candidate;
                return true;
            }
            offset = end;
        }
        return false;
    }

    private bool OpenContentControlMenu(ContentControlTarget target, Run run)
    {
        if (run.Control?.Kind is not (ContentControlKind.DropDownList or ContentControlKind.ComboBox or ContentControlKind.DatePicker))
            return false;

        var isEnabled = ContentControlInteractionPlanner.CanEditExistingContentControl(run, RestrictEditingPolicy);
        var today = DateTime.Today;
        var menu = AvaloniaContextMenuRenderer.BuildContextMenu(
            FreeWContextMenuPlanner.BuildContentControl(run, today, isEnabled),
            commandId => ApplyContentControlInteraction(
                target,
                item => FreeWContextMenuPlanner.ApplyContentControlCommand(item, commandId, today)));
        OpenContextMenu(menu);
        return true;
    }

    private void PositionCaretForContextMenu(Point point)
    {
        if (_hfCaret is not null || !TryHitTest(point, out var position))
            return;

        if (_cellCaret is not null)
        {
            _cellAnchor = _cellCaret;
            CaretMoved?.Invoke();
            return;
        }

        _caret = position;
        _selectionAnchor = position;
        CaretMoved?.Invoke();
        InvalidateVisual();
    }

    private void OpenEditorContextMenu()
    {
        var spellingDiagnostic = CurrentProofingDiagnostic;
        var menu = AvaloniaContextMenuRenderer.BuildContextMenu(
            FreeWContextMenuPlanner.BuildEditor(new FreeWEditorContextMenuState(
                CanUndo,
                CanRedo,
                HasSelection: SelectedText.Length > 0,
                CanPaste: CanPasteProvider?.Invoke() == true,
                CanEdit: !IsEditingLocked),
                spellingDiagnostic is { Kind: ProofingDiagnosticKind.Spelling } diagnostic
                    ? new FreeWSpellingContextMenuState(
                        diagnostic,
                        CanEdit: !IsEditingLocked,
                        CanIgnore: true,
                        CanAddToDictionary: true)
                    : null),
            commandId =>
            {
                if (spellingDiagnostic is { Kind: ProofingDiagnosticKind.Spelling } diagnostic)
                {
                    if (FreeWContextMenuPlanner.TryParseIndex(
                        commandId,
                        FreeWContextMenuPlanner.EditorSpellingReplacementPrefix,
                        out var replacementIndex))
                    {
                        var suggestions = ProofingCorrectionCatalog.SuggestionsFor(diagnostic.Word);
                        if (replacementIndex < suggestions.Count)
                            ReplaceCurrentProofingWord(suggestions[replacementIndex]);
                        return;
                    }

                    if (commandId.Value == FreeWContextMenuPlanner.EditorSpellingIgnoreAll)
                    {
                        IgnoreCurrentProofingWord();
                        return;
                    }

                    if (commandId.Value == FreeWContextMenuPlanner.EditorSpellingAddToDictionary)
                    {
                        AddCurrentWordToDictionary();
                        return;
                    }
                }

                ContextMenuCommandRequested?.Invoke(commandId);
            });
        OpenContextMenu(menu);
    }

    private void OpenContextMenu(ContextMenu menu)
    {
        _activeContextMenu?.Close();
        _activeContextMenu = menu;
        menu.Opened += (_, _) => menu.Items.OfType<MenuItem>().FirstOrDefault(item => item.IsEnabled)?.Focus();
        menu.Closed += (_, _) =>
        {
            if (ReferenceEquals(_activeContextMenu, menu))
                _activeContextMenu = null;
        };
        menu.Open(this);
    }

    private ContextMenu? _activeContextMenu;
    internal ContextMenu? ActiveContextMenuForTests => _activeContextMenu;
    internal void OpenEditorContextMenuForTests() => OpenEditorContextMenu();
    internal void RaiseKeyDownForContextMenuTests(KeyEventArgs args) => OnKeyDown(args);

    // ---- Input ----------------------------------------------------------------------------------

    protected override void OnPointerPressed(PointerPressedEventArgs e)
    {
        base.OnPointerPressed(e);

        Focus();
        var point = e.GetPosition(this);
        var shift = (e.KeyModifiers & KeyModifiers.Shift) != 0;
        var ctrlOrMeta = (e.KeyModifiers & (KeyModifiers.Control | KeyModifiers.Meta)) != 0;
        var updateKind = e.GetCurrentPoint(this).Properties.PointerUpdateKind;

        if (updateKind == PointerUpdateKind.RightButtonPressed)
        {
            PositionCaretForContextMenu(point);
            if (!TryOpenContentControlMenu(point))
                OpenEditorContextMenu();
            e.Handled = true;
            return;
        }

        if (updateKind == PointerUpdateKind.LeftButtonPressed && TryActivateContentControl(point))
        {
            e.Handled = true;
            return;
        }

        // AV-SHAPETEXT3: once a text box is in edit mode, a left-button press inside its body starts a
        // text-range drag. The active end uses the same pointer caret-stop map as a click, while the
        // floating-object move/resize route remains available before text-edit mode is entered.
        if (updateKind == PointerUpdateKind.LeftButtonPressed
            && _shapeCaret is not null
            && BeginShapeTextSelectionDrag(point, shift, e.Pointer, out _))
        {
            e.Handled = true;
            return;
        }

        // AV-LINK: Ctrl+Click follows a hyperlink (Word's convention) — open an external URL via the
        // HyperlinkActivated event, or jump the caret to an internal bookmark target. Checked before the
        // body hit-test so the click is consumed instead of just moving the caret.
        if (ctrlOrMeta && !shift && TryHitTestHyperlink(point, out var clickedLink))
        {
            FollowHyperlink(clickedLink);
            e.Handled = true;
            return;
        }

        // AV-HANDLES: when a float is already selected, a press on one of its 8 resize handles starts a
        // resize drag (checked BEFORE the float hit-test so the handle squares, which sit on/outside the
        // object's edge, win over whatever object lies under them).
        var extendFloatingSelection = shift || ctrlOrMeta;

        // A group selected at the parent level gives its direct child hit-test first refusal. Without
        // this guard, the parent group's Body handle claims every point inside the group and a click on
        // a child starts moving the group instead of entering child-local selection.
        if (!extendFloatingSelection
            && _selectedFloating is { Kind: "Group" }
            && _selectedFloatingGroupChild is null
            && TryHitTestFloatingGroupChild(point, out var groupChildSelection))
        {
            SelectFloatingGroupChildCore(groupChildSelection);
            _floatingDrag.Reset();
            Cursor = Cursor.Default;
            e.Handled = true;
            return;
        }

        if (!extendFloatingSelection && _selectedFloating is { } curSel)
        {
            var editPoint = HitTestShapeEditPoint(point);
            if (editPoint >= 0)
            {
                BeginShapeEditPointDrag(editPoint, e.Pointer);
                Cursor = new Cursor(StandardCursorType.Hand);
                e.Handled = true;
                return;
            }

            var handle = HitTestHandle(point);
            if (handle is not FloatHandle.None and not FloatHandle.Body)
            {
                BeginFloatingDrag(point, SelectedFloatingDragRect(curSel), handle);
                Cursor = CursorForHandle(handle);
                InvalidateVisual();
                e.Handled = true;
                return;
            }
        }

        // A direct click on a rendered child enters group-child selection. The group remains the
        // owning selection for arrange/ungroup commands, while local transforms target the child.
        if (!extendFloatingSelection && TryHitTestFloatingGroupChild(point, out var groupChildHit))
        {
            if (_selectedFloatingGroupChild is { } selectedChild
                && IsSameFloatingGroupChild(selectedChild, groupChildHit))
            {
                if (groupChildHit.Kind == "Shape"
                    && TryGetShapeTextTarget(
                        groupChildHit.BlockIndex,
                        groupChildHit.RunIndex,
                        groupChildHit.ChildPath,
                        out _,
                        out var selectedTextShape)
                    && selectedTextShape.TextParagraphs.Count > 0
                    && EnterSelectedShapeTextEditing())
                {
                    _floatingDrag.Reset();
                    Cursor = Cursor.Default;
                    e.Handled = true;
                    return;
                }
                BeginFloatingDrag(point, groupChildHit.Rect, FloatHandle.Body);
                Cursor = CursorForHandle(FloatHandle.Body);
            }
            else
            {
                SelectFloatingGroupChildCore(groupChildHit);
                _floatingDrag.Reset();
                Cursor = Cursor.Default;
            }
            e.Handled = true;
            return;
        }

        // AV-FLSEL: check whether the click landed on a floating object BEFORE body text hit-test.
        // The topmost object (highest z-order, in-front preferred over behind) wins.
        if (TryHitTestFloat(point, out var floatHit))
        {
            SelectFloatingCore(floatHit.BlockIndex, floatHit.RunIndex, floatHit.Kind, extendFloatingSelection);
            if (!extendFloatingSelection && _selectedFloating is { } selected)
            {
                // AV-HANDLES: a press inside the selected float's body starts a drag-move. Whether it
                // becomes a real move or stays a plain selecting click is decided on release by the 1px
                // threshold in CommitFloatDrag.
                BeginFloatingDrag(point, selected.Rect, FloatHandle.Body);
                Cursor = CursorForHandle(FloatHandle.Body);
            }
            else
            {
                _floatingDrag.Reset();
                Cursor = Cursor.Default;
            }
            InvalidateVisual();
            e.Handled = true;
            return;
        }

        // Click outside any float → deselect.
        if (_selectedFloating is not null)
        {
            _shapeCaret = null;
            _shapeSelectionAnchor = null;
            _activeShapeTextChildPath = null;
            _selectedFloating = null;
            _selectedFloatingGroupChild = null;
            _selectedFloatingObjects.Clear();
            _floatingDrag.Reset();
            _shapeEditPointsTarget = null;
            _shapeEditPointDragState = null;
            Cursor = Cursor.Default;
            RaiseFloatingSelectionChangedIfIdentityChanged();
            InvalidateVisual();
        }

        // AV-HFEDIT: a click inside a rendered header/footer region routes the caret into that region.
        // Only in PrintLayout (the only mode that draws H/F bands). Checked before the body hit-test
        // because H/F bands sit in the page margins, which the body hit-test does not own.
        if (!shift && _viewMode == DocumentViewMode.PrintLayout && TryHitTestHeaderFooter(point))
        {
            CaretMoved?.Invoke();
            e.Handled = true;
            return;
        }

        if (TryHitTest(point, out var pos))
        {
            // AV-HFEDIT: clicking back into the body exits any active header/footer caret.
            _hfCaret = null;

            // AV-TBL2: clear any prior cross-cell block selection on a fresh (non-shift) press.
            if (!shift)
            {
                _cellBlockAnchor = null;
                _cellBlockFocus  = null;
            }

            // AV-TBL: When entering a cell, _cellCaret was set by TryHitTest.
            // When leaving a cell (hitting body text), _cellCaret is cleared.
            if (!shift)
            {
                _selectionAnchor = pos;
                _cellAnchor = _cellCaret;
            }
            else
            {
                // Shift-click extends selection; keep existing anchor.
                _selectionAnchor ??= _caret;
                _cellAnchor ??= _cellCaret;
            }
            _caret = pos;
            InvalidateVisual();
            CaretMoved?.Invoke();
        }
    }

    protected override void OnPointerMoved(PointerEventArgs e)
    {
        base.OnPointerMoved(e);
        var point = e.GetPosition(this);

        if (_shapeTextSelectionDragState is not null)
        {
            UpdateShapeTextSelectionDrag(point);
            e.Handled = true;
            return;
        }

        if (!e.GetCurrentPoint(this).Properties.IsLeftButtonPressed)
        {
            // AV-HANDLES: with the button up, update the hover cursor over the selection so handles
            // advertise their resize direction (and the body shows a move cursor).
            if (_selectedFloating is not null && !_floatingDrag.IsActive)
            {
                var hover = HitTestHandle(point);
                if (_shapeEditPointsTarget is not null && HitTestShapeEditPoint(point) >= 0)
                    Cursor = new Cursor(StandardCursorType.Hand);
                else
                    Cursor = hover == FloatHandle.None ? Cursor.Default : CursorForHandle(hover);
            }
            return;
        }

        if (_shapeEditPointDragState is { } editDrag)
        {
            if (TryPointToCustomCoordinate(point, out var x, out var y))
                MoveActiveShapeEditPoint(editDrag.SegmentIndex, x, y);
            e.Handled = true;
            return;
        }

        // AV-HANDLES: live drag (move or resize) of the selected floating object.
        if (_floatingDrag.IsActive)
        {
            var shift = (e.KeyModifiers & KeyModifiers.Shift) != 0;
            UpdateFloatDrag(point, shift);
            e.Handled = true;
            return;
        }
        var previousCellBlockSelection = SelectedCellRange;
        if (!TryHitTest(point, out var pos))
            return;

        // AV-TBL2: when a drag starts inside a cell and moves to a DIFFERENT cell, switch to
        // rectangular cross-cell block selection instead of single-cell text selection.
        if (_cellBlockAnchor is { } blockAnchor && _cellCaret is { } movingFocus
            && blockAnchor.TableBlock == movingFocus.TableBlock)
        {
            // BF4: block selection is already active — just update focus to the current cell.
            // _cellCaret/_cellAnchor are already null (cleared when block selection was first activated).
            _cellBlockFocus = (movingFocus.TableBlock, movingFocus.Row, movingFocus.Col);
            _cellCaret  = null;
            _cellAnchor = null;
            _selectionAnchor = _caret;
        }
        else if (_cellAnchor is { } anchor && _cellCaret is { } focus
            && anchor.TableBlock == focus.TableBlock
            && (anchor.Row != focus.Row || anchor.Col != focus.Col))
        {
            // Different cell than where the drag started → activate block selection.
            _cellBlockAnchor = (anchor.TableBlock, anchor.Row, anchor.Col);
            _cellBlockFocus  = (focus.TableBlock,  focus.Row,  focus.Col);
            // BF4: clear single-cell caret/anchor so SelectedCellRange and CellCaretInfo are
            // never both non-null (mirrors SetCellBlockSelection invariant).
            _cellCaret  = null;
            _cellAnchor = null;
            // Suppress the single-cell text selection anchor so IsWithin() doesn't highlight glyphs.
            _selectionAnchor = _caret;
        }
        else if (_cellAnchor is { } anch && _cellCaret is { } foc
                 && anch.TableBlock == foc.TableBlock
                 && anch.Row == foc.Row && anch.Col == foc.Col)
        {
            // Still in the same cell — clear block selection if it was set.
            _cellBlockAnchor = null;
            _cellBlockFocus  = null;
        }

        _caret = pos;
        InvalidateVisual();
        if (previousCellBlockSelection != SelectedCellRange)
            CaretMoved?.Invoke();
    }

    protected override void OnPointerCaptureLost(PointerCaptureLostEventArgs e)
    {
        base.OnPointerCaptureLost(e);
        if (_shapeTextSelectionDragState is not null)
            FinishShapeTextSelectionDrag(releasePointerCapture: false);
        if (_shapeEditPointDragState is null)
            return;

        // Pointer capture keeps an outside-control release on the same drag, but a platform or
        // window teardown can still revoke capture without a matching PointerReleased event.
        // Commit the already-applied point moves so the undo group never remains open.
        FinishShapeEditPointDrag(releasePointerCapture: false);
        Cursor = _selectedFloating is null ? Cursor.Default : CursorForHandle(FloatHandle.None);
    }

    protected override void OnPointerReleased(PointerReleasedEventArgs e)
    {
        base.OnPointerReleased(e);
        if (_shapeTextSelectionDragState is not null)
        {
            UpdateShapeTextSelectionDrag(e.GetPosition(this));
            FinishShapeTextSelectionDrag(releasePointerCapture: true);
            e.Handled = true;
            return;
        }
        if (_shapeEditPointDragState is not null)
        {
            FinishShapeEditPointDrag(releasePointerCapture: true);
            Cursor = _selectedFloating is null ? Cursor.Default : CursorForHandle(HitTestHandle(e.GetPosition(this)));
            e.Handled = true;
            return;
        }

        // AV-HANDLES: commit the in-flight drag (move or resize) when the left button is released.
        // _selectedFloating is refreshed via the commit path's relayout; the cursor is reset to the
        // hover cursor for wherever the pointer ended up.
        if (_floatingDrag.IsActive)
        {
            var shift = (e.KeyModifiers & KeyModifiers.Shift) != 0;
            CommitFloatDrag(e.GetPosition(this), shift);
            Cursor = _selectedFloating is null
                ? Cursor.Default
                : CursorForHandle(HitTestHandle(e.GetPosition(this)));
        }

        if (ApplyFormatPainterToSelection())
            e.Handled = true;
    }

    protected override void OnTextInput(TextInputEventArgs e)
    {
        base.OnTextInput(e);
        if (IsEditingLocked)
        {
            e.Handled = true;
            return;
        }

        if (_shapeCaret is not null)
        {
            if (!string.IsNullOrEmpty(e.Text) && e.Text != "\r" && e.Text != "\n")
                InsertText(e.Text);
            e.Handled = true;
            return;
        }

        if (string.IsNullOrEmpty(e.Text) || e.Text == "\r" || e.Text == "\n")
            return;

        if (e.Text.Length == 1 && TryAutoCorrect(e.Text[0]))
        {
            e.Handled = true;
            return;
        }

        InsertText(e.Text);
        e.Handled = true;
    }

    /// <summary>
    /// Applies the same shared AutoCorrect/AutoFormat result that the WPF preview-text path uses. The
    /// typed character is still outside the model when this runs, so the result replaces the preceding
    /// <see cref="AutoCorrectResult.DeleteBefore"/> characters and emits the result's insertion text as
    /// one undoable paragraph edit.
    /// </summary>
    private bool TryAutoCorrect(char justTyped)
    {
        if (!AutoCorrectEnabled
            || _shapeCaret is not null
            || _hfCaret is not null
            || _cellCaret is not null
            || NormalizedSelection() is not null
            || CurrentParagraph() is not { } paragraph
            || !IsEditable(paragraph))
            return false;

        var cells = ParaCells(paragraph);
        var bodyOffset = Math.Clamp(_caret.Offset, 0, cells.Count);
        var textBefore = new string(cells.Take(bodyOffset).Select(cell => cell.Ch).ToArray());
        // WPF's native list marker supplies sentence context that is absent from Avalonia's model cells.
        var formatOptions = paragraph.Formatting.ListKind != ListKind.None && bodyOffset == 0
            ? AutoFormatOptions with { Capitalization = false }
            : AutoFormatOptions;
        var result = AutoCorrectEvaluationPolicy.Evaluate(
            textBefore,
            justTyped,
            AutoCorrectOptions,
            formatOptions);
        if (!result.Applies)
            return false;

        var deleteStart = bodyOffset - result.DeleteBefore;
        if (deleteStart < 0 || deleteStart > bodyOffset)
            return false;

        var pendingFmt = _pendingRunFmt;
        _pendingRunFmt = null;
        var replacementFmt = pendingFmt ?? ActiveFormatting(paragraph, bodyOffset);

        if (result.Outcome is AutoFormatOutcomeKind.BulletList or AutoFormatOutcomeKind.NumberList)
        {
            _bus.BeginUndoGroup();
            try
            {
                _bus.Execute(new ReplaceParagraphRunsCommand(_caret.Block, p =>
                {
                    var live = ParaCells(p);
                    live.RemoveRange(deleteStart, Math.Min(result.DeleteBefore, live.Count - deleteStart));
                    SetRuns(p, live);
                }));
                var listKind = result.Outcome == AutoFormatOutcomeKind.BulletList
                    ? ListKind.Bullet
                    : ListKind.Number;
                _editingSession.FormatParagraphs(
                    [_caret.Block],
                    formatting => formatting with { ListKind = listKind, ListLevel = 0 });
                _bus.CommitUndoGroup("AutoFormat list");
            }
            catch
            {
                _bus.AbortUndoGroup();
                throw;
            }

            _caret = new DocPosition(_caret.Block, deleteStart);
            _selectionAnchor = _caret;
            return true;
        }

        var replacement = new List<Cell>(result.Insert.Length);
        for (var index = 0; index < result.Insert.Length; index++)
        {
            var fmt = replacementFmt;
            if (result.Outcome == AutoFormatOutcomeKind.SuperscriptSuffix
                && result.SuffixLength > 0
                && index >= result.Insert.Length - 1 - result.SuffixLength
                && index < result.Insert.Length - 1)
            {
                fmt = fmt with { VerticalAlign = VerticalAlign.Superscript };
            }

            LinkInfo? link = null;
            if (result.Outcome == AutoFormatOutcomeKind.Hyperlink
                && result.LinkTarget is { Length: > 0 }
                && index < result.Insert.Length - 1)
            {
                link = new LinkInfo(result.LinkTarget, null, null);
            }

            replacement.Add(new Cell(result.Insert[index], fmt, Link: link));
        }

        _bus.Execute(new ReplaceParagraphRunsCommand(_caret.Block, p =>
        {
            var live = ParaCells(p);
            live.RemoveRange(deleteStart, Math.Min(result.DeleteBefore, live.Count - deleteStart));
            live.InsertRange(deleteStart, replacement);
            SetRuns(p, live);
        }));

        _caret = new DocPosition(_caret.Block, deleteStart + result.Insert.Length);
        _selectionAnchor = _caret;
        return true;
    }

    /// <summary>Test seam for driving the same one-character path used by Avalonia text input.</summary>
    internal void SimulateTextInputForTest(string text)
    {
        foreach (var character in text)
            OnTextInput(new TextInputEventArgs { Text = character.ToString() });
    }

    protected override void OnKeyDown(KeyEventArgs e)
    {
        base.OnKeyDown(e);
        var shift = (e.KeyModifiers & KeyModifiers.Shift) != 0;
        var ctrl = (e.KeyModifiers & (KeyModifiers.Control | KeyModifiers.Meta)) != 0;
        var input = DocumentEditorInteractionSession.PlanBodyKey(
            ToEditorInputKey(e.Key),
            ToEditorInputModifiers(e.KeyModifiers));

        if (e.Key == Key.Apps || e.Key == Key.F10 && e.KeyModifiers == KeyModifiers.Shift)
        {
            if (!TryOpenContentControlMenuAtCaret())
                OpenEditorContextMenu();
            e.Handled = true;
            return;
        }

        if (IsEditingLocked && input.IsEditingMutation)
        {
            e.Handled = true;
            return;
        }

        if (_shapeCaret is { } shapeCaret)
        {
            switch (e.Key)
            {
                case Key.Escape:
                    ExitShapeTextEditing();
                    e.Handled = true;
                    return;
                case Key.Left:
                    MoveShapeTextCaret(-1);
                    e.Handled = true;
                    return;
                case Key.Right:
                    MoveShapeTextCaret(+1);
                    e.Handled = true;
                    return;
                case Key.Home:
                    SetShapeTextCaretOffset(0);
                    e.Handled = true;
                    return;
                case Key.End:
                    SetShapeTextCaretOffset(GetShapeTextLength(shapeCaret));
                    e.Handled = true;
                    return;
                case Key.Enter:
                    InsertShapeTextParagraphBreak();
                    e.Handled = true;
                    return;
                case Key.Back:
                    Backspace();
                    e.Handled = true;
                    return;
                case Key.Delete:
                    DeleteForward();
                    e.Handled = true;
                    return;
                case Key.Z when ctrl:
                    Undo(); e.Handled = true; return;
                case Key.Y when ctrl:
                    Redo(); e.Handled = true; return;
            }
        }

        if (e.Key == Key.Escape && IsFormatPainterArmed)
        {
            CancelFormatPainter();
            e.Handled = true;
            return;
        }

        if (e.Key == Key.Escape && _shapeEditPointsTarget is not null)
        {
            if (_shapeEditPointDragState is not null)
                CancelShapeEditPointDrag();
            else
            {
                _shapeEditPointsTarget = null;
                InvalidateVisual();
            }
            e.Handled = true;
            return;
        }

        // AV-FLSEL: when a float is selected, intercept navigation/delete keys before body text.
        if (_selectedFloating is { } selFloat)
        {
            if (e.Key == Key.F2
                && _selectedFloatingGroupChild is { Kind: "Shape" }
                && EnterSelectedShapeTextEditing())
            {
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Enter)
            {
                if ((selFloat.Kind == "Shape"
                        || _selectedFloatingGroupChild is { Kind: "Shape" })
                    && EnterSelectedShapeTextEditing())
                    e.Handled = true;
                else if (selFloat.Kind != "Shape"
                    && _selectedFloatingGroupChild is not { Kind: "Shape" })
                    e.Handled = true;
                return;
            }

            const double NudgePt = 6; // 6pt ≈ 8px nudge per arrow key press
            switch (e.Key)
            {
                case Key.Escape:
                    // AV-HANDLES: Esc mid-drag cancels the drag (reverts the transient rect) and KEEPS
                    // the selection; a second Esc (no drag in flight) then deselects.
                    if (CancelFloatDrag())
                    {
                        Cursor = Cursor.Default;
                        e.Handled = true;
                        return;
                    }
                    if (_selectedFloatingGroupChild is not null)
                    {
                        _selectedFloatingGroupChild = null;
                        _activeShapeTextChildPath = null;
                        Cursor = Cursor.Default;
                        RaiseFloatingSelectionChangedIfIdentityChanged();
                        InvalidateVisual();
                        e.Handled = true;
                        return;
                    }
                    _selectedFloating = null;
                    _selectedFloatingGroupChild = null;
                    _selectedFloatingObjects.Clear();
                    _floatingDrag.Reset();
                    _shapeEditPointsTarget = null;
                    _shapeEditPointDragState = null;
                    Cursor = Cursor.Default;
                    RaiseFloatingSelectionChangedIfIdentityChanged();
                    InvalidateVisual();
                    e.Handled = true;
                    return;
                case Key.Delete:
                case Key.Back:
                    DeleteSelectedFloating();
                    e.Handled = true;
                    return;
                case Key.Left:
                    NudgeSelectedFloating(-NudgePt, 0);
                    e.Handled = true;
                    return;
                case Key.Right:
                    NudgeSelectedFloating(+NudgePt, 0);
                    e.Handled = true;
                    return;
                case Key.Up:
                    NudgeSelectedFloating(0, -NudgePt);
                    e.Handled = true;
                    return;
                case Key.Down:
                    NudgeSelectedFloating(0, +NudgePt);
                    e.Handled = true;
                    return;
                case Key.Z when ctrl:
                    Undo(); e.Handled = true; return;
                case Key.Y when ctrl:
                    Redo(); e.Handled = true; return;
            }
            // Any other key: pass through (don't consume).
        }

        // AV-HFEDIT: when the caret is in a header/footer region, intercept navigation/exit keys.
        // Editing keys (Back/Delete/Enter) route through the shared methods which already check _hfCaret.
        if (_hfCaret is not null)
        {
            switch (e.Key)
            {
                case Key.Escape:
                    ExitHeaderFooterCaret();
                    e.Handled = true;
                    return;
                case Key.Left:
                    HfMoveCaret(-1); e.Handled = true; return;
                case Key.Right:
                    HfMoveCaret(+1); e.Handled = true; return;
                case Key.Home:
                    _hfCaret = (_hfCaret.Value.Target, 0); InvalidateVisual(); CaretMoved?.Invoke(); e.Handled = true; return;
                case Key.End:
                    _hfCaret = (_hfCaret.Value.Target, HfParaLength(_hfCaret.Value.Target)); InvalidateVisual(); CaretMoved?.Invoke(); e.Handled = true; return;
                case Key.Back: Backspace(); e.Handled = true; return;
                case Key.Delete: DeleteForward(); e.Handled = true; return;
                case Key.Enter: InsertParagraphBreak(); e.Handled = true; return;
                case Key.Z when ctrl: Undo(); e.Handled = true; return;
                case Key.Y when ctrl: Redo(); e.Handled = true; return;
                // DD1 (AV-HFEDIT): Tab/Shift+Tab while H/F caret is active — insert a literal tab into the
                // header/footer and mark handled. This prevents fall-through to the body Tab path which would
                // fire ListTabAtItemStart and mutate body list items (or navigate table cells) instead.
                // Shift+Tab is a no-op (no reverse-tab concept in H/F single-line context) but still consumed
                // so the body list is never touched while the H/F caret is active.
                case Key.Tab:
                    if (!shift) HfInsertText("\t");
                    e.Handled = true; return;
                // DD2 (AV-HFEDIT): Up/Down are consumed as no-ops inside a header/footer.
                // Previously the comment said "no-op for H/F" but both keys fell through to MoveCaretVertical
                // which moved the BODY caret while _hfCaret stayed non-null, leaving the body caret displaced
                // after ExitHeaderFooterCaret(). Intercept here so the body caret never moves during H/F editing.
                case Key.Up:
                case Key.Down:
                    e.Handled = true; return;
            }
            // All other keys fall through to default handling below.
        }

        switch (input.Intent)
        {
            case DocumentEditorInputIntent.Undo: Undo(); e.Handled = true; break;
            case DocumentEditorInputIntent.Redo: Redo(); e.Handled = true; break;
            case DocumentEditorInputIntent.ToggleBold: ToggleBold(); e.Handled = true; break;
            case DocumentEditorInputIntent.ToggleItalic: ToggleItalic(); e.Handled = true; break;
            case DocumentEditorInputIntent.ToggleUnderline: ToggleUnderline(); e.Handled = true; break;
            case DocumentEditorInputIntent.DeleteBackward: Backspace(); e.Handled = true; break;
            case DocumentEditorInputIntent.DeleteForward: DeleteForward(); e.Handled = true; break;
            case DocumentEditorInputIntent.InsertParagraphBreak: InsertParagraphBreak(); e.Handled = true; break;
            case DocumentEditorInputIntent.MovePrevious: MoveCaret(-1, input.ExtendSelection); e.Handled = true; break;
            case DocumentEditorInputIntent.MoveNext: MoveCaret(+1, input.ExtendSelection); e.Handled = true; break;
            case DocumentEditorInputIntent.MoveLineStart: MoveToLineEdge(toStart: true, input.ExtendSelection); e.Handled = true; break;
            case DocumentEditorInputIntent.MoveLineEnd: MoveToLineEdge(toStart: false, input.ExtendSelection); e.Handled = true; break;
            case DocumentEditorInputIntent.MoveLineUp: MoveCaretVertical(-1, input.ExtendSelection); e.Handled = true; break;
            case DocumentEditorInputIntent.MoveLineDown: MoveCaretVertical(+1, input.ExtendSelection); e.Handled = true; break;
            // AV-TBL3: Tab navigates between cells when the caret is in a table; outside a table
            // it handles list demote/promote at item start, or inserts a literal tab character
            // (body-paragraph behaviour, same as before).
            case DocumentEditorInputIntent.NavigateTab:
                if (_cellCaret is not null)
                {
                    TabNavigateCell(forward: !input.ExtendSelection);
                    e.Handled = true;
                }
                else if (ListTabAtItemStart(input.ExtendSelection))
                {
                    // AV-LIST: Tab/Shift+Tab at the start of a list item demotes/promotes.
                    e.Handled = true;
                }
                else if (!input.ExtendSelection)
                {
                    InsertText("\t");
                    e.Handled = true;
                }
                break;
        }
    }

    private static DocumentEditorInputKey ToEditorInputKey(Key key) => key switch
    {
        Key.Back => DocumentEditorInputKey.Backspace,
        Key.Delete => DocumentEditorInputKey.Delete,
        Key.Enter => DocumentEditorInputKey.Enter,
        Key.Tab => DocumentEditorInputKey.Tab,
        Key.Left => DocumentEditorInputKey.Left,
        Key.Right => DocumentEditorInputKey.Right,
        Key.Up => DocumentEditorInputKey.Up,
        Key.Down => DocumentEditorInputKey.Down,
        Key.Home => DocumentEditorInputKey.Home,
        Key.End => DocumentEditorInputKey.End,
        Key.B => DocumentEditorInputKey.B,
        Key.I => DocumentEditorInputKey.I,
        Key.U => DocumentEditorInputKey.U,
        Key.Y => DocumentEditorInputKey.Y,
        Key.Z => DocumentEditorInputKey.Z,
        _ => DocumentEditorInputKey.None,
    };

    private static DocumentEditorInputModifiers ToEditorInputModifiers(KeyModifiers modifiers)
    {
        var result = DocumentEditorInputModifiers.None;
        if ((modifiers & (KeyModifiers.Control | KeyModifiers.Meta)) != 0)
            result |= DocumentEditorInputModifiers.Control;
        if ((modifiers & KeyModifiers.Shift) != 0)
            result |= DocumentEditorInputModifiers.Shift;
        if ((modifiers & KeyModifiers.Alt) != 0)
            result |= DocumentEditorInputModifiers.Alt;
        return result;
    }

    // ---- Editing operations (all via the command bus) -------------------------------------------

    public void InsertText(string text)
    {
        if (IsEditingLocked)
            return;

        if (ShapeTextSelectionInfo is not null)
        {
            ReplaceShapeTextSelection(text);
            return;
        }

        if (_shapeCaret is { } shapeCaret)
        {
            InsertShapeText(shapeCaret, text);
            return;
        }

        // AV-HFEDIT: route into a header/footer region when the caret is inside one.
        if (_hfCaret is not null)
        {
            HfInsertText(text);
            return;
        }

        // AV-TBL: route into table cell when the caret is inside a cell.
        if (SelectedCellRange is not null || HasCellTextSelection())
        {
            // Word treats replacement of a table selection as one edit (the deletion and the typed
            // text undo together). Keep that atomicity for same-cell, cross-cell, and rectangular
            // selections alike.
            var ownsUndoGroup = !_bus.IsUndoGroupOpen;
            if (ownsUndoGroup)
                _bus.BeginUndoGroup();
            try
            {
                if (SelectedCellRange is not null)
                    DeleteSelectedCellBlock(beginUndoGroup: false);
                else if (_cellCaret is { } selectedCell)
                    DeleteCellSelection(selectedCell, beginUndoGroup: false);

                if (_cellCaret is not { } replacementCaret)
                    return;
                var para = GetCellParagraph(replacementCaret.TableBlock, replacementCaret.Row,
                    replacementCaret.Col, replacementCaret.ParaIdx);
                if (para == null || !IsEditable(para))
                    return;
                var offset = replacementCaret.Offset;
                var fmt = ActiveFormatting(para, offset);
                _bus.Execute(new ReplaceCellParagraphRunsCommand(
                    replacementCaret.TableBlock, replacementCaret.Row, replacementCaret.Col,
                    replacementCaret.ParaIdx, p =>
                    {
                        RevisionEditPlanner.InsertText(
                            p,
                            offset,
                            text,
                            fmt,
                            TrackChangesEnabled
                                ? new RevisionEditPlanner.InsertOptions(
                                    RevisionKind.Inserted,
                                    RevisionAuthor,
                                    _editingSession.RevisionDateXmlForEdit())
                                : default);
                    }));
                _cellCaret = replacementCaret with { Offset = offset + text.Length };
                _cellAnchor = _cellCaret;
                _caret = new DocPosition(
                    replacementCaret.TableBlock,
                    FindCellGlyphOffset(replacementCaret.TableBlock, replacementCaret.Row,
                        replacementCaret.Col, replacementCaret.ParaIdx, offset + text.Length));
                _selectionAnchor = _caret;
            }
            finally
            {
                if (ownsUndoGroup)
                    _bus.CommitUndoGroup("Replace table selection");
            }
            return;
        }

        if (_cellCaret is { } cc)
        {
            var para = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx);
            if (para == null || !IsEditable(para))
                return;
            var offset = cc.Offset;
            var fmt = ActiveFormatting(para, offset);
            _bus.Execute(new ReplaceCellParagraphRunsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, p =>
            {
                RevisionEditPlanner.InsertText(
                    p,
                    offset,
                    text,
                    fmt,
                    TrackChangesEnabled
                        ? new RevisionEditPlanner.InsertOptions(
                            RevisionKind.Inserted,
                            RevisionAuthor,
                            _editingSession.RevisionDateXmlForEdit())
                        : default);
            }));
            _cellCaret = cc with { Offset = offset + text.Length };
            _cellAnchor = _cellCaret;
            // Update _caret.Offset to match so TryGetCaretRect can find the sentinel.
            _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, cc.Offset + text.Length));
            _selectionAnchor = _caret;
            return;
        }

        var bodyRange = CurrentBodyTextRange();
        var bodyStart = bodyRange.Normalize().Start;
        if (bodyStart.BlockIndex < 0
            || bodyStart.BlockIndex >= _doc.Blocks.Count
            || _doc.Blocks[bodyStart.BlockIndex] is not Paragraph paragraph
            || !IsEditable(paragraph))
        {
            return;
        }

        var block = bodyStart.BlockIndex;
        var bodyOffset = bodyStart.Offset;
        // BZ5: use pending format if set (from collapsed-caret Font dialog apply), otherwise
        // inherit from the character at the caret position.
        var pendingFmt = _pendingRunFmt;
        _pendingRunFmt = null; // consume immediately so only the next typed char gets it
        var bodyFmt = pendingFmt ?? ActiveFormatting(paragraph, bodyOffset);
        // AV-TRACKEDIT: when Track Changes is on, typed characters are recorded as a tracked insertion
        // (author + date) so they render underlined/coloured and round-trip as w:ins. OFF behaves as before.
        // AV-LINK: typing strictly inside a hyperlink span extends that link (Word's behaviour); typing at a
        // link's edge or outside a link inserts plain (un-linked) text.
        var insLink = ActiveLink(paragraph, bodyOffset);
        var bodyLink = insLink is { } activeLink
            ? new DocumentTextHyperlink(activeLink.Url, activeLink.Anchor, activeLink.Tooltip)
            : (DocumentTextHyperlink?)null;
        if (_editingSession.Body.TryApplyTextInput(
                bodyRange,
                new DocumentBodyTextInput(
                    text,
                    TrackChangesEnabled,
                    bodyFmt,
                    InheritHyperlink: false,
                    Hyperlink: bodyLink),
                out var result))
        {
            _caret = new DocPosition(result.Caret.BlockIndex, result.Caret.Offset);
            _selectionAnchor = _caret;
            return;
        }

        // Structurally special paragraphs stay on the renderer-owned path.
        if (NormalizedSelection() is not null)
            DeleteSelection();
        if (CurrentParagraph() is not { } fallbackParagraph || !IsEditable(fallbackParagraph))
            return;
        block = _caret.Block;
        bodyOffset = _caret.Offset;
        bodyFmt = pendingFmt ?? ActiveFormatting(fallbackParagraph, bodyOffset);
        insLink = ActiveLink(fallbackParagraph, bodyOffset);
        _bus.Execute(new ReplaceParagraphRunsCommand(block, p =>
        {
            // BE4 (body parity): insert at an incrementing position so multi-char text (paste / IME /
            // model inserts like a citation string) keeps its order — a fixed insert index would reverse it.
            RevisionEditPlanner.InsertText(
                p,
                bodyOffset,
                text,
                bodyFmt,
                TrackChangesEnabled
                    ? new RevisionEditPlanner.InsertOptions(
                        RevisionKind.Inserted,
                        RevisionAuthor,
                        _editingSession.RevisionDateXmlForEdit(),
                        insLink?.Url,
                        insLink?.Anchor,
                        insLink?.Tooltip)
                    : new RevisionEditPlanner.InsertOptions(
                        HyperlinkUrl: insLink?.Url,
                        HyperlinkAnchor: insLink?.Anchor,
                        HyperlinkTooltip: insLink?.Tooltip));
            CoalesceAdjacentPlainTextRuns(p);
            CoalesceAdjacentHyperlinkRuns(p);
        }));
        _caret = new DocPosition(block, bodyOffset + text.Length);
        _selectionAnchor = _caret;
    }

    private void InsertShapeText(
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) caret,
        string text)
    {
        if (string.IsNullOrEmpty(text)
            || !TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, caret.TextParagraphIndex, caret.TextRunIndex, out var run))
            return;

        var offset = Math.Clamp(caret.Offset, 0, run.Text.Length);
        _bus.Execute(new SetShapeTextRunCommand(
            caret.BlockIndex,
            caret.RunIndex,
            caret.TextParagraphIndex,
            caret.TextRunIndex,
            run.Text.Insert(offset, text),
            _activeShapeTextChildPath));
        SetShapeTextCaretOffset(offset + text.Length);
        _shapeSelectionAnchor = _shapeCaret;
        InvalidateLayoutAndVisual();
    }

    private int GetShapeTextLength(
        (int BlockIndex, int RunIndex, int TextParagraphIndex, int TextRunIndex, int Offset) caret) =>
        TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, caret.TextParagraphIndex, caret.TextRunIndex, out var run)
            ? run.Text.Length
            : 0;

    private void MoveShapeTextCaret(int delta)
    {
        if (_shapeCaret is not { } caret) return;
        SetShapeTextCaretOffset(caret.Offset + delta);
    }

    private void SetShapeTextCaretOffset(int offset)
    {
        if (_shapeCaret is not { } caret
            || !TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, caret.TextParagraphIndex, caret.TextRunIndex, out var run))
            return;

        _shapeCaret = caret with { Offset = Math.Clamp(offset, 0, run.Text.Length) };
        _shapeSelectionAnchor = _shapeCaret;
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    private void DeleteShapeText(bool backward)
    {
        if (ShapeTextSelectionInfo is not null)
        {
            ReplaceShapeTextSelection(string.Empty);
            return;
        }

        if (_shapeCaret is not { } caret
            || !TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, caret.TextParagraphIndex, caret.TextRunIndex, out var run))
            return;

        var offset = Math.Clamp(caret.Offset, 0, run.Text.Length);
        if (backward && offset == 0 && caret.TextParagraphIndex > 0)
        {
            _bus.Execute(new MergeShapeTextParagraphWithPreviousCommand(
                caret.BlockIndex,
                caret.RunIndex,
                caret.TextParagraphIndex,
                _activeShapeTextChildPath));

            var previousParagraphIndex = caret.TextParagraphIndex - 1;
            if (TryGetShapeTextRun(caret.BlockIndex, caret.RunIndex, previousParagraphIndex, 0, out var previousRun))
            {
                _shapeCaret = caret with
                {
                    TextParagraphIndex = previousParagraphIndex,
                    TextRunIndex = 0,
                    Offset = previousRun.Text.Length
                };
                _shapeSelectionAnchor = _shapeCaret;
            }

            InvalidateLayoutAndVisual();
            CaretMoved?.Invoke();
            return;
        }

        var deleteAt = backward ? offset - 1 : offset;
        if (deleteAt < 0 || deleteAt >= run.Text.Length) return;

        _bus.Execute(new SetShapeTextRunCommand(
            caret.BlockIndex,
            caret.RunIndex,
            caret.TextParagraphIndex,
            caret.TextRunIndex,
            run.Text.Remove(deleteAt, 1),
            _activeShapeTextChildPath));
        SetShapeTextCaretOffset(backward ? deleteAt : offset);
        _shapeSelectionAnchor = _shapeCaret;
        InvalidateLayoutAndVisual();
    }

    // Avalonia's model edit planner splits a run at every insertion boundary. WPF's text surface
    // coalesces adjacent ordinary runs with the same formatting, so keep the model representation
    // equivalent while preserving boundaries that carry links, revisions, comments, or objects.
    private static void CoalesceAdjacentPlainTextRuns(Paragraph paragraph)
    {
        for (var index = 0; index < paragraph.Runs.Count - 1; index++)
        {
            var left = paragraph.Runs[index];
            var right = paragraph.Runs[index + 1];
            if (!IsPlainTextRun(left) || !IsPlainTextRun(right)
                || !left.Formatting.Equals(right.Formatting))
                continue;

            paragraph.Runs[index] = RevisionEditPlanner.CloneRunWithText(left, left.Text + right.Text);
            paragraph.Runs.RemoveAt(index + 1);
            index--;
        }
    }

    private static bool IsPlainTextRun(Run run) =>
        run.Text.Length > 0
        && run.Image is null
        && run.Equation is null
        && run.Shape is null
        && run.WordArt is null
        && run.Ruby is null
        && run.Chart is null
        && run.EmbeddedObject is null
        && run.SmartArt is null
        && run.PreservedDrawing is null
        && run.DrawingGroup is null
        && run.HyperlinkUrl is null
        && run.HyperlinkAnchor is null
        && run.HyperlinkTooltip is null
        && run.FieldKind == RunFieldKind.None
        && run.TableFormula is null
        && run.Citation is null
        && run.CrossReference is null
        && run.ComplexField is null
        && run.FootnoteId is null
        && run.EndnoteId is null
        && run.CommentId is null
        && !run.IsCommentReference
        && !run.IsPageBreak
        && !run.IsColumnBreak
        && run.Revision == RevisionKind.None
        && run.Control is null
        && run.FormatRevision is null;

    /// <summary>
    /// Word keeps ordinary text typed inside one hyperlink as one contiguous link span. The shared edit
    /// planner intentionally splits runs at the insertion boundary, so restore that representation here
    /// for plain hyperlink runs only. Revision, field, drawing, comment, and content-control runs remain
    /// separate because their boundaries carry document semantics.
    /// </summary>
    private static void CoalesceAdjacentHyperlinkRuns(Paragraph paragraph)
    {
        for (var index = 0; index < paragraph.Runs.Count - 1; index++)
        {
            var left = paragraph.Runs[index];
            var right = paragraph.Runs[index + 1];
            if (!CanCoalesceHyperlinkRuns(left, right))
                continue;

            paragraph.Runs[index] = RevisionEditPlanner.CloneRunWithText(left, left.Text + right.Text);
            paragraph.Runs.RemoveAt(index + 1);
            index--;
        }
    }

    private static bool CanCoalesceHyperlinkRuns(Run left, Run right) =>
        left.Text.Length > 0
        && right.Text.Length > 0
        && (left.HyperlinkUrl is { Length: > 0 } || left.HyperlinkAnchor is { Length: > 0 })
        && (right.HyperlinkUrl is { Length: > 0 } || right.HyperlinkAnchor is { Length: > 0 })
        && string.Equals(left.HyperlinkUrl, right.HyperlinkUrl, StringComparison.Ordinal)
        && string.Equals(left.HyperlinkAnchor, right.HyperlinkAnchor, StringComparison.Ordinal)
        && string.Equals(left.HyperlinkTooltip, right.HyperlinkTooltip, StringComparison.Ordinal)
        && left.Formatting.Equals(right.Formatting)
        && left.Image is null && right.Image is null
        && left.Equation is null && right.Equation is null
        && left.Shape is null && right.Shape is null
        && left.WordArt is null && right.WordArt is null
        && left.Ruby is null && right.Ruby is null
        && left.Chart is null && right.Chart is null
        && left.EmbeddedObject is null && right.EmbeddedObject is null
        && left.SmartArt is null && right.SmartArt is null
        && left.PreservedDrawing is null && right.PreservedDrawing is null
        && left.DrawingGroup is null && right.DrawingGroup is null
        && left.FieldKind == RunFieldKind.None && right.FieldKind == RunFieldKind.None
        && left.TableFormula is null && right.TableFormula is null
        && left.Citation is null && right.Citation is null
        && left.CrossReference is null && right.CrossReference is null
        && left.ComplexField is null && right.ComplexField is null
        && left.FootnoteId is null && right.FootnoteId is null
        && left.EndnoteId is null && right.EndnoteId is null
        && left.CommentId is null && right.CommentId is null
        && !left.IsCommentReference && !right.IsCommentReference
        && !left.IsPageBreak && !right.IsPageBreak
        && !left.IsColumnBreak && !right.IsColumnBreak
        && left.Revision == RevisionKind.None && right.Revision == RevisionKind.None
        && left.Control is null && right.Control is null
        && left.MoveRevisionId is null && right.MoveRevisionId is null
        && left.FormatRevision is null && right.FormatRevision is null;

    /// <summary>
    /// Inserts a plain-text content control at the body caret. A selected body range becomes the control
    /// content; an empty caret gets Word's default prompt text.
    /// </summary>
    public void InsertPlainTextControl(string? tag = null, string? alias = null)
    {
        InsertBodyContentControlRun(Run.PlainTextControl(
            ContentControlInteractionPlanner.PromptText(SelectedText),
            tag,
            alias));
    }

    /// <summary>Inserts an unchecked checkbox content control at the body caret.</summary>
    public void InsertCheckBoxControl(string? tag = null, string? alias = null) =>
        InsertBodyContentControlRun(Run.CheckBoxControl(@checked: false, tag, alias));

    /// <summary>
    /// Inserts a rich-text content control at the body caret. A selected body range becomes the control
    /// content; an empty caret gets Word's default prompt text.
    /// </summary>
    public void InsertRichTextControl(string? tag = null, string? alias = null)
    {
        InsertBodyContentControlRun(Run.RichTextControl(
            ContentControlInteractionPlanner.PromptText(SelectedText),
            tag,
            alias));
    }

    /// <summary>Inserts a date-picker content control at the body caret.</summary>
    public void InsertDatePickerControl(string? tag = null, string? alias = null, string? dateFormat = null)
    {
        var format = ContentControlInteractionPlanner.DateFormatOrDefault(dateFormat);
        var today = ContentControlInteractionPlanner.FormatDate(format, DateTime.Today);
        InsertBodyContentControlRun(Run.DatePickerControl(today, tag, alias, format));
    }

    /// <summary>Inserts a drop-down-list content control at the body caret.</summary>
    public void InsertDropDownListControl(
        IReadOnlyList<ContentControlListItem>? items = null,
        string? tag = null,
        string? alias = null) =>
        InsertBodyContentControlRun(Run.DropDownListControl(
            ContentControlInteractionPlanner.ListItemsOrDefault(items),
            tag: tag,
            alias: alias));

    /// <summary>Inserts a combo-box content control at the body caret.</summary>
    public void InsertComboBoxControl(
        IReadOnlyList<ContentControlListItem>? items = null,
        string? tag = null,
        string? alias = null) =>
        InsertBodyContentControlRun(Run.ComboBoxControl(
            ContentControlInteractionPlanner.ListItemsOrDefault(items),
            tag: tag,
            alias: alias));

    public bool ToggleContentControl(int blockIndex, int runIndex) =>
        ApplyContentControlInteraction(
            new ContentControlTarget(blockIndex, runIndex),
            ContentControlInteractionPlanner.ToggleCheckBox);

    public bool SelectContentControlItem(int blockIndex, int runIndex, int itemIndex) =>
        ApplyContentControlInteraction(new ContentControlTarget(blockIndex, runIndex), run =>
            ContentControlInteractionPlanner.SelectItem(run, itemIndex));

    public bool SelectContentControlRelativeDate(int blockIndex, int runIndex, int choiceIndex) =>
        ApplyContentControlInteraction(new ContentControlTarget(blockIndex, runIndex), run =>
            ContentControlInteractionPlanner.SelectRelativeDate(run, choiceIndex));

    private bool ApplyContentControlInteraction(ContentControlTarget target, Func<Run, Run?> planner)
    {
        Paragraph? paragraph;
        if (target.Row is { } row && target.Column is { } column && target.ParagraphIndex is { } paragraphIndex)
            paragraph = GetCellParagraph(target.BlockIndex, row, column, paragraphIndex);
        else if (target.BlockIndex >= 0
            && target.BlockIndex < _doc.Blocks.Count
            && _doc.Blocks[target.BlockIndex] is Paragraph bodyParagraph)
            paragraph = bodyParagraph;
        else
            paragraph = null;

        if (paragraph is null || target.RunIndex < 0 || target.RunIndex >= paragraph.Runs.Count)
        {
            return false;
        }

        var current = paragraph.Runs[target.RunIndex];
        if (!ContentControlInteractionPlanner.CanEditExistingContentControl(current, RestrictEditingPolicy))
            return false;

        var updated = planner(current);
        if (updated is null)
            return false;

        if (target.Row is { } targetRow
            && target.Column is { } targetColumn
            && target.ParagraphIndex is { } targetParagraph)
        {
            _bus.Execute(new ReplaceCellParagraphRunsCommand(
                target.BlockIndex,
                targetRow,
                targetColumn,
                targetParagraph,
                cellParagraph => cellParagraph.Runs[target.RunIndex] = updated));
        }
        else
        {
            ReferenceEdits.ReplaceContentControlRun(target.BlockIndex, target.RunIndex, updated);
        }
        return true;
    }

    private void InsertBodyContentControlRun(Run run)
    {
        if (IsEditingLocked || _hfCaret is not null || _cellCaret is not null)
            return;

        if (NormalizedSelection() is not null)
            DeleteSelection();
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;

        var block = _caret.Block;
        var offset = _caret.Offset;
        _bus.Execute(new ReplaceParagraphRunsCommand(block, p => InsertRunAtOffset(p, offset, run)));
        _caret = new DocPosition(block, offset + run.Text.Length);
        _selectionAnchor = _caret;
    }

    private void Backspace()
    {
        if (IsEditingLocked)
            return;

        if (_shapeCaret is not null)
        {
            DeleteShapeText(backward: true);
            return;
        }

        // AV-HFEDIT: route into a header/footer region.
        if (_hfCaret is not null)
        {
            HfBackspace();
            return;
        }

        // AV-TBL: route into table cell.
        if (SelectedCellRange is not null)
        {
            DeleteSelectedCellBlock();
            return;
        }

        if (_cellCaret is { } cc)
        {
            // Delete any in-cell, cross-paragraph, or cross-cell selection as one edit.
            if (DeleteCellSelection(cc)) return;
            cc = _cellCaret!.Value; // re-read in case anchor was updated
            if (cc.Offset > 0)
            {
                var offset = cc.Offset;
                _bus.Execute(new ReplaceCellParagraphRunsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, p =>
                {
                    if (TrackChangesEnabled)
                    {
                        var (marked, _) = MarkCellsDeleted(ParaCells(p), offset - 1, offset);
                        SetRuns(p, marked);
                        return;
                    }
                    var chars = ParaCells(p);
                    if (offset - 1 < chars.Count)
                        chars.RemoveAt(offset - 1);
                    SetRuns(p, chars);
                }));
                _cellCaret = cc with { Offset = offset - 1 };
                _cellAnchor = _cellCaret;
                _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, cc.Offset - 1));
                _selectionAnchor = _caret;
            }
            else if (cc.ParaIdx > 0)
            {
                // At start of a non-first paragraph in a cell → merge with previous paragraph.
                if (TrackChangesEnabled)
                {
                    _bus.Execute(new SetCellParagraphMarkRevisionCommand(
                        cc.TableBlock,
                        cc.Row,
                        cc.Col,
                        cc.ParaIdx - 1,
                        RevisionKind.Deleted,
                        RevisionAuthor,
                        _editingSession.RevisionDateXmlForEdit()));
                }
                else
                {
                    CellMergeWithPreviousParagraph(cc);
                }
            }
            // else: at start of first paragraph in cell → do nothing (can't go back past cell boundary)
            return;
        }

        if (_editingSession.Body.TryApplyDeletion(
                CurrentBodyTextRange(),
                DocumentBodyDeleteDirection.Backward,
                TrackChangesEnabled,
                mergeForwardBoundary: false,
                out var bodyResult))
        {
            _caret = new DocPosition(bodyResult.Caret.BlockIndex, bodyResult.Caret.Offset);
            _selectionAnchor = _caret;
            return;
        }

        if (NormalizedSelection() is not null) { DeleteSelection(); return; }
        if (TrackChangesEnabled)
            return;

        // Structurally special paragraphs stay on the renderer-owned path.
        if (_caret.Offset > 0)
        {
            var block = _caret.Block;
            var offset = _caret.Offset;
            _bus.Execute(new ReplaceParagraphRunsCommand(block, p =>
            {
                var cells = ParaCells(p);
                if (offset - 1 < cells.Count)
                    cells.RemoveAt(offset - 1);
                SetRuns(p, cells);
            }));
            _caret = new DocPosition(block, offset - 1);
            _selectionAnchor = _caret;
        }
        else
            MergeWithPrevious();
    }

    private void DeleteForward()
    {
        if (IsEditingLocked)
            return;

        if (_shapeCaret is not null)
        {
            DeleteShapeText(backward: false);
            return;
        }

        // AV-HFEDIT: route into a header/footer region.
        if (_hfCaret is not null)
        {
            HfDeleteForward();
            return;
        }

        // AV-TBL: route into table cell.
        if (SelectedCellRange is not null)
        {
            DeleteSelectedCellBlock();
            return;
        }

        if (_cellCaret is { } cc)
        {
            // Delete any in-cell, cross-paragraph, or cross-cell selection as one edit.
            if (DeleteCellSelection(cc)) return;
            cc = _cellCaret!.Value; // re-read after potential anchor update
            var para = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx);
            if (para == null || !IsEditable(para))
                return;
            var len = ParaCells(para).Count;
            if (cc.Offset < len)
            {
                var offset = cc.Offset;
                if (TrackChangesEnabled)
                {
                    var before = ParaCells(para);
                    var ownInsertion = offset < before.Count
                        && before[offset].Revision == RevisionKind.Inserted
                        && string.Equals(before[offset].RevisionAuthor, RevisionAuthor, StringComparison.Ordinal);
                    _bus.Execute(new ReplaceCellParagraphRunsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, p =>
                    {
                        var (marked, _) = MarkCellsDeleted(ParaCells(p), offset, offset + 1);
                        SetRuns(p, marked);
                    }));
                    // Advance past a kept-struck char so repeated Delete progresses; stay put if it collapsed.
                    if (!ownInsertion)
                    {
                        _cellCaret = cc with { Offset = offset + 1 };
                        _cellAnchor = _cellCaret;
                        _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, offset + 1));
                        _selectionAnchor = _caret;
                    }
                }
                else
                {
                    _bus.Execute(new ReplaceCellParagraphRunsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, p =>
                    {
                        var chars = ParaCells(p);
                        if (offset < chars.Count)
                            chars.RemoveAt(offset);
                        SetRuns(p, chars);
                    }));
                    // Caret stays at same offset (now pointing at the next char).
                }
            }
            // else at end of paragraph → delete paragraph break (join with next paragraph in cell)
            else
            {
                var cellModel = GetCellModel(cc.TableBlock, cc.Row, cc.Col);
                if (cellModel != null && cc.ParaIdx < cellModel.Paragraphs.Count - 1)
                {
                    if (TrackChangesEnabled)
                    {
                        _bus.Execute(new SetCellParagraphMarkRevisionCommand(
                            cc.TableBlock,
                            cc.Row,
                            cc.Col,
                            cc.ParaIdx,
                            RevisionKind.Deleted,
                            RevisionAuthor,
                            _editingSession.RevisionDateXmlForEdit()));
                        return;
                    }

                    // Merge current para + next para in cell.
                    var curPara = cellModel.Paragraphs[cc.ParaIdx];
                    var nextPara = cellModel.Paragraphs[cc.ParaIdx + 1];
                    var merged = new Paragraph { Formatting = curPara.Formatting, StyleId = curPara.StyleId };
                    var mergedCells = ParaCells(curPara);
                    mergedCells.AddRange(ParaCells(nextPara));
                    SetRuns(merged, mergedCells);
                    _bus.Execute(new SpliceCellParagraphsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, 2, [merged]));
                }
            }
            return;
        }

        if (_editingSession.Body.TryApplyDeletion(
                CurrentBodyTextRange(),
                DocumentBodyDeleteDirection.Forward,
                TrackChangesEnabled,
                mergeForwardBoundary: false,
                out var bodyResult))
        {
            _caret = new DocPosition(bodyResult.Caret.BlockIndex, bodyResult.Caret.Offset);
            _selectionAnchor = _caret;
            return;
        }

        if (NormalizedSelection() is not null) { DeleteSelection(); return; }
        if (TrackChangesEnabled)
            return;

        // Structurally special paragraphs stay on the renderer-owned path.
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        var bodyLen = ParaCells(paragraph).Count;
        if (_caret.Offset < bodyLen)
        {
            var block = _caret.Block;
            var offset = _caret.Offset;
            _bus.Execute(new ReplaceParagraphRunsCommand(block, p =>
            {
                var cells = ParaCells(p);
                if (offset < cells.Count)
                    cells.RemoveAt(offset);
                SetRuns(p, cells);
            }));
        }
    }

    private void InsertParagraphBreak()
    {
        if (IsEditingLocked)
            return;

        // AV-HFEDIT: route into a header/footer region.
        if (_hfCaret is not null)
        {
            HfInsertParagraphBreak();
            return;
        }

        // AV-TBL: deletion plus Enter is one replacement edit in Word. Keep the outer group owned by
        // this operation (or join a paste/dialog group already in progress) so the two model commands
        // undo together.
        if (SelectedCellRange is not null || HasCellTextSelection())
        {
            var ownsUndoGroup = !_bus.IsUndoGroupOpen;
            if (ownsUndoGroup)
                _bus.BeginUndoGroup();
            try
            {
                if (SelectedCellRange is not null)
                    DeleteSelectedCellBlock(beginUndoGroup: false);
                if (_cellCaret is not { } selectedCaret)
                    return;
                if (HasCellTextSelection() && DeleteCellSelection(selectedCaret, beginUndoGroup: false))
                    selectedCaret = _cellCaret!.Value;

                var para = GetCellParagraph(selectedCaret.TableBlock, selectedCaret.Row,
                    selectedCaret.Col, selectedCaret.ParaIdx);
                if (para == null || !IsEditable(para))
                    return;
                var chars = ParaCells(para);
                var first = new Paragraph { Formatting = para.Formatting, StyleId = para.StyleId };
                SetRuns(first, chars.Take(selectedCaret.Offset).ToList());
                var second = new Paragraph { Formatting = para.Formatting };
                SetRuns(second, chars.Skip(selectedCaret.Offset).ToList());
                _bus.Execute(new SpliceCellParagraphsCommand(
                    selectedCaret.TableBlock, selectedCaret.Row, selectedCaret.Col,
                    selectedCaret.ParaIdx, 1, [first, second]));
                _cellCaret = selectedCaret with { ParaIdx = selectedCaret.ParaIdx + 1, Offset = 0 };
                _cellAnchor = _cellCaret;
                _caret = new DocPosition(selectedCaret.TableBlock,
                    FindCellGlyphOffset(selectedCaret.TableBlock, selectedCaret.Row, selectedCaret.Col,
                        selectedCaret.ParaIdx + 1, 0));
                _selectionAnchor = _caret;
            }
            finally
            {
                if (ownsUndoGroup)
                    _bus.CommitUndoGroup("Replace table selection with paragraph break");
            }
            return;
        }

        // AV-TBL: route into table cell.
        if (_cellCaret is { } cc)
        {
            if (DeleteCellSelection(cc))
                cc = _cellCaret!.Value;
            var para = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx);
            if (para == null || !IsEditable(para))
                return;
            var offset = cc.Offset;
            var chars = ParaCells(para);
            var first = new Paragraph { Formatting = para.Formatting, StyleId = para.StyleId };
            SetRuns(first, chars.Take(offset).ToList());
            var second = new Paragraph { Formatting = para.Formatting };
            SetRuns(second, chars.Skip(offset).ToList());
            _bus.Execute(new SpliceCellParagraphsCommand(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, 1, [first, second]));
            // Move caret to start of the new second paragraph.
            _cellCaret = cc with { ParaIdx = cc.ParaIdx + 1, Offset = 0 };
            _cellAnchor = _cellCaret;
            _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx + 1, 0));
            _selectionAnchor = _caret;
            return;
        }

        var bodyRange = CurrentBodyTextRange();
        if (_editingSession.Body.TryApplyParagraphBreak(bodyRange, out var bodyResult))
        {
            _caret = new DocPosition(bodyResult.Caret.BlockIndex, bodyResult.Caret.Offset);
            _selectionAnchor = _caret;
            return;
        }

        if (NormalizedSelection() is not null)
            DeleteSelection();
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;

        var block = _caret.Block;
        var bodyOffset = _caret.Offset;
        var bodyCells = ParaCells(paragraph);

        // AV-LIST: list continuation / exit-list logic.
        var listFmt = paragraph.Formatting;
        if (listFmt.ListKind != ListKind.None)
        {
            if (bodyCells.Count == 0)
            {
                // Enter on an EMPTY list item → exit the list: turn the paragraph into a normal one.
                var exitFmt = listFmt with { ListKind = ListKind.None, ListLevel = 0 };
                _editingSession.FormatParagraphs([block], _ => exitFmt);
                // Caret stays at block 0 (now a normal paragraph). No split.
                return;
            }
            // Enter on a NON-EMPTY list item → split and continue the list on the new paragraph.
            // The new paragraph inherits ListKind + ListLevel (not StyleId, same as Word).
            var firstPara = new Paragraph { Formatting = listFmt, StyleId = paragraph.StyleId };
            SetRuns(firstPara, bodyCells.Take(bodyOffset).ToList());
            var contFmt = listFmt with { };   // same list kind + level; renumbering is render-time
            var secondPara = new Paragraph { Formatting = contFmt };
            SetRuns(secondPara, bodyCells.Skip(bodyOffset).ToList());
            _bus.Execute(new ReplaceBlocksCommand(block, 1, new Block[] { firstPara, secondPara }));
            _caret = new DocPosition(block + 1, 0);
            _selectionAnchor = _caret;
            return;
        }

        var firstParaNL = new Paragraph { Formatting = paragraph.Formatting, StyleId = paragraph.StyleId };
        SetRuns(firstParaNL, bodyCells.Take(bodyOffset).ToList());
        var secondParaNL = new Paragraph { Formatting = paragraph.Formatting };
        SetRuns(secondParaNL, bodyCells.Skip(bodyOffset).ToList());
        _bus.Execute(new ReplaceBlocksCommand(block, 1, new Block[] { firstParaNL, secondParaNL }));
        _caret = new DocPosition(block + 1, 0);
        _selectionAnchor = _caret;
    }

    // AV-TBL: merge the current cell paragraph with the previous one (Backspace at start of para).
    private void CellMergeWithPreviousParagraph((int TableBlock, int Row, int Col, int ParaIdx, int Offset) cc)
    {
        var prevParaIdx = cc.ParaIdx - 1;
        var prevPara = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, prevParaIdx);
        var curPara = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx);
        if (prevPara == null || curPara == null)
            return;
        var prevLen = ParaCells(prevPara).Count;
        var merged = new Paragraph { Formatting = prevPara.Formatting, StyleId = prevPara.StyleId };
        var mergedCells = ParaCells(prevPara);
        mergedCells.AddRange(ParaCells(curPara));
        SetRuns(merged, mergedCells);
        _bus.Execute(new SpliceCellParagraphsCommand(cc.TableBlock, cc.Row, cc.Col, prevParaIdx, 2, [merged]));
        _cellCaret = cc with { ParaIdx = prevParaIdx, Offset = prevLen };
        _cellAnchor = _cellCaret;
        _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, prevParaIdx, prevLen));
        _selectionAnchor = _caret;
    }

    private void MergeWithPrevious()
    {
        var block = _caret.Block;
        var prev = PreviousEditableBlock(block);
        if (prev < 0 || _doc.Blocks[prev] is not Paragraph prevPara || _doc.Blocks[block] is not Paragraph curPara)
            return;
        var prevCells = ParaCells(prevPara);
        var prevLen = prevCells.Count;
        var merged = new Paragraph { Formatting = prevPara.Formatting, StyleId = prevPara.StyleId };
        prevCells.AddRange(ParaCells(curPara));
        SetRuns(merged, prevCells);
        _bus.Execute(new ReplaceBlocksCommand(prev, block - prev + 1, new Block[] { merged }));
        _caret = new DocPosition(prev, prevLen);
        _selectionAnchor = _caret;
    }

    // AV-TBL-DELETE: Word's RichTextBox selection editor deletes text across paragraph and cell
    // boundaries without deleting the table structure. A rectangular cell selection is a separate
    // state from a text selection, so both routes converge here and are committed as one undo edit.
    private bool HasCellTextSelection() =>
        _cellAnchor is { } anchor
        && _cellCaret is { } caret
        && CompareCellEndpoints(anchor, caret) != 0;

    private bool DeleteCellSelection(
        (int TableBlock, int Row, int Col, int ParaIdx, int Offset) cc,
        bool beginUndoGroup = true)
    {
        if (SelectedCellRange is not null)
            return DeleteSelectedCellBlock(beginUndoGroup);

        if (_cellAnchor is not { } anchor
            || anchor.TableBlock != cc.TableBlock
            || CompareCellEndpoints(anchor, cc) == 0)
            return false;

        if (_doc.Blocks[cc.TableBlock] is not Table table)
            return false;

        var start = anchor;
        var end = cc;
        if (CompareCellEndpoints(start, end) > 0)
            (start, end) = (end, start);

        var startEntry = CanonicalCellEntry(table, start.TableBlock, start.Row, start.Col);
        var endEntry = CanonicalCellEntry(table, end.TableBlock, end.Row, end.Col);
        if (startEntry is not { } first || endEntry is not { } last)
            return false;

        var ownsUndoGroup = beginUndoGroup && !_bus.IsUndoGroupOpen;
        if (ownsUndoGroup)
            _bus.BeginUndoGroup();
        var handled = false;
        try
        {
            if (ReferenceEquals(first.Cell, last.Cell))
                handled = DeleteWithinCell(first, start.ParaIdx, start.Offset, end.ParaIdx, end.Offset);
            else
                handled = DeleteAcrossCells(table, first, last, end.Offset);
        }
        finally
        {
            if (ownsUndoGroup)
                _bus.CommitUndoGroup("Delete table selection");
        }

        if (!handled)
            return false;

        var collapsedParaIndex = ReferenceEquals(first.Cell, last.Cell) ? start.ParaIdx : 0;
        var collapsedOffset = ReferenceEquals(first.Cell, last.Cell)
            ? Math.Clamp(start.Offset, 0, ParaLength(first.Cell, collapsedParaIndex))
            : 0;
        _cellCaret = (start.TableBlock, first.Row, first.Col, collapsedParaIndex, collapsedOffset);
        _cellAnchor = _cellCaret;
        _caret = new DocPosition(
            start.TableBlock,
            FindCellGlyphOffset(start.TableBlock, first.Row, first.Col, collapsedParaIndex, collapsedOffset));
        _selectionAnchor = _caret;
        return true;
    }

    private bool DeleteSelectedCellBlock(bool beginUndoGroup = true)
    {
        if (SelectedCellRange is not { } selection
            || selection.TableBlock < 0
            || selection.TableBlock >= _doc.Blocks.Count
            || _doc.Blocks[selection.TableBlock] is not Table table)
            return false;

        var targets = new List<TableCellEntry>();
        var visited = new HashSet<TableCell>();
        for (var rowIndex = selection.MinRow; rowIndex <= selection.MaxRow && rowIndex < table.Rows.Count; rowIndex++)
        {
            var row = table.Rows[rowIndex];
            foreach (var projected in TableGridProjection.ProjectRow(row))
            {
                var overlaps = projected.StartColumn <= selection.MaxCol
                    && projected.EndColumnExclusive - 1 >= selection.MinCol
                    && projected.Cell.VerticalMerge != VerticalMergeState.Continue;
                if (overlaps && visited.Add(projected.Cell))
                    targets.Add(new TableCellEntry(
                        selection.TableBlock,
                        rowIndex,
                        projected.StartColumn,
                        projected.Cell));
            }
        }

        if (targets.Count == 0)
            return false;

        var ownsUndoGroup = beginUndoGroup && !_bus.IsUndoGroupOpen;
        if (ownsUndoGroup)
            _bus.BeginUndoGroup();
        try
        {
            foreach (var target in targets)
                DeleteWholeCell(target);
        }
        finally
        {
            if (ownsUndoGroup)
                _bus.CommitUndoGroup("Delete table block");
        }

        _cellBlockAnchor = null;
        _cellBlockFocus = null;
        var caretEntry = CanonicalCellEntry(table, selection.TableBlock, selection.MinRow, selection.MinCol);
        if (caretEntry is { } entry)
            PlaceCaretInCell(selection.TableBlock, entry.Row, entry.Col, 0, 0);
        else
            ClampCaret();
        return true;
    }

    private bool DeleteWithinCell(
        TableCellEntry entry,
        int startParaIndex,
        int startOffset,
        int endParaIndex,
        int endOffset)
    {
        var cell = entry.Cell;
        if (cell.Paragraphs.Count == 0)
            return false;
        startParaIndex = Math.Clamp(startParaIndex, 0, cell.Paragraphs.Count - 1);
        endParaIndex = Math.Clamp(endParaIndex, startParaIndex, cell.Paragraphs.Count - 1);
        startOffset = Math.Clamp(startOffset, 0, ParaCells(cell.Paragraphs[startParaIndex]).Count);
        endOffset = Math.Clamp(endOffset, 0, ParaCells(cell.Paragraphs[endParaIndex]).Count);

        if (TrackChangesEnabled)
        {
            for (var paraIndex = startParaIndex; paraIndex <= endParaIndex; paraIndex++)
            {
                var para = cell.Paragraphs[paraIndex];
                var cells = ParaCells(para);
                var lo = paraIndex == startParaIndex ? startOffset : 0;
                var hi = paraIndex == endParaIndex ? endOffset : cells.Count;
                if (hi <= lo)
                    continue;
                _bus.Execute(new ReplaceCellParagraphRunsCommand(
                    entry.TableBlock, entry.Row, entry.Col, paraIndex,
                    p =>
                    {
                        var (marked, _) = MarkCellsDeleted(ParaCells(p), lo, hi);
                        SetRuns(p, marked);
                    }));
            }
            return endParaIndex > startParaIndex || endOffset > startOffset;
        }

        var startPara = cell.Paragraphs[startParaIndex];
        var endPara = cell.Paragraphs[endParaIndex];
        var mergedCells = ParaCells(startPara).Take(startOffset).ToList();
        mergedCells.AddRange(ParaCells(endPara).Skip(endOffset));
        var merged = ParagraphWithFormatting(startPara);
        SetRuns(merged, mergedCells);
        _bus.Execute(new SpliceCellParagraphsCommand(
            entry.TableBlock,
            entry.Row,
            entry.Col,
            startParaIndex,
            endParaIndex - startParaIndex + 1,
            [merged]));
        return true;
    }

    private bool DeleteAcrossCells(
        Table table,
        TableCellEntry startEntry,
        TableCellEntry endEntry,
        int endOffset)
    {
        var entries = EnumerateLogicalCells(table, startEntry.TableBlock).ToList();
        var startIndex = entries.FindIndex(entry => ReferenceEquals(entry.Cell, startEntry.Cell));
        var endIndex = entries.FindIndex(entry => ReferenceEquals(entry.Cell, endEntry.Cell));
        if (startIndex < 0 || endIndex < 0 || startIndex >= endIndex)
            return false;

        // WPF RichTextBox normalizes a text selection that crosses a cell boundary to whole logical
        // cells. The final cell is included when the endpoint is inside its text; an endpoint at zero
        // is the boundary before that cell. Preserve the table graph while clearing those cells.
        var lastSelectedIndex = endOffset > 0 ? endIndex : endIndex - 1;
        if (lastSelectedIndex < startIndex)
            return false;

        for (var index = startIndex; index <= lastSelectedIndex; index++)
            DeleteWholeCell(entries[index]);
        return true;
    }

    private bool DeleteCellCharactersAsRevision(TableCellEntry entry, int paraIndex, int lo, int hi)
    {
        if (hi <= lo)
            return false;
        _bus.Execute(new ReplaceCellParagraphRunsCommand(
            entry.TableBlock, entry.Row, entry.Col, paraIndex,
            p =>
            {
                var (marked, _) = MarkCellsDeleted(ParaCells(p), lo, hi);
                SetRuns(p, marked);
            }));
        return true;
    }

    private bool DeleteWholeCell(TableCellEntry entry)
    {
        if (entry.Cell.Paragraphs.Count == 0)
            return false;

        if (TrackChangesEnabled)
        {
            var mutated = false;
            for (var paraIndex = 0; paraIndex < entry.Cell.Paragraphs.Count; paraIndex++)
                mutated |= DeleteCellCharactersAsRevision(
                    entry,
                    paraIndex,
                    0,
                    ParaLength(entry.Cell, paraIndex));
            return mutated;
        }

        if (entry.Cell.Paragraphs.Count == 1 && ParaLength(entry.Cell, 0) == 0)
            return false;

        var first = entry.Cell.Paragraphs[0];
        var empty = ParagraphWithFormatting(first);
        _bus.Execute(new SpliceCellParagraphsCommand(
            entry.TableBlock, entry.Row, entry.Col, 0, entry.Cell.Paragraphs.Count, [empty]));
        return true;
    }

    private static Paragraph ParagraphWithFormatting(Paragraph source)
    {
        // This shell is intentionally local to same-document deletion. The source paragraph is
        // consumed by the splice command, so retaining its mutable section/revision metadata does
        // not create a second live owner. DocumentMerge's independent-clone contract remains deep.
        var clone = new Paragraph
        {
            BlockContentControl = source.BlockContentControl,
            Formatting = source.Formatting,
            StyleId = source.StyleId,
            DropCap = source.DropCap,
            SectionBreak = source.SectionBreak,
            PreservedNumbering = source.PreservedNumbering,
            ParagraphFormatRevision = source.ParagraphFormatRevision
        };
        clone.BookmarkNames.AddRange(source.BookmarkNames);
        clone.BookmarkBoundaries.AddRange(source.BookmarkBoundaries);
        return clone;
    }

    private static int ParaLength(TableCell cell, int paraIndex) =>
        paraIndex >= 0 && paraIndex < cell.Paragraphs.Count
            ? ParaCells(cell.Paragraphs[paraIndex]).Count
            : 0;

    private static int CompareCellEndpoints(
        (int TableBlock, int Row, int Col, int ParaIdx, int Offset) left,
        (int TableBlock, int Row, int Col, int ParaIdx, int Offset) right)
    {
        var result = left.TableBlock.CompareTo(right.TableBlock);
        if (result != 0) return result;
        result = left.Row.CompareTo(right.Row);
        if (result != 0) return result;
        result = left.Col.CompareTo(right.Col);
        if (result != 0) return result;
        result = left.ParaIdx.CompareTo(right.ParaIdx);
        return result != 0 ? result : left.Offset.CompareTo(right.Offset);
    }

    private static IEnumerable<TableCellEntry> EnumerateLogicalCells(Table table, int tableBlock)
    {
        for (var rowIndex = 0; rowIndex < table.Rows.Count; rowIndex++)
        {
            foreach (var projected in TableGridProjection.ProjectRow(table.Rows[rowIndex]))
            {
                if (projected.Cell.VerticalMerge != VerticalMergeState.Continue)
                    yield return new TableCellEntry(
                        tableBlock,
                        rowIndex,
                        projected.StartColumn,
                        projected.Cell);
            }
        }
    }

    private static TableCellEntry? CanonicalCellEntry(Table table, int tableBlock, int row, int gridCol)
    {
        if (row < 0 || row >= table.Rows.Count)
            return null;
        var cell = GetCellModelGridCol(table, row, gridCol);
        if (cell is null)
            return null;

        var logicalRow = row;
        while (cell.VerticalMerge == VerticalMergeState.Continue && logicalRow > 0)
        {
            logicalRow--;
            cell = GetCellModelGridCol(table, logicalRow, gridCol);
            if (cell is null)
                return null;
        }

        var projected = TableGridProjection.At(table.Rows[logicalRow], gridCol);
        return projected is null || !ReferenceEquals(projected.Value.Cell, cell)
            ? null
            : new TableCellEntry(tableBlock, logicalRow, projected.Value.StartColumn, cell);
    }

    private readonly record struct TableCellEntry(int TableBlock, int Row, int Col, TableCell Cell);

    private void DeleteSelection()
    {
        if (IsEditingLocked)
            return;

        if (NormalizedSelection() is not { } sel)
            return;

        var bodyRange = new DocumentTextRange(
            new DocumentTextPosition(sel.Start.Block, sel.Start.Offset),
            new DocumentTextPosition(sel.End.Block, sel.End.Offset));
        if (_editingSession.Body.TryApplyDeletion(
                bodyRange,
                DocumentBodyDeleteDirection.Backward,
                TrackChangesEnabled,
                mergeForwardBoundary: false,
                out var sharedResult))
        {
            _caret = new DocPosition(sharedResult.Caret.BlockIndex, sharedResult.Caret.Offset);
            _selectionAnchor = _caret;
            return;
        }

        if (sel.Start.Block == sel.End.Block)
        {
            var block = sel.Start.Block;
            var a = sel.Start.Offset;
            var b = sel.End.Offset;
            // BE5: guard against DeleteSelection being called when the block is a Table (not a Paragraph).
            // This can happen when _caret is positioned on a table block but _cellCaret is null (e.g.,
            // a glyph-offset body selection that spans into a table block). Silently no-op to avoid an
            // InvalidCastException in ReplaceParagraphRunsCommand's Apply.
            if (_doc.Blocks[block] is not Paragraph)
            {
                _selectionAnchor = _caret;
                return;
            }
            if (TrackChangesEnabled)
            {
                _selectionAnchor = _caret;
                return;
            }

            _bus.Execute(new ReplaceParagraphRunsCommand(block, p =>
            {
                var cells = ParaCells(p);
                var lo = Math.Clamp(a, 0, cells.Count);
                var hi = Math.Clamp(b, 0, cells.Count);
                cells.RemoveRange(lo, Math.Max(0, hi - lo));
                SetRuns(p, cells);
            }));
            _caret = new DocPosition(block, Math.Min(a, b));
        }
        else if (_doc.Blocks[sel.Start.Block] is Paragraph startPara && _doc.Blocks[sel.End.Block] is Paragraph endPara)
        {
            var head = ParaCells(startPara).Take(sel.Start.Offset).ToList();
            head.AddRange(ParaCells(endPara).Skip(sel.End.Offset));
            var merged = new Paragraph { Formatting = startPara.Formatting, StyleId = startPara.StyleId };
            SetRuns(merged, head);
            _bus.Execute(new ReplaceBlocksCommand(sel.Start.Block, sel.End.Block - sel.Start.Block + 1, new Block[] { merged }));
            _caret = new DocPosition(sel.Start.Block, sel.Start.Offset);
        }

        _selectionAnchor = _caret;
    }

    private DocumentTextRange CurrentBodyTextRange()
    {
        if (NormalizedSelection() is { } selection)
        {
            return new DocumentTextRange(
                new DocumentTextPosition(selection.Start.Block, selection.Start.Offset),
                new DocumentTextPosition(selection.End.Block, selection.End.Offset));
        }

        var caret = new DocumentTextPosition(_caret.Block, _caret.Offset);
        return new DocumentTextRange(caret, caret);
    }

    // ---- Formatting -----------------------------------------------------------------------------

    public void ToggleBold() => ToggleRunFlag(f => f.Bold, (f, v) => f with { Bold = v });
    public void ToggleItalic() => ToggleRunFlag(f => f.Italic, (f, v) => f with { Italic = v });
    public void ToggleUnderline() => ToggleRunFlag(f => f.Underline, (f, v) => f with { Underline = v });
    public void ToggleStrikethrough() => ToggleRunFlag(f => f.Strikethrough, (f, v) => f with { Strikethrough = v });
    public void ToggleDoubleStrikethrough() => ToggleRunFlag(
        f => f.DoubleStrikethrough,
        (f, v) => f with { DoubleStrikethrough = v });
    public void ToggleHidden() => ToggleRunFlag(f => f.Hidden, (f, v) => f with { Hidden = v });
    public void ToggleSmallCaps() => ToggleRunFlag(f => f.SmallCaps, (f, v) => f with { SmallCaps = v });
    public void ToggleAllCaps() => ToggleRunFlag(f => f.AllCaps, (f, v) => f with { AllCaps = v });

    /// <summary>
    /// Toggle superscript on the selection (clears subscript if set; clears superscript if already set).
    /// Word semantics: superscript and subscript are mutually exclusive.
    /// </summary>
    public void ToggleSuperscript()
    {
        var cells = SelectionOrParagraphCells();
        var allSuper = cells.Count > 0 && cells.All(c => c.Fmt.VerticalAlign == VerticalAlign.Superscript);
        ApplyRunFormatting(f => f with { VerticalAlign = allSuper ? VerticalAlign.Baseline : VerticalAlign.Superscript });
    }

    /// <summary>
    /// Toggle subscript on the selection (clears superscript if set; clears subscript if already set).
    /// </summary>
    public void ToggleSubscript()
    {
        var cells = SelectionOrParagraphCells();
        var allSub = cells.Count > 0 && cells.All(c => c.Fmt.VerticalAlign == VerticalAlign.Subscript);
        ApplyRunFormatting(f => f with { VerticalAlign = allSub ? VerticalAlign.Baseline : VerticalAlign.Subscript });
    }

    /// <summary>
    /// Set the highlight (background) colour of the selection. Pass null or empty to clear.
    /// </summary>
    public void SetHighlightColor(string? colorHex) =>
        ApplyRunFormatting(f => f with { HighlightColorHex = string.IsNullOrWhiteSpace(colorHex) ? null : colorHex });

    public void SetCharacterBorder(ParagraphBorder? border) =>
        ApplyCharacterFormattingToParagraphs(f => f with { CharacterBorder = border });

    public void SetCharacterShading(string? colorHex, ShadingPattern pattern = ShadingPattern.Clear) =>
        ApplyCharacterFormattingToParagraphs(f => f with
        {
            CharacterShadingHex = string.IsNullOrWhiteSpace(colorHex) ? null : colorHex,
            CharacterShadingPattern = string.IsNullOrWhiteSpace(colorHex) ? ShadingPattern.Clear : pattern,
        });

    /// <summary>
    /// Set the proofing (spelling/grammar) language on the selected text range, or on the current
    /// proofing word when the caret is collapsed inside one.
    /// </summary>
    public void SetProofingLanguage(string? languageTag)
    {
        if (IsEditingLocked)
            return;

        var sel = NormalizedSelection();
        int[] selectedBlocks;
        int startOffset;
        int endOffset;
        ProofingLanguageCaretContext? caretContext = null;

        if (sel is { } s)
        {
            selectedBlocks = Enumerable.Range(s.Start.Block, s.End.Block - s.Start.Block + 1).ToArray();
            startOffset = s.Start.Offset;
            endOffset = s.End.Offset;
        }
        else
        {
            selectedBlocks = [_caret.Block];
            startOffset = _caret.Offset;
            endOffset = _caret.Offset;
            if (CurrentParagraph() is { } paragraph && IsEditable(paragraph))
            {
                caretContext = new ProofingLanguageCaretContext(
                    _caret.Block,
                    _caret.Offset,
                    paragraph.PlainText);
            }
        }

        var plan = ProofingLanguageApplyPlanner.BuildForSelectionOrCaretWord(
            languageTag,
            selectedBlocks,
            startOffset,
            endOffset,
            caretContext);

        ApplyProofingLanguagePlan(plan);
    }

    private void ApplyProofingLanguagePlan(ProofingLanguageApplyPlan plan) =>
        _editingSession.TryApplyProofingLanguage(plan);

    public bool ToggleSpellCheck()
    {
        SpellCheckEnabled = !SpellCheckEnabled;
        InvalidateVisual();
        return SpellCheckEnabled;
    }

    public bool AddCurrentWordToDictionary()
    {
        if (CurrentProofingDiagnostic is not { Kind: ProofingDiagnosticKind.Spelling } diagnostic)
            return false;

        if (!_customDictionary.Add(diagnostic.Word))
            return false;

        InvalidateVisual();
        return true;
    }

    public bool IgnoreCurrentProofingWord()
    {
        if (CurrentProofingDiagnostic is not { Kind: ProofingDiagnosticKind.Spelling } diagnostic)
            return false;

        if (!_ignoredProofingWords.Add(diagnostic.NormalizedWord))
            return false;

        InvalidateVisual();
        return true;
    }

    public bool AddToDictionary(string? word)
    {
        var normalized = NormalizeProofingWord(word);
        if (normalized is null || !_customDictionary.Add(normalized))
            return false;

        InvalidateVisual();
        return true;
    }

    public bool IsInCustomDictionary(string? word) =>
        NormalizeProofingWord(word) is { } normalized && _customDictionary.Contains(normalized);

    public string? CurrentProofingWord =>
        NormalizeProofingWord(SelectedText) ?? WordAtCaret();

    public bool CanReplaceCurrentProofingWord(string replacement)
    {
        if (string.IsNullOrWhiteSpace(replacement) || IsEditingLocked || _hfCaret is not null || _cellCaret is not null)
            return false;

        if (NormalizedSelection() is { } selection
            && selection.Start.Block == selection.End.Block
            && selection.Start.Offset != selection.End.Offset
            && NormalizeProofingWord(SelectedText) is not null)
            return true;

        return ProofingWordRangeAtCaret() is not null;
    }

    public bool ReplaceCurrentProofingWord(string replacement)
    {
        if (!CanReplaceCurrentProofingWord(replacement))
            return false;

        if (NormalizedSelection() is { } selection
            && selection.Start.Block == selection.End.Block
            && selection.Start.Offset != selection.End.Offset
            && NormalizeProofingWord(SelectedText) is not null)
        {
            ReplaceSelectionWith(replacement);
            return true;
        }

        if (ProofingWordRangeAtCaret() is not { } range)
            return false;

        _selectionAnchor = new DocPosition(range.Block, range.Start);
        _caret = new DocPosition(range.Block, range.End);
        ReplaceSelectionWith(replacement);
        return true;
    }

    public ProofingDiagnostic? CurrentProofingDiagnostic => CurrentProofingDiagnosticAtCaret();

    private IReadOnlyList<ProofingDiagnostic> BuildProofingDiagnostics() =>
        ProofingDiagnosticPlanner.Build(_doc, SpellCheckEnabled, _customDictionary.Words)
            .Where(diagnostic => !_ignoredProofingWords.Contains(diagnostic.NormalizedWord))
            .ToArray();

    private IReadOnlyList<ProofingDiagnostic> BuildVisibleProofingDiagnostics() =>
        ProofingDiagnosticPlanner.BuildVisibleIndicators(_doc, SpellCheckEnabled, _customDictionary.Words)
            .Where(diagnostic => !_ignoredProofingWords.Contains(diagnostic.NormalizedWord))
            .ToArray();

    private HashSet<(int Block, int Offset)> BuildProofingOffsetSet()
    {
        var offsets = new HashSet<(int Block, int Offset)>();
        foreach (var diagnostic in BuildVisibleProofingDiagnostics())
        {
            for (var offset = diagnostic.ParagraphOffset; offset < diagnostic.ParagraphOffset + diagnostic.Length; offset++)
                offsets.Add((diagnostic.BlockIndex, offset));
        }
        return offsets;
    }

    private ProofingDiagnostic? CurrentProofingDiagnosticAtCaret()
    {
        if (!SpellCheckEnabled || _cellCaret is not null || _hfCaret is not null)
            return null;

        var caretOffset = Math.Clamp(_caret.Offset, 0, BlockLength(_caret.Block));
        return BuildProofingDiagnostics()
            .FirstOrDefault(d =>
                d.BlockIndex == _caret.Block
                && caretOffset >= d.ParagraphOffset
                && caretOffset <= d.ParagraphOffset + d.Length);
    }

    // ── AV-COMMENT: review-comment insert / delete / resolve + introspection ──────────────────────
    // Model-backed (comments already round-trip through Core.IO). All mutations ride the shared
    // DocumentCommandBus so they are undoable, mirroring the WPF host's InsertComment / DeleteComment /
    // ToggleResolve behaviour but reusing the portable model directly (no ribbon wiring this wave).

    /// <summary>
    /// Anchors a new review comment over the current selection (or, when the selection is empty or spans
    /// multiple blocks, the whole caret paragraph). Allocates the next comment id, marks the covered body
    /// runs with it + appends a reference anchor, and stores the <see cref="Comment"/> (author/initials/
    /// text/date) in the model. Undoable; re-renders so the anchor highlight + margin marker appear.
    /// Returns the new comment id, or null when there was nothing textual to anchor to.
    /// </summary>
    public int? AddComment(string text, string author = "", string initials = "")
    {
        if (!AllowsRestrictEditingOperation(RestrictEditingOperationKind.CommentInsert))
            return null;

        if (string.IsNullOrWhiteSpace(text))
            return null;

        // Resolve the anchor block + char range. A single-block non-empty selection anchors to that range;
        // an empty or cross-block selection anchors to the whole caret paragraph (mirrors WPF InsertComment).
        var sel = NormalizedSelection();
        int block, startOffset, endOffset;
        if (sel is { } s && s.Start.Block == s.End.Block && s.Start.Offset != s.End.Offset)
        {
            block = s.Start.Block;
            startOffset = s.Start.Offset;
            endOffset = s.End.Offset;
        }
        else
        {
            block = _caret.Block;
            startOffset = 0;
            endOffset = int.MaxValue;
        }

        if (block < 0 || block >= _doc.Blocks.Count || _doc.Blocks[block] is not Paragraph paragraph || !IsPlainTextEditable(paragraph))
            return null;

        // Nothing to anchor to (empty paragraph) → no comment.
        if (ParaCells(paragraph).Count == 0)
            return null;

        return _editingSession.Review.TryAddComment(
            block,
            startOffset,
            endOffset,
            text,
            author,
            initials);
    }

    /// <summary>
    /// Deletes the comment thread with <paramref name="commentId"/> (and its replies), clearing the body
    /// anchor marks + reference run(s). Undoable. Returns true when a comment was removed.
    /// </summary>
    public bool DeleteComment(int commentId)
    {
        if (!AllowsRestrictEditingOperation(RestrictEditingOperationKind.CommentDelete))
            return false;

        return _editingSession.Review.TryDeleteComment(commentId);
    }

    /// <summary>Deletes the comment thread covering the caret/selection. Returns true when one was removed.</summary>
    public bool DeleteCommentAtCaret() =>
        CommentIdAtCaret() is { } id && DeleteComment(id);

    /// <summary>
    /// Sets the resolved/done flag on the comment thread with <paramref name="commentId"/>. Undoable.
    /// Returns true when the comment exists (flag was set/cleared), false otherwise.
    /// </summary>
    public bool SetCommentResolved(int commentId, bool resolved)
    {
        if (!AllowsRestrictEditingOperation(RestrictEditingOperationKind.CommentResolve))
            return false;

        return _editingSession.Review.TrySetCommentResolved(commentId, resolved);
    }

    /// <summary>
    /// Appends a reply to the specified top-level comment thread using the shared comment model.
    /// Undoable. Returns true when the reply was appended.
    /// </summary>
    public bool ReplyToComment(int commentId, string text, string author = "", string initials = "")
    {
        if (!AllowsRestrictEditingOperation(RestrictEditingOperationKind.CommentReply))
            return false;

        if (string.IsNullOrWhiteSpace(text))
            return false;

        return _editingSession.Review.TryReplyToComment(
            commentId,
            text,
            author,
            initials,
            CommentTextNormalization.Preserve);
    }

    /// <summary>Replies to the comment thread covering the caret. Returns true when a reply was appended.</summary>
    public bool ReplyToCommentAtCaret(string text = "Reply")
    {
        if (CommentIdAtCaret() is not { } id)
            return false;

        var identity = CurrentCommentIdentity();
        return ReplyToComment(
            id,
            text,
            identity.Author,
            identity.Initials);
    }

    /// <summary>
    /// Toggles the resolved flag of the comment thread covering the caret/selection. Returns the new
    /// resolved state, or null when the caret is not inside a comment.
    /// </summary>
    public bool? ToggleResolveCommentAtCaret()
    {
        if (!AllowsRestrictEditingOperation(RestrictEditingOperationKind.CommentResolve))
            return null;

        if (CommentIdAtCaret() is not { } id)
            return null;

        return _editingSession.Review.TryToggleCommentResolved(id);
    }

    /// <summary>All top-level review comments in the document, in id order. Replies live on each thread.</summary>
    public IReadOnlyList<Comment> AllComments =>
        _editingSession.Review.AllComments();

    /// <summary>Shared planned comment list rows in document order, including anchor positions.</summary>
    public IReadOnlyList<CommentListItem> PlannedCommentList() =>
        _editingSession.Review.BuildCommentList();

    /// <summary>Moves the caret to the previous comment in document order, wrapping at the start.</summary>
    public bool PreviousComment() => NavigateComment(direction: -1);

    /// <summary>Moves the caret to the next comment in document order, wrapping at the end.</summary>
    public bool NextComment() => NavigateComment(direction: 1);

    private bool NavigateComment(int direction)
    {
        var target = _editingSession.Review.SelectAdjacentComment(CommentIdAtCaret(), direction);
        return target is not null && MoveCaretToComment(target);
    }

    private bool MoveCaretToComment(CommentListItem item)
    {
        var anchor = item.Anchor;
        if (anchor.IsTableAnchor)
        {
            PlaceCaretInCell(
                anchor.BlockIndex,
                anchor.TableRowIndex!.Value,
                anchor.TableGridColumnIndex!.Value,
                anchor.TableParagraphIndex!.Value,
                anchor.Offset);
            ScrollToCaretRequested?.Invoke();
            return true;
        }

        if (anchor.BlockIndex < 0 || anchor.BlockIndex >= _doc.Blocks.Count || _doc.Blocks[anchor.BlockIndex] is not Paragraph)
            return false;

        _hfCaret = null;
        MoveCaretToBlock(anchor.BlockIndex, Math.Clamp(anchor.Offset, 0, BlockLength(anchor.BlockIndex)));
        InvalidateVisual();
        CaretMoved?.Invoke();
        ScrollToCaretRequested?.Invoke();
        return true;
    }

    /// <summary>
    /// The top-level comment threads whose anchored range covers the caret (or selection start), in id
    /// order. Empty when the caret is not inside any comment.
    /// </summary>
    public IReadOnlyList<Comment> CommentsAtCaret =>
        CommentIdAtCaret() is { } id && _doc.Comments.TryGetValue(id, out var comment)
            ? new[] { comment }
            : System.Array.Empty<Comment>();

    /// <summary>
    /// The id of the top-level comment whose anchored range covers the caret (or selection start), or
    /// null when the caret is not inside a comment. Resolved from the model run carrying CommentId at the
    /// caret offset; a reply's id is mapped up to its owning top-level comment.
    /// </summary>
    private int? CommentIdAtCaret()
    {
        if (_cellCaret is { } cellCaret && GetCellParagraph(
                cellCaret.TableBlock,
                cellCaret.Row,
                cellCaret.Col,
                cellCaret.ParaIdx) is { } cellParagraph)
        {
            return CommentIdInParagraphAtOffset(cellParagraph, cellCaret.Offset);
        }

        if (_caret.Block < 0 || _caret.Block >= _doc.Blocks.Count || _doc.Blocks[_caret.Block] is not Paragraph paragraph)
            return null;

        return CommentIdInParagraphAtOffset(paragraph, _caret.Offset);
    }

    private int? CommentIdInParagraphAtOffset(Paragraph paragraph, int offset)
    {
        var cells = ParaCells(paragraph);
        if (cells.Count == 0)
            return null;

        // Probe the cell just before the caret (the char the caret sits after), then the one at the caret.
        foreach (var probe in new[] { offset - 1, offset })
        {
            if (probe < 0 || probe >= cells.Count)
                continue;
            if (cells[probe].CommentId is { } cid)
                return _editingSession.Review.ResolveTopLevelCommentId(cid);
        }
        // Fallback: any commented run in the paragraph (caret placed loosely inside the range).
        foreach (var cell in cells)
            if (cell.CommentId is { } cid)
                return _editingSession.Review.ResolveTopLevelCommentId(cid);
        return null;
    }

    /// <summary>
    /// Test/introspection hook: the page-space rectangles of every laid-out glyph currently marked by a
    /// review comment, paired with the anchoring top-level comment id. Non-empty exactly when a comment's
    /// anchored range maps onto rendered glyphs. Reflects the last layout pass (call after Measure).
    /// </summary>
    internal IReadOnlyList<(int CommentId, Rect Rect)> CommentAnchorGlyphs()
    {
        // Force a fresh layout so the result always reflects the current model (introspection/test hook).
        Relayout(_laidOutWidth > 0 ? _laidOutWidth : FallbackWidth);
        return CommentAnchorGlyphSnapshot(highlightedOnly: false);
    }

    private IReadOnlyList<(int CommentId, Rect Rect)> CommentAnchorGlyphSnapshot(bool highlightedOnly)
    {
        var policy = CurrentReviewDisplayPolicy;
        if (highlightedOnly && !policy.ShouldHighlightComments)
            return [];

        return _placed
            .Where(p => !p.Sentinel
                && p.CommentId is not null
                && policy.IsRevisionTextVisible(p.Revision))
            .Select(p => (_editingSession.Review.ResolveTopLevelCommentId(p.CommentId!.Value),
                          new Rect(p.X, p.Y, Math.Max(1, p.W), p.LineHeight)))
            .ToList();
    }

    private IReadOnlyList<(int Block, Rect Rect)> SimpleMarkupChangeBarSnapshot()
    {
        var policy = CurrentReviewDisplayPolicy;
        if (!policy.ShouldShowSimpleMarkupChangeBar)
            return [];

        return _placed
            .Where(p => !p.Sentinel && p.Revision != RevisionKind.None)
            .GroupBy(p => p.Block)
            .Select(g =>
            {
                var top = g.Min(p => p.Y);
                var bottom = g.Max(p => p.Y + Math.Max(1, p.LineHeight));
                var x = Math.Max(0, _contentLeft - 9);
                return (g.Key, new Rect(x, top, 2, Math.Max(6, bottom - top)));
            })
            .ToList();
    }

    // ── AV-REVIEW: Review-tab tracked-changes + comments + word count wiring ──────────────────────────
    // Accept/reject ride the shared DocumentCommandBus (undoable), mirroring the WPF host's accept/reject
    // but reusing the portable TrackChanges/RevisionList model directly. Comments reuse the AV-COMMENT
    // infra (AddComment/DeleteComment). Word count reads DocumentStatistics from the model.

    /// <summary>
    /// When true, the editor is in Track Changes mode and the edit pipeline records edits as revisions
    /// (AV-TRACKEDIT): typing inserts text marked as a tracked insertion (current <see cref="RevisionAuthor"/>
    /// + date), and Backspace/Delete/selection-delete mark the affected text as a tracked deletion (the text
    /// is kept and struck, per Word) rather than removing it — except deleting one's own still-pending tracked
    /// insertion, which is removed outright. Accept/Reject of existing revisions work regardless of this flag.
    /// </summary>
    private bool _trackChangesEnabled;

    public bool TrackChangesEnabled
    {
        get => _trackChangesEnabled;
        private set
        {
            _trackChangesEnabled = value;
            _doc.TrackRevisions = value;
        }
    }

    /// <summary>
    /// Whether formatting-only edits participate in tracked revisions. Word persists the inverse policy
    /// as <c>w:doNotTrackFormatting</c>.
    /// </summary>
    public bool TrackFormattingEnabled => !_doc.DoNotTrackFormatting;

    /// <summary>The default revision author stamped on tracked changes this editor records.</summary>
    public string RevisionAuthor { get; set; } = "FreeW User";

    private ReviewDisplayState _reviewDisplayState = ReviewDisplayState.Default;

    public ReviewDisplayState CurrentReviewDisplayState => _reviewDisplayState;

    public ReviewDisplayMode DisplayForReview => _reviewDisplayState.DisplayMode;

    public bool ShowMarkupInsertionsAndDeletions => _reviewDisplayState.ShowInsertionsAndDeletions;

    public bool ShowMarkupComments => _reviewDisplayState.ShowComments;

    public bool ShowMarkupFormatting => _reviewDisplayState.ShowFormatting;

    public bool ShowMarkupBalloons { get; private set; }

    public ReviewDisplayPolicy CurrentReviewDisplayPolicy =>
        _reviewDisplayState.ToPolicy();

    public ReviewWorkflowStatus CurrentReviewWorkflowStatus =>
        ReviewWorkflowStatusPlanner.Build(_doc, CurrentReviewDisplayPolicy, TrackChangesEnabled);

    public void ApplyDisplayForReview(ReviewDisplayMode mode)
    {
        _reviewDisplayState = _reviewDisplayState.WithDisplayMode(mode);
        InvalidateLayoutAndVisual();
    }

    public void ApplyShowMarkupInsertionsAndDeletions(bool show)
    {
        _reviewDisplayState = _reviewDisplayState.WithShowInsertionsAndDeletions(show);
        InvalidateLayoutAndVisual();
    }

    public void ApplyShowMarkupComments(bool show)
    {
        _reviewDisplayState = _reviewDisplayState.WithShowComments(show);
        InvalidateLayoutAndVisual();
    }

    public void ApplyShowMarkupFormatting(bool show)
    {
        _reviewDisplayState = _reviewDisplayState.WithShowFormatting(show);
        InvalidateLayoutAndVisual();
    }

    public void ApplyShowMarkupBalloons(bool show)
    {
        ShowMarkupBalloons = show;
        InvalidateLayoutAndVisual();
    }

    /// <summary>
    /// AV-TRACKEDIT: mark the cell range [lo, hi) of <paramref name="cells"/> as a tracked deletion (per Word:
    /// the characters are KEPT and struck, not removed) and return the resulting list together with the caret
    /// offset that should follow the operation. Characters that are an unaccepted tracked insertion <em>by the
    /// same author</em> are removed outright instead (Word behaviour: deleting your own pending insertion just
    /// takes it back). Characters already marked deleted are left as-is. The returned caret offset is the start
    /// of the range when anything was kept-struck, otherwise <paramref name="lo"/> (the run collapsed away).
    /// </summary>
    private (List<Cell> Cells, int Caret) MarkCellsDeleted(List<Cell> cells, int lo, int hi)
    {
        var paragraph = new Paragraph();
        SetRuns(paragraph, cells);
        var sharedResult = RevisionEditPlanner.DeleteRangeAsRevision(
            paragraph,
            lo,
            hi,
            RevisionAuthor,
            _editingSession.RevisionDateXmlForEdit());
        return (ParaCells(paragraph), sharedResult.CaretOffset);
    }

    /// <summary>
    /// Toggles <see cref="TrackChangesEnabled"/> and returns the new state. Re-renders so any change-bar /
    /// markup adorners that depend on the mode update. While on, subsequent edits are recorded as tracked
    /// revisions — see <see cref="TrackChangesEnabled"/>.
    /// </summary>
    public bool ToggleTrackChanges()
    {
        TrackChangesEnabled = !TrackChangesEnabled;
        InvalidateVisual();
        DocumentChanged?.Invoke();
        return TrackChangesEnabled;
    }

    public bool ToggleTrackFormatting()
    {
        _doc.DoNotTrackFormatting = TrackFormattingEnabled;
        DocumentChanged?.Invoke();
        return TrackFormattingEnabled;
    }

    /// <summary>
    /// Marks the current selection (or, when empty, the whole caret paragraph) as a tracked change of
    /// <paramref name="kind"/> (insertion or deletion) by <see cref="RevisionAuthor"/>. Undoable; re-renders
    /// so the revision colour/decoration appears and the marks round-trip on save. Returns true when a run
    /// was marked. A no-op for <see cref="RevisionKind.None"/> or when there is nothing textual to mark.
    /// </summary>
    public bool MarkSelectionAsRevision(RevisionKind kind)
    {
        if (kind == RevisionKind.None)
            return false;

        var sel = NormalizedSelection();
        int block, startOffset, endOffset;
        if (sel is { } s && s.Start.Block == s.End.Block && s.Start.Offset != s.End.Offset)
        {
            block = s.Start.Block;
            startOffset = s.Start.Offset;
            endOffset = s.End.Offset;
        }
        else
        {
            block = _caret.Block;
            startOffset = 0;
            endOffset = int.MaxValue;
        }

        if (block < 0 || block >= _doc.Blocks.Count || _doc.Blocks[block] is not Paragraph paragraph || !IsEditable(paragraph))
            return false;
        if (ParaCells(paragraph).Count == 0)
            return false;

        var dateXml = DateTimeOffset.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ", CultureInfo.InvariantCulture);
        return _editingSession.Review.TryMarkRevisionRange(
            block,
            startOffset,
            endOffset,
            kind,
            RevisionAuthor,
            dateXml);
    }

    /// <summary>Every tracked change in the committed document, in reading order — drives Previous/Next.</summary>
    public IReadOnlyList<RevisionEntry> Revisions => _editingSession.Review.ListRevisions();

    /// <summary>Moves the caret to the top-level block owning a tracked change without mutating the document.</summary>
    public void NavigateToRevision(RevisionEntry entry)
    {
        if (_editingSession.Review.ResolveRevisionTarget(entry) is not { } target)
            return;

        _hfCaret = null;
        MoveCaretToBlock(target.TopLevelBlockIndex, 0);
        InvalidateVisual();
        Focus();
        CaretMoved?.Invoke();
        ScrollToCaretRequested?.Invoke();
    }

    /// <summary>True when the document carries any tracked change (insertion/deletion/formatting).</summary>
    public bool HasRevisions => TrackChanges.HasRevisions(_doc);

    /// <summary>
    /// Accept exactly one tracked change — the one at or after the caret, falling back to the first revision
    /// in reading order. Undoable; re-renders. Returns true when a revision was resolved.
    /// </summary>
    public bool AcceptCurrentRevision() => ResolveCurrentRevision(accept: true);

    /// <summary>
    /// Reject exactly one tracked change — the one at or after the caret, falling back to the first revision
    /// in reading order. Undoable; re-renders. Returns true when a revision was resolved.
    /// </summary>
    public bool RejectCurrentRevision() => ResolveCurrentRevision(accept: false);

    private bool ResolveCurrentRevision(bool accept)
    {
        var target = _editingSession.Review.ResolveRevisionTargetAtOrAfterTopLevelBlock(_caret.Block);
        if (target is null)
            return false;

        return _editingSession.Review.TryResolveRevision(
            target,
            accept ? RevisionResolutionAction.Accept : RevisionResolutionAction.Reject);
    }

    /// <summary>
    /// Accept every tracked change: insertions become ordinary text, deletions are removed. Undoable as a
    /// single step; re-renders. Returns true when there was anything to resolve.
    /// </summary>
    public bool AcceptAllRevisions()
    {
        return _editingSession.Review.TryResolveAllRevisions(RevisionResolutionAction.Accept);
    }

    /// <summary>
    /// Reject every tracked change: insertions are removed, deletions become ordinary text. Undoable as a
    /// single step; re-renders. Returns true when there was anything to resolve.
    /// </summary>
    public bool RejectAllRevisions()
    {
        return _editingSession.Review.TryResolveAllRevisions(RevisionResolutionAction.Reject);
    }

    /// <summary>
    /// Adds a review comment over the current selection using the shared current-reviewer identity.
    /// Reuses the AV-COMMENT <see cref="AddComment(string,string,string)"/>
    /// infra. Returns the new comment id, or null when there was nothing textual to anchor to.
    /// Wired to <c>freew.new-comment</c>.
    /// </summary>
    public int? NewComment(string text = "New comment")
    {
        var identity = CurrentCommentIdentity();
        return AddComment(text, identity.Author, identity.Initials);
    }

    private string CurrentRevisionAuthor() =>
        ReviewAuthorIdentityPlanner.ResolveAuthor(
            RevisionAuthor,
            _doc.Properties.Author,
            Environment.UserName);

    private CommentStampIdentity CurrentCommentIdentity() =>
        ReviewAuthorIdentityPlanner.BuildCommentStamp(
            RevisionAuthor,
            _doc.Properties.Author,
            Environment.UserName);

    /// <summary>
    /// Full word/character/paragraph statistics for the document, computed from the model via
    /// <see cref="DocumentStatistics.Compute(TextDocument)"/>. Drives the Word Count dialog.
    /// </summary>
    public DocumentStatistics ComputeStatistics() => DocumentStatistics.Compute(_doc);

    /// <summary>
    /// Set the paragraph space-before (in points) for the current paragraph.
    /// </summary>
    public void SetSpaceBefore(double pt)
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        _editingSession.FormatParagraphs(
            [_caret.Block],
            formatting => formatting with
            {
                SpaceBeforePt = Math.Max(0, pt),
                SpaceBeforeIsSet = true,
            });
    }

    /// <summary>
    /// Set the paragraph space-after (in points) for the current paragraph.
    /// </summary>
    public void SetSpaceAfter(double pt)
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        _editingSession.FormatParagraphs(
            [_caret.Block],
            formatting => formatting with
            {
                SpaceAfterPt = Math.Max(0, pt),
                SpaceAfterIsSet = true,
            });
    }

    /// <summary>
    /// Set the paragraph line-spacing rule. For <see cref="LineSpacingRule.Multiple"/> pass
    /// <paramref name="value"/> as the multiplier (e.g. 1.5 or 2.0). For
    /// <see cref="LineSpacingRule.Exact"/> or <see cref="LineSpacingRule.AtLeast"/> pass the
    /// absolute line height in points.
    /// </summary>
    public void SetLineSpacing(LineSpacingRule rule, double value)
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        ParagraphEdits.SetLineSpacing([_caret.Block], rule, value);
    }

    /// <summary>
    /// Set the left/right/first-line indents (in points) for the current paragraph.
    /// Pass null to leave a particular indent unchanged.
    /// </summary>
    public void SetIndents(double? leftPt = null, double? rightPt = null, double? firstLinePt = null)
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        var fmt = paragraph.Formatting;
        if (leftPt.HasValue)     fmt = fmt with { IndentLeftPt      = Math.Max(0, leftPt.Value) };
        if (rightPt.HasValue)    fmt = fmt with { IndentRightPt     = Math.Max(0, rightPt.Value) };
        if (firstLinePt.HasValue) fmt = fmt with { FirstLineIndentPt = firstLinePt.Value };
        _editingSession.FormatParagraphs([_caret.Block], _ => fmt);
    }

    /// <summary>
    /// Returns the cells in the current selection (if any and single-block), or all cells in the
    /// current paragraph. Used for toggle-state queries (e.g. "are all selected chars superscript?").
    /// </summary>
    private IReadOnlyList<Cell> SelectionOrParagraphCells()
    {
        var sel = NormalizedSelection();
        if (sel is { } s && s.Start.Block == s.End.Block && _doc.Blocks[s.Start.Block] is Paragraph selPara && IsEditable(selPara))
        {
            var all = ParaCells(selPara);
            var a = Math.Clamp(s.Start.Offset, 0, all.Count);
            var b = Math.Clamp(s.End.Offset, 0, all.Count);
            return all.Skip(a).Take(b - a).ToList();
        }
        return CurrentParagraph() is { } p && IsEditable(p) ? ParaCells(p) : [];
    }

    /// <summary>
    /// Increase the font size of the selection (or whole paragraph when no selection) to the next
    /// standard size step: 8 9 10 11 12 14 16 18 20 24 28 36 48 72. Above 72 the step is 8.
    /// </summary>
    public void GrowFont() => ApplyRunFormatting(f => f with { FontSizePt = NextFontSize(f.FontSizePt ?? DefaultFontSizePt, +1) });

    /// <summary>
    /// Decrease the font size of the selection (or whole paragraph when no selection) to the
    /// previous standard size step.
    /// </summary>
    public void ShrinkFont() => ApplyRunFormatting(f => f with { FontSizePt = NextFontSize(f.FontSizePt ?? DefaultFontSizePt, -1) });

    /// <summary>
    /// Remove all character-level formatting from the selection (resets to <see cref="RunFormatting.Default"/>).
    /// Paragraph-level properties (alignment, list kind, style) are untouched.
    /// </summary>
    public void ClearFormatting() => ApplyRunFormatting(_ => RunFormatting.Default);

    /// <summary>
    /// Set the text (foreground) colour of the selection or current paragraph to the given RRGGBB
    /// hex (e.g. <c>"#FF0000"</c>). Pass null to clear the explicit colour (inherit from theme).
    /// </summary>
    public void SetFontColor(string? colorHex) => ApplyRunFormatting(f => f with { ColorHex = colorHex });

    /// <summary>
    /// Extend the selection to encompass every block in the document (mirrors Ctrl+A / Edit → Select All).
    /// </summary>
    public void SelectAll()
    {
        if (_doc.Blocks.Count == 0)
            return;
        _selectionAnchor = new DocPosition(0, 0);
        var lastBlock = _doc.Blocks.Count - 1;
        _caret = new DocPosition(lastBlock, BlockLength(lastBlock));
        InvalidateVisual();
    }

    /// <summary>
    /// Cycle the text case of the selection: lower → Title → UPPER → lower.
    /// When there is no selection the whole current paragraph is cycled.
    /// </summary>
    public void ChangeCase() => ApplyRunFormattingToText(CycleCase);

    /// <summary>
    /// Increase the list indent level of the current paragraph by one (up to a reasonable cap).
    /// For non-list paragraphs this increases the left indent.
    /// </summary>
    public void IncreaseIndent()
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        var fmt = paragraph.Formatting;
        if (fmt.ListKind != ListKind.None)
            _editingSession.FormatParagraphs(
                [_caret.Block],
                formatting => formatting with { ListLevel = Math.Min(formatting.ListLevel + 1, 8) });
        else
            _editingSession.FormatParagraphs(
                [_caret.Block],
                formatting => formatting with { IndentLeftPt = formatting.IndentLeftPt + 36 });
    }

    /// <summary>
    /// Decrease the list indent level of the current paragraph by one (floor at 0).
    /// For non-list paragraphs this decreases the left indent (floor at 0).
    /// </summary>
    public void DecreaseIndent()
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return;
        var fmt = paragraph.Formatting;
        if (fmt.ListKind != ListKind.None)
            _editingSession.FormatParagraphs(
                [_caret.Block],
                formatting => formatting with { ListLevel = Math.Max(formatting.ListLevel - 1, 0) });
        else
            _editingSession.FormatParagraphs(
                [_caret.Block],
                formatting => formatting with { IndentLeftPt = Math.Max(formatting.IndentLeftPt - 36, 0) });
    }

    /// <summary>
    /// Toggle display of paragraph marks (¶) and other formatting symbols.
    /// The marks are drawn as faint decorations that do not affect layout.
    /// </summary>
    public bool ShowParagraphMarks
    {
        get => _showParagraphMarks;
        set
        {
            if (_showParagraphMarks == value)
                return;
            _showParagraphMarks = value;
            InvalidateVisual();
        }
    }

    /// <summary>
    /// AV-VIEW: Toggle a faint layout-gridlines overlay drawn behind the body text on each page
    /// (View → Show → Gridlines in Word). The grid is purely visual chrome; it does not affect layout.
    /// Only meaningful in <see cref="DocumentViewMode.PrintLayout"/> (where discrete pages exist).
    /// </summary>
    public bool ShowGridlines
    {
        get => _showGridlines;
        set
        {
            if (_showGridlines == value)
                return;
            _showGridlines = value;
            InvalidateVisual();
        }
    }

    /// <summary>
    /// Display-only Table Layout > View Gridlines toggle. Draws table cell outlines for borderless
    /// tables without changing the document model.
    /// </summary>
    public bool ViewTableGridlines
    {
        get => _showTableGridlines;
        set
        {
            if (_showTableGridlines == value)
                return;
            _showTableGridlines = value;
            InvalidateVisual();
        }
    }

    /// <summary>
    /// AV-VIEW: Toggle a horizontal (top) + vertical (left) ruler strip with tick marks and margin
    /// markers, drawn on the first page in <see cref="DocumentViewMode.PrintLayout"/> (View → Show →
    /// Ruler in Word). View-only chrome; does not affect layout.
    /// </summary>
    public bool ShowRuler
    {
        get => _showRuler;
        set
        {
            if (_showRuler == value)
                return;
            _showRuler = value;
            InvalidateVisual();
        }
    }

    /// <summary>
    /// AV-VIEW: Compute the layout-gridlines for the current layout — one horizontal line every
    /// <see cref="GridlineStepDip"/> within each page's text area, plus one vertical line every
    /// step across the text width. Returns page-space line segments (X1,Y1)-(X2,Y2). Exposed for the
    /// Render pass and for tests; empty when gridlines are off or not in Print Layout.
    /// </summary>
    internal IReadOnlyList<(double X1, double Y1, double X2, double Y2)> ComputeGridlines()
    {
        if (!_showGridlines || _viewMode != DocumentViewMode.PrintLayout)
            return [];

        return DocumentViewLayoutPlanner
            .BuildGridlines(_surfacePlan with { UsesHorizontalPageFlow = false, PageGridColumns = 1 }, _pageCount, GridlineStepDip)
            .Select(line =>
            {
                if (!_surfacePlan.UsesProjectedPageFlow)
                    return (line.X1, line.Y1, line.X2, line.Y2);

                var page = Math.Clamp(_surfacePlan.PageIndexFromPageSpaceY(line.Y1), 0, _pageCount - 1);
                var xOffset = _surfacePlan.RenderedPageLeftDip(page) - _surfacePlan.PageLeftDip;
                var yOffset = _surfacePlan.RenderedPageTopDip(page) - _surfacePlan.PageTopDip(page);
                return (line.X1 + xOffset, line.Y1 + yOffset, line.X2 + xOffset, line.Y2 + yOffset);
            })
            .ToList();
    }

    /// <summary>
    /// AV-VIEW: Compute the ruler tick marks for the first page's horizontal ruler — one tick every
    /// inch (72pt) across the page width, measured from the left page edge. Returns page-space tick X
    /// positions. Exposed for the Render pass and for tests; empty when the ruler is off or not in
    /// Print Layout.
    /// </summary>
    internal IReadOnlyList<double> ComputeRulerTicks()
    {
        if (!_showRuler || _viewMode != DocumentViewMode.PrintLayout)
            return [];
        const double inchDip = 72.0; // 1in = 72pt = 72 DIP at 96 DPI base
        return DocumentViewLayoutPlanner.BuildRulerTicks(_surfacePlan, inchDip);
    }

    public void SetAlignment(TextAlignment alignment)
    {
        if (CurrentParagraph() is not { } paragraph)
            return;
        _editingSession.FormatParagraphs(
            [_caret.Block],
            formatting => formatting with { Alignment = alignment });
    }

    public void ApplyMultiLevelListToSelection()
    {
        FormatSelectedParagraphs(formatting => formatting with
        {
            ListKind = ListKind.MultiLevel,
            ListLevel = formatting.ListLevel
        });
    }

    public void ApplyMultiLevelNumberFormats(IReadOnlyList<ListNumberFormat> numberFormats)
        => _editingSession.SetMultiLevelNumberFormats(numberFormats);

    internal int CaretBlockForTest => _caret.Block;
    internal int CaretOffsetForTest => _caret.Offset;

    public void ApplyMultiLevelListDefinition(MultilevelListDefinition definition)
    {
        ArgumentNullException.ThrowIfNull(definition);
        var indices = SelectedParagraphIndices();
        if (indices.Count == 0)
            return;

        _editingSession.ApplyMultilevelListDefinition(indices, definition);
    }

    public void ApplyMultiLevelListStartOverrides(int? level0StartAt, int? level1StartAt)
    {
        FormatSelectedParagraphs(formatting =>
            formatting.ListKind != ListKind.MultiLevel ? formatting :
            formatting.ListLevel == 0 && level0StartAt.HasValue ? formatting with { ListStartOverride = level0StartAt } :
            formatting.ListLevel == 1 && level1StartAt.HasValue ? formatting with { ListStartOverride = level1StartAt } :
            formatting);
    }

    public void ApplyMultiLevelHeadingPreset()
    {
        ApplyMultiLevelListToSelection();

        var styleId = GetCaretFormatting().Paragraph.ListLevel switch
        {
            0 => "Heading1",
            1 => "Heading2",
            _ => "Heading3",
        };

        ApplyNamedStyle(styleId);
    }

    /// <summary>
    /// Enumerate every paragraph block index spanned by the current selection (start block to end
    /// block inclusive). When there is no selection the result is just the caret's block (if it is
    /// an editable paragraph). Tables in the range are skipped (only paragraphs are returned),
    /// mirroring the WPF FormatSelectedModelParagraphs behaviour.
    /// </summary>
    private IReadOnlyList<int> SelectedParagraphIndices()
    {
        var sel = NormalizedSelection();
        int startBlock, endBlock;
        if (sel is { } s)
        {
            startBlock = s.Start.Block;
            endBlock   = s.End.Block;
        }
        else
        {
            startBlock = _caret.Block;
            endBlock   = _caret.Block;
        }

        var result = new List<int>();
        for (var i = startBlock; i <= endBlock && i < _doc.Blocks.Count; i++)
        {
            if (_doc.Blocks[i] is Paragraph p && IsEditable(p))
                result.Add(i);
        }
        return result;
    }

    private IReadOnlyList<DocumentTextRange> BodyTextRanges(
        (DocPosition Start, DocPosition End)? selection)
    {
        var start = selection?.Start ?? _caret;
        var end = selection?.End ?? _caret;
        var ranges = new List<DocumentTextRange>();
        for (var blockIndex = start.Block;
             blockIndex <= end.Block && blockIndex < _doc.Blocks.Count;
             blockIndex++)
        {
            var startOffset = blockIndex == start.Block ? start.Offset : 0;
            var endOffset = blockIndex == end.Block ? end.Offset : int.MaxValue;
            if (DocumentTextRangeProjection.TryProject(
                    _doc,
                    blockIndex,
                    startOffset,
                    endOffset,
                    out var range,
                    IsEditable))
            {
                ranges.Add(range);
            }
        }
        return ranges;
    }

    /// <summary>
    /// Apply <paramref name="transform"/> to the formatting of every paragraph spanned by the
    /// current selection (or just the caret paragraph when there is no selection). All mutations
    /// are wrapped in a single undo group so one Undo reverts them all atomically.
    /// Mirrors the WPF DocumentView.FormatSelectedModelParagraphs.
    /// </summary>
    private void ApplySelectedParagraphFormatting(Func<IReadOnlyList<int>, bool> apply)
    {
        ArgumentNullException.ThrowIfNull(apply);
        if (IsEditingLocked)
            return;

        _ = apply(SelectedParagraphIndices());
    }

    private void FormatSelectedParagraphs(Func<ParagraphFormatting, ParagraphFormatting> transform)
    {
        var indices = SelectedParagraphIndices();
        if (indices.Count == 0)
            return;

        _editingSession.FormatParagraphs(indices, transform);
    }

    public void ToggleKeepWithNext() =>
        ApplySelectedParagraphFormatting(ParagraphEdits.ToggleKeepWithNext);

    public void ToggleKeepLinesTogether() =>
        ApplySelectedParagraphFormatting(ParagraphEdits.ToggleKeepLinesTogether);

    public void ToggleWidowControl() =>
        ApplySelectedParagraphFormatting(ParagraphEdits.ToggleWidowControl);

    public void SetParagraphBorder(ParagraphBorder? border) =>
        ApplySelectedParagraphFormatting(indices => ParagraphEdits.SetBorder(indices, border));

    public void ToggleParagraphBorder(string colorHex = "#000000", double widthPt = 0.5) =>
        ApplySelectedParagraphFormatting(indices => ParagraphEdits.ToggleBorder(indices, colorHex, widthPt));

    public void SetParagraphShading(string? colorHex, ShadingPattern pattern = ShadingPattern.Clear) =>
        ApplySelectedParagraphFormatting(indices => ParagraphEdits.SetShading(indices, colorHex, pattern));

    public void ToggleParagraphShading(string? colorHex = "#FFF2CC") =>
        ApplySelectedParagraphFormatting(indices => ParagraphEdits.ToggleShading(indices, colorHex));

    public void SetParagraphTabStops(IReadOnlyList<TabStop> tabStops) =>
        ApplySelectedParagraphFormatting(indices => ParagraphEdits.SetTabStops(indices, tabStops));

    public bool IsCaretInTable() => CaretTableCell() is not null;

    public void SortSelectedParagraphs(SortKind kind, bool ascending, bool caseSensitive, bool hasHeaderRow)
    {
        if (IsEditingLocked)
            return;

        var indices = SelectedParagraphIndices();
        if (indices.Count == 0)
            return;

        var first = indices[0];
        var last = indices[^1];
        if (first < 0 || last >= _doc.Blocks.Count)
            return;

        _editingSession.SortParagraphSpan(
            first,
            last,
            kind,
            ascending,
            caseSensitive,
            hasHeaderRow);
    }

    public void SortCaretTableRows(SortKind kind, bool ascending, bool caseSensitive, bool hasHeaderRow)
    {
        if (IsEditingLocked || _cellCaret is not { } cc)
            return;
        TableEdits.SortRows(
            new DocumentTableCellAddress(cc.TableBlock, cc.Row, cc.Col),
            kind,
            ascending,
            caseSensitive,
            hasHeaderRow);
    }

    /// <summary>
    /// Apply the WPF-authoritative Paragraph dialog fields to every selected paragraph in one undo step.
    /// </summary>
    public void ApplyParagraphDialogFormatting(
        double indentLeftPt,
        double indentRightPt,
        double firstLineIndentPt,
        double spaceBeforePt,
        double spaceAfterPt,
        double lineSpacing,
        bool keepWithNext,
        bool keepLinesTogether,
        bool widowControl,
        bool pageBreakBefore,
        bool suppressAutoHyphens,
        bool suppressLineNumbers,
        bool contextualSpacing)
        => ApplySelectedParagraphFormatting(indices => ParagraphEdits.ApplyDialogFormatting(
            indices,
            indentLeftPt,
            indentRightPt,
            firstLineIndentPt,
            spaceBeforePt,
            spaceAfterPt,
            lineSpacing,
            keepWithNext,
            keepLinesTogether,
            widowControl,
            pageBreakBefore,
            suppressAutoHyphens,
            suppressLineNumbers,
            contextualSpacing));

    public void SetSelectionFontSize(double points) => ApplyRunFormatting(f => f with { FontSizePt = points });

    /// <summary>
    /// Applies the model-backed typography fields exposed by the Font dialog's Advanced tab while
    /// preserving every basic run-formatting property. The caller owns the surrounding undo group.
    /// </summary>
    public void ApplyAdvancedFontFormatting(RunFormatting formatting) =>
        ApplyRunFormatting(current => current with
        {
            CharacterSpacingPt = formatting.CharacterSpacingPt,
            KerningMinSizePt = formatting.KerningMinSizePt,
            PositionPt = formatting.PositionPt,
            Ligatures = formatting.Ligatures,
            StylisticSet = formatting.StylisticSet,
            NumberForm = formatting.NumberForm,
            NumberSpacing = formatting.NumberSpacing,
        });

    /// <summary>
    /// Apply <paramref name="settings"/> to the document's page geometry in a single undoable step
    /// (AV-PAGE). The command snapshots the prior values and restores them on Undo. Triggers a
    /// relayout so the page chrome (size, margins) updates immediately in Print Layout mode.
    /// </summary>
    public void SetPageSettings(PageSettings settings)
    {
        ArgumentNullException.ThrowIfNull(settings);
        DesignEdits.SetPageSettings(settings, CurrentPageSettingsSectionIndex());
    }

    /// <summary>
    /// Clone the current page settings, apply a layout mutation, then commit it as one undoable page
    /// setup command. Used by Layout ribbon commands such as Columns.
    /// </summary>
    public void ApplyPageSettings(Action<PageSettings> apply)
    {
