        var offset = ReferenceInsertionOffset(hostIndex);
        var result = ReferenceEdits.InsertIndexEntry(hostIndex, offset, mark);
        if (!result.Applied)
            return;
        _cellCaret = null;
        _caret = new DocPosition(result.HostBlockIndex, result.TextOffset);
