    private int CurrentPageSettingsSectionIndex() =>
        PageSettingsSectionResolver.ResolveSectionIndex(_doc, _caret.Block);

    /// <summary>
    /// AV-STYLES: clear any named paragraph style from the spanned paragraphs (revert to the document
    /// default — Word's "Clear Formatting" / "Normal" reset at the paragraph level), model-backed and
    /// undoable. Equivalent to applying the empty (null) style id via <see cref="SetParagraphStyleCommand"/>.
    /// </summary>
    public void ClearParagraphStyle()
    {
        var indices = SelectedParagraphIndices();
        if (indices.Count == 0)
            return;

        _editingSession.SetParagraphStyles(indices, null, "Clear Style");
    }

    public void SetSelectionFontFamily(string family) =>
        ApplyRunFormatting(f => f with { FontFamily = string.IsNullOrWhiteSpace(family) ? null : family });

    /// <summary>
    /// Returns the effective run and paragraph formatting at the caret (or at the start of the
    /// selection when there is one). This is the same formatting the ribbon state reflects.
    /// The returned values are already resolved through the style chain so they are suitable for
    /// passing directly to <see cref="RevealFormatting.Describe"/>. Read-only; never mutates the
    /// document.
    /// </summary>
    public (RunFormatting Run, ParagraphFormatting Paragraph) GetCaretFormatting()
    {
        var paragraph = CurrentParagraph();
        if (paragraph is null)
            return (RunFormatting.Default, ParagraphFormatting.Default);

        var cells = ParaCells(paragraph);
        var rawRun = cells.Count == 0
            ? (paragraph.Runs.Count > 0 ? paragraph.Runs[^1].Formatting : RunFormatting.Default)
            : cells[Math.Clamp(_caret.Offset - 1, 0, cells.Count - 1)].Fmt;

        var resolvedRun = ResolveRunFmt(rawRun, paragraph);
        var resolvedParagraph = ResolveParagraphFmt(paragraph);
        return (resolvedRun, resolvedParagraph);
    }

    /// <summary>
    /// Returns the effective run and paragraph formatting for the current selection, scanning ALL
    /// selected cells to detect mixed (indeterminate) properties. Used by the Font dialog to show
    /// indeterminate checkboxes and blank combos when the selection has mixed formatting, matching
    /// Word / WPF parity.
    /// <para>
    /// When there is no selection, behaves identically to <see cref="GetCaretFormatting"/>
    /// (single-cell read, no indeterminate flags).
    /// </para>
    /// </summary>
    public FontDialogSelectionState GetSelectionFormatting()
    {
        var (run, _) = GetCaretFormatting();

        var sel = NormalizedSelection();
        if (sel is not { } s || s.Start.Block != s.End.Block)
            return new FontDialogSelectionState(run);

        if (_doc.Blocks[s.Start.Block] is not Paragraph selPara || !IsEditable(selPara))
            return new FontDialogSelectionState(run);

        var allCells = ParaCells(selPara);
        var a = Math.Clamp(s.Start.Offset, 0, allCells.Count);
        var b = Math.Clamp(s.End.Offset, 0, allCells.Count);
        if (b <= a)
            return new FontDialogSelectionState(run);

        var selectedFormatting = allCells
            .Skip(a)
            .Take(b - a)
            .Select(cell => ResolveRunFmt(cell.Fmt, selPara));
        return FontDialogPlanner.BuildSelectionState(run, selectedFormatting);
    }

    // ── Undo-group pass-throughs (used by FontDialog to group all format steps) ─────────────────

    /// <summary>
    /// Begins collecting subsequent command-bus calls into a single undoable group.
    /// Each command still applies immediately. Must be followed by
    /// <see cref="CommitFontUndoGroup"/> or <see cref="AbortFontUndoGroup"/>.
    /// </summary>
    public void BeginFontUndoGroup() => _bus.BeginUndoGroup();

    /// <summary>Commits the current undo group as a single undo step labelled <paramref name="label"/>.</summary>
    public void CommitFontUndoGroup(string label) => _bus.CommitUndoGroup(label);

    /// <summary>Discards the current undo group without pushing onto the undo stack.</summary>
    public void AbortFontUndoGroup() => _bus.AbortUndoGroup();

    /// <summary>Text spanning the current selection (empty when there is no selection).</summary>
    public string SelectedText
    {
        get => NormalizedSelection() is null
            ? string.Empty
            : _editingSession.Interaction.ProjectSelectionText(CurrentBodyTextRange());
    }

    public bool TryDeleteSelection()
    {
        if (IsEditingLocked)
            return false;

        if (NormalizedSelection() is null)
            return false;
        DeleteSelection();
        return true;
    }

    public void SelectAllText()
    {
        if (_editingSession.Interaction.SelectAllBodyText() is not { } selection)
            return;

        _selectionAnchor = new DocPosition(selection.Start.BlockIndex, selection.Start.Offset);
        _caret = new DocPosition(selection.End.BlockIndex, selection.End.Offset);
        _cellCaret = null;
        _cellAnchor = null;
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    public bool PastePlainText(string? clipboardText) =>
        PasteNormalizedText(clipboardText, DocumentPasteTextKind.TextOnly);

    public bool PasteMergeFormatting(string? clipboardText) =>
        PasteNormalizedText(clipboardText, DocumentPasteTextKind.MergeFormatting);

    /// <summary>
    /// Replaces one empty editable body paragraph with parsed source blocks. Partial-paragraph and
    /// tracked-change edits keep the merge-formatting route until inline rich splicing is lossless.
    /// </summary>
    internal bool PasteKeepSourceFormatting(TextDocument source)
    {
        if (source is null
            || source.Blocks.Count == 0
            || IsEditingLocked
            || TrackChangesEnabled
            || _hfCaret is not null
            || _cellCaret is not null
            || NormalizedSelection() is not null
            || CurrentParagraph() is not { } paragraph
            || !IsEditable(paragraph)
            || ParaCells(paragraph).Count != 0)
        {
            return false;
        }

        var blockIndex = _caret.Block;
        if (!_editingSession.ReplaceEmptyParagraphWithDocument(blockIndex, source))
            return false;
        _caret = new DocPosition(blockIndex, 0);
        _selectionAnchor = _caret;
        _pendingRunFmt = null;
        InvalidateLayoutAndVisual();
        CaretMoved?.Invoke();
        Focus();
        return true;
    }

    /// <summary>
    /// Insert the body of another document after the caret's current body block.
    /// This is the model-backed Avalonia equivalent of WPF's Text from File command:
    /// source blocks are deep-cloned, missing styles and preserved package parts are
    /// transferred through <see cref="DocumentMerge"/>, and the whole insertion is one
    /// undoable action.
    /// </summary>
    public void InsertDocument(TextDocument source)
    {
        if (source is null || IsEditingLocked || source.Blocks.Count == 0)
            return;

        _editingSession.InsertDocumentAfter(_caret.Block, source);
        Focus();
    }

    private bool PasteNormalizedText(string? clipboardText, DocumentPasteTextKind kind)
    {
        if (IsEditingLocked)
            return false;

        var plan = _editingSession.Interaction.PlanPasteText(clipboardText, kind);
        if (!plan.HasText)
            return false;

        _bus.BeginUndoGroup();
        try
        {
            InsertText(plan.Lines[0]);
            for (var i = 1; i < plan.Lines.Count; i++)
            {
                InsertParagraphBreak();
                if (plan.Lines[i].Length > 0)
                    InsertText(plan.Lines[i]);
            }

            _bus.CommitUndoGroup(plan.UndoLabel);
        }
        catch
        {
            _bus.AbortUndoGroup();
            throw;
        }

        Focus();
        return true;
    }

    public bool IsFormatPainterArmed => _editingSession.Interaction.IsFormatPainterArmed;

    public void ArmFormatPainter(bool locked = false)
    {
        if (IsEditingLocked)
            return;

        var (run, paragraph) = GetCaretFormatting();
        _editingSession.Interaction.ToggleFormatPainter(
            run,
            paragraph,
            locked);
    }

    public void CancelFormatPainter() =>
        _editingSession.Interaction.CancelFormatPainter();

    public bool ApplyFormatPainterToSelection()
    {
        if (IsEditingLocked || NormalizedSelection() is null)
            return false;

        if (!_editingSession.Interaction.TryApplyFormatPainter(CurrentBodyTextRange()))
            return false;
        Focus();
        return true;
    }

    /// <summary>
    /// Returns the next font size on the standard ladder in the given direction (+1 = grow, -1 = shrink).
    /// Clamps to [1, 1638] (Word's limits). Above the ladder top the step is 8pt.
    /// </summary>
    private static double NextFontSize(double current, int direction)
    {
        if (direction > 0)
        {
            foreach (var s in FontSizeLadder)
                if (s > current + 0.01)
                    return s;
            return Math.Min(current + 8, 1638);
        }
        else
        {
            for (var i = FontSizeLadder.Length - 1; i >= 0; i--)
                if (FontSizeLadder[i] < current - 0.01)
                    return FontSizeLadder[i];
            return Math.Max(current - 8, 1);
        }
    }

    /// <summary>
    /// Applies a character-level text transform to the raw characters in the selection or paragraph.
    /// Used for Change Case operations that need to read each character before writing.
    /// Handles single-block selections, multi-block selections, and the no-selection (whole paragraph) case.
    /// </summary>
    private void ApplyRunFormattingToText(Func<string, string> textTransform)
    {
        var sel = NormalizedSelection();
        if (sel is { } s && s.Start.Block == s.End.Block)
        {
            // Single-block selection: transform only the selected character range.
            var block = s.Start.Block;
            if (_doc.Blocks[block] is not Paragraph p0 || !IsEditable(p0))
                return;
            var a = s.Start.Offset;
            var b = s.End.Offset;
            _bus.Execute(new ReplaceParagraphRunsCommand(block, p =>
            {
                var live = ParaCells(p);
                var selectedText = new string(live.Skip(a).Take(b - a).Select(c => c.Ch).ToArray());
                var transformed = textTransform(selectedText);
                for (var i = 0; i < b - a && i < transformed.Length; i++)
                    live[a + i] = live[a + i] with { Ch = transformed[i] };
                SetRuns(p, live);
            }));
        }
        else if (sel is { } ms && ms.Start.Block != ms.End.Block)
        {
            // Multi-block selection: transform the selected portion of each paragraph in range.
            // First block: from Start.Offset to end of paragraph.
            // Interior blocks: entire paragraph.
            // Last block: from start of paragraph to End.Offset.
            for (var bi = ms.Start.Block; bi <= ms.End.Block && bi < _doc.Blocks.Count; bi++)
            {
                if (_doc.Blocks[bi] is not Paragraph para || !IsEditable(para))
                    continue;

                var blockIndex = bi; // capture for lambda
                var isFirst = bi == ms.Start.Block;
                var isLast  = bi == ms.End.Block;
                var from    = isFirst ? ms.Start.Offset : 0;
                // 'to' will be resolved inside the lambda against the live cell list length.
                var toOffset = isLast ? ms.End.Offset : -1; // -1 = end of paragraph

                _bus.Execute(new ReplaceParagraphRunsCommand(blockIndex, p =>
                {
                    var live = ParaCells(p);
                    var effectiveTo = toOffset < 0 ? live.Count : Math.Min(toOffset, live.Count);
                    var effectiveFrom = Math.Min(from, live.Count);
                    if (effectiveTo <= effectiveFrom)
                        return;
                    var segText = new string(live.Skip(effectiveFrom).Take(effectiveTo - effectiveFrom).Select(c => c.Ch).ToArray());
                    var transformed = textTransform(segText);
                    for (var i = 0; i < effectiveTo - effectiveFrom && i < transformed.Length; i++)
                        live[effectiveFrom + i] = live[effectiveFrom + i] with { Ch = transformed[i] };
                    SetRuns(p, live);
                }));
            }
        }
        else if (CurrentParagraph() is { } paragraph && IsEditable(paragraph))
        {
            // No selection: transform the whole current paragraph.
            _bus.Execute(new ReplaceParagraphRunsCommand(_caret.Block, p =>
            {
                var live = ParaCells(p);
                var text = new string(live.Select(c => c.Ch).ToArray());
                var transformed = textTransform(text);
                for (var i = 0; i < live.Count && i < transformed.Length; i++)
                    live[i] = live[i] with { Ch = transformed[i] };
                SetRuns(p, live);
            }));
        }
    }

    /// <summary>Cycles text case: lower → Title Case → UPPER → lower.</summary>
    private string? WordAtCaret()
    {
        if (ProofingWordRangeAtCaret() is not { } range || _doc.Blocks[range.Block] is not Paragraph paragraph)
            return null;

        var cells = ParaCells(paragraph);
        return NormalizeProofingWord(new string(cells.Skip(range.Start).Take(range.End - range.Start).Select(c => c.Ch).ToArray()));
    }

    private (int Block, int Start, int End)? ProofingWordRangeAtCaret()
    {
        if (CurrentParagraph() is not { } paragraph || !IsEditable(paragraph))
            return null;

        var cells = ParaCells(paragraph);
        if (cells.Count == 0)
            return null;

        var index = Math.Clamp(_caret.Offset, 0, cells.Count - 1);
        if (!IsProofingWordChar(cells[index].Ch) && index > 0 && IsProofingWordChar(cells[index - 1].Ch))
            index--;
        if (!IsProofingWordChar(cells[index].Ch))
            return null;

        var start = index;
        while (start > 0 && IsProofingWordChar(cells[start - 1].Ch))
            start--;
        var end = index + 1;
        while (end < cells.Count && IsProofingWordChar(cells[end].Ch))
            end++;

        var word = new string(cells.Skip(start).Take(end - start).Select(c => c.Ch).ToArray());
        return NormalizeProofingWord(word) is null ? null : (_caret.Block, start, end);
    }

    private static string? NormalizeProofingWord(string? word)
    {
        return ProofingDiagnosticPlanner.NormalizeWord(word);
    }

    private static bool IsProofingWordChar(char ch) =>
        char.IsLetter(ch) || ch is '\'' or '-' or '\u2019';

    private static string CycleCase(string text)
    {
        if (string.IsNullOrEmpty(text))
            return text;

        // Determine current state.
        var isAllLower = text == text.ToLowerInvariant();
        var isAllUpper = text == text.ToUpperInvariant();
        var isTitle = !isAllUpper && text == System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(text.ToLowerInvariant());

        if (isAllLower)
            return System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(text);
        if (isTitle)
            return text.ToUpperInvariant();
        return text.ToLowerInvariant();
    }

    // Character border/shading has no native pending property and applies to every run in each
    // paragraph touched by the selection, matching the WPF authority behavior.
    private void ApplyCharacterFormattingToParagraphs(Func<RunFormatting, RunFormatting> transform)
    {
        var indices = SelectedParagraphIndices();
        if (indices.Count == 0)
            return;

        _editingSession.FormatParagraphRuns(indices, transform);
    }

    private void ApplyRunFormatting(Func<RunFormatting, RunFormatting> transform)
    {
        if (ShapeTextSelectionInfo is not null)
        {
            ApplyShapeTextFormatting(transform);
            return;
        }

        if (NormalizedSelection() is { } selection)
        {
            _editingSession.TryApplyRunFormatting(BodyTextRanges(selection), transform);
        }
        else if (CurrentParagraph() is { } paragraph && IsEditable(paragraph))
        {
            // BZ5: on a collapsed caret (no selection), store a pending format for the next
            // typed character instead of reformatting every run in the paragraph. Word semantics:
            // a format change at a collapsed caret only affects newly typed text.
            var caretFmt = ActiveFormatting(paragraph, _caret.Offset);
            var newFmt = transform(caretFmt);
            _pendingRunFmt = newFmt;
            // No _bus.Execute here — existing paragraph text is NOT changed.
        }
    }

    private void ToggleRunFlag(Func<RunFormatting, bool> get, Func<RunFormatting, bool, RunFormatting> set)
    {
        if (ShapeTextSelectionInfo is { } shapeSelection)
        {
            if (_shapeCaret is not { } shapeCaret
                || !TryGetShapeTextTarget(
                    shapeCaret.BlockIndex, shapeCaret.RunIndex, _activeShapeTextChildPath,
                    out _, out var shape)
                || !IsValidShapeTextSelection(shape, shapeSelection, shapeCaret.BlockIndex, shapeCaret.RunIndex))
                return;

            var allSet = true;
            var sawText = false;
            for (var paragraphIndex = shapeSelection.Start.TextParagraphIndex;
                 paragraphIndex <= shapeSelection.End.TextParagraphIndex && paragraphIndex < shape.TextParagraphs.Count;
                 paragraphIndex++)
            {
                var paragraph = shape.TextParagraphs[paragraphIndex];
                var from = paragraphIndex == shapeSelection.Start.TextParagraphIndex
                    ? ShapeTextOffset(shape, shapeSelection.Start) : 0;
                var to = paragraphIndex == shapeSelection.End.TextParagraphIndex
                    ? ShapeTextOffset(shape, shapeSelection.End) : paragraph.PlainText.Length;
                var position = 0;
                foreach (var run in paragraph.Runs)
                {
                    var runStart = position;
                    var runEnd = position + run.Text.Length;
                    position = runEnd;
                    var overlap = Math.Min(to, runEnd) - Math.Max(from, runStart);
                    if (overlap <= 0)
                        continue;
                    sawText = true;
                    if (!get(run.Formatting))
                        allSet = false;
                }
            }

            if (sawText)
                ApplyShapeTextFormatting(formatting => set(formatting, !allSet));
            return;
        }

        if (NormalizedSelection() is { } selection)
        {
            _editingSession.TryToggleRunFormatting(BodyTextRanges(selection), get, set);
        }
        else if (CurrentParagraph() is { } paragraph && IsEditable(paragraph))
        {
            // BZ5: on a collapsed caret, update the pending format for the next typed character
            // instead of reformatting every run in the paragraph.
            var caretFmt = _pendingRunFmt ?? ActiveFormatting(paragraph, _caret.Offset);
            var cells = ParaCells(paragraph);
            // Toggle: if ALL existing cells plus pending have the flag set → clear; else → set.
            var allSetNow = get(caretFmt) && AllSet(cells, 0, cells.Count, get);
            var newValue = !allSetNow;
            _pendingRunFmt = set(caretFmt, newValue);
            // No _bus.Execute here — existing paragraph text is NOT changed.
        }
    }

    private static bool AllSet(IReadOnlyList<Cell> cells, int a, int b, Func<RunFormatting, bool> get)
    {
        var lo = Math.Clamp(a, 0, cells.Count);
        var hi = Math.Clamp(b, 0, cells.Count);
        if (hi <= lo)
            return false;
        for (var i = lo; i < hi; i++)
            if (!get(cells[i].Fmt))
                return false;
        return true;
    }

    // ---- Caret movement -------------------------------------------------------------------------

    private void MoveCaret(int delta, bool extend)
    {
        _pendingRunFmt = null; // BZ5: discard pending format on caret movement
        // AV-TBL: when caret is in a cell, navigate within the cell's paragraph, then cross to
        // adjacent cell paragraphs, then adjacent cells. Cross-row (up/down) navigation is handled
        // by MoveCaretVertical.
        if (_cellCaret is { } cc)
        {
            ApplyCaretNavigation(
                _editingSession.Interaction.NavigateTableHorizontal(ToPortableCaret(cc), delta),
                extend);
            return;
        }

        ApplyCaretNavigation(
            _editingSession.Interaction.NavigateBodyHorizontal(
                new DocumentTextPosition(_caret.Block, _caret.Offset),
                delta),
            extend);
    }

    // AV-TBL3: Tab / Shift-Tab cell navigation.
    // Tab  → next cell (left→right, wrap to first cell of next row).
    //         Tab in the last cell of the table appends a new row and moves into its first cell
    //         (Word behaviour).
    // Shift+Tab → previous cell.
    // Never inserts a literal tab character when the caret is in a table.
    private void TabNavigateCell(bool forward)
    {
        if (_cellCaret is not { } cc)
            return;
        var navigation = _editingSession.Interaction.NavigateTableTab(ToPortableCaret(cc), forward);
        if (!navigation.Handled)
            return;

        if (navigation.AppendTableRow)
        {
            TableEdits.InsertRow(
                new DocumentTableCellAddress(cc.TableBlock, cc.Row, cc.Col),
                after: true);
            // After insert the table has grown; re-read to find the new last row.
            if (_doc.Blocks[cc.TableBlock] is not Table updatedTable)
                return;
            var newRow = updatedTable.Rows.Count - 1;
            _cellBlockAnchor = null;
            _cellBlockFocus  = null;
            InvalidateLayoutAndVisual();
            PlaceCaretInCell(cc.TableBlock, newRow, 0, 0, 0);
            return;
        }

        if (navigation.TableCaret is not { } target || target == ToPortableCaret(cc))
            return;

        _cellBlockAnchor = null;
        _cellBlockFocus  = null;
        PlaceCaretInCell(
            target.TableBlockIndex,
            target.RowIndex,
            target.GridColumnIndex,
            target.ParagraphIndex,
            target.Offset);
    }

    private static DocumentTableCaretPosition ToPortableCaret(
        (int TableBlock, int Row, int Col, int ParaIdx, int Offset) caret) =>
        new(caret.TableBlock, caret.Row, caret.Col, caret.ParaIdx, caret.Offset);

    private void ApplyCaretNavigation(DocumentCaretNavigationResult navigation, bool extend)
    {
        if (!navigation.Handled)
            return;

        if (navigation.TableCaret is { } tableCaret)
        {
            _cellCaret = (
                tableCaret.TableBlockIndex,
                tableCaret.RowIndex,
                tableCaret.GridColumnIndex,
                tableCaret.ParagraphIndex,
                tableCaret.Offset);
            _caret = new DocPosition(
                tableCaret.TableBlockIndex,
                FindCellGlyphOffset(
                    tableCaret.TableBlockIndex,
                    tableCaret.RowIndex,
                    tableCaret.GridColumnIndex,
                    tableCaret.ParagraphIndex,
                    tableCaret.Offset));
        }
        else
        {
            _cellCaret = null;
            _caret = new DocPosition(navigation.BodyCaret.BlockIndex, navigation.BodyCaret.Offset);
        }

        if (!extend)
        {
            _selectionAnchor = _caret;
            _cellAnchor = _cellCaret;
        }
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    private void MoveToLineEdge(bool toStart, bool extend)
    {
        // AV-TBL: Home/End within a cell moves to start/end of the current cell paragraph.
        if (_cellCaret is { } cc)
        {
            var para = GetCellParagraph(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx);
            var len = para != null ? ParaCells(para).Count : 0;
            var newOffset = toStart ? 0 : len;
            _cellCaret = cc with { Offset = newOffset };
            _cellAnchor = _cellCaret;
            _caret = new DocPosition(cc.TableBlock, FindCellGlyphOffset(cc.TableBlock, cc.Row, cc.Col, cc.ParaIdx, newOffset));
            _selectionAnchor = _caret;
            InvalidateVisual();
            CaretMoved?.Invoke();
            return;
        }

        _caret = _caret with { Offset = toStart ? 0 : CurrentLength() };
        if (!extend)
            _selectionAnchor = _caret;
        InvalidateVisual();
        CaretMoved?.Invoke();
    }

    private void MoveCaretVertical(int direction, bool extend)
    {
        _pendingRunFmt = null; // BZ5: discard pending format on caret movement
        if (!TryGetCaretRect(out var rect))
            return;
        var targetY = rect.Y + (direction > 0 ? rect.Height * 1.5 : -rect.Height * 0.5);
        if (TryHitTest(new Point(rect.X, targetY), out var pos))
        {
            _caret = pos;
            if (!extend)
            {
                _selectionAnchor = _caret;
                _cellAnchor = _cellCaret;
            }
            InvalidateVisual();
            CaretMoved?.Invoke();
        }
    }

    // ---- Hit testing / selection ----------------------------------------------------------------

    private bool TryHitTest(Point point, out DocPosition pos)
    {
        pos = _caret;
        if (_placed.Count == 0)
            return false;

        PlacedChar? best = null;
        var bestScore = double.MaxValue;
        foreach (var pc in _placed)
        {
            if (_surfacePlan.UsesProjectedPageFlow
                && RenderedPageIndexForPoint(point.X, point.Y)
                    != RenderedPageIndexForPoint(pc.X, pc.Y))
                continue;
            var dy = point.Y < pc.Y ? pc.Y - point.Y : point.Y > pc.Y + pc.LineHeight ? point.Y - (pc.Y + pc.LineHeight) : 0;
            var dx = Math.Abs(point.X - pc.X);
            var score = dy * 1000 + dx;
            if (score < bestScore)
            {
                bestScore = score;
                best = pc;
            }
        }

        if (best is not { } b)
            return false;

        // AV-TBL: if the best hit is inside a table cell, route into cell editing.
        if (b.IsCell)
        {
            // Snap to the nearer edge of the hit glyph within the cell paragraph.
            var cellOffset = b.CellParaOffset;
            if (!b.Sentinel && point.X > b.X + b.W / 2)
                cellOffset = b.CellParaOffset + 1;

            // Clamp offset to paragraph length.
            var cellPara = GetCellParagraph(b.Block, b.CellRow, b.CellCol, b.CellParaIdx);
            var maxOffset = cellPara != null ? ParaCells(cellPara).Count : 0;
            cellOffset = Math.Clamp(cellOffset, 0, maxOffset);

            // Find the PlacedChar that matches the target cell address+offset so we can use its
            // PlacedChar.Offset as _caret.Offset (needed for TryGetCaretRect lookup).
            var matchingGlyphOffset = FindCellGlyphOffset(b.Block, b.CellRow, b.CellCol, b.CellParaIdx, cellOffset);
            _cellCaret = (b.Block, b.CellRow, b.CellCol, b.CellParaIdx, cellOffset);
            pos = new DocPosition(b.Block, matchingGlyphOffset);
            return true;
        }

        // Body paragraph hit-test (original logic).
        if (_doc.Blocks[b.Block] is not Paragraph paragraph || !IsEditable(paragraph))
        {
            _cellCaret = null;
            return false;
        }

        _cellCaret = null;
        // Snap to the nearer edge of the hit glyph.
        var bodyOffset = b.Offset;
        if (!b.Sentinel && point.X > b.X + b.W / 2)
            bodyOffset = b.Offset + 1;
        pos = new DocPosition(b.Block, Math.Clamp(bodyOffset, 0, BlockLength(b.Block)));
        return true;
    }

    // AV-TBL: find the PlacedChar.Offset value (unique within the table block) for a given cell
    // address + paragraph offset, so _caret.Offset can be set correctly for TryGetCaretRect.
    private int FindCellGlyphOffset(int tableBlock, int row, int col, int paraIdx, int paraOffset)
    {
        // Find the glyph (character or sentinel) at exactly that cell+para+offset.
        // Prefer non-sentinel glyphs; fall back to sentinel if offset == para length.
        PlacedChar? found = null;
        foreach (var pc in _placed)
        {
            if (pc.Block == tableBlock && pc.CellRow == row && pc.CellCol == col && pc.CellParaIdx == paraIdx)
            {
                if (!pc.Sentinel && pc.CellParaOffset == paraOffset)
                {
                    found = pc;
                    break;
                }
                if (pc.Sentinel && pc.CellParaOffset == paraOffset)
                    found = pc; // sentinel match — keep searching for a non-sentinel match
            }
        }
        return found?.Offset ?? (_caret.Block == tableBlock ? _caret.Offset : 0);
    }

    // AV-TBL: retrieve the Paragraph model for a given cell address + paragraph index.
    private Paragraph? GetCellParagraph(int tableBlock, int row, int col, int paraIdx)
    {
        if (tableBlock < 0 || tableBlock >= _doc.Blocks.Count) return null;
        if (_doc.Blocks[tableBlock] is not Table table) return null;
        if (row < 0 || row >= table.Rows.Count) return null;
        var cell = TableGridProjection.StartingAt(table.Rows[row], col)?.Cell;
        return cell is not null && paraIdx >= 0 && paraIdx < cell.Paragraphs.Count
            ? cell.Paragraphs[paraIdx]
            : null;
    }

    // BF5: Expand the raw (TableBlock, MinRow, MinCol, MaxRow, MaxCol) rectangle so that any
    // horizontally-merged cell (GridSpan > 1) whose column span straddles the boundary is fully
    // included. Mirrors Word semantics: a straddling merged cell is included and the effective
    // selection grows to cover the whole merged cell. Iterates until stable (a single pass is
    // usually sufficient; a second pass handles cascaded merges).
    private (int TableBlock, int MinRow, int MinCol, int MaxRow, int MaxCol)
        ExpandForMergedCells((int TableBlock, int MinRow, int MinCol, int MaxRow, int MaxCol) raw)
    {
        if (raw.TableBlock < 0 || raw.TableBlock >= _doc.Blocks.Count)
            return raw;
        if (_doc.Blocks[raw.TableBlock] is not Table table)
            return raw;

        var (block, minRow, minCol, maxRow, maxCol) = raw;
        bool changed;
        do
        {
            changed = false;

            // ── Horizontal expansion ─────────────────────────────────────────────────────────────
            // For every row in the current range, extend minCol/maxCol to fully cover any
            // horizontally merged cell (GridSpan > 1) that straddles the boundary.
            for (var r = minRow; r <= maxRow; r++)
            {
                if (r < 0 || r >= table.Rows.Count) continue;
                foreach (var projected in TableGridProjection.ProjectRow(table.Rows[r]))
                {
                    var cellEnd = projected.EndColumnExclusive - 1;

                    // Overlap: cell's [col, cellEnd] overlaps selection [minCol, maxCol]?
                    if (projected.StartColumn <= maxCol && cellEnd >= minCol)
                    {
                        // Expand the selection to fully include this merged cell.
                        if (projected.StartColumn < minCol) { minCol = projected.StartColumn; changed = true; }
                        if (cellEnd > maxCol) { maxCol = cellEnd; changed = true; }
                    }
                }
            }

            // ── Vertical expansion (BG1) ─────────────────────────────────────────────────────────
            // For every grid column in [minCol, maxCol], walk UP from minRow while the cell is a
            // VerticalMerge.Continue (include its Restart head), and walk DOWN from maxRow while
            // the next row's cell is Continue, expanding minRow/maxRow until stable.
            for (var gridCol = minCol; gridCol <= maxCol; gridCol++)
            {
                // Walk UP: if minRow contains a Continue cell, include the Restart head.
                while (minRow > 0)
                {
                    var cell = GetCellModelGridCol(table, minRow, gridCol);
                    if (cell?.VerticalMerge != VerticalMergeState.Continue)
                        break;
                    minRow--;
                    changed = true;
                }

                // Walk DOWN: if the row just below maxRow is Continue, include it.
                while (maxRow + 1 < table.Rows.Count)
                {
                    var cell = GetCellModelGridCol(table, maxRow + 1, gridCol);
                    if (cell?.VerticalMerge != VerticalMergeState.Continue)
                        break;
                    maxRow++;
                    changed = true;
                }
            }
        } while (changed);

        return (block, minRow, minCol, maxRow, maxCol);
    }

    private static int GridColumnToCellIndex(TableRow row, int targetGridCol) =>
        TableGridProjection.At(row, targetGridCol)?.CellIndex ?? -1;

    // BG1: retrieve a cell by GRID column from a Table instance directly (no block lookup).
    // Returns the first cell whose cumulative grid span covers gridCol, or null if out of range.
    private static TableCell? GetCellModelGridCol(Table table, int row, int gridCol)
        => TableGridProjection.At(table, row, gridCol)?.Cell;

    // AV-TBL: retrieve the TableCell model for a given cell address.
    private TableCell? GetCellModel(int tableBlock, int row, int col)
    {
        if (tableBlock < 0 || tableBlock >= _doc.Blocks.Count) return null;
        if (_doc.Blocks[tableBlock] is not Table table) return null;
        if (row < 0 || row >= table.Rows.Count) return null;
        return TableGridProjection.StartingAt(table.Rows[row], col)?.Cell;
    }

    private (DocPosition Start, DocPosition End)? NormalizedSelection()
    {
        if (_selectionAnchor is not { } anchor || anchor.Equals(_caret))
            return null;
        return Compare(anchor, _caret) <= 0 ? (anchor, _caret) : (_caret, anchor);
    }

    private static bool IsWithin((DocPosition Start, DocPosition End) sel, int block, int offset)
    {
        var p = new DocPosition(block, offset);
        return Compare(sel.Start, p) <= 0 && Compare(p, sel.End) < 0;
    }

    private static int Compare(DocPosition a, DocPosition b) =>
        a.Block != b.Block ? a.Block.CompareTo(b.Block) : a.Offset.CompareTo(b.Offset);

    // ---- Model helpers --------------------------------------------------------------------------

    /// <summary>
    /// Called by the reviewing pane (and any future consumer) when it mutates the document model
    /// directly outside the command bus — e.g. accept/reject tracked changes. Invalidates the layout
    /// and visual and raises <see cref="DocumentChanged"/> exactly as an in-bus edit does. Note that
    /// direct mutations bypass undo/redo, matching Word's accept/reject semantics.
    /// </summary>
    public void InvalidateAfterExternalMutation()
    {
        ClampCaret();
        InvalidateLayoutAndVisual();
        DocumentChanged?.Invoke();
    }

    /// <summary>
    /// Apply the Document Inspector's selected removal operations to the model and re-render.
    /// Direct mutations bypass undo/redo, matching the existing accept/reject review semantics.
    /// </summary>
    public void ApplyInspectorRemovals(InspectorRemovalChoice choice)
    {
        _editingSession.Review.PlanInspectorRemovals(choice).Apply(_doc);
        InvalidateAfterExternalMutation();
    }

    private void OnModelChanged()
    {
        ClearBitmapCache();
        InvalidateLayoutAndVisual();
        DocumentChanged?.Invoke();
    }

    private void ClearBitmapCache()
    {
        foreach (var rendered in _bitmapCache.Values)
            rendered?.Dispose();
        _bitmapCache.Clear();
    }

    private void InvalidateLayoutAndVisual()
    {
        _laidOutWidth = -1;
        InvalidateMeasure();
        InvalidateVisual();
    }

    private void ClampCaret()
    {
        // AV-TBL: clear cell caret on undo/redo to avoid stale cell addresses.
        _cellCaret = null;
        _cellAnchor = null;
        // AV-TBL2: also clear cross-cell block selection (indices may have shifted after mutation).
        _cellBlockAnchor = null;
        _cellBlockFocus  = null;
        if (_caret.Block >= _doc.Blocks.Count)
            _caret = new DocPosition(Math.Max(0, _doc.Blocks.Count - 1), 0);
        _caret = _caret with { Offset = Math.Clamp(_caret.Offset, 0, CurrentLength()) };
        _selectionAnchor = _caret;
        InvalidateVisual();
    }

    private Paragraph? CurrentParagraph() =>
        _caret.Block >= 0 && _caret.Block < _doc.Blocks.Count ? _doc.Blocks[_caret.Block] as Paragraph : null;

    private int CurrentLength() => BlockLength(_caret.Block);

    private int BlockLength(int block) => _editingSession.Interaction.BodyTextLength(block);

    private int FirstEditableBlock() => _editingSession.Interaction.FirstBodyTextBlock();

    private int NextEditableBlock(int from) => _editingSession.Interaction.NextBodyTextBlock(from);

    private int PreviousEditableBlock(int from) =>
        _editingSession.Interaction.PreviousBodyTextBlock(from);

    /// <summary>Char-level editing only on paragraphs whose runs are all plain text (no images/fields/controls).</summary>
    private bool IsEditable(Paragraph paragraph) =>
        !IsEditingLocked && IsPlainTextEditable(paragraph);

    private bool IsFieldInsertable(Paragraph paragraph) =>
        !IsEditingLocked
        && paragraph.Runs.All(r => r.Image is null && r.Equation is null
            && r.FootnoteId is null && r.EndnoteId is null && r.Control is null
            && !IsFloatingDrawingRun(r));

    private static bool IsPlainTextEditable(Paragraph paragraph) =>
        // AV-COMMENT: a CommentId is a soft run mark (like a hyperlink) — it must NOT make the paragraph
        // non-editable, or its glyphs would fall back to FallbackCells (which drops the comment id and the
        // anchor render). Word keeps commented text fully editable. The textless comment-reference run has
        // empty text and contributes no cells, so it does not affect editability either.
        paragraph.Runs.All(r => r.Image is null && r.Equation is null && r.FieldKind == RunFieldKind.None
            && r.ComplexField is null && r.FootnoteId is null && r.EndnoteId is null && r.Control is null
            && !IsFloatingDrawingRun(r));

    private static bool IsFloatingDrawingRun(Run run) =>
        run.Image is { IsFloating: true }
        || run.Shape is { IsFloating: true }
        || run.Chart is { IsFloating: true }
        || run.WordArt is { IsFloating: true }
        || run.SmartArt is { IsFloating: true }
        || run.DrawingGroup is { IsFloating: true };

    private static List<Cell> ParaCells(Paragraph paragraph, bool includeFlowBreaks = false)
    {
        var cells = new List<Cell>();
        foreach (var run in paragraph.Runs)
        {
            // AV-LINK: capture the run's hyperlink target so the link span survives the cell round-trip and
            // SetRuns can re-segment runs on a hyperlink boundary. null when the run carries no link.
            // A floating drawing's fallback text belongs to its overlay, not the body flow.
            if (IsFloatingDrawingRun(run))
                continue;

            if (includeFlowBreaks)
                AddInlineFlowBreakCell(run, cells);

            var link = run.HyperlinkUrl is { Length: > 0 } || run.HyperlinkAnchor is { Length: > 0 }
                ? new LinkInfo(run.HyperlinkUrl, run.HyperlinkAnchor, run.HyperlinkTooltip)
                : (LinkInfo?)null;
            foreach (var ch in run.Text)
                // AV-COMMENT: carry the run's CommentId so commented ranges survive the cell round-trip
                // (layout + edit). Textless comment-reference runs contribute no cells, as before.
                // AV-TRACKEDIT: also carry the run's tracked-change mark so recorded revisions survive the
                // round-trip (and SetRuns can re-segment runs on a revision boundary).
                cells.Add(new Cell(ch, run.Formatting, run.CommentId, run.Revision, run.RevisionAuthor, run.RevisionDateXml, link, run.FormatRevision));
        }
        return cells;
    }

    private List<Cell> DisplayCells(int blockIndex, Paragraph paragraph, bool includeFlowBreaks = false)
    {
        var cells = new List<Cell>();
        foreach (var run in paragraph.Runs)
        {
            // Non-editable paragraphs (including note references and fields) still need their
            // per-run display formatting. Flattening to PlainText loses superscript markers.
            // A floating drawing's fallback text belongs to its overlay, not the body flow.
            if (IsFloatingDrawingRun(run))
                continue;

            if (includeFlowBreaks)
                AddInlineFlowBreakCell(run, cells);

            var link = run.HyperlinkUrl is { Length: > 0 } || run.HyperlinkAnchor is { Length: > 0 }
                ? new LinkInfo(run.HyperlinkUrl, run.HyperlinkAnchor, run.HyperlinkTooltip)
                : (LinkInfo?)null;
            if (run.Equation is { } equation)
            {
                AddEquationDisplayCells(equation, run.Formatting, cells);
                continue;
            }

            var displayText = run.Text;
            var displayFormatting = run.Formatting;
            if (run.ComplexField is { } complexField)
            {
                var displayPlan = BuildBodyComplexFieldDisplayPlan(blockIndex, run);
                displayText = displayPlan.Text;
                if (displayPlan.IsFieldCode)
                    displayFormatting = displayFormatting with { ColorHex = ComplexFieldDisplayPlanner.FieldCodeColorHex };
            }

            foreach (var ch in displayText)
                cells.Add(new Cell(ch, displayFormatting, run.CommentId, run.Revision, run.RevisionAuthor,
                    run.RevisionDateXml, link, run.FormatRevision));
        }
        return cells;
    }

    private static void AddInlineFlowBreakCell(Run run, List<Cell> cells)
    {
        var breakKind = InlineFlowBreakSegmentationPlanner.ResolveBreakKind(
            run.IsPageBreak,
            run.IsColumnBreak);
        if (breakKind == InlineFlowBreakKind.None)
            return;

        cells.Add(new Cell(
            '\0',
            run.Formatting,
            IsPageBreak: breakKind == InlineFlowBreakKind.Page,
            IsColumnBreak: breakKind == InlineFlowBreakKind.Column));
    }

    private ComplexFieldDisplayPlan BuildBodyComplexFieldDisplayPlan(int blockIndex, Run run)
    {
        var complexField = run.ComplexField!;
        var resolved = ComplexFieldEngine.CanRecompute(complexField)
            ? run.Text
            : ResolveComplexField(run, run.Text);
        if (ComplexFieldDisplayPlanner.IsPageSectionField(complexField.Keyword)
            && blockIndex >= 0
            && blockIndex < _bodyBlockSectionAssignments.Length)
        {
            var sectionIndex = Math.Clamp(
                _bodyBlockSectionAssignments[blockIndex],
                0,
                Math.Max(0, _bodySectionPageCounts.Length - 1));
            resolved = ComplexFieldDisplayPlanner.ResolvePageSectionField(
                complexField,
                resolved,
                sectionIndex + 1,
                sectionIndex < _bodySectionPageCounts.Length
                    ? _bodySectionPageCounts[sectionIndex]
                    : 0);
        }

        return ComplexFieldDisplayPlanner.Build(complexField, resolved, _doc);
    }

    private void AddEquationDisplayCells(Equation equation, RunFormatting baseFormatting, List<Cell> cells)
    {
        var plan = EquationVisualPlanner.Build(equation);
        foreach (var element in plan.Elements)
            AddEquationVisualElement(element, baseFormatting, cells);
    }

    private void AddEquationVisualElement(
        EquationVisualElement element,
        RunFormatting baseFormatting,
        List<Cell> cells)
    {
        _equationVisualElements.Add((
            element.Kind,
            element.LinearText,
            element.Numerator,
            element.Denominator,
            element.Radicand,
            element.Degree,
            element.Operator,
            element.LowerLimit,
            element.UpperLimit,
            element.Operand,
            element.MatrixRows,
            element.BaseText,
            element.Accent,
            element.BarTop,
            element.OpenDelimiter,
            element.CloseDelimiter,
            element.GroupCharacter,
            element.GroupCharacterPosition,
            element.FunctionName,
            element.FunctionArgument));

        // Keep genuinely two-dimensional OfficeMath forms intact through pagination. Scripts stay
        // character-level so the normal text/caret path continues to own their inline behavior.
        if (element.Kind != EquationVisualElementKind.Segments)
        {
            foreach (var segment in element.Segments)
                CaptureEquationVisualSegment(segment);
            cells.Add(new Cell('\uFFFC', baseFormatting, EquationElement: element));
            return;
        }

        foreach (var segment in element.Segments)
            AddEquationVisualSegment(segment, baseFormatting, cells);
    }

    private void AddEquationVisualSegment(
        EquationVisualSegment segment,
        RunFormatting baseFormatting,
        List<Cell> cells)
    {
        CaptureEquationVisualSegment(segment);
        var fmt = ApplyEquationVisualStyle(baseFormatting, segment.Style);
        foreach (var ch in segment.Text)
            cells.Add(new Cell(ch, fmt));
    }

    private void CaptureEquationVisualSegment(EquationVisualSegment segment)
    {
        _equationVisualSegments.Add((
            segment.Text,
            segment.Role,
            segment.Style.BaselineRole,
            segment.Style.FontSizeScale,
            segment.Style.FontFamily,
            segment.Style.Italic));
    }

    private static RunFormatting ApplyEquationVisualStyle(RunFormatting baseFormatting, EquationVisualStyle style)
    {
        var verticalAlign = style.BaselineRole switch
        {
            EquationVisualBaselineRole.Superscript => VerticalAlign.Superscript,
            EquationVisualBaselineRole.Subscript => VerticalAlign.Subscript,
            _ => VerticalAlign.Baseline
        };

        var styled = baseFormatting with
        {
            FontFamily = style.FontFamily,
            Italic = style.Italic,
            VerticalAlign = verticalAlign
        };

        return verticalAlign == VerticalAlign.Baseline && Math.Abs(style.FontSizeScale - 1.0) > 0.001
            ? styled with { FontSizePt = (baseFormatting.FontSizePt ?? DefaultFontSizePt) * style.FontSizeScale }
            : styled;
    }

    private static List<Cell> FallbackCells(string text)
    {
        var cells = new List<Cell>(text.Length);
        foreach (var ch in text)
            cells.Add(new Cell(ch, RunFormatting.Default));
        return cells;
    }

    private static void InsertRunAtOffset(Paragraph paragraph, int offset, Run insertedRun)
    {
        var targetOffset = Math.Clamp(offset, 0, paragraph.PlainText.Length);
        var consumed = 0;
        for (var i = 0; i < paragraph.Runs.Count; i++)
        {
            var run = paragraph.Runs[i];
            var runLength = run.Text.Length;
            if (targetOffset > consumed + runLength)
            {
                consumed += runLength;
                continue;
            }

            var local = targetOffset - consumed;
            if (local <= 0)
            {
                paragraph.Runs.Insert(i, insertedRun);
            }
            else if (local >= runLength)
            {
                paragraph.Runs.Insert(i + 1, insertedRun);
            }
            else
            {
                var before = RevisionEditPlanner.CloneRunWithText(run, run.Text[..local]);
                var after = RevisionEditPlanner.CloneRunWithText(run, run.Text[local..]);
                paragraph.Runs.RemoveAt(i);
                paragraph.Runs.Insert(i, before);
                paragraph.Runs.Insert(i + 1, insertedRun);
                paragraph.Runs.Insert(i + 2, after);
            }
            return;
        }

        paragraph.Runs.Add(insertedRun);
    }


    private static void SetRuns(Paragraph paragraph, IReadOnlyList<Cell> cells)
    {
        var preservedTextlessRuns = TextlessRunPositions(paragraph)
            .Where(item => item.Run.Citation is not null || item.Run.IsPageBreak || item.Run.IsColumnBreak)
            .ToList();

        // AV-COMMENT: preserve which comment ids had a textless reference run (they carry no cells, so the
        // cell round-trip would otherwise drop them). Re-emitted after the run is last anchored below so the
        // w:commentReference survives an edit inside a commented paragraph.
        var referencedComments = paragraph.Runs
            .Where(r => r.IsCommentReference && r.CommentId is not null)
            .Select(r => r.CommentId!.Value)
            .ToHashSet();

        paragraph.Runs.Clear();
        var lastAnchorIndexFor = new Dictionary<int, int>();
        var i = 0;
        while (i < cells.Count)
        {
            var fmt = cells[i].Fmt;
            // AV-COMMENT: also break runs on a comment-id boundary so the anchoring CommentId is preserved
            // across edits (a run is one contiguous run of equal Fmt AND equal CommentId).
            var commentId = cells[i].CommentId;
            // AV-TRACKEDIT: a run is also broken on a tracked-change boundary so recorded insertions /
            // deletions (and their author/date) survive the cell round-trip (a run is one contiguous run of
            // equal Fmt AND CommentId AND Revision mark).
            var revision = cells[i].Revision;
            var revisionAuthor = cells[i].RevisionAuthor;
            var revisionDateXml = cells[i].RevisionDateXml;
            // AV-LINK: a run is also one contiguous span of equal hyperlink target, so an inserted/edited
            // hyperlink survives the cell round-trip and re-emits as a w:hyperlink-wrapped run on save.
            var link = cells[i].Link;
            var formatRevision = cells[i].FormatRevision;
            var start = i;
            while (i < cells.Count
                   && cells[i].Fmt.Equals(fmt)
                   && cells[i].CommentId == commentId
                   && cells[i].Revision == revision
                   && cells[i].RevisionAuthor == revisionAuthor
                   && cells[i].RevisionDateXml == revisionDateXml
                   && cells[i].Link == link
                   && cells[i].FormatRevision == formatRevision)
                i++;
            var text = new string(cells.Skip(start).Take(i - start).Select(c => c.Ch).ToArray());
            paragraph.Runs.Add(new Run(text, fmt)
            {
                CommentId = commentId,
                Revision = revision,
                RevisionAuthor = revisionAuthor,
                RevisionDateXml = revisionDateXml,
                HyperlinkUrl = link?.Url,
                HyperlinkAnchor = link?.Anchor,
                HyperlinkTooltip = link?.Tooltip,
                FormatRevision = formatRevision,
            });
            if (commentId is { } cid)
                lastAnchorIndexFor[cid] = paragraph.Runs.Count - 1;
        }

        // Re-append a comment-reference run just after each comment's last anchored run, for every comment
        // that still has anchored text and previously carried a reference. Insert from the rightmost anchor
        // first so earlier insert positions stay valid.
        foreach (var cid in referencedComments
                     .Where(lastAnchorIndexFor.ContainsKey)
                     .OrderByDescending(cid => lastAnchorIndexFor[cid]))
        {
            paragraph.Runs.Insert(lastAnchorIndexFor[cid] + 1, Run.CommentReference(cid));
        }

        foreach (var item in preservedTextlessRuns
                     .Select((entry, index) => (entry.Offset, entry.Run, Index: index))
                     .OrderByDescending(entry => entry.Offset)
                     .ThenByDescending(entry => entry.Index))
        {
            InsertRunAtOffset(
                paragraph,
                item.Offset,
                RevisionEditPlanner.CloneRunWithText(item.Run, string.Empty));
        }
    }

    private static List<(int Offset, Run Run)> TextlessRunPositions(Paragraph paragraph)
    {
        var positions = new List<(int Offset, Run Run)>();
        var offset = 0;
        foreach (var run in paragraph.Runs)
        {
            if (run.Text.Length == 0)
                positions.Add((offset, run));
            else
                offset += run.Text.Length;
        }

        return positions;
    }

    /// <summary>
    /// Resolve a run's effective display formatting by cascading the paragraph's named style under it
    /// (run override wins; then the style chain's Run values; then the document default size). Display-only —
    /// the model runs stay raw so the StyleId link round-trips on save.
    /// </summary>
    private bool IsTextHiddenInCurrentView(RunFormatting formatting) =>
        formatting.Hidden || (formatting.WebHidden && _viewMode == DocumentViewMode.WebLayout);

    private RunFormatting ResolveRunFmt(RunFormatting raw, Paragraph paragraph)
    {
        var resolved = _doc.DefaultRun;
        foreach (var style in StyleChain(paragraph.StyleId))
            resolved = OverlayRun(resolved, style.Run);

        return OverlayRun(resolved, raw);
    }

    /// <summary>Cascade the paragraph's named-style paragraph formatting (alignment + spacing)
    /// under the paragraph's own values; the paragraph's explicit values win.</summary>
    private ParagraphFormatting ResolveParagraphFmt(Paragraph paragraph)
    {
        var styleParagraph = ParagraphFormatting.Default;
        var hasStyle = false;
        foreach (var style in StyleChain(paragraph.StyleId))
        {
            styleParagraph = OverlayParagraph(styleParagraph, style.Paragraph);
            hasStyle = true;
        }

        if (!hasStyle)
            return paragraph.Formatting;

        return paragraph.Formatting with
        {
            Alignment = paragraph.Formatting.Alignment == TextAlignment.Left
                ? styleParagraph.Alignment
                : paragraph.Formatting.Alignment,
            SpaceBeforePt = paragraph.Formatting.SpaceBeforeIsSet
                ? paragraph.Formatting.SpaceBeforePt
                : styleParagraph.SpaceBeforePt,
            SpaceBeforeIsSet = paragraph.Formatting.SpaceBeforeIsSet || styleParagraph.SpaceBeforeIsSet,
            SpaceAfterPt = paragraph.Formatting.SpaceAfterIsSet
                ? paragraph.Formatting.SpaceAfterPt
                : styleParagraph.SpaceAfterPt,
            SpaceAfterIsSet = paragraph.Formatting.SpaceAfterIsSet || styleParagraph.SpaceAfterIsSet,
            SuppressAutoHyphens = (paragraph.Formatting.SuppressAutoHyphensIsSet
                    || paragraph.Formatting.SuppressAutoHyphens)
                ? paragraph.Formatting.SuppressAutoHyphens
                : styleParagraph.SuppressAutoHyphens,
            SuppressAutoHyphensIsSet = paragraph.Formatting.SuppressAutoHyphensIsSet
                || paragraph.Formatting.SuppressAutoHyphens
                || styleParagraph.SuppressAutoHyphensIsSet
                || styleParagraph.SuppressAutoHyphens,
            SuppressLineNumbers = paragraph.Formatting.SuppressLineNumbersIsSet
                ? paragraph.Formatting.SuppressLineNumbers
                : styleParagraph.SuppressLineNumbers,
            SuppressLineNumbersIsSet = paragraph.Formatting.SuppressLineNumbersIsSet
                || styleParagraph.SuppressLineNumbersIsSet,
            TabStops = MergeTabStops(styleParagraph.TabStops, paragraph.Formatting.TabStops),
        };
    }

    private IEnumerable<DocumentStyle> StyleChain(string? styleId)
    {
        if (string.IsNullOrEmpty(styleId))
            yield break;

        var seen = new HashSet<string>(StringComparer.Ordinal);
        var chain = new List<DocumentStyle>();
        var id = styleId;
        while (!string.IsNullOrEmpty(id) && seen.Add(id) && _doc.Styles.TryGetValue(id, out var style))
        {
            chain.Add(style);
            id = style.BasedOnStyleId;
        }

        for (var i = chain.Count - 1; i >= 0; i--)
            yield return chain[i];
    }

    private static RunFormatting OverlayRun(RunFormatting baseRun, RunFormatting over) => baseRun with
    {
        FontFamily = over.FontFamily ?? baseRun.FontFamily,
        FontSizePt = over.FontSizePt ?? baseRun.FontSizePt,
        ColorHex = over.ColorHex ?? baseRun.ColorHex,
        HighlightColorHex = over.HighlightColorHex ?? baseRun.HighlightColorHex,
        CharacterBorder = over.CharacterBorder ?? baseRun.CharacterBorder,
        CharacterShadingHex = over.CharacterShadingHex ?? baseRun.CharacterShadingHex,
        CharacterShadingPattern = over.CharacterShadingHex is not null
            ? over.CharacterShadingPattern
            : baseRun.CharacterShadingPattern,
        LanguageTag = over.LanguageTag ?? baseRun.LanguageTag,
        VerticalAlign = over.VerticalAlign != VerticalAlign.Baseline ? over.VerticalAlign : baseRun.VerticalAlign,
        Rtl = baseRun.Rtl || over.Rtl,
        CharacterSpacingPt = over.CharacterSpacingPt != 0 ? over.CharacterSpacingPt : baseRun.CharacterSpacingPt,
        KerningMinSizePt = over.KerningMinSizePt ?? baseRun.KerningMinSizePt,
        PositionPt = over.PositionPt != 0 ? over.PositionPt : baseRun.PositionPt,
        Ligatures = over.Ligatures != LigatureMode.None ? over.Ligatures : baseRun.Ligatures,
        NumberForm = over.NumberForm != NumberForm.Default ? over.NumberForm : baseRun.NumberForm,
        NumberSpacing = over.NumberSpacing != NumberSpacing.Default ? over.NumberSpacing : baseRun.NumberSpacing,
        StylisticSet = over.StylisticSet ?? baseRun.StylisticSet,
        Bold = baseRun.Bold || over.Bold,
        Italic = baseRun.Italic || over.Italic,
        Underline = baseRun.Underline || over.Underline,
        Strikethrough = baseRun.Strikethrough || over.Strikethrough,
        DoubleStrikethrough = baseRun.DoubleStrikethrough || over.DoubleStrikethrough,
        Hidden = baseRun.Hidden || over.Hidden,
        WebHidden = baseRun.WebHidden || over.WebHidden,
        NoProof = baseRun.NoProof || over.NoProof,
        SmallCaps = baseRun.SmallCaps || over.SmallCaps,
        AllCaps = baseRun.AllCaps || over.AllCaps,
    };

    private static ParagraphFormatting OverlayParagraph(ParagraphFormatting baseParagraph, ParagraphFormatting over) => baseParagraph with
    {
        Alignment = over.Alignment == TextAlignment.Left ? baseParagraph.Alignment : over.Alignment,
        SpaceBeforePt = over.SpaceBeforeIsSet ? over.SpaceBeforePt : baseParagraph.SpaceBeforePt,
        SpaceBeforeIsSet = baseParagraph.SpaceBeforeIsSet || over.SpaceBeforeIsSet,
        SpaceAfterPt = over.SpaceAfterIsSet ? over.SpaceAfterPt : baseParagraph.SpaceAfterPt,
        SpaceAfterIsSet = baseParagraph.SpaceAfterIsSet || over.SpaceAfterIsSet,
        SuppressAutoHyphens = (over.SuppressAutoHyphensIsSet || over.SuppressAutoHyphens)
            ? over.SuppressAutoHyphens
            : baseParagraph.SuppressAutoHyphens,
        SuppressAutoHyphensIsSet = baseParagraph.SuppressAutoHyphensIsSet || baseParagraph.SuppressAutoHyphens
            || over.SuppressAutoHyphensIsSet || over.SuppressAutoHyphens,
        SuppressLineNumbers = over.SuppressLineNumbersIsSet
            ? over.SuppressLineNumbers
            : baseParagraph.SuppressLineNumbers,
        SuppressLineNumbersIsSet = baseParagraph.SuppressLineNumbersIsSet || over.SuppressLineNumbersIsSet,
        TabStops = MergeTabStops(baseParagraph.TabStops, over.TabStops),
    };

    private static IReadOnlyList<TabStop> MergeTabStops(
        IReadOnlyList<TabStop> inherited,
        IReadOnlyList<TabStop> operations)
    {
        var effective = inherited.Where(stop => !stop.IsClear).ToList();
        foreach (var operation in operations)
        {
            effective.RemoveAll(stop => Math.Abs(stop.PositionPt - operation.PositionPt) <= 0.01);
            if (!operation.IsClear)
                effective.Add(operation);
        }

        effective.Sort((left, right) => left.PositionPt.CompareTo(right.PositionPt));
        return effective;
    }

    private static RunFormatting ActiveFormatting(Paragraph paragraph, int offset)
    {
        var cells = ParaCells(paragraph);
        if (cells.Count == 0)
            return paragraph.Runs.Count > 0 ? paragraph.Runs[^1].Formatting : RunFormatting.Default;
        var index = Math.Clamp(offset - 1, 0, cells.Count - 1);
        return cells[index].Fmt;
    }

    // AV-LINK: the hyperlink a character typed at <paramref name="offset"/> should inherit — i.e. the link
    // only when the insertion point is strictly INSIDE a contiguous link span (the chars on both sides share
    // it). This extends a hyperlink when typing within it (matching Word) without extending it when typing at
    // its trailing edge. Returns null at a paragraph edge or outside any link.
    private static LinkInfo? ActiveLink(Paragraph paragraph, int offset)
    {
        var cells = ParaCells(paragraph);
        if (offset <= 0 || offset >= cells.Count)
            return null;
        var left = cells[offset - 1].Link;
        var right = cells[offset].Link;
        return left is { HasTarget: true } && left == right ? left : null;
    }

    // ---- Text shaping helpers -------------------------------------------------------------------

    private static readonly IPen EquationLinePen = new Pen(Brushes.Black, 1);

    private Size MeasureEquationVisualElement(EquationVisualElement element, RunFormatting baseFormatting)
    {
        return element.Kind switch
        {
            EquationVisualElementKind.Fraction => MeasureEquationFraction(element, baseFormatting),
            EquationVisualElementKind.Radical => MeasureEquationRadical(element, baseFormatting),
            EquationVisualElementKind.NAry => MeasureEquationNAry(element, baseFormatting),
            EquationVisualElementKind.Matrix => MeasureEquationMatrix(element, baseFormatting, includeDelimiters: true),
            EquationVisualElementKind.EquationArray => MeasureEquationMatrix(element, baseFormatting, includeDelimiters: false),
            EquationVisualElementKind.Accent or EquationVisualElementKind.GroupChar => MeasureEquationDecorator(element, baseFormatting),
            EquationVisualElementKind.Bar => MeasureEquationBar(element, baseFormatting),
            EquationVisualElementKind.Delimiter => MeasureEquationDelimiter(element, baseFormatting),
            EquationVisualElementKind.FunctionApply => MeasureEquationFunctionApply(element, baseFormatting),
            _ => MeasureEquationSegments(element.Segments, baseFormatting)
        };
    }

    private Size MeasureEquationPlan(EquationVisualPlan plan, RunFormatting baseFormatting)
    {
        var width = 0.0;
        var height = 0.0;
        foreach (var element in plan.Elements)
        {
            var size = MeasureEquationVisualElement(element, baseFormatting);
            width += size.Width;
            height = Math.Max(height, size.Height);
        }

        return new Size(width, height);
    }

    private Size MeasureEquationSegments(IReadOnlyList<EquationVisualSegment> segments, RunFormatting baseFormatting)
    {
        var width = 0.0;
        var height = 0.0;
        foreach (var segment in segments)
        {
            var text = Build(segment.Text, EquationFormatting(baseFormatting, segment.Style));
            width += text.WidthIncludingTrailingWhitespace;
            height = Math.Max(height, text.Height);
        }

        return new Size(width, height);
    }

    private Size MeasureEquationSlot(EquationVisualPlan? plan, string text, RunFormatting baseFormatting, EquationVisualStyle style) =>
        plan is null
            ? MeasureEquationSegments([new EquationVisualSegment(text, EquationVisualSegmentRole.Text, style)], baseFormatting)
            : MeasureEquationPlan(plan, EquationFormatting(baseFormatting, style));

    private Size MeasureEquationFraction(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var numerator = MeasureEquationSlot(element.NumeratorPlan, element.Numerator, baseFormatting, EquationStructureStyle);
        var denominator = MeasureEquationSlot(element.DenominatorPlan, element.Denominator, baseFormatting, EquationStructureStyle);
        return new Size(Math.Max(14, Math.Max(numerator.Width, denominator.Width) + 4), numerator.Height + denominator.Height + 3);
    }

    private Size MeasureEquationRadical(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var degree = MeasureEquationSlot(element.DegreePlan, element.Degree, baseFormatting, EquationScriptStyle);
        var sign = MeasureEquationText(EquationVisualPlanner.RadicalSignText, baseFormatting, EquationNormalStyle);
        var radicand = MeasureEquationSlot(element.RadicandPlan, element.Radicand, baseFormatting, EquationStructureStyle);
        return new Size(degree.Width + sign.Width + radicand.Width + 3, Math.Max(sign.Height, radicand.Height + 2) + degree.Height * 0.25);
    }

    private Size MeasureEquationNAry(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var lower = MeasureEquationSlot(element.NAryLowerLimitPlan, element.LowerLimit, baseFormatting, EquationScriptStyle);
        var upper = MeasureEquationSlot(element.NAryUpperLimitPlan, element.UpperLimit, baseFormatting, EquationScriptStyle);
        var op = MeasureEquationText(element.Operator, baseFormatting, EquationLargeOperatorStyle);
        var operand = MeasureEquationSlot(element.NAryOperandPlan, element.Operand, baseFormatting, EquationStructureStyle);
        var operatorWidth = Math.Max(op.Width, Math.Max(lower.Width, upper.Width));
        // Word allows the operator itself to overhang a compact text line; reserving the whole
        // glyph box would push the following equation paragraph down by roughly one script band.
        return new Size(operatorWidth + operand.Width + 4, Math.Max(1, op.Height - 6));
    }

    private Size MeasureEquationMatrix(EquationVisualElement element, RunFormatting baseFormatting, bool includeDelimiters)
    {
        var metrics = BuildEquationMatrixMetrics(element, baseFormatting);
        var delimiterWidth = includeDelimiters
            ? MeasureEquationText(EquationVisualPlanner.MatrixOpenDelimiterText, baseFormatting, EquationNormalStyle).Width * 2 + 4
            : 0;
        return new Size(metrics.Width + delimiterWidth, metrics.Height);
    }

    private Size MeasureEquationDecorator(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var basePlan = element.Kind == EquationVisualElementKind.Accent ? element.AccentBasePlan : element.GroupCharBasePlan;
        var baseText = MeasureEquationSlot(basePlan, element.BaseText, baseFormatting, EquationStructureStyle);
        var markText = element.Kind == EquationVisualElementKind.Accent
            ? EquationAccentText(element.Accent)
            : element.GroupCharacter;
        var mark = MeasureEquationText(markText, baseFormatting, EquationDecoratorStyle);
        return new Size(Math.Max(baseText.Width, mark.Width) + 2, baseText.Height);
    }

    private Size MeasureEquationBar(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var baseText = MeasureEquationSlot(element.BarBasePlan, element.BaseText, baseFormatting, EquationStructureStyle);
        return new Size(Math.Max(14, baseText.Width + 2), baseText.Height);
    }

    private Size MeasureEquationDelimiter(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var open = MeasureEquationText(element.OpenDelimiter, baseFormatting, EquationDelimiterStyle);
        var content = MeasureEquationSlot(element.DelimiterContentPlan, element.BaseText, baseFormatting, EquationStructureStyle);
        var close = MeasureEquationText(element.CloseDelimiter, baseFormatting, EquationDelimiterStyle);
        return new Size(open.Width + content.Width + close.Width + 4, Math.Max(content.Height, Math.Max(open.Height, close.Height)));
    }

    private Size MeasureEquationFunctionApply(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var name = MeasureEquationText(element.FunctionName, baseFormatting, EquationFunctionNameStyle);
        var argument = MeasureEquationSlot(element.FunctionArgumentPlan, element.FunctionArgument, baseFormatting, EquationStructureStyle);
        return new Size(name.Width + argument.Width + 2, Math.Max(name.Height, argument.Height));
    }

    private Size MeasureEquationText(string text, RunFormatting baseFormatting, EquationVisualStyle style)
    {
        var formatted = Build(text, EquationFormatting(baseFormatting, style));
        return new Size(formatted.WidthIncludingTrailingWhitespace, formatted.Height);
    }

    private static RunFormatting EquationFormatting(RunFormatting baseFormatting, EquationVisualStyle style) =>
        baseFormatting with
        {
            FontFamily = style.FontFamily,
            FontSizePt = (baseFormatting.FontSizePt ?? DefaultFontSizePt) * style.FontSizeScale,
            Italic = style.Italic,
            VerticalAlign = VerticalAlign.Baseline
        };

    private void DrawEquationVisualElement(
        DrawingContext context,
        EquationVisualElement element,
        Rect bounds,
        RunFormatting baseFormatting)
    {
        switch (element.Kind)
        {
            case EquationVisualElementKind.Fraction:
                DrawEquationFraction(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.Radical:
                DrawEquationRadical(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.NAry:
                DrawEquationNAry(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.Matrix:
                DrawEquationMatrix(context, element, bounds, baseFormatting, includeDelimiters: true);
                return;
            case EquationVisualElementKind.EquationArray:
                DrawEquationMatrix(context, element, bounds, baseFormatting, includeDelimiters: false);
                return;
            case EquationVisualElementKind.Accent:
            case EquationVisualElementKind.GroupChar:
                DrawEquationDecorator(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.Bar:
                DrawEquationBar(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.Delimiter:
                DrawEquationDelimiter(context, element, bounds, baseFormatting);
                return;
            case EquationVisualElementKind.FunctionApply:
                DrawEquationFunctionApply(context, element, bounds, baseFormatting);
                return;
            default:
                DrawEquationSegments(context, element.Segments, bounds, baseFormatting);
                return;
        }
    }

    private void DrawEquationFraction(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var numerator = MeasureEquationSlot(element.NumeratorPlan, element.Numerator, baseFormatting, EquationStructureStyle);
        var denominator = MeasureEquationSlot(element.DenominatorPlan, element.Denominator, baseFormatting, EquationStructureStyle);
        var barY = bounds.Y + numerator.Height + 1;
        DrawEquationSlot(context, element.NumeratorPlan, element.Numerator, new Rect(bounds.X, bounds.Y, bounds.Width, numerator.Height), baseFormatting, EquationStructureStyle, centered: true);
        context.DrawLine(EquationLinePen, new Point(bounds.X + 1, barY), new Point(bounds.Right - 1, barY));
        DrawEquationSlot(context, element.DenominatorPlan, element.Denominator, new Rect(bounds.X, barY + 2, bounds.Width, denominator.Height), baseFormatting, EquationStructureStyle, centered: true);
    }

    private void DrawEquationRadical(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var degree = MeasureEquationSlot(element.DegreePlan, element.Degree, baseFormatting, EquationScriptStyle);
        var sign = MeasureEquationText(EquationVisualPlanner.RadicalSignText, baseFormatting, EquationNormalStyle);
        var radicand = MeasureEquationSlot(element.RadicandPlan, element.Radicand, baseFormatting, EquationStructureStyle);
        var radicandX = bounds.X + degree.Width + sign.Width;
        DrawEquationSlot(context, element.DegreePlan, element.Degree, new Rect(bounds.X, bounds.Y, degree.Width, degree.Height), baseFormatting, EquationScriptStyle);
        DrawEquationText(context, EquationVisualPlanner.RadicalSignText, new Rect(bounds.X + degree.Width, bounds.Bottom - sign.Height, sign.Width, sign.Height), baseFormatting, EquationNormalStyle);
        context.DrawLine(EquationLinePen, new Point(radicandX, bounds.Y + degree.Height * 0.25), new Point(radicandX + radicand.Width + 1, bounds.Y + degree.Height * 0.25));
        DrawEquationSlot(context, element.RadicandPlan, element.Radicand, new Rect(radicandX + 1, bounds.Bottom - radicand.Height, radicand.Width, radicand.Height), baseFormatting, EquationStructureStyle);
    }

    private void DrawEquationNAry(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var lower = MeasureEquationSlot(element.NAryLowerLimitPlan, element.LowerLimit, baseFormatting, EquationScriptStyle);
        var upper = MeasureEquationSlot(element.NAryUpperLimitPlan, element.UpperLimit, baseFormatting, EquationScriptStyle);
        var op = MeasureEquationText(element.Operator, baseFormatting, EquationLargeOperatorStyle);
        var operand = MeasureEquationSlot(element.NAryOperandPlan, element.Operand, baseFormatting, EquationStructureStyle);
        var operatorWidth = Math.Max(op.Width, Math.Max(lower.Width, upper.Width));
        var limitOverlap = Math.Max(lower.Height, upper.Height) * 0.55;
        var visualTop = bounds.Y - limitOverlap;
        var visualHeight = op.Height + limitOverlap * 2;
        var operatorY = visualTop + limitOverlap;
        DrawEquationSlot(context, element.NAryUpperLimitPlan, element.UpperLimit, new Rect(bounds.X, visualTop, operatorWidth, upper.Height), baseFormatting, EquationScriptStyle, centered: true);
        DrawEquationText(context, element.Operator, new Rect(bounds.X, operatorY, operatorWidth, op.Height), baseFormatting, EquationLargeOperatorStyle, centered: true);
        DrawEquationSlot(context, element.NAryLowerLimitPlan, element.LowerLimit, new Rect(bounds.X, visualTop + visualHeight - lower.Height, operatorWidth, lower.Height), baseFormatting, EquationScriptStyle, centered: true);
        DrawEquationSlot(context, element.NAryOperandPlan, element.Operand, new Rect(bounds.X + operatorWidth + 3, bounds.Y + (bounds.Height - operand.Height) / 2, operand.Width, operand.Height), baseFormatting, EquationStructureStyle);
    }

    private void DrawEquationMatrix(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting, bool includeDelimiters)
    {
        var metrics = BuildEquationMatrixMetrics(element, baseFormatting);
        var delimiterWidth = includeDelimiters
            ? MeasureEquationText(EquationVisualPlanner.MatrixOpenDelimiterText, baseFormatting, EquationNormalStyle).Width + 2
            : 0;
        var gridX = bounds.X + delimiterWidth;
        var y = bounds.Y + (bounds.Height - metrics.Height) / 2;
        for (var rowIndex = 0; rowIndex < element.MatrixRows.Count; rowIndex++)
        {
            var x = gridX;
            var rowHeight = metrics.RowHeights[rowIndex];
            for (var columnIndex = 0; columnIndex < metrics.ColumnWidths.Length; columnIndex++)
            {
                var cell = columnIndex < element.MatrixRows[rowIndex].Cells.Count ? element.MatrixRows[rowIndex].Cells[columnIndex] : null;
                if (cell is not null)
                    DrawEquationSlot(context, cell.CellPlan, cell.Text, new Rect(x, y, metrics.ColumnWidths[columnIndex], rowHeight), baseFormatting, EquationStructureStyle, centered: true);
                x += metrics.ColumnWidths[columnIndex] + EquationVisualPlanner.MatrixColumnGapEm * FontSizePx(baseFormatting);
            }
            y += rowHeight + EquationVisualPlanner.MatrixRowGapEm * FontSizePx(baseFormatting);
        }

        if (includeDelimiters)
        {
            DrawEquationMatrixBracket(context, bounds.X, bounds.Y, bounds.Bottom, delimiterWidth, opening: true);
            DrawEquationMatrixBracket(context, gridX + metrics.Width + 2, bounds.Y, bounds.Bottom, delimiterWidth, opening: false);
        }
    }

    private static void DrawEquationMatrixBracket(
        DrawingContext context,
        double x,
        double top,
        double bottom,
        double width,
        bool opening)
    {
        var cap = Math.Max(2, Math.Min(4, width - 2));
        var verticalX = opening ? x + width - 1 : x + 1;
        var topY = top + 1;
        var bottomY = bottom - 1;
        context.DrawLine(EquationLinePen, new Point(verticalX, topY), new Point(verticalX, bottomY));
        var capDirection = opening ? -1 : 1;
        context.DrawLine(EquationLinePen, new Point(verticalX, topY), new Point(verticalX + capDirection * cap, topY));
        context.DrawLine(EquationLinePen, new Point(verticalX, bottomY), new Point(verticalX + capDirection * cap, bottomY));
    }

    private void DrawEquationDecorator(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var basePlan = element.Kind == EquationVisualElementKind.Accent ? element.AccentBasePlan : element.GroupCharBasePlan;
        var mark = element.Kind == EquationVisualElementKind.Accent ? EquationAccentText(element.Accent) : element.GroupCharacter;
        var markSize = MeasureEquationText(mark, baseFormatting, EquationDecoratorStyle);
        var baseSize = MeasureEquationSlot(basePlan, element.BaseText, baseFormatting, EquationStructureStyle);
        var markOnTop = element.Kind == EquationVisualElementKind.Accent || element.GroupCharacterTop;
        var baseY = bounds.Y + (bounds.Height - baseSize.Height) / 2;
        var markY = markOnTop
            ? baseY - markSize.Height * 0.55
            : baseY + baseSize.Height - markSize.Height * 0.45;
        DrawEquationText(context, mark, new Rect(bounds.X, markY, bounds.Width, markSize.Height), baseFormatting, EquationDecoratorStyle, centered: true);
        DrawEquationSlot(context, basePlan, element.BaseText, new Rect(bounds.X, baseY, bounds.Width, baseSize.Height), baseFormatting, EquationStructureStyle, centered: true);
    }

    private void DrawEquationBar(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var baseSize = MeasureEquationSlot(element.BarBasePlan, element.BaseText, baseFormatting, EquationStructureStyle);
        var baseY = bounds.Y + (bounds.Height - baseSize.Height) / 2;
        DrawEquationSlot(context, element.BarBasePlan, element.BaseText, new Rect(bounds.X, baseY, bounds.Width, baseSize.Height), baseFormatting, EquationStructureStyle, centered: true);
        var lineY = element.BarTop ? baseY - 1 : baseY + baseSize.Height + 1;
        context.DrawLine(EquationLinePen, new Point(bounds.X + 1, lineY), new Point(bounds.Right - 1, lineY));
    }

    private void DrawEquationDelimiter(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var open = MeasureEquationText(element.OpenDelimiter, baseFormatting, EquationDelimiterStyle);
        var close = MeasureEquationText(element.CloseDelimiter, baseFormatting, EquationDelimiterStyle);
        DrawEquationText(context, element.OpenDelimiter, new Rect(bounds.X, bounds.Y, open.Width, bounds.Height), baseFormatting, EquationDelimiterStyle, centered: true);
        DrawEquationSlot(context, element.DelimiterContentPlan, element.BaseText, new Rect(bounds.X + open.Width + 1, bounds.Y, bounds.Width - open.Width - close.Width - 2, bounds.Height), baseFormatting, EquationStructureStyle, centered: true);
        DrawEquationText(context, element.CloseDelimiter, new Rect(bounds.Right - close.Width, bounds.Y, close.Width, bounds.Height), baseFormatting, EquationDelimiterStyle, centered: true);
    }

    private void DrawEquationFunctionApply(DrawingContext context, EquationVisualElement element, Rect bounds, RunFormatting baseFormatting)
    {
        var name = MeasureEquationText(element.FunctionName, baseFormatting, EquationFunctionNameStyle);
        DrawEquationText(context, element.FunctionName, new Rect(bounds.X, bounds.Y, name.Width, bounds.Height), baseFormatting, EquationFunctionNameStyle);
        DrawEquationSlot(context, element.FunctionArgumentPlan, element.FunctionArgument, new Rect(bounds.X + name.Width + 2, bounds.Y, Math.Max(0, bounds.Width - name.Width - 2), bounds.Height), baseFormatting, EquationStructureStyle);
    }

    private void DrawEquationSlot(DrawingContext context, EquationVisualPlan? plan, string text, Rect bounds, RunFormatting baseFormatting, EquationVisualStyle style, bool centered = false)
    {
        if (plan is not null)
        {
            DrawEquationPlan(context, plan, bounds, EquationFormatting(baseFormatting, style), centered);
            return;
        }

        DrawEquationText(context, text, bounds, baseFormatting, style, centered);
    }

    private void DrawEquationPlan(DrawingContext context, EquationVisualPlan plan, Rect bounds, RunFormatting baseFormatting, bool centered = false)
    {
        var size = MeasureEquationPlan(plan, baseFormatting);
        var x = bounds.X + (centered ? Math.Max(0, (bounds.Width - size.Width) / 2) : 0);
        foreach (var element in plan.Elements)
        {
            var elementSize = MeasureEquationVisualElement(element, baseFormatting);
            DrawEquationVisualElement(context, element, new Rect(x, bounds.Y + (bounds.Height - elementSize.Height) / 2, elementSize.Width, elementSize.Height), baseFormatting);
            x += elementSize.Width;
        }
    }

    private void DrawEquationSegments(DrawingContext context, IReadOnlyList<EquationVisualSegment> segments, Rect bounds, RunFormatting baseFormatting)
    {
        var x = bounds.X;
        foreach (var segment in segments)
        {
            var size = MeasureEquationText(segment.Text, baseFormatting, segment.Style);
            DrawEquationText(context, segment.Text, new Rect(x, bounds.Y, size.Width, bounds.Height), baseFormatting, segment.Style);
            x += size.Width;
        }
    }

    private void DrawEquationText(DrawingContext context, string text, Rect bounds, RunFormatting baseFormatting, EquationVisualStyle style, bool centered = false)
    {
        if (string.IsNullOrEmpty(text))
            return;

        var formatted = Build(text, EquationFormatting(baseFormatting, style));
        var x = bounds.X + (centered ? Math.Max(0, (bounds.Width - formatted.WidthIncludingTrailingWhitespace) / 2) : 0);
        var y = bounds.Y + Math.Max(0, (bounds.Height - formatted.Height) / 2) - style.BaselineOffsetEm * FontSizePx(baseFormatting);
        context.DrawText(formatted, new Point(x, y));
    }

    private EquationMatrixMetrics BuildEquationMatrixMetrics(EquationVisualElement element, RunFormatting baseFormatting)
    {
        var columnCount = element.MatrixColumnCount;
        var columnWidths = new double[columnCount];
        var rowHeights = new double[element.MatrixRows.Count];
        for (var rowIndex = 0; rowIndex < element.MatrixRows.Count; rowIndex++)
        {
            var row = element.MatrixRows[rowIndex];
            for (var columnIndex = 0; columnIndex < row.Cells.Count; columnIndex++)
            {
                var cell = row.Cells[columnIndex];
                var size = MeasureEquationSlot(cell.CellPlan, cell.Text, baseFormatting, EquationStructureStyle);
                columnWidths[columnIndex] = Math.Max(columnWidths[columnIndex], size.Width);
                rowHeights[rowIndex] = Math.Max(rowHeights[rowIndex], size.Height);
            }
        }

        var fontSize = FontSizePx(baseFormatting);
        var width = columnWidths.Sum() + Math.Max(0, columnCount - 1) * EquationVisualPlanner.MatrixColumnGapEm * fontSize;
        var height = rowHeights.Sum() + Math.Max(0, rowHeights.Length - 1) * EquationVisualPlanner.MatrixRowGapEm * fontSize;
        return new EquationMatrixMetrics(columnWidths, rowHeights, width, height);
    }

    private static string EquationAccentText(string accent) => accent switch
    {
        "\u0302" => "^",
        "\u0303" => "~",
        "\u0304" => EquationVisualPlanner.OverbarCueText,
        "\u0307" => ".",
        "\u0308" => "..",
        "\u20d7" => "\u2192",
        _ => string.IsNullOrEmpty(accent) ? "^" : accent
    };

    private readonly record struct EquationMatrixMetrics(double[] ColumnWidths, double[] RowHeights, double Width, double Height);

    private static EquationVisualStyle EquationNormalStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, true, 1, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationStructureStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, true, EquationVisualPlanner.StructureFontSizeScale, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationScriptStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, true, EquationVisualPlanner.ScriptFontSizeScale, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationLargeOperatorStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, false, EquationVisualPlanner.LargeOperatorFontSizeScale, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationDecoratorStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, false, EquationVisualPlanner.DecoratorFontSizeScale, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationDelimiterStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, false, EquationVisualPlanner.DelimiterFontSizeScale, EquationVisualBaselineRole.Normal, 0);
    private static EquationVisualStyle EquationFunctionNameStyle { get; } = new(EquationVisualPlanner.DefaultMathFontFamily, false, EquationVisualPlanner.StructureFontSizeScale, EquationVisualBaselineRole.Normal, 0);

    private FormattedText Build(string text, RunFormatting fmt)
    {
        var typeface = new Typeface(
            fmt.FontFamily is { Length: > 0 } family ? new FontFamily(family) : FontFamily.Default,
            fmt.Italic ? FontStyle.Italic : FontStyle.Normal,
            fmt.Bold ? FontWeight.Bold : FontWeight.Normal);

        var formatted = new FormattedText(
            text,
            CultureInfo.CurrentCulture,
            FlowDirection.LeftToRight,
            typeface,
            FontSizePx(fmt),
            BrushFor(fmt.ColorHex));
        var featurePlan = RunOpenTypeFeaturePlanner.Build(fmt);
        if (featurePlan.AvaloniaFeatureSettings.Count > 0)
        {
            formatted.SetFontFeatures(new FontFeatureCollection(
                featurePlan.AvaloniaFeatureSettings.Select(FontFeature.Parse)));
        }

        return formatted;
    }

    // Layout must use the same superscript/subscript scale that drawing uses. Otherwise a marker
    // is painted small but reserves full-size width, which can push an otherwise fitting Word line over.
    private FormattedText BuildForLayout(string text, RunFormatting fmt) =>
        Build(text, LayoutMetricFormatting(fmt));

    private static RunFormatting LayoutMetricFormatting(RunFormatting fmt) =>
        fmt.VerticalAlign is VerticalAlign.Superscript or VerticalAlign.Subscript
            ? fmt with { FontSizePt = (fmt.FontSizePt ?? DefaultFontSizePt) * SuperSubScale }
            : fmt;

    private static double FontSizePx(RunFormatting fmt) => (fmt.FontSizePt ?? DefaultFontSizePt) * PxPerPoint;

    private IBrush BrushFor(string? hex)
    {
        if (string.IsNullOrWhiteSpace(hex))
            return Brushes.Black;
        if (_brushCache.TryGetValue(hex, out var brush))
            return brush;
        brush = TryParseAvaloniaColor(hex, out var color)
            ? new SolidColorBrush(color)
            : Brushes.Black;

        _brushCache[hex] = brush;
        return brush;
    }

