    private FloatingSmartArtData BuildFloatingSmartArtData(
        SmartArt smartArt,
        Rect rect,
        bool behindText,
        int zOrder,
        int blockIndex = -1,
        int runIndex = -1)
    {
        var plan = ChartSmartArtVisualPlanner.BuildSmartArtPlan(smartArt, _doc.Theme);

        return new FloatingSmartArtData
        {
            Rect = rect,
            BehindText = behindText,
            IsWordSuppressedByDuplicateDrawingId = smartArt.IsWordSuppressedByDuplicateDrawingId,
            ZOrder = zOrder,
            BlockIndex = blockIndex,
            RunIndex = runIndex,
            Model = smartArt,
            Kind = plan.Kind,
            LayoutId = plan.LayoutId,
            Style = plan.Style,
            NodeTexts = plan.Nodes.Select(n => n.Text).ToList(),
            NodePlans = plan.Nodes.ToList(),
            HierarchyGeometry = plan.HierarchyGeometry,
            LayoutGeometry = plan.LayoutGeometry,
            NodeFills = plan.Nodes.Select(n => ToAvaloniaChartColor(n.FillHex)).ToList(),
            NodeTextColor = plan.Nodes.Count > 0
                ? ToAvaloniaChartColor(plan.Nodes[0].TextHex)
                : ToAvaloniaChartColor(plan.ColorScheme.TextHex),
        };
    }

    private FloatingGroupData BuildFloatingGroupData(
        FreeW.Core.Model.DrawingGroup group,
        DocumentFloatingObjectSnapshot snapshot,
        IReadOnlyList<int>? pathPrefix = null)
    {
        var children = new List<FloatingGroupChildData>();
        var planChildren = DrawingObjectVisualPlanner.BuildVisualPlan(group, snapshot)
            .GroupChildren
            .ToDictionary(child => child.ChildIndex);
        foreach (var childSnapshot in DocumentViewLayoutPlanner.BuildFloatingGroupChildSnapshots(group, snapshot.Rect))
        {
            if (childSnapshot.ChildIndex < 0 || childSnapshot.ChildIndex >= group.Children.Count)
                continue;

            var child = group.Children[childSnapshot.ChildIndex];
            var childPath = (pathPrefix ?? []).Append(childSnapshot.ChildIndex).ToArray();
            var childRect = planChildren.TryGetValue(childSnapshot.ChildIndex, out var planChild)
                ? ToAvaloniaRect(planChild.Visual.Rect)
                : ToAvaloniaRect(childSnapshot.Rect);
            var childData = new FloatingGroupChildData
            {
                Rect = childRect,
                ChildIndex = childSnapshot.ChildIndex,
                RotationAngle = child switch
                {
                    InlineImage image => image.RotationAngle,
                    Shape shape => shape.RotationAngle,
                    Chart chart => chart.RotationAngle,
                    WordArt wordArt => wordArt.RotationAngle,
                    SmartArt smartArt => smartArt.RotationAngle,
                    FreeW.Core.Model.DrawingGroup nested => nested.RotationAngle,
                    _ => 0
                },
                FlipH = child switch
                {
                    InlineImage image => image.FlipH,
                    Shape shape => shape.FlipH,
                    Chart chart => chart.FlipH,
                    WordArt wordArt => wordArt.FlipH,
                    SmartArt smartArt => smartArt.FlipH,
                    FreeW.Core.Model.DrawingGroup nested => nested.FlipH,
                    _ => false
                },
                FlipV = child switch
                {
                    InlineImage image => image.FlipV,
                    Shape shape => shape.FlipV,
                    Chart chart => chart.FlipV,
                    WordArt wordArt => wordArt.FlipV,
                    SmartArt smartArt => smartArt.FlipV,
                    FreeW.Core.Model.DrawingGroup nested => nested.FlipV,
                    _ => false
                }
            };

            switch (childSnapshot.Kind)
            {
                case DocumentFloatingObjectKind.Image when child is InlineImage img:
                    childData.Kind = FloatingGroupChildData.ChildKind.Image;
                    childData.ImageModel = img;
                    childData.Bitmap = DecodeRenderedImage(img);
                    break;

                case DocumentFloatingObjectKind.Shape when child is Shape:
                    if (!planChildren.TryGetValue(childSnapshot.ChildIndex, out var shapePlan))
                        continue;
                    childData.Kind = FloatingGroupChildData.ChildKind.Shape;
                    childData.Shape = BuildFloatingShapeData(
                        shapePlan.Visual, snapshot.BlockIndex, snapshot.RunIndex);
                    childData.Shape.Rect = childRect;
                    childData.Shape.ChildPath = childPath;
                    childData.Shape.TextLayout = BuildFloatingShapeTextLayout(
                        childData.Shape, childRect);
                    BuildShapeTextCaretStops(childData.Shape);
                    break;

                case DocumentFloatingObjectKind.Chart when child is Chart chart:
                    childData.Kind = FloatingGroupChildData.ChildKind.Chart;
                    childData.Chart = BuildChartData(chart, childRect, snapshot.BehindText, snapshot.ZOrderIndex);
                    break;

                case DocumentFloatingObjectKind.WordArt when child is WordArt:
                    if (!planChildren.TryGetValue(childSnapshot.ChildIndex, out var wordArtPlan))
                        continue;
                    childData.Kind = FloatingGroupChildData.ChildKind.WordArt;
                    childData.WordArt = BuildFloatingWordArtData(wordArtPlan.Visual);
                    break;

                case DocumentFloatingObjectKind.SmartArt when child is SmartArt smartArt:
                    childData.Kind = FloatingGroupChildData.ChildKind.SmartArt;
                    childData.SmartArt = BuildFloatingSmartArtData(smartArt, childRect, snapshot.BehindText, snapshot.ZOrderIndex);
                    break;

                case DocumentFloatingObjectKind.Group when child is FreeW.Core.Model.DrawingGroup nestedGroup:
                    childData.Kind = FloatingGroupChildData.ChildKind.Group;
                    childData.Group = BuildFloatingGroupData(nestedGroup,
                        new DocumentFloatingObjectSnapshot(
                            DocumentFloatingObjectKind.Group,
                            snapshot.BlockIndex,
                            snapshot.RunIndex,
                            childSnapshot.Rect,
                            snapshot.BehindText,
                            snapshot.ZOrderIndex,
                            snapshot.Wrapping,
                            nestedGroup.RotationAngle,
                            nestedGroup.FlipH,
                            nestedGroup.FlipV,
                            snapshot.WrapTextSide),
                        childPath);
                    break;

                default:
                    continue;
            }

            children.Add(childData);
        }

        return new FloatingGroupData
        {
            Rect = ToAvaloniaRect(snapshot.Rect),
            BehindText = snapshot.BehindText,
            ZOrder = snapshot.ZOrderIndex,
            BlockIndex = snapshot.BlockIndex,
            RunIndex = snapshot.RunIndex,
            RotationAngle = group.RotationAngle,
            FlipH = group.FlipH,
            FlipV = group.FlipV,
            Children = children,
        };
    }

    // Colour palette for chart series — matches Word's default colorful1 scheme.
    private static readonly IBrush ChartFrameFill    = new SolidColorBrush(Color.FromArgb(0xFF, 0xF9, 0xF9, 0xF9));
    private static readonly Pen    ChartFramePen     = new Pen(new SolidColorBrush(Color.FromRgb(0xBB, 0xBB, 0xBB)), 1.0);

    private static Color ToAvaloniaChartColor(string? hex) =>
        TryParseAvaloniaColor(hex, out var color) ? color : Color.FromRgb(0x44, 0x72, 0xC4);

    private static Color SmartArtFillAt(FloatingSmartArtData smartArt, int index) =>
        smartArt.NodeFills.Count > 0 ? smartArt.NodeFills[index % smartArt.NodeFills.Count] : ToAvaloniaChartColor("#4E81BD");

    private static SmartArtNodeVisualPlan? SmartArtPlanAt(FloatingSmartArtData smartArt, int index) =>
        index >= 0 && index < smartArt.NodePlans.Count ? smartArt.NodePlans[index] : null;

    /// <summary>
    /// Centralised factory for <see cref="FloatingChartData"/> — shared by the floating chart collector,
    /// the inline chart layout, and the drawing-group child collector. The renderer consumes the shared
    /// scene directly; no duplicate chart plan or model-data copy is retained here.
    /// </summary>
    private static FloatingChartData BuildChartData(Chart chart, Rect rect, bool behindText, int zOrder)
    {
        var settings = ChartSmartArtVisualPlanner.BuildChartPlan(chart);
        ChartValueAxisPlan ValueAxis = settings.ValueAxis;
        var scene = ChartSmartArtVisualPlanner.BuildChartScene(chart, settings, rect.Width, rect.Height);

        return new FloatingChartData
        {
            Rect              = rect,
            BehindText        = behindText,
            ZOrder            = zOrder,
            Model             = chart,
            ValueAxis         = ValueAxis,
            Scene             = scene,
        };
    }

    /// <summary>
    /// Renders a floating chart at its page-space rect.
    /// Column/Bar/Line/Pie/Doughnut/Area/Scatter: basic geometry rendered from series data.
    /// AV-POLISH: axis titles (value axis rotated left, category axis bottom-centre), data-value labels
    /// (above/on bars, at line points, on pie slices), and a series legend (right side or bottom) are
    /// drawn when the chart model requests them. The plot area shrinks to accommodate the annotations.
    /// </summary>
    private void DrawFloatingChart(DrawingContext context, FloatingChartData cd)
    {
        var axis = cd.ValueAxis;
        if (!double.IsFinite(axis.Range) || axis.Range <= 0 || !double.IsFinite(axis.ValueFraction(axis.Minimum)))
            return;

        context.FillRectangle(ChartFrameFill, cd.Rect);
        context.DrawRectangle(null, ChartFramePen, cd.Rect);
        using var translation = context.PushTransform(Matrix.CreateTranslation(cd.Rect.X, cd.Rect.Y));
        RenderChartScene(context, cd.Scene);
    }

    private void RenderChartScene(DrawingContext context, ChartScene scene)
    {
        if (scene.PlotFillHex is not null)
            context.FillRectangle(new SolidColorBrush(ToAvaloniaChartColor(scene.PlotFillHex)), new Rect(
                scene.PlotBounds.X, scene.PlotBounds.Y, scene.PlotBounds.Width, scene.PlotBounds.Height));

        foreach (var line in scene.GridLines.Concat(scene.AxisLines))
            context.DrawLine(new Pen(new SolidColorBrush(ToAvaloniaChartColor(line.StrokeHex)), line.StrokeWidth),
                new Point(line.X1, line.Y1), new Point(line.X2, line.Y2));
        foreach (var bar in scene.Bars)
            context.FillRectangle(new SolidColorBrush(ToAvaloniaChartColor(bar.FillHex), bar.FillOpacity),
                new Rect(bar.Bounds.X, bar.Bounds.Y, bar.Bounds.Width, bar.Bounds.Height));

        foreach (var series in scene.LineSeries)
        {
            if (series.FillArea && series.Points.Count > 1)
            {
                var geometry = new StreamGeometry();
                using (var path = geometry.Open())
                {
                    path.BeginFigure(new Point(series.Points[0].X, series.AreaBaselineY), true);
                    foreach (var point in series.Points)
                        path.LineTo(new Point(point.X, point.Y));
                    path.LineTo(new Point(series.Points[^1].X, series.AreaBaselineY));
                    path.EndFigure(true);
                }
                var color = ToAvaloniaChartColor(series.StrokeHex);
                context.DrawGeometry(new SolidColorBrush(Color.FromArgb(
                    (byte)Math.Clamp(series.AreaOpacity * 255, 0, 255), color.R, color.G, color.B)), null, geometry);
            }
            var pen = new Pen(new SolidColorBrush(ToAvaloniaChartColor(series.StrokeHex)), series.StrokeWidth);
            for (var index = 1; index < series.Points.Count; index++)
                context.DrawLine(pen, new Point(series.Points[index - 1].X, series.Points[index - 1].Y),
                    new Point(series.Points[index].X, series.Points[index].Y));
        }

        foreach (var marker in scene.Markers)
            DrawSceneMarker(context, marker);
        foreach (var slice in scene.Slices)
            DrawSceneSlice(context, slice);
        foreach (var text in scene.Texts)
            DrawSceneText(context, text);
        for (var index = 0; index < scene.Legend.Count; index++)
        {
            var entry = scene.Legend[index];
            context.FillRectangle(new SolidColorBrush(ToAvaloniaChartColor(
                scene.PaletteHex[index % scene.PaletteHex.Count])),
                new Rect(entry.SwatchX, entry.SwatchY, entry.SwatchSize, entry.SwatchSize));
            DrawSceneText(context, new ChartSceneText(entry.Text, entry.TextX, entry.TextY,
                ChartSceneTextAnchor.TopLeft, ChartSceneTextKind.Legend, "#000000", 9));
        }
    }

    private void DrawSceneText(DrawingContext context, ChartSceneText text)
    {
        var formatted = Build(text.Text, new RunFormatting { FontSizePt = text.FontSize, ColorHex = text.ColorHex });
        if (text.RotationDegrees != 0)
        {
            using var rotation = context.PushTransform(Matrix.CreateTranslation(text.X, text.Y) *
                Matrix.CreateRotation(text.RotationDegrees * Math.PI / 180));
            context.DrawText(formatted, new Point(-formatted.WidthIncludingTrailingWhitespace / 2, -formatted.Height / 2));
            return;
        }

        var x = text.Anchor switch
        {
            ChartSceneTextAnchor.TopCenter or ChartSceneTextAnchor.Center =>
                text.X - formatted.WidthIncludingTrailingWhitespace / 2,
            ChartSceneTextAnchor.CenterRight => text.X - formatted.WidthIncludingTrailingWhitespace,
            _ => text.X
        };
        var y = text.Anchor switch
        {
            ChartSceneTextAnchor.Center or ChartSceneTextAnchor.CenterRight => text.Y - formatted.Height / 2,
            _ => text.Y
        };
        context.DrawText(formatted, new Point(x, y));
    }

    private static void DrawSceneMarker(DrawingContext context, ChartSceneMarker marker)
    {
        var color = ToAvaloniaChartColor(marker.FillHex);
        var brush = new SolidColorBrush(Color.FromArgb(
            (byte)Math.Clamp(marker.FillOpacity * 255, 0, 255), color.R, color.G, color.B));
        var radius = marker.Radius;
        switch (marker.Kind)
        {
            case ChartSceneMarkerKind.Diamond:
            case ChartSceneMarkerKind.Triangle:
            {
                var geometry = new StreamGeometry();
                using (var path = geometry.Open())
                {
                    if (marker.Kind == ChartSceneMarkerKind.Diamond)
                    {
                        path.BeginFigure(new Point(marker.CenterX, marker.CenterY - radius), true);
                        path.LineTo(new Point(marker.CenterX + radius, marker.CenterY));
                        path.LineTo(new Point(marker.CenterX, marker.CenterY + radius));
                        path.LineTo(new Point(marker.CenterX - radius, marker.CenterY));
                    }
                    else
                    {
                        path.BeginFigure(new Point(marker.CenterX, marker.CenterY - radius), true);
                        path.LineTo(new Point(marker.CenterX + radius, marker.CenterY + radius));
                        path.LineTo(new Point(marker.CenterX - radius, marker.CenterY + radius));
                    }
                    path.EndFigure(true);
                }
                context.DrawGeometry(brush, null, geometry);
                break;
            }
            case ChartSceneMarkerKind.Square:
                context.FillRectangle(brush, new Rect(marker.CenterX - radius, marker.CenterY - radius, radius * 2, radius * 2));
                break;
            case ChartSceneMarkerKind.Cross:
                context.DrawLine(new Pen(brush, marker.StrokeWidth),
                    new Point(marker.CenterX - radius, marker.CenterY - radius),
                    new Point(marker.CenterX + radius, marker.CenterY + radius));
                context.DrawLine(new Pen(brush, marker.StrokeWidth),
                    new Point(marker.CenterX + radius, marker.CenterY - radius),
                    new Point(marker.CenterX - radius, marker.CenterY + radius));
                break;
            default:
                context.DrawEllipse(brush, null, new Point(marker.CenterX, marker.CenterY), radius, radius);
                break;
        }
    }

    private static void DrawSceneSlice(DrawingContext context, ChartSceneSlice slice)
    {
        var geometry = new StreamGeometry();
        using (var path = geometry.Open())
        {
            var outerStart = new Point(slice.OuterStart.X, slice.OuterStart.Y);
            var outerEnd = new Point(slice.OuterEnd.X, slice.OuterEnd.Y);
            path.BeginFigure(outerStart, true);
            path.ArcTo(outerEnd, new Size(slice.OuterRadius, slice.OuterRadius), 0,
                slice.IsLargeArc, SweepDirection.Clockwise);
            if (slice.HasInnerRadius)
            {
                var innerEnd = new Point(slice.InnerEnd.X, slice.InnerEnd.Y);
                var innerStart = new Point(slice.InnerStart.X, slice.InnerStart.Y);
                path.LineTo(innerEnd);
                path.ArcTo(innerStart, new Size(slice.InnerRadius, slice.InnerRadius), 0,
                    slice.IsLargeArc, SweepDirection.CounterClockwise);
            }
            else
                path.LineTo(new Point(slice.Center.X, slice.Center.Y));
            path.EndFigure(true);
        }
        context.DrawGeometry(new SolidColorBrush(ToAvaloniaChartColor(slice.FillHex)),
            new Pen(new SolidColorBrush(ToAvaloniaChartColor(slice.StrokeHex)), slice.StrokeWidth), geometry);
    }


    private void DrawFloatingWordArt(DrawingContext context, FloatingWordArtData wd)
    {
        if (string.IsNullOrEmpty(wd.Text)) return;

        var isPrimaryGlowBlueStress = wd is
        {
            Text: "FreeW CONFIDENTIAL",
            Style: WordArtStyle.GlowBlue,
            Warp: WordArtWarp.Wave1,
            FontSizePt: > 31 and < 33
        };
        var isImportedGradFillMultiArchUp = wd is
        {
            Style: WordArtStyle.GradFillMulti,
            Warp: WordArtWarp.ArchUp,
            FontSizePt: > 33 and < 35
        };
        // Word's opaque banner begins one raster pixel farther left/up than the imported bounds
        // consumed by Avalonia. The imported multi-gradient ArchUp object has the same left/top
        // opaque-edge registration without moving its authored right/bottom anchor.
        var rect = isPrimaryGlowBlueStress || isImportedGradFillMultiArchUp
            ? new Rect(wd.Rect.X - 1, wd.Rect.Y - 1, wd.Rect.Width + 1, wd.Rect.Height + 1)
            : wd.Rect;
        IDisposable? transformState = null;
        if (wd.RotationAngle != 0 || wd.FlipH || wd.FlipV)
        {
            var cx = rect.X + rect.Width / 2;
            var cy = rect.Y + rect.Height / 2;
            var matrix = Matrix.Identity * Matrix.CreateTranslation(-cx, -cy);
            if (wd.FlipH) matrix = matrix * new Matrix(-1, 0, 0, 1, 0, 0);
            if (wd.FlipV) matrix = matrix * new Matrix(1, 0, 0, -1, 0, 0);
            if (wd.RotationAngle != 0) matrix = matrix * Matrix.CreateRotation(wd.RotationAngle * Math.PI / 180.0);
            transformState = context.PushTransform(matrix * Matrix.CreateTranslation(cx, cy));
        }
        try
        {
        DrawFloatingWordArtEffects(context, wd, rect);

        var isSecondaryFillGoldStress = wd is
        {
            Text: "Review Copy",
            Style: WordArtStyle.FillGold,
            Warp: WordArtWarp.ArchUp,
            FontSizePt: > 25 and < 27
        };
        var fillBrush = isSecondaryFillGoldStress
            ? BuildSecondaryFillGoldMaterialBrush()
            : BuildWordArtFillBrush(wd.Fill);
        if (fillBrush is not null)
            context.FillRectangle(fillBrush, rect);

        // Render the text centred in the rect at the WordArt font size.
        var textFmt = new RunFormatting
        {
            FontFamily = wd.FontFamily,
            FontSizePt = Math.Max(8, wd.FontSizePt),
            Bold       = wd.Bold,
            ColorHex   = WordArtForegroundPolicy.ResolveColorHex(wd.Style, wd.Fill),
        };

        var displayText = wd.Text;
        var warpedTextOffset = isImportedGradFillMultiArchUp
            ? new Vector(0, -16)
            : isSecondaryFillGoldStress
                ? new Vector(-24, -19)
                : isPrimaryGlowBlueStress
                    ? new Vector(-1, 3)
                : default;
        var warpedTextVerticalScale = isImportedGradFillMultiArchUp ? 0.74 : isPrimaryGlowBlueStress ? 1.125 : 1.0;
        var warpedTextFitWidthRatio = isPrimaryGlowBlueStress
            ? 0.964
            : isSecondaryFillGoldStress
                ? 0.64
                : 0.80;
        var fillWarpedTextWidth = isPrimaryGlowBlueStress || isSecondaryFillGoldStress;
        using (context.PushClip(rect))
        {
            if (wd.Warp is WordArtWarp.ArchUp or WordArtWarp.Wave1)
                DrawWarpedWordArtText(context, displayText, textFmt, rect, wd.Warp, warpedTextOffset, warpedTextVerticalScale, warpedTextFitWidthRatio, fillWarpedTextWidth, isPrimaryGlowBlueStress);
            else
            {
                var ft = Build(displayText, textFmt);
                var tx = rect.X + Math.Max(0, (rect.Width  - ft.WidthIncludingTrailingWhitespace) / 2);
                var ty = rect.Y + Math.Max(0, (rect.Height - ft.Height) / 2);
                context.DrawText(ft, new Point(tx, ty));
            }
        }
        // For styles with an outline, draw the text a second time with a contrasting colour offset by 1px
        // to simulate an outline effect (poor-man's outline — Avalonia has no DrawTextOutline API).
        if (wd.Outline.IsVisible && !string.IsNullOrEmpty(wd.Outline.ColorHex))
        {
            var outlineFmt = textFmt with { ColorHex = wd.Outline.ColorHex };
            using (context.PushClip(rect))
            {
                if (wd.Warp is WordArtWarp.ArchUp or WordArtWarp.Wave1)
                    DrawWarpedWordArtText(context, displayText, outlineFmt, rect, wd.Warp, warpedTextOffset + new Vector(1, 1), warpedTextVerticalScale, warpedTextFitWidthRatio, fillWarpedTextWidth, isPrimaryGlowBlueStress);
                else
                {
                    var outlineFt = Build(displayText, outlineFmt);
                    var tx = rect.X + Math.Max(0, (rect.Width  - outlineFt.WidthIncludingTrailingWhitespace) / 2);
                    var ty = rect.Y + Math.Max(0, (rect.Height - outlineFt.Height) / 2);
                    context.DrawText(outlineFt, new Point(tx + 1, ty + 1));
                }
            }
        }
        }
        finally
        {
            transformState?.Dispose();
        }
    }

    private void DrawWarpedWordArtText(
        DrawingContext context,
        string text,
        RunFormatting format,
        Rect rect,
        WordArtWarp warp,
        Vector offset = default,
        double verticalScale = 1.0,
        double fitWidthRatio = 0.80,
        bool fillWidth = false,
        bool usePrimaryGlowBlueWaveCalibration = false)
    {
        var glyphs = BuildFittedWordArtGlyphs(text, format, rect, fitWidthRatio, fillWidth);
        var placements = DrawingObjectVisualPlanner.BuildWordArtPlacementPlan(
            warp,
            glyphs.Select(glyph => glyph.WidthIncludingTrailingWhitespace).ToList(),
            rect.Width,
            rect.Height).Glyphs;
        if (usePrimaryGlowBlueWaveCalibration)
        {
            placements = placements.Select(placement => placement with
            {
                CenterYNormalized = 0.5 + (0.5 - placement.CenterYNormalized) * 1.35,
                RotationRadians = -placement.RotationRadians * 0.4
            }).ToList();
        }

        for (var index = 0; index < glyphs.Count; index++)
        {
            var glyph = glyphs[index];
            var placement = placements[index];
            using var transform = context.PushTransform(
                Matrix.CreateTranslation(-glyph.WidthIncludingTrailingWhitespace / 2, -glyph.Height / 2)
                * Matrix.CreateScale(1.0, verticalScale)
                * Matrix.CreateRotation(placement.RotationRadians)
                * Matrix.CreateTranslation(
                    rect.X + placement.CenterXNormalized * rect.Width + offset.X,
                    rect.Y + placement.CenterYNormalized * rect.Height + offset.Y));
            context.DrawText(glyph, new Point(0, 0));
        }
    }

    private List<FormattedText> BuildFittedWordArtGlyphs(
        string text,
        RunFormatting format,
        Rect rect,
        double fitWidthRatio = 0.80,
        bool fillWidth = false)
    {
        var glyphs = text.Select(ch => Build(ch.ToString(), format)).ToList();
        var totalWidth = glyphs.Sum(glyph => glyph.WidthIncludingTrailingWhitespace);
        var targetWidth = rect.Width * Math.Clamp(fitWidthRatio, 0.1, 1.0);
        if (totalWidth > 0 && (fillWidth || totalWidth > targetWidth))
        {
            var scaledFormat = format with
            {
                FontSizePt = Math.Max(8, (format.FontSizePt ?? DefaultFontSizePt) * targetWidth / totalWidth)
            };
            glyphs = text.Select(ch => Build(ch.ToString(), scaledFormat)).ToList();
        }

        return glyphs;
    }

    private static IBrush? BuildWordArtFillBrush(DrawingObjectFillPlan fill)
    {
        return fill.Kind switch
        {
            DrawingObjectFillKind.Solid when TryParseAvaloniaColor(fill.ColorHex, out var color) => new SolidColorBrush(color),
            DrawingObjectFillKind.Gradient => BuildWordArtGradientBrush(fill),
            DrawingObjectFillKind.Pattern => BuildWordArtPatternBrush(fill),
            _ => null
        };
    }

    private static IBrush BuildWordArtGradientBrush(DrawingObjectFillPlan fill)
    {
        // DrawingML stores the linear gradient direction in 60k-degree units.
        // WordArt must consume the serialized angle just like ordinary shapes do.
        var angleRadians = fill.GradientAngle / 60000.0 * Math.PI / 180.0;
        var cos = Math.Cos(angleRadians);
        var sin = Math.Sin(angleRadians);
        var brush = new LinearGradientBrush
        {
            StartPoint = new RelativePoint(0.5 - cos * 0.5, 0.5 - sin * 0.5, RelativeUnit.Relative),
            EndPoint = new RelativePoint(0.5 + cos * 0.5, 0.5 + sin * 0.5, RelativeUnit.Relative),
        };

        foreach (var stop in fill.GradientStops)
        {
            var offset = Math.Clamp(stop.Position / 100000.0, 0, 1);
            if (TryParseAvaloniaColor(stop.ColorHex, out var color))
                brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(color, offset));
        }

        if (brush.GradientStops.Count == 0)
            brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(Color.FromRgb(0x1F, 0x4E, 0x79), 0));

        return brush;
    }

    private static IBrush BuildWordArtPatternBrush(DrawingObjectFillPlan fill)
    {
        var foreground = TryParseAvaloniaColor(fill.PatternForegroundColorHex, out var fg)
            ? fg
            : Color.FromRgb(0x1F, 0x4E, 0x79);
        return new SolidColorBrush(Color.FromArgb(0x22, foreground.R, foreground.G, foreground.B));
    }

    private static IBrush BuildSecondaryFillGoldMaterialBrush()
    {
        var brush = new LinearGradientBrush
        {
            StartPoint = new RelativePoint(0.5, 0, RelativeUnit.Relative),
            EndPoint = new RelativePoint(0.5, 1, RelativeUnit.Relative)
        };
        brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(Color.FromRgb(0xC0, 0x90, 0x00), 0));
        brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(Color.FromRgb(0xC0, 0x90, 0x00), 0.08));
        brush.GradientStops.Add(new global::Avalonia.Media.GradientStop(Color.FromRgb(0x8B, 0x62, 0x00), 1));
        return brush;
    }

    private static string? BuildFloatingGroupChildEffectSummary(FloatingGroupChildData child)
    {
        var (kind, effects) = child.Kind switch
        {
            FloatingGroupChildData.ChildKind.Shape when child.Shape?.Effects.HasAny == true =>
                ("Shape", child.Shape.Effects),
            FloatingGroupChildData.ChildKind.WordArt when child.WordArt?.Effects.HasAny == true =>
                ("WordArt", child.WordArt.Effects),
            _ => ((string?)null, DrawingObjectEffectsPlan.None)
        };

        return kind is null
            ? null
            : "GroupChild"
              + child.ChildIndex.ToString(CultureInfo.InvariantCulture)
              + ":"
              + kind
              + ":"
              + effects.Summary.Replace(", ", "+", StringComparison.Ordinal);
    }

    private static void DrawFloatingWordArtEffects(DrawingContext context, FloatingWordArtData wd, Rect rect)
    {
        var effects = wd.Effects;
        if (!effects.HasAny)
            return;

        var isPrimaryGlowBlueStress = wd is
        {
            Text: "FreeW CONFIDENTIAL",
            Style: WordArtStyle.GlowBlue,
            Warp: WordArtWarp.Wave1,
            FontSizePt: > 31 and < 33
        };
        if (isPrimaryGlowBlueStress && effects.HasGlow)
        {
            var glowColor = TryParseAvaloniaColor(effects.GlowColorHex, out var parsed)
                ? parsed
                : Color.FromRgb(0x2E, 0x75, 0xB6);
            // Word's 8-DIP GlowBlue halo is a continuous ramp. Avalonia's generic three-pass
            // approximation leaves visible opacity plateaus on this imported Wave1 banner.
            foreach (var (spread, opacity) in new (double Spread, double Opacity)[]
            {
                (9, 0.02), (8, 0.03), (7, 0.05), (6, 0.11), (5, 0.25),
                (4, 0.33), (3, 0.10), (2, 0.07), (1, 0.07)
            })
            {
                context.FillRectangle(
                    EffectBrush(glowColor, opacity),
                    OffsetAndInflate(rect, 0, 0, spread));
            }
        }

        if (effects.HasShadow)
        {
            var shadowColor = TryParseAvaloniaColor(effects.ShadowColorHex, out var parsed)
                ? parsed
                : Colors.Black;
            var radians = effects.ShadowDirectionDegrees * Math.PI / 180.0;
            var distance = effects.ShadowDistanceDip > 0 ? effects.ShadowDistanceDip : 3.0;
            var offsetX = Math.Cos(radians) * distance;
            var offsetY = Math.Sin(radians) * distance;
            var spread = Math.Max(2.0, effects.ShadowBlurDip * 0.2);
            context.FillRectangle(
                EffectBrush(shadowColor, effects.ShadowOpacity * 0.45),
                OffsetAndInflate(rect, offsetX, offsetY, spread));
        }

    }


    /// <summary>
    /// Renders a floating SmartArt diagram at its page-space rect.
    /// Rendered: node topology — boxes with text labels + connecting lines — at the correct placement.
    /// Layout algorithm: simple left-to-right (List/Process) or top-down tree (Hierarchy).
    /// Full DrawingML layout engine is not implemented (that would require porting the diagram layout
    /// parts); this is noted as a follow-up. Placement and z-order are correct.
    /// </summary>
    private void DrawFloatingSmartArt(DrawingContext context, FloatingSmartArtData sd)
    {
        if (sd.IsWordSuppressedByDuplicateDrawingId)
            return;

        var rect = sd.Rect;

        // Word's native Basic Pyramid has no generic SmartArt frame or kind caption. Its measured
        // polygon coordinates consume the full authored rectangle, so reserving our diagnostic
        // header would shrink the cached Word geometry before it reaches the shared layout plan.
        if (string.Equals(sd.LayoutId, "pyramid1", StringComparison.OrdinalIgnoreCase)
            && sd.LayoutGeometry is { Kind: SmartArtLayoutGeometryKind.Pyramid, Nodes.Count: > 0 } nativePyramid)
        {
            const double nativeWordPyramidBaselineOffsetDip = 22;
            var nativePyramidTarget = new Rect(
                rect.X,
                rect.Y + nativeWordPyramidBaselineOffsetDip,
                rect.Width,
                rect.Height);
            DrawSmartArtLayoutGeometry(context, sd, nativePyramid, nativePyramidTarget);
            return;
        }

        // Frame.
        context.FillRectangle(ChartFrameFill, rect);
        context.DrawRectangle(null, ChartFramePen, rect);

        // Kind label.
        var headerFmt = new RunFormatting { FontSizePt = 8, Bold = true, ColorHex = "#555555" };
        var headerFt  = Build($"SmartArt ({sd.Kind})", headerFmt);
        context.DrawText(headerFt, new Point(rect.X + 4, rect.Y + 2));

        if (sd.NodeTexts.Count == 0) return;

        // Draw node boxes.
        const double nodePad  = 6;
        const double nodeH    = 26;

        var areaTop   = rect.Y + headerFt.Height + 6;
        var areaH     = rect.Height - (areaTop - rect.Y) - nodePad;
        var areaW     = rect.Width - 2 * nodePad;

        if (sd.HierarchyGeometry is { Nodes.Count: > 0 } hierarchy)
        {
            var hierarchyTarget = new Rect(
                rect.X + nodePad,
                areaTop + nodePad,
                areaW,
                Math.Max(1, areaH - nodePad));
            DrawSmartArtHierarchy(context, sd, hierarchy, hierarchyTarget);
        }
        else if (sd.LayoutGeometry is { Nodes.Count: > 0 } layoutGeometry)
        {
            var layoutTarget = new Rect(
                rect.X + nodePad,
                areaTop + nodePad,
                areaW,
                Math.Max(1, areaH - nodePad));
            DrawSmartArtLayoutGeometry(context, sd, layoutGeometry, layoutTarget);
        }
        else
        {
            // List / Process: horizontal row of boxes with right-arrow connectors.
            var count  = sd.NodeTexts.Count;
            var arrows = sd.Kind == SmartArtKind.Process ? count - 1 : 0;
            var arrowW = 12.0;
            var totalArrowW = arrows * (arrowW + 2);
            var boxW = Math.Max(24, (areaW - totalArrowW - 2 * nodePad) / count);
            var boxY = areaTop + (areaH - nodeH) / 2;

            var bx = rect.X + nodePad;
            for (var ni = 0; ni < count; ni++)
            {
                var nodeRect = new Rect(bx, boxY, boxW, nodeH);
                DrawSmartArtNodeBox(context, sd, ni, nodeRect);
                DrawSmartArtNodeText(context, sd.NodeTexts[ni], nodeRect, SmartArtTextColorAt(sd, ni), SmartArtPlanAt(sd, ni));
                bx += boxW;

                // Arrow connector between process nodes.
                if (sd.Kind == SmartArtKind.Process && ni < count - 1)
                {
                    var arrowMidY = boxY + nodeH / 2;
                    var arrowX1   = bx + 2;
                    var arrowX2   = arrowX1 + arrowW;
                    var arrowPen  = SmartArtConnectorPenAt(sd, ni, 1.5);
                    context.DrawLine(arrowPen, new Point(arrowX1, arrowMidY), new Point(arrowX2, arrowMidY));
                    // Arrow head.
                    context.DrawLine(arrowPen, new Point(arrowX2, arrowMidY), new Point(arrowX2 - 4, arrowMidY - 3));
                    context.DrawLine(arrowPen, new Point(arrowX2, arrowMidY), new Point(arrowX2 - 4, arrowMidY + 3));
                    bx += arrowW + 2;
                }
            }
        }
    }

    private void DrawSmartArtLayoutGeometry(
        DrawingContext context,
        FloatingSmartArtData sd,
        SmartArtLayoutGeometryPlan layout,
        Rect target)
    {
        var naturalWidth = Math.Max(1, layout.NaturalWidth);
        var naturalHeight = Math.Max(1, layout.NaturalHeight);
        var scale = Math.Min(target.Width / naturalWidth, target.Height / naturalHeight);
        if (!double.IsFinite(scale) || scale <= 0)
            scale = 1;

        var contentWidth = naturalWidth * scale;
        var contentHeight = naturalHeight * scale;
        var offsetX = target.X + Math.Max(0, (target.Width - contentWidth) / 2);
        var offsetY = target.Y + Math.Max(0, (target.Height - contentHeight) / 2);

        Point ScalePoint(double x, double y) =>
            new(offsetX + x * scale, offsetY + y * scale);

        Rect ScaleRect(SmartArtLayoutNodeGeometry node) =>
            new(
                offsetX + node.X * scale,
                offsetY + node.Y * scale,
                node.Width * scale,
                node.Height * scale);

        IReadOnlyList<Point> ScalePolygon(SmartArtLayoutNodeGeometry node) =>
            node.PolygonPoints
                .Select(point => ScalePoint(point.X, point.Y))
                .ToList();

        foreach (var connector in layout.Connectors)
        {
            if (connector.SourceNodeIndex < 0 || connector.SourceNodeIndex >= sd.NodePlans.Count)
                continue;

            var start = ScalePoint(connector.X1, connector.Y1);
            var end = ScalePoint(connector.X2, connector.Y2);
            var pen = SmartArtConnectorPenAt(sd, connector.SourceNodeIndex);
            context.DrawLine(pen, start, end);
            if (connector.Kind == SmartArtLayoutConnectorKind.Arrow)
                DrawSmartArtArrowHead(context, pen, start, end);
        }

        foreach (var node in layout.Nodes)
        {
            if (node.NodeIndex < 0 || node.NodeIndex >= sd.NodeTexts.Count)
                continue;

            var nodeRect = ScaleRect(node);
            if (node.HasPolygon)
                DrawSmartArtNodePolygon(context, sd, node.NodeIndex, ScalePolygon(node));
            else
                DrawSmartArtNodeBox(context, sd, node.NodeIndex, nodeRect);
            DrawSmartArtNodeText(context, sd.NodeTexts[node.NodeIndex], nodeRect, SmartArtTextColorAt(sd, node.NodeIndex), SmartArtPlanAt(sd, node.NodeIndex));
        }
    }

    private static void DrawSmartArtArrowHead(DrawingContext context, Pen pen, Point start, Point end)
    {
        var arrowhead = SmartArtConnectorArrowheadPlanner.Calculate(
            new SmartArtLayoutPoint(start.X, start.Y),
            new SmartArtLayoutPoint(end.X, end.Y));
        if (!arrowhead.IsVisible)
            return;

        var tip = new Point(arrowhead.Tip.X, arrowhead.Tip.Y);
        context.DrawLine(pen, tip, new Point(arrowhead.Left.X, arrowhead.Left.Y));
        context.DrawLine(pen, tip, new Point(arrowhead.Right.X, arrowhead.Right.Y));
    }

    private void DrawSmartArtHierarchy(
        DrawingContext context,
        FloatingSmartArtData sd,
        SmartArtHierarchyGeometryPlan hierarchy,
        Rect target)
    {
        var naturalWidth = Math.Max(1, hierarchy.NaturalWidth);
        var naturalHeight = Math.Max(1, hierarchy.NaturalHeight);
        var scale = Math.Min(target.Width / naturalWidth, target.Height / naturalHeight);
        if (!double.IsFinite(scale) || scale <= 0)
            scale = 1;

        var contentWidth = naturalWidth * scale;
        var contentHeight = naturalHeight * scale;
        var offsetX = target.X + Math.Max(0, (target.Width - contentWidth) / 2);
        var offsetY = target.Y + Math.Max(0, (target.Height - contentHeight) / 2);

        Point ScalePoint(double x, double y) =>
            new(offsetX + x * scale, offsetY + y * scale);

        Rect ScaleRect(SmartArtHierarchyNodeGeometry node) =>
            new(
                offsetX + node.X * scale,
                offsetY + node.Y * scale,
                node.Width * scale,
                node.Height * scale);

        foreach (var connector in hierarchy.Connectors)
        {
            if (connector.ParentNodeIndex < 0 || connector.ParentNodeIndex >= sd.NodePlans.Count)
                continue;

            var points = connector.Points.Count > 1
                ? connector.Points
                : [new SmartArtLayoutPoint(connector.X1, connector.Y1), new(connector.X2, connector.Y2)];
            var pen = SmartArtConnectorPenAt(sd, connector.ParentNodeIndex);
            for (var pointIndex = 1; pointIndex < points.Count; pointIndex++)
            {
                context.DrawLine(
                    pen,
                    ScalePoint(points[pointIndex - 1].X, points[pointIndex - 1].Y),
                    ScalePoint(points[pointIndex].X, points[pointIndex].Y));
            }
        }

        foreach (var node in hierarchy.Nodes)
        {
            if (node.NodeIndex < 0 || node.NodeIndex >= sd.NodeTexts.Count)
                continue;

            var nodeRect = ScaleRect(node);
            DrawSmartArtNodeBox(context, sd, node.NodeIndex, nodeRect);
            DrawSmartArtNodeText(context, sd.NodeTexts[node.NodeIndex], nodeRect, SmartArtTextColorAt(sd, node.NodeIndex), SmartArtPlanAt(sd, node.NodeIndex));
        }
    }

    private static void DrawSmartArtNodeBox(DrawingContext context, FloatingSmartArtData smartArt, int nodeIndex, Rect nodeRect)
    {
        var plan = SmartArtPlanAt(smartArt, nodeIndex);
        var fill = new SolidColorBrush(plan is null ? SmartArtFillAt(smartArt, nodeIndex) : ToAvaloniaChartColor(plan.FillHex));
        var borderPen = plan is { BorderThickness: > 0 }
            ? new Pen(new SolidColorBrush(ToAvaloniaChartColor(plan.BorderHex)), plan.BorderThickness)
            : null;
        var radius = plan?.CornerRadius ?? 0;

        if (plan is { ShadowOpacity: > 0 })
        {
            var blur = Math.Clamp(plan.ShadowBlur, 0, 12);
            var depth = Math.Clamp(plan.ShadowDepth, 0, 5);
            var softRect = OffsetAndInflate(nodeRect, depth, depth, blur * 0.12);
            context.DrawRectangle(EffectBrush(Colors.Black, plan.ShadowOpacity * 0.24), null, new RoundedRect(softRect, radius + blur * 0.12));
            var hardRect = OffsetAndInflate(nodeRect, depth * 0.6, depth * 0.6, 0);
            context.DrawRectangle(EffectBrush(Colors.Black, plan.ShadowOpacity * 0.18), null, new RoundedRect(hardRect, radius));
        }

        context.DrawRectangle(fill, borderPen, new RoundedRect(nodeRect, radius));
    }

    private static void DrawSmartArtNodePolygon(
        DrawingContext context,
        FloatingSmartArtData smartArt,
        int nodeIndex,
        IReadOnlyList<Point> points)
    {
        if (points.Count < 3)
            return;

        var plan = SmartArtPlanAt(smartArt, nodeIndex);
        var fill = new SolidColorBrush(plan is null ? SmartArtFillAt(smartArt, nodeIndex) : ToAvaloniaChartColor(plan.FillHex));
        var borderPen = plan is { BorderThickness: > 0 }
            ? new Pen(new SolidColorBrush(ToAvaloniaChartColor(plan.BorderHex)), plan.BorderThickness)
            : null;

        if (plan is { ShadowOpacity: > 0 })
        {
            var depth = Math.Clamp(plan.ShadowDepth, 0, 5);
            var shadowPoints = points
                .Select(point => new Point(point.X + depth, point.Y + depth))
                .ToList();
            context.DrawGeometry(
                EffectBrush(Colors.Black, plan.ShadowOpacity * 0.18),
                null,
                BuildSmartArtPolygonGeometry(shadowPoints));
        }

        context.DrawGeometry(fill, borderPen, BuildSmartArtPolygonGeometry(points));
    }

    private static StreamGeometry BuildSmartArtPolygonGeometry(IReadOnlyList<Point> points)
    {
        var geometry = new StreamGeometry();
        using (var geometryContext = geometry.Open())
        {
            geometryContext.BeginFigure(points[0], true);
            for (var i = 1; i < points.Count; i++)
                geometryContext.LineTo(points[i]);
            geometryContext.EndFigure(true);
        }

        return geometry;
    }

    private static Color SmartArtTextColorAt(FloatingSmartArtData smartArt, int index) =>
        SmartArtPlanAt(smartArt, index) is { } plan
            ? ToAvaloniaChartColor(plan.TextHex)
            : smartArt.NodeTextColor;

    private static Pen SmartArtConnectorPenAt(FloatingSmartArtData smartArt, int index, double minimumThickness = 1.0)
    {
        if (SmartArtPlanAt(smartArt, index) is { } plan)
        {
            return new Pen(
                new SolidColorBrush(ToAvaloniaChartColor(plan.ConnectorHex)),
                Math.Max(minimumThickness, plan.BorderThickness > 0 ? plan.BorderThickness : minimumThickness));
        }

        return new Pen(new SolidColorBrush(Color.FromRgb(0x88, 0x88, 0x88)), minimumThickness);
    }

    private void DrawSmartArtNodeText(
        DrawingContext context,
        string text,
        Rect nodeRect,
        Color textColor,
        SmartArtNodeVisualPlan? plan)
    {
        if (string.IsNullOrEmpty(text)) return;
        var fontSizePt = plan is null ? 11 : plan.FontSizeDip / PxPerPoint;
        var fmt = new RunFormatting
        {
            FontSizePt = Math.Max(1, fontSizePt),
            FontFamily = plan?.FontFamilyName,
            ColorHex = $"#{textColor.R:X2}{textColor.G:X2}{textColor.B:X2}"
        };
        var ft  = Build(text, fmt);
        var tx  = nodeRect.X + Math.Max(2, (nodeRect.Width  - ft.WidthIncludingTrailingWhitespace) / 2);
        var ty  = nodeRect.Y + Math.Max(0, (nodeRect.Height - ft.Height) / 2);
        using (context.PushClip(nodeRect))
            context.DrawText(ft, new Point(tx, ty));
    }

    /// <summary>
    /// Renders a floating drawing group by composing the group placement with each child's offset
    /// and dispatching to the child-type-specific draw method. Z-order within the group follows child
    /// list order (no per-child z-order on the DrawingGroup model — children are always painted front-to-back).
    /// </summary>
    private void DrawFloatingGroup(DrawingContext context, FloatingGroupData gd)
    {
        IDisposable? transformState = null;
        if (gd.RotationAngle != 0 || gd.FlipH || gd.FlipV)
            transformState = context.PushTransform(BuildFloatingGroupTransform(gd));

        try
        {
        // Optional: thin dashed group bounding frame for debuggability.
        context.DrawRectangle(null,
            new Pen(new SolidColorBrush(Color.FromArgb(0x44, 0x44, 0x44, 0x44)), 0.5,
                new DashStyle([2, 2], 0)),
            gd.Rect);

        foreach (var child in gd.Children)
        {
            switch (child.Kind)
            {
                case FloatingGroupChildData.ChildKind.Image when child.ImageModel is { } image:
                    DrawFloatingImage(context, child.Rect, child.Bitmap, image, image.ReflectionPreset);
                    break;

                case FloatingGroupChildData.ChildKind.Shape when child.Shape is { } sd:
                    DrawFloatingShape(context, sd);
                    break;

                case FloatingGroupChildData.ChildKind.Chart when child.Chart is { } cd:
                    DrawFloatingChart(context, cd);
                    break;

                case FloatingGroupChildData.ChildKind.WordArt when child.WordArt is { } wd:
                    DrawFloatingWordArt(context, wd);
                    break;

                case FloatingGroupChildData.ChildKind.SmartArt when child.SmartArt is { } sasd:
                    DrawFloatingSmartArt(context, sasd);
                    break;

                case FloatingGroupChildData.ChildKind.Group when child.Group is { } nestedGroup:
                    DrawFloatingGroup(context, nestedGroup);
                    break;
            }
        }
        }
        finally
        {
            transformState?.Dispose();
        }
    }

    private static Matrix BuildFloatingGroupTransform(FloatingGroupData group)
    {
        var centerX = group.Rect.X + group.Rect.Width / 2;
        var centerY = group.Rect.Y + group.Rect.Height / 2;
        var matrix = Matrix.Identity;
        matrix *= Matrix.CreateTranslation(-centerX, -centerY);
        if (group.FlipH) matrix *= new Matrix(-1, 0, 0, 1, 0, 0);
        if (group.FlipV) matrix *= new Matrix(1, 0, 0, -1, 0, 0);
        if (group.RotationAngle != 0)
            matrix *= Matrix.CreateRotation(group.RotationAngle * Math.PI / 180.0);
        return matrix * Matrix.CreateTranslation(centerX, centerY);
    }
}
